def currency_symbol(ticker: str) -> str:
    t = (ticker or "").upper()
    return "\u20b9" if (t in _INR_SYMBOLS or t.endswith((".NS", ".BO"))) else "$"


def sanitize_period(interval: str, period: str) -> tuple[str, str | None]:
    """Clamp a period to what Yahoo will actually serve for the interval."""
    ceiling = INTERVAL_MAX_DAYS.get(interval)
    if ceiling is None or PERIOD_DAYS.get(period, 0) <= ceiling:
        return period, None
    allowed = [p for p in PERIODS if PERIOD_DAYS[p] <= ceiling]
    eff = allowed[-1] if allowed else "1d"
    return eff, (f"Yahoo caps `{interval}` history at ~{ceiling} days. "
                 f"Period `{period}` was clamped to `{eff}`.")


# --------------------------------------------------------------- formatting ---
def fmt(value, digits: int = 2, dash: str = "--") -> str:
    if value is None:
        return dash
    try:
        f = float(value)
    except (TypeError, ValueError):
        return str(value)
    return dash if (math.isnan(f) or math.isinf(f)) else f"{f:,.{digits}f}"


def fmt_signed(value, digits: int = 2) -> str:
    if value is None:
        return "--"
    try:
        f = float(value)
    except (TypeError, ValueError):
        return str(value)
    return "--" if math.isnan(f) else f"{f:+,.{digits}f}"


def fmt_time(ts) -> str:
    if ts is None:
        return "--"
    try:
        if pd.isna(ts):
            return "--"
    except (TypeError, ValueError):
        pass
    if isinstance(ts, (pd.Timestamp, datetime)):
        return pd.Timestamp(ts).strftime("%Y-%m-%d %H:%M:%S")
    return str(ts)


def safe_last(series, offset: int = 0):
    idx = -1 - offset
    if series is None or len(series) < abs(idx):
        return None
    v = series.iloc[idx]
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):
        pass
    return v


def _f(v, default=np.nan) -> float:
    """Coerce to float, mapping None/NaT to NaN."""
    try:
        if v is None:
            return default
        f = float(v)
        return f if np.isfinite(f) else default
    except (TypeError, ValueError):
        return default


# =============================================================================
# SECTION 2 -- INDICATORS  (all hand-written; no pandas-ta / ta / TA-Lib)
# =============================================================================
def _seeded_recursive(values: np.ndarray, length: int, alpha: float) -> np.ndarray:
    """
    SMA-seeded recursive smoother:  out[t] = out[t-1] + alpha*(x[t] - out[t-1])

    pandas' ewm(adjust=False) seeds with the FIRST observation; TradingView seeds
    with the simple average of the first `length` observations. That difference
    is the usual cause of RSI/ATR drift against the chart, so the kernel below
    reproduces the TradingView convention explicitly.
    """
    n = values.shape[0]
    out = np.full(n, np.nan, dtype=float)
    if length <= 0 or n == 0:
        return out
    finite = np.isfinite(values)
    if finite.sum() < length:
        return out
    first = int(np.argmax(finite))
    seed_end = first + length
    if seed_end > n:
        return out
    if not np.isfinite(values[first:seed_end]).all():
        win = np.convolve(finite.astype(int), np.ones(length, dtype=int), mode="valid")
        idx = np.where(win == length)[0]
        if idx.size == 0:
            return out
        first = int(idx[0])
        seed_end = first + length
    out[seed_end - 1] = float(np.mean(values[first:seed_end]))
    prev = out[seed_end - 1]
    for i in range(seed_end, n):
        x = values[i]
        prev = prev if not np.isfinite(x) else prev + alpha * (x - prev)
        out[i] = prev
    return out


def sma(series: pd.Series, length: int) -> pd.Series:
    return series.rolling(int(length), min_periods=int(length)).mean()


def ema(series: pd.Series, length: int) -> pd.Series:
    length = int(length)
    return pd.Series(_seeded_recursive(np.asarray(series, float), length, 2.0 / (length + 1.0)),
                     index=series.index, name=f"EMA{length}")


def rma(series: pd.Series, length: int) -> pd.Series:
    length = int(length)
    return pd.Series(_seeded_recursive(np.asarray(series, float), length, 1.0 / length),
                     index=series.index, name=f"RMA{length}")


def rsi(close: pd.Series, length: int = 14) -> pd.Series:
    delta = close.diff()
    avg_gain = rma(delta.clip(lower=0.0), length)
    avg_loss = rma((-delta).clip(lower=0.0), length)
    rs = avg_gain / avg_loss.replace(0.0, np.nan)
    out = 100.0 - (100.0 / (1.0 + rs))
    out = out.where(avg_loss != 0.0, 100.0)
    out = out.where(avg_gain != 0.0, 0.0)
    out[avg_gain.isna() | avg_loss.isna()] = np.nan
    return out.rename(f"RSI{length}")


def true_range(high: pd.Series, low: pd.Series, close: pd.Series) -> pd.Series:
    pc = close.shift(1)
    tr = pd.concat([(high - low).abs(), (high - pc).abs(), (low - pc).abs()], axis=1).max(axis=1)
    if len(tr):
        tr.iloc[0] = float(high.iloc[0] - low.iloc[0])
    return tr.rename("TR")


def atr(high: pd.Series, low: pd.Series, close: pd.Series, length: int = 14) -> pd.Series:
    return rma(true_range(high, low, close), length).rename(f"ATR{length}")


def adx(high: pd.Series, low: pd.Series, close: pd.Series, length: int = 14):
    """Wilder ADX. Returns (adx, plus_di, minus_di)."""
    up, down = high.diff(), -low.diff()
    plus_dm = pd.Series(np.where((up > down) & (up > 0), up, 0.0), index=high.index)
    minus_dm = pd.Series(np.where((down > up) & (down > 0), down, 0.0), index=high.index)
    atr_ = rma(true_range(high, low, close), length).replace(0.0, np.nan)
    plus_di = 100.0 * rma(plus_dm, length) / atr_
    minus_di = 100.0 * rma(minus_dm, length) / atr_
    denom = (plus_di + minus_di).replace(0.0, np.nan)
    dx = 100.0 * (plus_di - minus_di).abs() / denom
    return rma(dx, length).rename("ADX"), plus_di.rename("+DI"), minus_di.rename("-DI")


def macd(close: pd.Series, fast=12, slow=26, signal=9):
    line = ema(close, fast) - ema(close, slow)
    sig = ema(line, signal)
    return line.rename("MACD"), sig.rename("MACD_SIGNAL"), (line - sig).rename("MACD_HIST")


def bollinger(close: pd.Series, length=20, mult=2.0):
    mid = sma(close, length)
    sd = close.rolling(int(length), min_periods=int(length)).std(ddof=0)
    return mid.rename("BB_MID"), (mid + mult * sd).rename("BB_UP"), (mid - mult * sd).rename("BB_LO")


def stdev(series: pd.Series, length: int) -> pd.Series:
    return series.rolling(int(length), min_periods=int(length)).std(ddof=0)


def rolling_high(series: pd.Series, length: int, exclude_current: bool = True) -> pd.Series:
    s = series.shift(1) if exclude_current else series
    return s.rolling(int(length), min_periods=int(length)).max()


def rolling_low(series: pd.Series, length: int, exclude_current: bool = True) -> pd.Series:
    s = series.shift(1) if exclude_current else series
    return s.rolling(int(length), min_periods=int(length)).min()


def slope(series: pd.Series, length: int = 5) -> pd.Series:
    return series - series.shift(int(length))


def cross_over(a: pd.Series, b: pd.Series) -> pd.Series:
    ok = a.shift(1).notna() & b.shift(1).notna()
    return ((a > b) & (a.shift(1) <= b.shift(1)) & ok).fillna(False)


def cross_under(a: pd.Series, b: pd.Series) -> pd.Series:
    ok = a.shift(1).notna() & b.shift(1).notna()
    return ((a < b) & (a.shift(1) >= b.shift(1)) & ok).fillna(False)


def supertrend(high, low, close, length=10, mult=3.0):
    """Classic SuperTrend. Returns (direction, upper_band, lower_band)."""
    a = atr(high, low, close, length)
    hl2 = (high + low) / 2.0
    ur, lr = (hl2 + mult * a).to_numpy(float), (hl2 - mult * a).to_numpy(float)
    c = close.to_numpy(float)
    n = len(close)
    up = np.full(n, np.nan)
    dn = np.full(n, np.nan)
    direction = np.zeros(n, dtype=int)
    prev = 1
    for i in range(n):
        if not np.isfinite(ur[i]):
            continue
        if i == 0 or not np.isfinite(up[i - 1]):
            up[i], dn[i], direction[i] = ur[i], lr[i], prev
            continue
        up[i] = min(ur[i], up[i - 1]) if c[i - 1] <= up[i - 1] else ur[i]
        dn[i] = max(lr[i], dn[i - 1]) if c[i - 1] >= dn[i - 1] else lr[i]
        if c[i] > up[i - 1]:
            prev = 1
        elif c[i] < dn[i - 1]:
            prev = -1
        direction[i] = prev
    idx = close.index
    return (pd.Series(direction, index=idx, name="ST_DIR"),
            pd.Series(up, index=idx, name="ST_UP"),
            pd.Series(dn, index=idx, name="ST_DN"))


def session_key(index: pd.DatetimeIndex) -> pd.Series:
    return pd.Series(pd.DatetimeIndex(index).normalize(), index=index)


def bar_of_session(index: pd.DatetimeIndex, intraday: bool) -> pd.Series:
    if not intraday:
        return pd.Series(np.arange(len(index)), index=index)
    k = session_key(index)
    return k.groupby(k).cumcount()


def vwap(df: pd.DataFrame, intraday: bool) -> tuple[pd.Series, bool]:
    """
    Session-anchored VWAP.

    Indices and spot FX report zero volume on Yahoo, which would make a true
    VWAP a division by zero. In that case we fall back to a session-anchored
    TWAP (cumulative mean of the typical price) and return volume_ok=False so
    the UI can say plainly that this is not a real VWAP.
    """
    tp = (df["High"] + df["Low"] + df["Close"]) / 3.0
    vol = df["Volume"].fillna(0.0)
    volume_ok = float(vol.abs().sum()) > 0.0
    if intraday:
        k = session_key(df.index)
        if volume_ok:
            pv = (tp * vol).groupby(k).cumsum()
            cv = vol.groupby(k).cumsum().replace(0.0, np.nan)
            return (pv / cv).rename("VWAP"), True
        return tp.groupby(k).expanding().mean().reset_index(level=0, drop=True).rename("TWAP"), False
    if volume_ok:
        pv, cv = (tp * vol).cumsum(), vol.cumsum().replace(0.0, np.nan)
        return (pv / cv).rename("VWAP"), True
    return tp.expanding().mean().rename("TWAP"), False


# ----------------------------------------------------- structure / swings ----
def swing_levels(high: pd.Series, low: pd.Series, left: int = 3, right: int = 3):
    """
    Confirmed swing levels, with no look-ahead.

    Returns ``(current_high, current_low, previous_high, previous_low)`` where
    "current" is the most recently confirmed pivot and "previous" is the one
    before it. A pivot at bar i is only knowable once `right` further bars have
    printed, so the detected value is shifted forward by `right` before being
    carried. That shift is the difference between a usable structural stop and a
    backtest that quietly cheats.
    """
    win = int(left) + int(right) + 1
    is_ph = high == high.rolling(win, center=True, min_periods=win).max()
    is_pl = low == low.rolling(win, center=True, min_periods=win).min()
    ph_raw = high.where(is_ph).shift(int(right))
    pl_raw = low.where(is_pl).shift(int(right))

    cur_h = ph_raw.ffill().rename("SWING_HIGH")
    cur_l = pl_raw.ffill().rename("SWING_LOW")
    prev_h = ph_raw.dropna().shift(1).reindex(high.index).ffill().rename("PREV_SWING_HIGH")
    prev_l = pl_raw.dropna().shift(1).reindex(low.index).ffill().rename("PREV_SWING_LOW")
    return cur_h, cur_l, prev_h, prev_l


def fair_value_gaps(df: pd.DataFrame):
    """ICT fair value gaps: a 3-candle imbalance where candle 1 and 3 do not overlap."""
    bull = (df["Low"] > df["High"].shift(2)) & (df["Close"] > df["Open"])
    bear = (df["High"] < df["Low"].shift(2)) & (df["Close"] < df["Open"])
    bull_top = df["Low"].where(bull)
    bull_bot = df["High"].shift(2).where(bull)
    bear_bot = df["High"].where(bear)
    bear_top = df["Low"].shift(2).where(bear)
    return (bull.rename("FVG_BULL"), bear.rename("FVG_BEAR"),
            bull_bot.ffill().rename("FVG_BULL_LO"), bull_top.ffill().rename("FVG_BULL_HI"),
            bear_bot.ffill().rename("FVG_BEAR_LO"), bear_top.ffill().rename("FVG_BEAR_HI"))


def market_structure(df: pd.DataFrame, left=3, right=3):
    """
    Smart-money style structure: break of structure (BOS) against confirmed swings.

    Returns (bos_direction, swing_high, swing_low) where bos_direction holds +1
    after a bullish break, -1 after a bearish break, carried forward until the
    opposite break occurs.
    """
    sh, sl_, _, _ = swing_levels(df["High"], df["Low"], left, right)
    bull_bos = (df["Close"] > sh) & sh.notna()
    bear_bos = (df["Close"] < sl_) & sl_.notna()
    raw = pd.Series(np.where(bull_bos, 1, np.where(bear_bos, -1, np.nan)), index=df.index)
    return raw.ffill().fillna(0).astype(int).rename("BOS"), sh, sl_



# =============================================================================
# SECTION 2b -- EXTENDED INDICATOR LIBRARY
# =============================================================================
# Everything here is written from the published definition in plain pandas and
# numpy. No indicator package is imported anywhere in this application, so each
# formula below is auditable against its own source rather than taken on trust.
#
# Smoothing conventions follow the originals: Wilder's smoothing (rma) where
# the author specified it, a simple mean where they specified that. Getting
# this wrong is the usual reason a "14-period RSI" disagrees with a chart.


def wma(series: pd.Series, length: int) -> pd.Series:
    """Linearly weighted moving average: the newest bar carries weight `length`."""
    length = max(int(length), 1)
    weights = np.arange(1, length + 1, dtype=float)
    return series.rolling(length).apply(
        lambda w: float(np.dot(w, weights) / weights.sum()), raw=True)


def hma(series: pd.Series, length: int) -> pd.Series:
    """Hull moving average: fast and smooth, at the cost of overshoot."""
    length = max(int(length), 2)
    half, root = max(length // 2, 1), max(int(round(math.sqrt(length))), 1)
    return wma(2.0 * wma(series, half) - wma(series, length), root)


def dema(series: pd.Series, length: int) -> pd.Series:
    """Double EMA: 2*EMA - EMA(EMA), which removes much of the EMA's lag."""
    first = ema(series, length)
    return 2.0 * first - ema(first, length)


def tema(series: pd.Series, length: int) -> pd.Series:
    """Triple EMA."""
    e1 = ema(series, length)
    e2 = ema(e1, length)
    return 3.0 * e1 - 3.0 * e2 + ema(e2, length)


def kama(series: pd.Series, length: int = 10, fast: int = 2, slow: int = 30) -> pd.Series:
    """
    Kaufman's adaptive moving average.

    Speeds up when price is trending and slows down when it is noisy, via an
    efficiency ratio: net movement over total movement across the window.
    """
    length = max(int(length), 1)
    values = series.astype(float).to_numpy()
    change = np.abs(values - np.roll(values, length))
    volatility = pd.Series(np.abs(np.diff(values, prepend=values[0]))).rolling(
        length).sum().to_numpy()
    with np.errstate(divide="ignore", invalid="ignore"):
        er = np.where(volatility > 0, change / volatility, 0.0)
    fast_sc, slow_sc = 2.0 / (fast + 1.0), 2.0 / (slow + 1.0)
    sc = (er * (fast_sc - slow_sc) + slow_sc) ** 2
    out = np.full(len(values), np.nan)
    seed = length
    if len(values) > seed:
        out[seed] = values[:seed + 1].mean()
        for i in range(seed + 1, len(values)):
            previous = out[i - 1]
            factor = sc[i] if np.isfinite(sc[i]) else 0.0
            out[i] = previous + factor * (values[i] - previous)
    return pd.Series(out, index=series.index)


def vwma(close: pd.Series, volume: pd.Series, length: int) -> pd.Series:
    """Volume-weighted moving average. Degrades to an SMA on a zero-volume feed."""
    length = max(int(length), 1)
    vol = volume.fillna(0.0)
    numerator = (close * vol).rolling(length).sum()
    denominator = vol.rolling(length).sum()
    out = numerator / denominator.replace(0.0, np.nan)
    return out.fillna(sma(close, length))


def stochastic(high, low, close, k_len: int = 14, d_len: int = 3, smooth: int = 3):
    """Stochastic oscillator. Returns (%K, %D), both 0-100."""
    hh = high.rolling(int(k_len)).max()
    ll = low.rolling(int(k_len)).min()
    span = (hh - ll).replace(0.0, np.nan)
    raw = 100.0 * (close - ll) / span
    k = raw.rolling(max(int(smooth), 1)).mean()
    return k, k.rolling(max(int(d_len), 1)).mean()


def stoch_rsi(close: pd.Series, rsi_len: int = 14, stoch_len: int = 14,
              k_len: int = 3, d_len: int = 3):
    """The stochastic of the RSI, which reacts far sooner than either alone."""
    r = rsi(close, rsi_len)
    ll = r.rolling(int(stoch_len)).min()
    hh = r.rolling(int(stoch_len)).max()
    span = (hh - ll).replace(0.0, np.nan)
    raw = 100.0 * (r - ll) / span
    k = raw.rolling(max(int(k_len), 1)).mean()
    return k, k.rolling(max(int(d_len), 1)).mean()


def cci(high, low, close, length: int = 20) -> pd.Series:
    """Commodity Channel Index, on the 0.015 scaling Lambert defined."""
    tp = (high + low + close) / 3.0
    mean = tp.rolling(int(length)).mean()
    deviation = tp.rolling(int(length)).apply(
        lambda w: float(np.mean(np.abs(w - w.mean()))), raw=True)
    return (tp - mean) / (0.015 * deviation.replace(0.0, np.nan))


def williams_r(high, low, close, length: int = 14) -> pd.Series:
    """Williams %R: 0 at the top of the range, -100 at the bottom."""
    hh = high.rolling(int(length)).max()
    ll = low.rolling(int(length)).min()
    return -100.0 * (hh - close) / (hh - ll).replace(0.0, np.nan)


def roc(series: pd.Series, length: int = 12) -> pd.Series:
    """Rate of change, in percent."""
    return (series / series.shift(int(length)) - 1.0) * 100.0


def momentum(series: pd.Series, length: int = 10) -> pd.Series:
    return series - series.shift(int(length))


def tsi(close: pd.Series, long_len: int = 25, short_len: int = 13) -> pd.Series:
    """True Strength Index: doubly smoothed momentum over doubly smoothed range."""
    diff = close.diff()
    smoothed = ema(ema(diff, long_len), short_len)
    absolute = ema(ema(diff.abs(), long_len), short_len)
    return 100.0 * smoothed / absolute.replace(0.0, np.nan)


def ultimate_oscillator(high, low, close, short=7, medium=14, long=28) -> pd.Series:
    """Williams' Ultimate Oscillator, weighted 4:2:1 across three windows."""
    prior = close.shift(1)
    buying = close - pd.concat([low, prior], axis=1).min(axis=1)
    tr = true_range(high, low, close)
    def avg(n):
        return buying.rolling(int(n)).sum() / tr.rolling(int(n)).sum().replace(0.0, np.nan)
    return 100.0 * (4 * avg(short) + 2 * avg(medium) + avg(long)) / 7.0


def awesome_oscillator(high, low, fast=5, slow=34) -> pd.Series:
    median = (high + low) / 2.0
    return sma(median, fast) - sma(median, slow)


def cmo(close: pd.Series, length: int = 14) -> pd.Series:
    """Chande Momentum Oscillator, -100 to +100."""
    diff = close.diff()
    up = diff.clip(lower=0.0).rolling(int(length)).sum()
    down = (-diff.clip(upper=0.0)).rolling(int(length)).sum()
    return 100.0 * (up - down) / (up + down).replace(0.0, np.nan)


def aroon(high, low, length: int = 25):
    """Aroon up and down: how recently the window's extreme was set."""
    n = int(length)
    up = high.rolling(n + 1).apply(lambda w: float(np.argmax(w)) / n * 100.0, raw=True)
    down = low.rolling(n + 1).apply(lambda w: float(np.argmin(w)) / n * 100.0, raw=True)
    return up, down


def vortex(high, low, close, length: int = 14):
    """Vortex indicator. Returns (VI+, VI-)."""
    vm_plus = (high - low.shift(1)).abs()
    vm_minus = (low - high.shift(1)).abs()
    tr_sum = true_range(high, low, close).rolling(int(length)).sum().replace(0.0, np.nan)
    return (vm_plus.rolling(int(length)).sum() / tr_sum,
            vm_minus.rolling(int(length)).sum() / tr_sum)


def psar(high, low, step: float = 0.02, cap: float = 0.2):
    """
    Parabolic SAR, iterated exactly as Wilder specified.

    Returns (sar, is_long). Vectorising this is not possible: each bar's stop
    depends on the extreme point and acceleration factor carried from the last.
    """
    h, l = high.to_numpy(float), low.to_numpy(float)
    n = len(h)
    sar = np.full(n, np.nan)
    bull = np.zeros(n, dtype=bool)
    if n < 2:
        return pd.Series(sar, index=high.index), pd.Series(bull, index=high.index)
    long_now = True
    af = float(step)
    ep = h[0]
    sar[0] = l[0]
    for i in range(1, n):
        prior = sar[i - 1]
        value = prior + af * (ep - prior)
        if long_now:
            value = min(value, l[i - 1], l[max(i - 2, 0)])
            if l[i] < value:                       # flip to short
                long_now, value, ep, af = False, ep, l[i], float(step)
            elif h[i] > ep:
                ep, af = h[i], min(af + step, cap)
        else:
            value = max(value, h[i - 1], h[max(i - 2, 0)])
            if h[i] > value:                       # flip to long
                long_now, value, ep, af = True, ep, h[i], float(step)
            elif l[i] < ep:
                ep, af = l[i], min(af + step, cap)
        sar[i], bull[i] = value, long_now
    return pd.Series(sar, index=high.index), pd.Series(bull, index=high.index)


def trix(close: pd.Series, length: int = 15) -> pd.Series:
    """Percent rate of change of a triple-smoothed EMA."""
    smoothed = ema(ema(ema(close, length), length), length)
    return smoothed.pct_change() * 100.0


def keltner(high, low, close, length: int = 20, mult: float = 2.0):
    """Keltner channels: an EMA basis with ATR-scaled bands."""
    basis = ema(close, length)
    width = atr(high, low, close, length) * float(mult)
    return basis + width, basis, basis - width


def donchian(high, low, length: int = 20):
    """Donchian channel over the PRIOR `length` bars, excluding this one."""
    return (rolling_high(high, int(length), True), rolling_low(low, int(length), True))


def choppiness(high, low, close, length: int = 14) -> pd.Series:
    """
    Choppiness Index, 0-100. Above ~61 the market is ranging, below ~38 trending.
    """
    n = int(length)
    tr_sum = true_range(high, low, close).rolling(n).sum()
    span = (high.rolling(n).max() - low.rolling(n).min()).replace(0.0, np.nan)
    with np.errstate(divide="ignore", invalid="ignore"):
        return 100.0 * np.log10(tr_sum / span) / math.log10(max(n, 2))


def obv(close: pd.Series, volume: pd.Series) -> pd.Series:
    """On-balance volume."""
    direction = np.sign(close.diff().fillna(0.0))
    return (direction * volume.fillna(0.0)).cumsum()


def money_flow_index(high, low, close, volume, length: int = 14) -> pd.Series:
    """MFI: an RSI weighted by money flow rather than price alone."""
    tp = (high + low + close) / 3.0
    flow = tp * volume.fillna(0.0)
    up = flow.where(tp > tp.shift(1), 0.0).rolling(int(length)).sum()
    down = flow.where(tp < tp.shift(1), 0.0).rolling(int(length)).sum()
    return 100.0 - 100.0 / (1.0 + up / down.replace(0.0, np.nan))


def _money_flow_volume(high, low, close, volume) -> pd.Series:
    span = (high - low).replace(0.0, np.nan)
    return ((close - low) - (high - close)) / span * volume.fillna(0.0)


def chaikin_money_flow(high, low, close, volume, length: int = 20) -> pd.Series:
    mfv = _money_flow_volume(high, low, close, volume)
    return mfv.rolling(int(length)).sum() / \
        volume.fillna(0.0).rolling(int(length)).sum().replace(0.0, np.nan)


def accumulation_distribution(high, low, close, volume) -> pd.Series:
    return _money_flow_volume(high, low, close, volume).fillna(0.0).cumsum()


def force_index(close: pd.Series, volume: pd.Series, length: int = 13) -> pd.Series:
    return ema(close.diff() * volume.fillna(0.0), length)


def ease_of_movement(high, low, volume, length: int = 14) -> pd.Series:
    midpoint = ((high + low) / 2.0).diff()
    box = volume.fillna(0.0).replace(0.0, np.nan) / (high - low).replace(0.0, np.nan)
    return (midpoint / box).rolling(int(length)).mean()


def price_volume_trend(close: pd.Series, volume: pd.Series) -> pd.Series:
    return (close.pct_change().fillna(0.0) * volume.fillna(0.0)).cumsum()


def volume_oscillator(volume: pd.Series, fast: int = 5, slow: int = 20) -> pd.Series:
    quick, slow_mean = sma(volume, fast), sma(volume, slow)
    return (quick - slow_mean) / slow_mean.replace(0.0, np.nan) * 100.0


def ichimoku(high, low, close, conversion: int = 9, base: int = 26, span_b: int = 52):
    """
    Ichimoku. Returns (tenkan, kijun, senkou_a, senkou_b).

    The spans are deliberately NOT shifted forward here. Plotting shifts them
    into the future; a screener must compare today's price with values derived
    from data that already exists, and shifting first then reading the last row
    is how an Ichimoku screen quietly acquires look-ahead.
    """
    def mid(n):
        return (high.rolling(int(n)).max() + low.rolling(int(n)).min()) / 2.0
    tenkan, kijun = mid(conversion), mid(base)
    return tenkan, kijun, (tenkan + kijun) / 2.0, mid(span_b)


def heikin_ashi(df: pd.DataFrame) -> pd.DataFrame:
    """Heikin Ashi candles, built recursively as the method requires."""
    ha_close = (df["Open"] + df["High"] + df["Low"] + df["Close"]) / 4.0
    opens = np.full(len(df), np.nan)
    o, c = df["Open"].to_numpy(float), ha_close.to_numpy(float)
    if len(df):
        opens[0] = (o[0] + c[0]) / 2.0
        for i in range(1, len(df)):
            opens[i] = (opens[i - 1] + c[i - 1]) / 2.0
    ha_open = pd.Series(opens, index=df.index)
    return pd.DataFrame({
        "ha_open": ha_open, "ha_close": ha_close,
        "ha_high": pd.concat([df["High"], ha_open, ha_close], axis=1).max(axis=1),
        "ha_low": pd.concat([df["Low"], ha_open, ha_close], axis=1).min(axis=1)})


def dpo(close: pd.Series, length: int = 20) -> pd.Series:
    """Detrended price oscillator."""
    shift = int(length) // 2 + 1
    return close.shift(shift) - sma(close, length)


def coppock(close: pd.Series, long_roc: int = 14, short_roc: int = 11,
            smooth: int = 10) -> pd.Series:
    return wma(roc(close, long_roc) + roc(close, short_roc), smooth)


def elder_ray(high, low, close, length: int = 13):
    """Bull power and bear power around an EMA."""
    basis = ema(close, length)
    return high - basis, low - basis


def kst(close: pd.Series) -> tuple:
    """Pring's Know Sure Thing, on his published default periods."""
    parts = [(10, 10), (15, 10), (20, 10), (30, 15)]
    total = None
    for i, (r, s) in enumerate(parts, start=1):
        component = sma(roc(close, r), s) * i
        total = component if total is None else total + component
    return total, sma(total, 9)


def mass_index(high, low, length: int = 9, total: int = 25) -> pd.Series:
    span = high - low
    ratio = ema(span, length) / ema(ema(span, length), length).replace(0.0, np.nan)
    return ratio.rolling(int(total)).sum()


def relative_vigor_index(df: pd.DataFrame, length: int = 10):
    """RVI: where the close sits in the bar, smoothed. Returns (rvi, signal)."""
    numerator = (df["Close"] - df["Open"]).rolling(int(length)).mean()
    denominator = (df["High"] - df["Low"]).rolling(int(length)).mean()
    value = numerator / denominator.replace(0.0, np.nan)
    return value, value.rolling(4).mean()


def balance_of_power(df: pd.DataFrame, length: int = 14) -> pd.Series:
    raw = (df["Close"] - df["Open"]) / (df["High"] - df["Low"]).replace(0.0, np.nan)
    return raw.rolling(int(length)).mean()


def fisher_transform(high, low, length: int = 9):
    """
    Ehlers' Fisher transform. Returns (fisher, trigger).

    The transform needs its input strictly inside -1 and 1, so the normalised
    price is clipped just short of both: at exactly +/-1 the logarithm diverges.
    """
    median = (high + low) / 2.0
    hh = median.rolling(int(length)).max()
    ll = median.rolling(int(length)).min()
    span = (hh - ll).replace(0.0, np.nan)
    raw = (2.0 * (median - ll) / span - 1.0).clip(-0.999, 0.999)
    smoothed = raw.ewm(alpha=0.33, adjust=False).mean().clip(-0.999, 0.999)
    value = 0.5 * np.log((1.0 + smoothed) / (1.0 - smoothed))
    value = value.ewm(alpha=0.5, adjust=False).mean()
    return value, value.shift(1)


def classic_pivots(df: pd.DataFrame) -> dict:
    """Classic floor-trader pivots from the PREVIOUS session."""
    sessions = session_key(df.index)
    unique = list(dict.fromkeys(sessions.tolist()))
    if len(unique) < 2:
        return {}
    prior = df[sessions == unique[-2]]
    if prior.empty:
        return {}
    high, low = float(prior["High"].max()), float(prior["Low"].min())
    close = float(prior["Close"].iloc[-1])
    pivot = (high + low + close) / 3.0
    return {"P": pivot, "R1": 2 * pivot - low, "S1": 2 * pivot - high,
            "R2": pivot + (high - low), "S2": pivot - (high - low),
            "R3": high + 2 * (pivot - low), "S3": low - 2 * (high - pivot)}


# =============================================================================
# SECTION 3 -- MARKET DATA  (the single rate-limit-guarded network choke-point)
# =============================================================================
OHLCV = ["Open", "High", "Low", "Close", "Volume"]


class MarketDataError(RuntimeError):
    """Raised when usable OHLCV data could not be assembled."""


@dataclass
class DataBundle:
    frame: pd.DataFrame
    symbol: str
    interval: str
    period: str
    warnings: list[str] = field(default_factory=list)

    @property
    def bars(self) -> int:
        return len(self.frame)


def _raw_download(symbol: str, period: str, interval: str) -> pd.DataFrame:
    """
    The ONE and ONLY call site for yfinance in this file.

    A hard 0.3s pause is taken before the request and again after it, in a
    finally block so the post-guard runs even when the request raises. Keeping
    this to a single function is what makes the guarantee auditable.
    """
    import yfinance as yf

    time.sleep(API_GUARD_DELAY)                      # ---- mandatory pre-guard ----
    try:
        return yf.download(tickers=symbol, period=period, interval=interval,
                           auto_adjust=False, actions=False, progress=False,
                           threads=False, group_by="column")
    except Exception as exc:                          # noqa: BLE001
        raise MarketDataError(f"Download failed for {symbol} [{interval}/{period}]: {exc}") from exc
    finally:
        time.sleep(API_GUARD_DELAY)                   # ---- mandatory post-guard ----


def _normalise(frame: pd.DataFrame, symbol: str) -> pd.DataFrame:
    if frame is None or frame.empty:
        raise MarketDataError(f"Yahoo returned an empty frame for `{symbol}`.")
    df = frame.copy()
    if isinstance(df.columns, pd.MultiIndex):
        lvl0 = set(df.columns.get_level_values(0))
        df.columns = (df.columns.get_level_values(0) if {"Open", "Close"} & lvl0
                      else df.columns.get_level_values(1))
    df = df.loc[:, ~df.columns.duplicated()]
    missing = [c for c in ["Open", "High", "Low", "Close"] if c not in df.columns]
    if missing:
        raise MarketDataError(f"`{symbol}` response is missing columns: {missing}")
    if "Volume" not in df.columns:
        df["Volume"] = 0.0
    df = df[OHLCV].astype(float)
    df.index = pd.to_datetime(df.index)
    df = df[~df.index.duplicated(keep="last")].sort_index()
    df = df.dropna(subset=["Open", "High", "Low", "Close"])
    df["Volume"] = df["Volume"].fillna(0.0)
    df = df[(df[["Open", "High", "Low", "Close"]] > 0).all(axis=1)]
    # High/Low sanity: Yahoo occasionally emits an inverted bar.
    df["High"] = df[["High", "Open", "Close"]].max(axis=1)
    df["Low"] = df[["Low", "Open", "Close"]].min(axis=1)
    return df


def _resample(df: pd.DataFrame, rule: str) -> pd.DataFrame:
    agg = {"Open": "first", "High": "max", "Low": "min", "Close": "last", "Volume": "sum"}
    out = df.resample(rule, label="left", closed="left", origin="start_day").agg(agg)
    return out.dropna(subset=["Open", "High", "Low", "Close"])


def _fetch_uncached(symbol: str, period: str, interval: str) -> pd.DataFrame:
    if interval in NATIVE_INTERVALS:
        return _normalise(_raw_download(symbol, period, interval), symbol)
    src, rule = DERIVED_INTERVALS[interval]
    # 3m/10m/4h are not served natively; resample them from a finer native feed.
    return _resample(_normalise(_raw_download(symbol, period, src), symbol), rule)


def _cached_fetch(symbol: str, period: str, interval: str, bucket: int) -> pd.DataFrame:
    """Streamlit-cached wrapper; `bucket` is the caller's freshness key."""
    if st is None:
        return _fetch_uncached(symbol, period, interval)
    if not hasattr(_cached_fetch, "_impl"):
        @st.cache_data(show_spinner=False, max_entries=96)
        def _impl(sym, per, itv, _b):
            return _fetch_uncached(sym, per, itv)
        _cached_fetch._impl = _impl
    return _cached_fetch._impl(symbol, period, interval, bucket)


def load_market_data(symbol: str, period: str, interval: str,
                     freshness_seconds: float = 300.0,
                     min_bars: int = ABSOLUTE_MIN_BARS) -> DataBundle:
    """Fetch, clean, resample and validate an OHLCV series."""
    symbol = (symbol or "").strip().upper()
    if not symbol:
        raise MarketDataError("No symbol supplied.")
    warnings: list[str] = []
    eff_period, clamp = sanitize_period(interval, period)
    if clamp:
        warnings.append(clamp)

    bucket = int(time.time() // max(0.3, float(freshness_seconds)))
    frame = _cached_fetch(symbol, eff_period, interval, bucket)

    if frame.empty:
        raise MarketDataError(
            f"No candles returned for `{symbol}` at {interval}/{eff_period}. The symbol "
            "may be wrong, delisted, or outside its trading calendar.")
    if len(frame) < min_bars:
        raise MarketDataError(
            f"Only {len(frame)} candles available for `{symbol}` at {interval}/{eff_period}; "
            f"at least {min_bars} are required. Widen the period or use a coarser interval.")
    if float(frame["Volume"].abs().sum()) == 0.0:
        warnings.append("This instrument reports zero volume on Yahoo (normal for indices and "
                        "spot FX). Volume-gated strategies and filters will not arm; VWAP "
                        "falls back to a session TWAP.")
    return DataBundle(frame=frame, symbol=symbol, interval=interval,
                      period=eff_period, warnings=warnings)


_LAST_QUOTE_CALL = {"t": 0.0}


def _space_quote_requests(min_gap: float = API_GUARD_DELAY) -> None:
    """
    Enforce the mandatory gap BETWEEN quote requests without double-sleeping.

    The heavy candle download brackets itself with 0.3s on each side. The quote
    path is hit on every tick, so it instead guarantees a 0.3s spacing measured
    from the previous call: same protection, but it does not burn 0.6s of every
    tick doing nothing.
    """
    gap = time.time() - _LAST_QUOTE_CALL["t"]
    if gap < min_gap:
        time.sleep(min_gap - gap)
    _LAST_QUOTE_CALL["t"] = time.time()


def yahoo_ltp(symbol: str) -> float | None:
    """
    Last traded price from Yahoo's QUOTE endpoint, not from a candle close.

    This is the difference between a price that moves and one that steps once
    per candle. The quote stream updates continuously; a 5m candle's close only
    changes when the candle rolls. (Yahoo's Indian quotes still carry an
    exchange delay, but they tick within that delay instead of freezing.)
    """
    import yfinance as yf

    _space_quote_requests()
    try:
        ticker = yf.Ticker(symbol)
        fast = getattr(ticker, "fast_info", None)
        for probe in ("last_price", "lastPrice", "regular_market_price", "regularMarketPrice"):
            value = None
            if fast is not None:
                value = getattr(fast, probe, None)
                if value is None:
                    try:
                        value = fast[probe]
                    except Exception:                               # noqa: BLE001
                        value = None
            if value is not None:
                price = float(value)
                if np.isfinite(price) and price > 0:
                    return price
    except Exception:                                               # noqa: BLE001
        pass
    # Last resort: the freshest 1-minute candle available.
    try:
        _space_quote_requests()
        hist = yf.Ticker(symbol).history(period="1d", interval="1m")
        if hist is not None and not hist.empty:
            price = float(hist["Close"].dropna().iloc[-1])
            if np.isfinite(price) and price > 0:
                return price
    except Exception:                                               # noqa: BLE001
        pass
    return None


def load_vix(freshness_seconds: float = 60.0) -> float | None:
    """Latest India VIX close, or None if unavailable. Never raises."""
    try:
        b = load_market_data(VIX_SYMBOL, "5d", "15m", freshness_seconds, min_bars=1)
        return float(b.frame["Close"].iloc[-1])
    except Exception:                                  # noqa: BLE001
        return None


def live_period_for(interval: str, needed_bars: int = WARMUP_BARS + 120) -> str:
    """
    Smallest period that still satisfies the warm-up requirement.

    Re-pulling `max` history on every poll is exactly how an IP gets throttled.
    """
    per_day = APPROX_BARS_PER_DAY.get(interval, 1.0)
    needed_days = needed_bars / max(per_day, 0.001)
    for p in PERIODS:
        if p != "max" and PERIOD_DAYS[p] >= needed_days * 1.6:
            return p
    return "max"


def gap_profile(df: pd.DataFrame, threshold_pct: float = 0.3) -> pd.DataFrame:
    pc = df["Close"].shift(1)
    gap = (df["Open"] - pc) / pc * 100.0
    out = df.loc[gap.abs() >= threshold_pct, ["Open", "Close"]].copy()
    out["gap_pct"] = gap.loc[out.index].round(3)
    out["direction"] = np.where(out["gap_pct"] > 0, "Gap Up", "Gap Down")
    return out


# =============================================================================
# SECTION 4 -- ADDITIONAL ENTRY FILTERS
# =============================================================================
# Every filter is OFF by default. An enabled filter must agree with the trade
# direction or the signal is discarded. Filters never create signals of their
# own -- they only veto.
#
# DATA HONESTY: PCR, open-interest change and news have no free feed wired in.
# They are exposed as manual inputs plus a hook so a user with their own source
# can plug it in. Left untouched they are inert and say so in the UI rather than
# silently passing or silently blocking.

