def init_state() -> None:
    for k, v in _STATE_DEFAULTS.items():
        if k not in st.session_state:
            st.session_state[k] = list(v) if isinstance(v, list) else v


def log_event(message: str, level: str = "info") -> None:
    # Logging is never important enough to break the caller: outside a Streamlit
    # session (tests, scripts) there is no state to write to.
    if st is None:
        return
    try:
        st.session_state.live_events
    except Exception:                                               # noqa: BLE001
        return
    st.session_state.live_events.insert(
        0, {"time": pd.Timestamp.now().strftime("%H:%M:%S"), "level": level, "message": message})
    del st.session_state.live_events[300:]


def entry_trace(verdict: str, detail: str, *, when=None, ago=None, direction: int = 0) -> None:
    """
    Record what this poll decided about entering, and why.

    "It did not enter and I do not know why" is unanswerable without this. The
    event feed only ever carried the interesting moments, so a signal that was
    quietly passed over left no trace at all -- and a silent pass is exactly the
    failure that matters. Every poll now files a verdict, and repeated identical
    verdicts are counted rather than repeated, so the trace stays readable at
    one poll per second.
    """
    if st is None:
        return
    try:
        log = st.session_state.setdefault("entry_trace", [])
    except Exception:                                               # noqa: BLE001
        return
    stamp = fmt_time(when) if when is not None else "-"
    side = "LONG" if direction > 0 else ("SHORT" if direction < 0 else "-")
    if log and log[0]["Verdict"] == verdict and log[0]["Signal bar"] == stamp:
        log[0]["Polls"] = int(log[0].get("Polls", 1)) + 1
        log[0]["Last seen"] = pd.Timestamp.now().strftime("%H:%M:%S")
        return
    log.insert(0, {"First seen": pd.Timestamp.now().strftime("%H:%M:%S"),
                   "Last seen": pd.Timestamp.now().strftime("%H:%M:%S"),
                   "Signal bar": stamp, "Side": side,
                   "Bars ago": "-" if ago is None else int(ago),
                   "Verdict": verdict, "Why": detail, "Polls": 1})
    del log[300:]


def record_live_trade(trade: dict) -> None:
    """
    The ONLY writer to the live ledger.

    Backtest output lives in a different session key and has no code path here,
    so Tab 3 cannot be contaminated by simulated fills.
    """
    trade = dict(trade)
    trade["Source"] = "LIVE"
    st.session_state.live_trades.append(trade)


def live_pnl_today() -> float:
    """Realised PnL from live trades closed today, for the daily guards."""
    rows = st.session_state.get("live_trades", []) if st is not None else []
    if not rows:
        return 0.0
    today = pd.Timestamp.now().normalize()
    total = 0.0
    for row in rows:
        try:
            if pd.Timestamp(row.get("Exit Time")).normalize() == today:
                total += float(row.get("PnL", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
    return float(total)


def live_ledger_frame() -> pd.DataFrame:
    rows = st.session_state.get("live_trades", [])
    if not rows:
        return pd.DataFrame()
    frame = pd.DataFrame(rows)
    if "Exit Time" in frame.columns:
        frame = frame.sort_values("Exit Time").reset_index(drop=True)
    frame.insert(0, "#", range(1, len(frame) + 1))
    return frame


def reset_live_runtime() -> None:
    st.session_state.live_position = None
    st.session_state.live_last_bar = None
    st.session_state.live_last_signal_time = None
    st.session_state.live_snapshot = None
    st.session_state.live_error = None
    st.session_state.live_poll_count = 0
    st.session_state.live_frame = None
    st.session_state.live_frame_at = 0.0
    st.session_state.candle_refreshes = 0
    st.session_state.feed_log = []
    st.session_state.last_seen_ltp = None
    st.session_state.last_ltp_change_ts = 0.0
    st.session_state.live_fail_streak = 0
    st.session_state.live_backoff_until = 0.0
    st.session_state.held_signal_polls = 0
    st.session_state.entry_trace = []
    st.session_state.newest_bar_seen = None
    st.session_state.newest_bar_advanced_ts = 0.0
    st.session_state.bars_added_last_refresh = 0


# =============================================================================
# SECTION 10 -- LIVE ENGINE
# =============================================================================
# Signal on the close of candle N -> entry at the OPEN of candle N+1, which is
# already printed and therefore immediately actionable. Stop and target are then
# evaluated against the LTP on every poll, stop first.


@dataclass
class LiveSnapshot:
    frame: pd.DataFrame
    ltp: float
    next_open: float
    last_closed_time: Any
    last_closed_signal: int
    raw_signal: int
    status: StatusReport
    filter_reports: list
    fetched_at: pd.Timestamp
    bars: int
    data_warnings: list[str]
    vix: float | None = None
    feed_age_seconds: float = 0.0
    stale: bool = False                     # candles are lagging (signals may be old)
    quote_live: bool = True                 # the PRICE is moving (the venue is open)
    closed_index: int = -2                  # position of the last FULLY CLOSED candle
    last_is_forming: bool = True            # is the newest row still being built?
    recent_signal: int = 0                  # most recent signal on ANY closed candle
    recent_signal_time: Any = None
    recent_signal_bars_ago: int | None = None
    ltp_source: str = "Yahoo (delayed candle close)"

    @property
    def frozen(self) -> bool:
        """Truly dead: candles lagging AND the price is not moving either."""
        return self.stale and not self.quote_live


def refresh_candles(cfg: dict):
    """
    The HEAVY leg: download candles and recompute indicators, signals, filters.

    Runs on its own slower cadence. Recomputing 200+ bars of indicators on every
    0.3s tick would be pointless work -- the candles simply have not changed.
    """
    strat = get_strategy(cfg["strategy"])
    bundle = load_market_data(symbol=cfg["symbol"], period=live_period_for(cfg["interval"]),
                              interval=cfg["interval"],
                              freshness_seconds=max(1.0, cfg.get("candle_seconds", 15.0) * 0.9),
                              min_bars=max(strat.min_bars, 30))
    extras = dict(cfg.get("filter_extras") or {})
    if cfg.get("filter_cfg", {}).get("vix", {}).get("enabled"):
        extras["vix"] = load_vix(freshness_seconds=60)
    if str(cfg.get("strategy", "")).startswith("50 "):
        broker = cfg.get("broker") or {}
        if broker.get("contract"):
            st.session_state.order_book = dhan_depth(broker, broker["contract"])

    frame, reports = prepare(bundle.frame, cfg["strategy"], cfg["params"],
                             cfg.get("filter_cfg"), extras)
    if len(frame) < 3:
        raise MarketDataError("Not enough candles to evaluate a live signal.")
    return frame, reports, bundle.warnings, extras.get("vix")


def fetch_live_ltp(cfg: dict, frame: pd.DataFrame) -> tuple[float, str]:
    """
    The LIGHT leg: one price, fetched on every tick.

    Order of preference: Dhan real-time quote, then Yahoo's quote endpoint,
    then -- only if both fail -- the newest candle close, which is the value
    that cannot move between candles.
    """
    broker = cfg.get("broker") or {}
    if broker.get("use_live_ltp") and broker.get("contract"):
        try:
            price = dhan_ltp(broker, broker["contract"])
            if price and np.isfinite(price) and price > 0:
                return float(price), "Dhan (real-time quote)"
        except BrokerError as exc:
            st.session_state.ltp_note = f"Dhan LTP failed, using Yahoo: {exc}"

    price = yahoo_ltp(cfg["symbol"])
    if price is not None:
        st.session_state.last_good_quote = (float(price), time.time())
        return float(price), "Yahoo quote (ticks continuously)"

    # Falling back to the candle close on a single failed quote call makes the
    # price flip between the live quote and a stale close on alternate ticks --
    # a sawtooth that looks like market movement but is pure feed artefact, and
    # one that can trip a trailing stop. Hold the last good quote instead.
    cached = st.session_state.get("last_good_quote")
    if cached:
        px, when = cached
        age = time.time() - float(when)
        if age <= 120:
            return float(px), f"Last good quote ({age:0.0f}s old — quote call failed)"
    return float(frame["Close"].iloc[-1]), "Candle close (no quote available)"


def build_snapshot(cfg: dict, frame: pd.DataFrame, reports, warnings, vix,
                   ltp: float, ltp_source: str) -> LiveSnapshot:
    strat = get_strategy(cfg["strategy"])
    last_ts = pd.Timestamp(frame.index[-1])
    now = pd.Timestamp.now(tz=last_ts.tz) if last_ts.tz is not None else pd.Timestamp.now()
    age = float((now - last_ts).total_seconds())
    bar_seconds = INTERVAL_SECONDS.get(cfg["interval"], 300)

    # Is the newest row still being built, or did it finish long ago?
    #
    # Assuming the last row is always the forming candle is wrong the moment the
    # feed lags. On a delayed feed a "5m" candle can be hours old, in which case
    # it is FINISHED, and treating it as unfinished throws away a real closed
    # candle's signal and leaves the engine permanently one candle behind.
    last_is_forming = age < bar_seconds
    closed = -2 if last_is_forming else -1
    closed_pos = len(frame) + closed

    # There is only a "next candle open" while a next candle actually exists. If
    # the newest row has already closed, no later candle has opened yet, and any
    # number printed here would be the open of a candle that finished hours ago.
    next_open = float(frame["Open"].iloc[-1]) if last_is_forming else float("nan")
    # Candles lagging by more than three bars. On a delayed feed this is routine
    # DURING market hours, so on its own it proves nothing about the venue.
    stale = age > max(3 * bar_seconds, 120)

    # Whether the venue is open is a question about the PRICE, not the candles.
    # The only trustworthy evidence is OBSERVED MOVEMENT: a closed exchange still
    # serves a quote, and that quote will differ from the last intraday candle
    # close (official close vs candle close), so "the numbers differ" proves
    # nothing. We therefore watch for the price actually changing.
    now_t = time.time()
    prev_ltp = st.session_state.get("last_seen_ltp")
    if prev_ltp is not None and abs(float(prev_ltp) - ltp) > 1e-9:
        st.session_state.last_ltp_change_ts = now_t
    st.session_state.last_seen_ltp = ltp

    since_change = now_t - float(st.session_state.get("last_ltp_change_ts", 0.0))
    observed_ticks = int(st.session_state.get("live_poll_count", 0))

    # A SECOND, independent proof that the venue is open: new candles keep
    # arriving. Yahoo serves many index quotes from a cache that only refreshes
    # on candle boundaries, so waiting for the quote to tick can wait forever on
    # a market that is plainly trading -- and the whole engine was gated on that
    # one signal. A newest-bar timestamp that keeps advancing cannot happen on a
    # closed exchange, so it is treated as evidence in its own right.
    seen_bar = st.session_state.get("newest_bar_seen")
    if seen_bar is None or pd.Timestamp(seen_bar) != last_ts:
        st.session_state.newest_bar_seen = last_ts
        if seen_bar is not None:
            st.session_state.newest_bar_advanced_ts = now_t
    since_new_bar = now_t - float(st.session_state.get("newest_bar_advanced_ts", 0.0))
    candles_advancing = (st.session_state.get("newest_bar_advanced_ts")
                         and since_new_bar <= max(2.5 * bar_seconds, QUOTE_LIVE_WINDOW))

    if not stale:
        quote_live = True                       # candles are current: the venue is open
    elif candles_advancing:
        quote_live = True                       # bars are still printing: it is trading
    elif observed_ticks < QUOTE_EVIDENCE_TICKS:
        quote_live = False                      # not enough evidence yet -- hold entries
    else:
        quote_live = since_change <= QUOTE_LIVE_WINDOW

    # The screener reports signals from a WINDOW of recent candles, so the live
    # panel must be able to talk about the same thing. Without this the engine
    # can only ever see the newest closed bar, and a signal that fired two bars
    # ago looks like nothing happened at all.
    closed_sig = frame["signal"].iloc[:closed_pos + 1]
    recent = closed_sig[closed_sig != 0]
    r_sig, r_time, r_ago = 0, None, None
    if len(recent):
        r_time = recent.index[-1]
        r_sig = int(recent.iloc[-1])
        r_ago = int(closed_pos - frame.index.get_loc(r_time))

    return LiveSnapshot(
        frame=frame, ltp=ltp, next_open=next_open,
        last_closed_time=frame.index[closed],
        last_closed_signal=int(frame["signal"].iloc[closed]),
        raw_signal=int(frame["raw_signal"].iloc[closed]),
        status=strat.status(frame.iloc[:closed_pos + 1], cfg["params"]),
        filter_reports=reports, fetched_at=pd.Timestamp.now(), bars=len(frame),
        data_warnings=warnings, vix=vix, feed_age_seconds=age, stale=stale,
        quote_live=quote_live, ltp_source=ltp_source,
        closed_index=closed, last_is_forming=last_is_forming,
        recent_signal=r_sig, recent_signal_time=r_time, recent_signal_bars_ago=r_ago)


def _live_close(position: Position, exit_price: float, reason: str) -> dict:
    mgr = position.manager
    points = round((float(exit_price) - position.entry_price) * position.direction, 4)
    trade = {
        "Strategy": position.strategy, "Symbol": position.symbol, "Interval": position.interval,
        "Direction": "LONG" if position.direction > 0 else "SHORT",
        "Quantity": position.quantity,
        "Entry Time": pd.Timestamp(position.entry_time),
        "Entry Price": round(position.entry_price, 4),
        "Exit Time": pd.Timestamp.now(), "Exit Price": round(float(exit_price), 4),
        "Initial Stop": None if mgr.initial_sl is None else round(mgr.initial_sl, 4),
        "Final Stop": None if mgr.sl is None else round(mgr.sl, 4),
        "Target": None if mgr.tp is None else round(mgr.tp, 4),
        "Best Price": round(mgr.mfe, 4), "Exit Reason": reason,
        "Points": points, "Gross PnL": round(points * position.quantity, 4),
        "Costs": round(mgr.risk.costs.total(position.entry_price, float(exit_price),
                                            position.quantity), 4),
        "PnL": round(points * position.quantity
                     - mgr.risk.costs.total(position.entry_price, float(exit_price),
                                            position.quantity), 4),
        "Broker Order": position.broker_order_id or "-",
        "Option Leg": position.option_leg or "-",
        **_ohlc_cols("Entry Bar", position.entry_bar),
        **_ohlc_cols("Exit Bar", st.session_state.get("last_closed_bar")),
    }
    record_live_trade(trade)
    return trade


def square_off(reason: str = "Manual Square-Off", price: float | None = None) -> dict | None:
    """Flatten the tracked position, book the PnL, zero the risk."""
    position: Position | None = st.session_state.live_position
    if position is None:
        return None
    if price is None:
        snap = st.session_state.live_snapshot
        price = snap.ltp if snap else position.entry_price

    cfg = st.session_state.live_config or {}
    _maybe_route_broker(cfg, position, closing=True)

    trade = _live_close(position, float(price), reason)
    st.session_state.live_position = None
    db_clear_position()
    db_append_trade(trade)
    err = send_email(cfg, f"EXIT {trade['Direction']} {trade['Symbol']} :: "
                          f"{fmt_signed(trade['PnL'])}",
                     f"Reason: {reason}\nEntry: {fmt(trade['Entry Price'])}\n"
                     f"Exit: {fmt(trade['Exit Price'])}\nPoints: {fmt_signed(trade['Points'])}\n"
                     f"PnL: {fmt_signed(trade['PnL'])}\nTime: {pd.Timestamp.now()}")
    if err:
        log_event(err, "error")
    log_event(f"{reason}: {trade['Direction']} closed at {fmt(trade['Exit Price'])} "
              f"for {fmt_signed(trade['PnL'])} ({fmt_signed(trade['Points'])} pts).",
              "warn" if trade["PnL"] < 0 else "success")
    return trade


def _maybe_route_broker(cfg: dict, position: Position, closing: bool) -> None:
    """Send the entry or exit leg to Dhan, if and only if the operator enabled it."""
    broker = cfg.get("broker") or {}
    if not broker.get("enabled"):
        return
    contract = broker.get("contract")
    if not contract:
        log_event("Broker routing is on but no contract is resolved; order skipped.", "error")
        return
    side = ("SELL" if position.direction > 0 else "BUY") if closing else \
           ("BUY" if position.direction > 0 else "SELL")
    try:
        receipt = place_dhan_order(broker, contract, side, position.quantity,
                                   dry_run=broker.get("dry_run", True))
        st.session_state.broker_receipts.insert(0, {
            "time": pd.Timestamp.now(), "leg": "EXIT" if closing else "ENTRY",
            "side": side, **{k: receipt.get(k) for k in ("status", "order_id", "message")}})
        del st.session_state.broker_receipts[100:]
        if not closing:
            position.broker_order_id = receipt.get("order_id")
        log_event(f"Broker {('EXIT' if closing else 'ENTRY')} {side} -> {receipt['status']}",
                  "info" if receipt["status"] == "DRY_RUN" else "success")
    except BrokerError as exc:
        log_event(f"Broker order FAILED: {exc}", "error")


def closed_pos_of(snapshot: LiveSnapshot) -> int:
    """Positional index of the last fully closed candle in the snapshot frame."""
    return len(snapshot.frame) + int(snapshot.closed_index)


def _live_fill_price(cfg: dict, snapshot: LiveSnapshot, ctx: BarCtx) -> float:
    """
    The price a live order can ACTUALLY get: the current LTP.

    The backtest fills a signal from candle N at the open of candle N+1, because
    when a bar is replayed its open is the first tradable price of that bar.
    Carrying that rule into live trading is wrong and expensive: by the time the
    engine sees the signal, candle N+1 has been forming for a while and its open
    is a price that already happened. Booking it manufactures profit — a trade
    opens showing a gain it never earned, and every live result is inflated by
    however far price drifted since the candle opened.

    The N+1 open is still offered for operators who want the backtest-consistent
    number, but only while it is still close to the live price; past a fraction
    of an ATR it is silently unobtainable, so the LTP wins and the log says so.
    """
    ltp = float(snapshot.ltp)
    if not cfg.get("prefer_candle_open"):
        return ltp

    if not snapshot.last_is_forming:
        return ltp                      # no candle is open; there is no open to use
    open_px = float(snapshot.next_open)
    if not np.isfinite(open_px) or open_px <= 0:
        return ltp
    drift = abs(open_px - ltp)
    tolerance = max(0.25 * ctx.atr if np.isfinite(ctx.atr) else 0.0, ltp * 0.0002)
    if drift <= tolerance:
        return open_px
    log_event(f"Candle-open fill rejected: the N+1 open was {fmt(open_px)} but price is now "
              f"{fmt(ltp)} ({fmt(drift)} away). That open is no longer obtainable, so the fill "
              f"is the live price. Booking the open would have shown "
              f"{fmt(drift)} points of profit the trade never made.", "warn")
    return ltp


def _open_live_position(cfg: dict, direction: int, price: float, ctx: BarCtx, bar_time,
                        levels_from: float | None = None, bars_ago: int | None = None,
                        route: str = "newest closed candle") -> Position:
    """
    Open a tracked position.

    ``levels_from`` anchors the stop and target on a DIFFERENT price from the
    fill. That is what "join the trade with whatever is left" means: the levels
    stay where the original signal put them, while PnL is measured from the
    price you actually got.
    """
    anchor = float(levels_from) if levels_from is not None else float(price)
    mgr = ExitManager(cfg["risk"], anchor, direction, ctx)
    if levels_from is not None:
        mgr.entry = float(price)
        mgr.mfe = float(price)
        mgr.risk_points = abs(float(price) - mgr.sl) if mgr.sl is not None else None
    position = Position(strategy=cfg["strategy"], symbol=cfg["symbol"], interval=cfg["interval"],
                        direction=direction, quantity=cfg["risk"].quantity,
                        entry_price=float(price), entry_time=pd.Timestamp.now(),
                        signal_bar_time=bar_time, manager=mgr,
                        entry_ltp_at_fill=cfg.get("_ltp_at_fill"),
                        entry_bar=_bar_dict(ctx),
                        high_since_entry=float(price), low_since_entry=float(price),
                        signal_bars_ago=bars_ago, entry_route=route,
                        option_leg=("CE" if direction > 0 else "PE")
                        if (cfg.get("broker") or {}).get("instrument") == "OPTIONS" else None)
    st.session_state.live_position = position
    if levels_from is not None:
        remaining = None if mgr.tp is None else abs(mgr.tp - float(price))
        log_event(f"Joined an existing signal: levels kept from the original entry "
                  f"{fmt(anchor)}, filled at {fmt(price)}. Remaining to target: "
                  f"{fmt(remaining)}; risk now {fmt(mgr.risk_points)}.", "warn")
    _maybe_route_broker(cfg, position, closing=False)
    db_save_position(position, cfg)
    err = send_email(cfg, f"ENTRY {'LONG' if direction > 0 else 'SHORT'} {cfg['symbol']} "
                          f"@ {fmt(price)}",
                     f"Strategy: {cfg['strategy']}\nSymbol: {cfg['symbol']} ({cfg['interval']})\n"
                     f"Direction: {'LONG' if direction > 0 else 'SHORT'}\n"
                     f"Entry: {fmt(price)}\nStop: {fmt(mgr.sl)}\nTarget: {fmt(mgr.tp)}\n"
                     f"Quantity: {fmt(cfg['risk'].quantity, 0)}\n"
                     f"Time: {pd.Timestamp.now()}")
    if err:
        log_event(err, "error")
    log_event(f"ENTRY {'LONG' if direction > 0 else 'SHORT'} @ {fmt(price)} on signal from "
              f"{cfg['strategy']} (candle {fmt_time(bar_time)}) | SL {fmt(mgr.sl)} | "
              f"TGT {fmt(mgr.tp)} | qty {fmt(cfg['risk'].quantity, 0)}", "success")
    for note in mgr.notes:
        log_event("Exit engine: " + note, "warn")
    return position


def run_cycle(cfg: dict) -> None:
    """
    One tick.

    Fast leg every tick (price, PnL, stop, target, trailing); slow leg only when
    the candle cadence is due (download, indicators, signals, filters).
    """
    if time.time() < st.session_state.get("live_backoff_until", 0.0):
        return

    now = time.time()
    candle_gap = float(cfg.get("candle_seconds", 15.0))
    need_candles = (st.session_state.live_frame is None
                    or (now - st.session_state.live_frame_at) >= candle_gap)
    try:
        if need_candles:
            previous_frame = st.session_state.live_frame
            frame, reports, warns, vix = refresh_candles(cfg)
            # How many candles this single refresh delivered. A delayed feed
            # hands over a burst, and every bar in that burst is being SEEN for
            # the first time -- so a signal inside it is not a signal the engine
            # was slow about, and judging its age by candle count alone would
            # reject the only chance there ever was to act on it.
            added = 0
            if previous_frame is not None and len(previous_frame):
                try:
                    newer = frame.index > pd.Timestamp(previous_frame.index[-1])
                    added = int(newer.sum())
                except (TypeError, ValueError):
                    added = 0
            st.session_state.bars_added_last_refresh = added
            st.session_state.live_frame = frame
            st.session_state.live_reports = reports
            st.session_state.live_frame_warnings = warns
            st.session_state.live_vix = vix
            st.session_state.live_frame_at = now
            st.session_state.candle_refreshes += 1
        frame = st.session_state.live_frame
        ltp, ltp_source = fetch_live_ltp(cfg, frame)
        snapshot = build_snapshot(cfg, frame, st.session_state.live_reports,
                                  st.session_state.live_frame_warnings,
                                  st.session_state.live_vix, ltp, ltp_source)
    except Exception as exc:                                        # noqa: BLE001
        st.session_state.live_fail_streak += 1
        streak = st.session_state.live_fail_streak
        backoff = min(300.0, max(2.0, cfg["poll_seconds"]) * (2 ** min(streak, 6)))
        st.session_state.live_backoff_until = time.time() + backoff
        st.session_state.live_error = (f"{exc}  --  backing off {backoff:.0f}s "
                                       f"(consecutive failures: {streak})")
        log_event(f"Feed error: {exc}. Backing off {backoff:.0f}s.", "error")
        return

    st.session_state.live_fail_streak = 0
    st.session_state.live_backoff_until = 0.0
    st.session_state.live_error = None
    st.session_state.live_snapshot = snapshot
    st.session_state.live_last_poll = time.time()
    st.session_state.live_poll_count += 1

    # Poll-by-poll record. If the LTP column never changes across dozens of
    # ticks, the refresh loop is fine and the FEED is standing still.
    log = st.session_state.feed_log
    prev_ltp = log[0]["LTP"] if log else None
    prev_source = log[0]["Source"] if log else None
    log.insert(0, {"Polled at": pd.Timestamp.now().strftime("%H:%M:%S.%f")[:-3],
                   "Newest candle": fmt_time(snapshot.frame.index[-1]),
                   "LTP": round(snapshot.ltp, 4),
                   "Changed": "-" if prev_ltp is None else
                              ("yes" if abs(prev_ltp - snapshot.ltp) > 1e-9 else "no"),
                   "Source": snapshot.ltp_source})
    del log[60:]

    # Alternating sources are the classic cause of a phantom sawtooth.
    if prev_source and prev_source != snapshot.ltp_source:
        log_event(f"Price source changed: {prev_source} -> {snapshot.ltp_source}. A change here "
                  f"moves the quoted price for reasons that have nothing to do with the market.",
                  "warn")

    closed_ctx = bar_ctx(frame, len(frame) + snapshot.closed_index)
    st.session_state.last_closed_bar = _bar_dict(closed_ctx)

    # A single bad print can hit a stop that the market never reached. A move of
    # this size between two ticks seconds apart is a data artefact, not a market
    # event, so the tick is logged and skipped for risk management -- the next
    # poll is 0.3s away and will confirm or deny it.
    suspect = False
    if prev_ltp is not None and np.isfinite(closed_ctx.atr) and closed_ctx.atr > 0:
        jump = abs(snapshot.ltp - float(prev_ltp))
        if jump > max(8.0 * closed_ctx.atr, 0.03 * float(prev_ltp)):
            suspect = True
            st.session_state.suspect_ticks += 1
            log_event(f"Suspect tick ignored: {fmt(prev_ltp)} -> {fmt(snapshot.ltp)} "
                      f"({fmt(jump)} in one poll, ATR {fmt(closed_ctx.atr)}). Waiting for the "
                      f"next quote to confirm.", "warn")
    if suspect:
        return
    position: Position | None = st.session_state.live_position
    new_bar = st.session_state.live_last_bar != snapshot.last_closed_time

    # ------------------------------------------------- 1. manage open risk ---
    if position is not None:
        mgr = position.manager
        hit = mgr.check_tick(snapshot.ltp)           # stop first, then target, both vs LTP
        if hit:
            price, reason = hit
            square_off(reason, price)
            st.session_state.live_last_bar = snapshot.last_closed_time
            return
        timed = mgr.time_exit_reason(pd.Timestamp.now(), snapshot.ltp)
        if timed:
            square_off(timed, snapshot.ltp)
            st.session_state.live_last_bar = snapshot.last_closed_time
            return
        if new_bar:
            reason = mgr.signal_exit_reason(closed_ctx)
            if reason:
                square_off(reason, snapshot.ltp)
                st.session_state.live_last_bar = snapshot.last_closed_time
                return
            mgr.bars_held += 1
        mgr.update(snapshot.ltp, closed_ctx)         # trail on the running price
        # True extremes of the trade, which differ from the manager's favourable
        # excursion: for a short the LOW is the good news and the HIGH is the pain.
        position.high_since_entry = max(position.high_since_entry or snapshot.ltp, snapshot.ltp)
        position.low_since_entry = min(position.low_since_entry or snapshot.ltp, snapshot.ltp)
        if new_bar:
            db_save_position(position, cfg)          # persist the ratcheted stop
        # ---- a signal that fires while a trade is already open ----
        #
        # This is where most "the crossover happened and nothing entered"
        # reports actually come from, and it is not a fault: the engine holds
        # ONE position at a time, so every signal that fires between an entry
        # and its exit is passed over. With a wide stop that can be hours and
        # several crossovers. The rule applies identically to all 50 strategy
        # profiles -- there is no per-strategy behaviour here.
        #
        # Two things were wrong about how it handled that. It said nothing, so
        # the next flat poll reported a mysteriously old signal; and it offered
        # no way to act on a genuine reversal without giving up a real stop by
        # setting "Strategy Reverse Signal" as the stop TYPE.
        fresh_sig = int(snapshot.recent_signal)
        sig_time = snapshot.recent_signal_time
        newer = (fresh_sig != 0 and sig_time is not None
                 and pd.Timestamp(sig_time) > pd.Timestamp(position.signal_bar_time))
        reverse_window = max(0, int(cfg.get("entry_lookback", DEFAULT_ENTRY_LOOKBACK)))
        if (newer and cfg.get("reverse_on_opposite") and fresh_sig == -position.direction
                and int(snapshot.recent_signal_bars_ago or 0) <= reverse_window):
            side = "LONG" if position.direction > 0 else "SHORT"
            square_off(f"Reversed on an opposite signal ({fmt_time(sig_time)})", snapshot.ltp)
            entry_trace("Reversed out",
                        f"An opposite signal closed the {side} position at {fmt(snapshot.ltp)}. "
                        f"The new side is taken on this same poll.",
                        when=sig_time, ago=snapshot.recent_signal_bars_ago, direction=fresh_sig)
            position = None                  # fall through to the entry section below
        else:
            if newer:
                st.session_state.live_last_signal_time = sig_time
                entry_trace("Skipped — already in a trade",
                            f"This {'LONG' if fresh_sig > 0 else 'SHORT'} signal fired while the "
                            f"engine was already holding a "
                            f"{'LONG' if position.direction > 0 else 'SHORT'} position opened on "
                            f"{fmt_time(position.signal_bar_time)}. One position at a time is "
                            f"the rule for every strategy. Tick 'Exit and reverse on an opposite "
                            f"signal' in the sidebar to trade reversals instead of sitting "
                            f"through them.",
                            when=sig_time, ago=snapshot.recent_signal_bars_ago,
                            direction=fresh_sig)
            st.session_state.live_last_bar = snapshot.last_closed_time
            return

    # ----------------------------------------------------- 2. fresh entries ---
    strat = get_strategy(cfg["strategy"])

    # Daily limits gate NEW entries only.
    risk = cfg["risk"]
    if risk.daily_profit_target or risk.daily_loss_limit:
        booked = live_pnl_today()
        if risk.daily_profit_target and booked >= float(risk.daily_profit_target):
            entry_trace("Blocked — daily profit target",
                        f"Booked {fmt(booked)} today, which is at or past your daily target of "
                        f"{fmt(risk.daily_profit_target)}. No further entries today.")
            return
        if risk.daily_loss_limit and booked <= -abs(float(risk.daily_loss_limit)):
            entry_trace("Blocked — daily loss limit",
                        f"Booked {fmt(booked)} today, which is at or past your daily loss limit "
                        f"of {fmt(risk.daily_loss_limit)}. No further entries today.")
            return

    # -- the one source of truth for "something fired that we have not acted on"
    #
    # Earlier versions asked "does the NEWEST CLOSED candle carry a signal?" and
    # that question is unanswerable in practice. A signal is only visible on the
    # single poll where its bar happens to be the newest closed one, and that
    # poll is missed constantly: a delayed feed delivers ten candles in one
    # burst so the trigger lands in the middle of the batch, the browser tab
    # sleeps, a rerun lands mid-candle, the liveness gate holds the cycle for
    # its first few ticks. Every one of those drops the trade silently, which is
    # exactly the reported failure -- two clean 9/21 crossovers on Nifty, no
    # entry, no explanation.
    #
    # So the engine now asks the durable question instead: what is the newest
    # closed candle carrying a signal anywhere in the frame, and have we already
    # made a decision about it? That is independent of which poll saw the bar
    # close, which makes batch arrival, missed polls and held cycles harmless.
    pending_dir = int(snapshot.recent_signal)
    pending_time = snapshot.recent_signal_time
    pending_ago = snapshot.recent_signal_bars_ago
    decided = st.session_state.get("live_last_signal_time")
    st.session_state.live_last_bar = snapshot.last_closed_time

    if strat.immediate:
        cfg["_ltp_at_fill"] = snapshot.ltp
        _open_live_position(cfg, 1 if "Buy" in strat.name else -1, snapshot.ltp, closed_ctx,
                            snapshot.last_closed_time, bars_ago=0,
                            route="immediate profile, no candle wait")
        st.session_state.live_first_cycle = False
        return

    first_cycle = bool(st.session_state.get("live_first_cycle"))
    if pending_dir == 0 or pending_time is None:
        st.session_state.live_first_cycle = False
        entry_trace("Waiting — no signal",
                    f"No candle in the loaded window carries a {cfg['strategy']} signal yet. "
                    f"The newest closed candle is {fmt_time(snapshot.last_closed_time)}.")
        return
    if decided is not None and pd.Timestamp(pending_time) == pd.Timestamp(decided):
        st.session_state.live_first_cycle = False
        entry_trace("Waiting — newest signal already handled",
                    "The most recent signal in the window has already been acted on or ruled "
                    "out. The engine is flat and waiting for the NEXT one.",
                    when=pending_time, ago=pending_ago, direction=pending_dir)
        return

    # -- how old a signal may be and still be worth taking
    #
    # On the first cycle the operator has just pressed Start, usually because a
    # screener showed a signal, so a wider window is the intent. Afterwards the
    # window only has to cover a burst of late candles. It is configurable, and
    # zero is honoured: it then means "the newest closed candle only".
    if first_cycle:
        window = int(cfg.get("join_window", 3) or 3)
    else:
        window = int(cfg.get("entry_lookback", DEFAULT_ENTRY_LOOKBACK))
    ago = int(pending_ago or 0)

    # A burst widens the window to cover itself, for one poll only. Ten candles
    # arriving together means the tenth-oldest was invisible until this instant,
    # and there is no sense in calling it "too old to act on" when this is the
    # first moment it could be acted on at all. The real economic test -- has
    # price already run to the stop or target the signal implied -- is applied
    # below regardless, so this widening cannot wave through a dead trade.
    burst = int(st.session_state.get("bars_added_last_refresh", 0) or 0)
    if burst > window and ago <= burst:
        window = min(burst, int(cfg.get("max_burst_entry", 12)))
        log_event(f"The feed delivered {burst} candles in one refresh, so the entry window is "
                  f"widened to {window} for this poll: the signal on {fmt_time(pending_time)} "
                  f"became visible only now. Whether anything is left of the trade is still "
                  f"checked against the price.", "info")

    if ago > max(0, window):
        # Mark it decided so this does not re-log on every poll, and say why.
        st.session_state.live_last_signal_time = pending_time
        st.session_state.live_first_cycle = False
        log_event(f"A {'LONG' if pending_dir > 0 else 'SHORT'} signal is present on "
                  f"{fmt_time(pending_time)}, {ago} candle(s) back. The entry window is "
                  f"{max(0, window)} candle(s), so it is too old to take -- chasing it would "
                  f"buy a move that has already happened. Raise 'Enter on signals up to N "
                  f"candles old' in the sidebar if you want stale signals taken.", "warn")
        entry_trace("Refused — older than the entry window",
                    f"{ago} candles old against a window of {max(0, window)}. Raise "
                    f"'Live: act on a signal up to N candles old' in the sidebar to take it.",
                    when=pending_time, ago=ago, direction=pending_dir)
        return

    # -- liveness: hold, never discard
    #
    # A dead tape must not produce fills, but the old code returned here BEFORE
    # looking at the signal, so a trigger that fired while the engine was still
    # gathering tick evidence was passed over and never revisited. Now the
    # candidate is simply HELD: it stays undecided, and the next cycle that has
    # its evidence takes it, as long as it is still inside the window above.
    if snapshot.frozen and not cfg.get("allow_stale_entries"):
        held = int(st.session_state.get("held_signal_polls", 0)) + 1
        st.session_state.held_signal_polls = held
        if held in (1, 5, 20) or held % 50 == 0:
            ticks = int(st.session_state.get("live_poll_count", 0))
            log_event(f"Holding a {'LONG' if pending_dir > 0 else 'SHORT'} signal from "
                      f"{fmt_time(pending_time)}: candles are lagging and the quote has not "
                      f"been seen to move yet ({ticks} of {QUOTE_EVIDENCE_TICKS} confirming "
                      f"ticks). The signal is NOT discarded -- it will be taken as soon as the "
                      f"tape proves it is live, or dropped once it ages past the entry window.",
                      "warn")
        entry_trace("Held — waiting for proof the venue is open",
                    "Candles are lagging and the quote has not been seen to move. The signal "
                    "is kept, not discarded. Tick 'Live: allow entries on a frozen feed' to "
                    "override.", when=pending_time, ago=ago, direction=pending_dir)
        return
    st.session_state.held_signal_polls = 0

    # -- is there anything left of the trade?
    #
    # A late entry is only worth taking if price has not already run to the stop
    # or the target that the original signal implied. Checking this stops the
    # engine opening a position that a faithful backtest would have closed
    # already, which is the cheapest way to manufacture a fake losing streak.
    frame_idx = snapshot.frame.index
    sig_pos = int(frame_idx.get_loc(pending_time))
    original_fill = (float(snapshot.frame["Open"].iloc[sig_pos + 1])
                     if sig_pos + 1 < len(frame_idx) else snapshot.ltp)
    if ago > 0:
        probe = ExitManager(cfg["risk"], original_fill, pending_dir, closed_ctx)
        done = probe.check_tick(snapshot.ltp)
        if done:
            st.session_state.live_last_signal_time = pending_time
            st.session_state.live_first_cycle = False
            log_event(f"A {'LONG' if pending_dir > 0 else 'SHORT'} signal fired {ago} candle(s) "
                      f"ago at {fmt(original_fill)}, but price has already reached its "
                      f"{done[1].lower()} at {fmt(snapshot.ltp)}. Not entering -- there is "
                      f"nothing left of that trade.", "warn")
            entry_trace("Refused — the trade is already over",
                        f"Signalled at {fmt(original_fill)}; price is now {fmt(snapshot.ltp)}, "
                        f"which is past the {done[1].lower()} that signal implied.",
                        when=pending_time, ago=ago, direction=pending_dir)
            return

    st.session_state.live_last_signal_time = pending_time
    st.session_state.live_first_cycle = False

    # Signal on candle N -> the backtest fills at the open of candle N+1. Live,
    # that open has already passed, so the fill is the price actually available.
    if ago == 0:
        route = "newest closed candle"
        fill = _live_fill_price(cfg, snapshot, closed_ctx)
        levels_from = None
    else:
        route = (f"joined on start ({ago} candle(s) after the signal)" if first_cycle
                 else f"arrived late ({ago} candle(s) after the signal)")
        fill = snapshot.ltp
        # Keep the stop and target where the original signal put them, so a late
        # entry takes whatever reward is LEFT instead of being handed a fresh
        # full-width target measured from a price that has already moved.
        levels_from = original_fill
        log_event(f"Entering {ago} candle(s) after the signal on {fmt_time(pending_time)}. The "
                  f"N+1 open of {fmt(original_fill)} is gone, so the fill is the live price "
                  f"{fmt(fill)} while the stop and target stay anchored to the original "
                  f"signal -- you are joining with what is left, not with a full target.",
                  "info")

    cfg["_ltp_at_fill"] = snapshot.ltp
    entry_trace("ENTERED", f"Filled at {fmt(fill)} via {route}.",
                when=pending_time, ago=ago, direction=pending_dir)
    _open_live_position(cfg, pending_dir, fill, closed_ctx, pending_time,
                        levels_from=levels_from, bars_ago=ago, route=route)


def should_poll(cfg: dict) -> bool:
    if time.time() < st.session_state.get("live_backoff_until", 0.0):
        return False
    return (time.time() - st.session_state.get("live_last_poll", 0.0)) >= float(cfg["poll_seconds"])


