# SECTION 13 -- TAB 1: BACKTESTING ENGINE STUDIO
# =============================================================================
def calendar_pnl(trades: pd.DataFrame) -> pd.Series:
    """Net PnL per calendar day, keyed by date, from closed trades."""
    if trades is None or trades.empty or "Exit Time" not in trades.columns:
        return pd.Series(dtype=float)
    frame = trades.copy()
    stamps = pd.to_datetime(frame["Exit Time"])
    # Drop the timezone before bucketing by day.
    #
    # Exit times are tz-aware, so the index came back tz-aware too, while the
    # calendar builds naive Timestamps to look each day up. A naive timestamp
    # never matches a tz-aware index, so every lookup missed, every cell resolved
    # to None, and the heatmap rendered completely blank beneath a correct
    # month header.
    if getattr(stamps.dt, "tz", None) is not None:
        stamps = stamps.dt.tz_localize(None)
    frame["_day"] = stamps.dt.normalize()
    daily = frame.groupby("_day")["PnL"].sum()
    daily.index = pd.DatetimeIndex(daily.index)
    return daily.sort_index()


def render_pnl_calendar(trades: pd.DataFrame, currency: str = "", max_months: int = 12) -> None:
    """
    Month-by-month PnL calendar, the way a broker statement shows it.

    Drawn with Plotly rather than raw HTML: Streamlit sanitises injected <style>
    blocks, so a hand-built table renders unstyled -- which is exactly why the
    colours went missing. Shading is scaled to the largest absolute day so one
    outlier does not wash out the rest, and a day with no closed trade is left
    blank: being flat is not a zero-PnL result, it is no result.
    """
    import calendar as _calendar
    import plotly.graph_objects as go

    daily = calendar_pnl(trades)
    if daily.empty:
        st.info("No closed trades to lay out on a calendar.")
        return

    wins = int((daily > 0).sum())
    losses = int((daily < 0).sum())
    a, b, c, d = st.columns(4)
    a.metric("Trading days", f"{len(daily):,}")
    b.metric("Green days", f"{wins:,}", f"{wins / len(daily) * 100:.0f}%")
    c.metric("Red days", f"{losses:,}")
    d.metric("Best / worst day", f"{fmt(float(daily.max()), 0)} / {fmt(float(daily.min()), 0)}")

    peak = float(daily.abs().max()) or 1.0
    months = sorted({(ts.year, ts.month) for ts in daily.index})
    if len(months) > max_months:
        st.caption(f"Showing the most recent {max_months} of {len(months)} months.")
        months = months[-max_months:]

    day_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    for year, month in months:
        weeks = _calendar.Calendar(firstweekday=0).monthdayscalendar(year, month)
        z, text, hover = [], [], []
        for week in weeks:
            z_row, t_row, h_row = [], [], []
            for day in week:
                if day == 0:
                    z_row.append(None)
                    t_row.append("")
                    h_row.append("")
                    continue
                stamp = pd.Timestamp(year=year, month=month, day=day)
                if stamp not in daily.index:
                    z_row.append(None)
                    t_row.append(f"<span style='color:#9aa0a6'>{day}</span>")
                    h_row.append(f"{stamp:%d %b %Y}<br>no closed trade")
                    continue
                value = float(daily.loc[stamp])
                z_row.append(value)
                t_row.append(f"<b>{day}</b><br>{fmt_signed(value, 0)}")
                h_row.append(f"{stamp:%d %b %Y}<br>{currency}{fmt_signed(value)}")
            z.append(z_row)
            text.append(t_row)
            hover.append(h_row)

        total = float(daily[(daily.index.year == year) & (daily.index.month == month)].sum())
        fig = go.Figure(go.Heatmap(
            z=z, text=text, texttemplate="%{text}", customdata=hover,
            hovertemplate="%{customdata}<extra></extra>",
            x=day_names, y=[f"W{i + 1}" for i in range(len(weeks))],
            colorscale=[[0.0, "#ef5350"], [0.5, "#f5f5f5"], [1.0, "#26a69a"]],
            zmid=0, zmin=-peak, zmax=peak, showscale=False,
            xgap=3, ygap=3, textfont=dict(size=11)))
        fig.update_yaxes(autorange="reversed", showgrid=False, ticks="")
        fig.update_xaxes(side="top", showgrid=False, ticks="")
        fig.update_layout(
            title=dict(text=f"{_calendar.month_name[month]} {year} · "
                            f"{currency}{fmt_signed(total)}",
                       x=0.01, xanchor="left", font=dict(size=14)),
            height=90 + 58 * len(weeks), margin=dict(l=10, r=10, t=60, b=10),
            template="plotly_white")
        st.plotly_chart(fig, width="stretch", config={"displayModeBar": False})

    st.caption("Shade depth is scaled to the largest absolute day in the sample. Blank days had "
               "no closed trade — being flat is not a zero result, it is no result.")


def tab_backtest(cfg: dict) -> None:
    st.subheader("Backtesting Engine Studio")
    st.caption("Historical simulation only. Nothing here can reach the live ledger in Tab 3.")

    left, right = st.columns([1, 3])
    run = left.button("Run Backtest Analysis", type="primary", width="stretch")
    right.info(f"**{cfg['strategy']}** on `{cfg['symbol']}` | `{cfg['interval']}` / "
               f"`{cfg['period']}` | {cfg['risk'].as_summary()}")

    if run:
        _run_backtest_ui(cfg)
    if st.session_state.backtest_error:
        st.error(st.session_state.backtest_error)
    if st.session_state.backtest_result is not None:
        _render_backtest(st.session_state.backtest_result, st.session_state.backtest_meta)
    elif not st.session_state.backtest_error:
        st.info("Configure the console on the left, then run the analysis.")


def _run_backtest_ui(cfg: dict) -> None:
    st.session_state.backtest_error = None
    st.session_state.backtest_result = None
    with st.status("Running simulation...", expanded=True) as status:
        try:
            st.write(f"Fetching `{cfg['symbol']}` at {cfg['interval']} / {cfg['period']} ...")
            bundle = load_market_data(cfg["symbol"], cfg["period"], cfg["interval"], 300.0,
                                      min_bars=max(30, get_strategy(cfg["strategy"]).min_bars))
            st.write(f"Received {bundle.bars:,} candles. Computing indicators and signals ...")
            extras = dict(cfg.get("filter_extras") or {})
            if cfg["filter_cfg"].get("vix", {}).get("enabled"):
                st.write("Fetching India VIX for the volatility filter ...")
                extras["vix"] = load_vix()
            result = run_backtest(bundle.frame, cfg["strategy"], cfg["params"], cfg["risk"],
                                  cfg["filter_cfg"], extras, WARMUP_BARS,
                                  square_off_eod=cfg.get("square_off_eod", True))
            result.warnings = list(bundle.warnings) + list(result.warnings)
            if cfg.get("walk_forward"):
                st.write(f"Running {cfg['wf_folds']} stability segments ...")
                result.walk_forward = walk_forward(bundle.frame, cfg["strategy"], cfg["params"],
                                                   cfg["risk"], cfg["filter_cfg"], extras,
                                                   int(cfg["wf_folds"]))
            st.session_state.backtest_result = result
            st.session_state.backtest_meta = dict(cfg)
            status.update(label=f"Complete :: {result.stats['total_trades']} trades",
                          state="complete", expanded=False)
        except (MarketDataError, BacktestError) as exc:
            st.session_state.backtest_error = str(exc)
            status.update(label="Simulation aborted", state="error", expanded=False)
        except Exception as exc:                                    # noqa: BLE001
            st.session_state.backtest_error = f"Unexpected failure: {exc}"
            status.update(label="Simulation aborted", state="error", expanded=False)


def _trust_header(result: BacktestResult, meta: dict) -> None:
    """
    A blunt verdict on whether this result deserves any confidence.

    Backtests fail in predictable ways: too few trades, an exit type the
    simulation cannot model honestly, results carried by gap fills, or no cost
    model. Each is checked and named rather than left for the operator to spot.
    """
    s = result.stats
    problems, cautions = [], []

    if s["total_trades"] == 0:
        problems.append("No trades at all -- there is nothing here to evaluate.")
    elif s["total_trades"] < 30:
        problems.append(f"Only {s['total_trades']} trades. Below roughly 30 the win rate and "
                        "Sharpe are noise; this sample cannot distinguish edge from luck.")
    elif s["total_trades"] < 100:
        cautions.append(f"{s['total_trades']} trades is a thin sample. Treat the numbers as "
                        "indicative, not established.")

    if s.get("reliability") == "Optimistic":
        problems.append("A distance-based trailing exit is active, which the simulation cannot "
                        "model honestly on OHLC data. Live results will be WORSE than shown.")
    if s["total_trades"] and s["gap_exits"] / max(s["total_trades"], 1) > 0.25:
        cautions.append(f"{s['gap_exits']} of {s['total_trades']} exits filled through gaps. The "
                        "stop is too tight for this instrument's gap behaviour.")
    if not meta["risk"].costs.enabled and s["total_trades"]:
        cautions.append("Costs are excluded. Brokerage, taxes and slippage often exceed the edge "
                        "on fast intraday profiles -- enable the cost model before believing this.")
    rdd = s.get("return_over_dd")
    if s["total_trades"] and isinstance(rdd, (int, float)) and np.isfinite(rdd):
        if rdd < 1.0:
            problems.append(
                f"**Return / max drawdown is {fmt(rdd)}.** The worst peak-to-trough fall was "
                f"{fmt(abs(s['max_drawdown']))} against total profit of {fmt(s['net_pnl'])} — "
                f"you would have been more underwater than you ended up ahead. A live drawdown "
                f"is normally DEEPER than the backtested one.")
        elif rdd < 2.0:
            cautions.append(
                f"Return / max drawdown is {fmt(rdd)}. To make {fmt(s['net_pnl'])} you had to "
                f"sit through {fmt(abs(s['max_drawdown']))} at the worst point. Below 2 the "
                f"profit is small next to the pain it cost, and most people stop trading a "
                f"system long before its backtested drawdown is over.")

    margin = s.get("win_rate_margin")
    if s["total_trades"] and isinstance(margin, (int, float)) and np.isfinite(margin):
        if margin < 0:
            problems.append(
                f"**This configuration loses money by construction.** Its reward:risk of "
                f"{fmt(s.get('reward_risk'))}:1 needs a {fmt(s.get('breakeven_win_rate'))}% win "
                f"rate just to break even, and it wins {fmt(s['win_rate'])}% of the time.")
        elif margin < 5:
            cautions.append(
                f"Only {fmt(margin)} percentage points of headroom. The average win is "
                f"{fmt(s.get('avg_win'))} against an average loss of {fmt(abs(s.get('avg_loss', 0)))}, "
                f"so this reward:risk needs {fmt(s.get('breakeven_win_rate'))}% to break even "
                f"and it is getting {fmt(s['win_rate'])}%. A slightly worse month turns it "
                f"negative.")
    if not meta.get("walk_forward"):
        cautions.append("No segment stability check was run, so it is unknown whether one lucky "
                        "stretch carried the result.")

    if problems:
        st.error("### Do not trust this result yet\n\n"
                 + "\n".join(f"- {x}" for x in problems)
                 + ("\n\nAlso worth noting:\n" + "\n".join(f"- {x}" for x in cautions)
                    if cautions else ""))
    elif cautions:
        st.warning("### Treat this result with caution\n\n"
                   + "\n".join(f"- {x}" for x in cautions))
    else:
        st.success("### This result passes the basic sanity checks\n\n"
                   f"- {s['total_trades']} trades, a sample large enough to mean something.\n"
                   "- Exit configuration is backtest-safe: no path ambiguity to guess at.\n"
                   "- Costs are included and drawdown sits within total profit.\n"
                   "- Segment stability was checked.\n\n"
                   "Passing these checks means the simulation is *honest*. It does not mean the "
                   "edge will persist: markets change, and out-of-sample forward testing on "
                   "paper is the only thing that tells you whether it still works.")


def _render_backtest(result: BacktestResult, meta: dict) -> None:
    cur, s = meta["currency"], result.stats
    _trust_header(result, meta)

    st.markdown("#### Performance Summary")
    a = st.columns(5)
    a[0].metric("Total Trades", s["total_trades"], f"{s['longs']}L / {s['shorts']}S")
    a[1].metric("Win Rate", f"{fmt(s['win_rate'])}%", f"{s['wins']}W / {s['losses']}L")
    a[2].metric(f"Net PnL ({cur})", fmt_signed(s["net_pnl"]), f"{fmt_signed(s['gross_points'])} pts")
    pf = s["profit_factor"]
    a[3].metric("Profit Factor", "inf" if pf == float("inf") else fmt(pf))
    rdd = s.get("return_over_dd")
    a[4].metric(f"Max Drawdown ({cur})", fmt(s["max_drawdown"]),
                "inf" if rdd == float("inf") else f"{fmt(rdd)}x covered by profit",
                help="The worst peak-to-trough fall in the equity curve, and how many times "
                     "over the total profit covers it. Below 2 the profit is small next to "
                     "the pain it cost. A live drawdown is normally deeper than a backtested "
                     "one, so treat this as a best case.")
    b = st.columns(5)
    b[0].metric("Expectancy / trade", fmt_signed(s["expectancy"]))
    rr = s.get("reward_risk")
    b[1].metric("Average Win", fmt(s["avg_win"]),
                "inf" if rr == float("inf") else f"reward:risk {fmt(rr)} : 1",
                help="What one correct trade earns, against what one mistake costs. Below 1:1 "
                     "a mistake costs more than being right earns, which only survives on a "
                     "very high win rate.")
    b[2].metric("Average Loss", fmt(s["avg_loss"]),
                f"breakeven needs {fmt(s.get('breakeven_win_rate'))}% wins",
                help="The win rate THIS reward:risk requires simply to break even. Compare it "
                     "with the actual win rate above: the gap between them is the whole margin "
                     "of safety.")
    b[3].metric("Best / Worst", f"{fmt(s['best_trade'], 0)} / {fmt(s['worst_trade'], 0)}")
    b[4].metric("Warm-up Bars", f"{s['warmup_bars']:,}", f"{s['bars_tested']:,} tested")
    c = st.columns(5)
    c[0].metric("Sharpe Ratio", fmt(s["sharpe"]), f"~{fmt(s['trades_per_year'],0)} trades/yr",
                help="Per-trade returns annualised by the sample's own trade frequency. Zero "
                     "risk-free rate, trades treated as independent. A Sharpe from a few dozen "
                     "trades is a noisy estimate, not a property of the strategy.")
    c[1].metric(f"Gross PnL ({cur})", fmt_signed(s.get("gross_pnl", s["net_pnl"])))
    c[2].metric(f"Costs charged ({cur})", fmt(s.get("total_costs", 0.0)),
                meta["risk"].costs.summary())
    c[3].metric("Avg Bars Held", fmt(s["avg_bars"], 1))
    margin = s.get("win_rate_margin")
    c[4].metric("Margin over breakeven", f"{fmt(margin)} pts",
                "fragile" if (isinstance(margin, (int, float))
                              and np.isfinite(margin) and margin < 5) else "has headroom",
                help="Actual win rate minus the win rate this reward:risk needs to break even. "
                     "This is the fragility measure: 2 points of margin means a slightly worse "
                     "month turns the system negative. Bigger is safer.")

    if meta.get("walk_forward") and not result.walk_forward.empty:
        st.markdown("#### Segment Stability")
        st.caption("The sample split into sequential stretches. With a fixed configuration there "
                   "is no in-sample fitting to guard against, so this asks a narrower question: "
                   "did the result hold across the whole sample, or did one window carry it? "
                   "Use the Strategy Optimiser for the fit-then-test version.")
        st.dataframe(result.walk_forward, width="stretch", hide_index=True)

    st.warning(
        "**Treat this result with caution.** These numbers describe what this exact "
        "configuration would have done on this exact sample. They are not a forecast. Before "
        "risking money: check the trade count (under about 30 proves little), check expectancy "
        "and profit factor rather than the win rate, confirm the reliability verdict is "
        "backtest-safe, and re-run the same configuration on a different period to see whether "
        "it survives.")

    if result.warnings:
        with st.expander(f"Run notes and caveats ({len(result.warnings)})", expanded=False):
            for w in result.warnings:
                st.warning(w)

    strat = get_strategy(meta["strategy"])
    st.plotly_chart(price_chart(result.frame,
                                f"{meta['symbol']} | {meta['interval']} | {meta['strategy']}",
                                strat.overlays, result.trades,
                                hide_weekends=meta["hide_weekends"]),
                    width="stretch", config={"scrollZoom": True})
    st.caption(f"The first {result.warmup_index:,} candles were reserved as the indicator warm-up "
               "window and produced no orders. Signals fire on a candle close and fill at the "
               "next candle's open.")
    t1, t2, t3, t4, t5 = st.tabs(["Simulated Trades", "PnL Calendar", "Exit Reasons",
                                  "Gap Diagnostics", "Indicator Frame"])
    with t1:
        if result.trades.empty:
            st.info("No simulated trades for this configuration.")
        else:
            st.dataframe(result.trades, width="stretch", hide_index=True,
                         column_config={"PnL": st.column_config.NumberColumn(f"PnL ({cur})",
                                                                            format="%.2f")})
            st.download_button("Download simulated trades (CSV)",
                               result.trades.to_csv(index=False).encode(),
                               f"backtest_{meta['symbol']}_{meta['interval']}.csv", "text/csv")
            st.caption("Simulation output. Deliberately NOT written to the live ledger.")
    with t2:
        render_pnl_calendar(result.trades, cur)

    with t3:
        if result.trades.empty:
            st.info("Nothing to break down yet.")
        else:
            by = result.trades.groupby("Exit Reason")["PnL"].agg(["count", "sum", "mean"]).round(2)
            by.columns = ["Trades", f"Total PnL ({cur})", f"Average ({cur})"]
            st.dataframe(by.reset_index(), width="stretch", hide_index=True)
            st.caption("Where the exits actually came from. If almost everything closes on "
                       "'Stop-Loss (Gap)', the stop is too tight for this instrument's gaps.")
    with t4:
        gaps = gap_profile(result.frame, 0.3)
        st.metric("Gap candles in sample (>= 0.30%)", f"{len(gaps):,}")
        st.dataframe(gaps.tail(200), width="stretch")
    with t5:
        st.dataframe(result.frame.tail(300), width="stretch")

    render_analyst_panel(
        "backtest", "this backtest",
        f"Strategy: {meta['strategy']} on {meta['symbol']} {meta['interval']}\n"
        f"Risk: {meta['risk'].as_summary()}\n"
        f"Stats: {json.dumps(result.stats, default=str)}\n"
        f"Warnings: {result.warnings}\n"
        f"Trades sample:\n{_frame_context(result.trades)}")


# =============================================================================
# SECTION 14 -- TAB 2: LIVE SANDBOX OPERATIONS PANEL
# =============================================================================
def tab_live(cfg: dict) -> None:
    st.subheader("Live Sandbox Operations Panel")
    st.caption("Signals are read from closed candles and filled at the next candle's open. "
               "Stop and target are then checked against the LTP on every poll, stop first.")
    if st.session_state.live_running:
        # The controls are rendered INSIDE the fragment. Left outside, they only
        # redraw on a full app rerun, so the square-off button stayed greyed out
        # for as long as the fragment was quietly opening and closing positions.
        _mount_live_fragment(float(st.session_state.live_config.get("poll_seconds", 5.0)))
    else:
        _live_controls(cfg)
        st.divider()
        _idle_panel(cfg)


def _live_controls(cfg: dict) -> None:
    """
    The three operator actions.

    Rendered inside the live fragment while running, so the square-off button
    reflects the position as it actually is on this tick rather than as it was
    at the last full page render.
    """
    running = bool(st.session_state.live_running)
    position = st.session_state.live_position
    c1, c2, c3 = st.columns(3)

    if c1.button("Start Live Automation Core", type="primary", disabled=running,
                 width="stretch"):
        reset_live_runtime()
        st.session_state.live_config = dict(cfg)
        st.session_state.live_running = True
        st.session_state.live_started_at = pd.Timestamp.now()
        st.session_state.live_last_poll = 0.0
        st.session_state.live_first_cycle = True
        log_event(f"Core started :: {cfg['symbol']} | {cfg['interval']} | {cfg['strategy']} | "
                  f"{cfg['risk'].as_summary()} | poll {fmt(cfg['poll_seconds'],1)}s", "success")
        st.rerun(scope="app")

    if running:
        c2.caption("Stop " + ("closes the position." if cfg.get("square_off_on_stop")
                              else "leaves the position OPEN (sidebar setting)."))
    if c2.button("Stop Live Processing Engine", disabled=not running, width="stretch"):
        squared = None
        if st.session_state.live_position is not None and cfg.get("square_off_on_stop"):
            squared = square_off("Squared Off on Engine Stop")
        st.session_state.live_running = False
        if squared:
            st.toast(f"Position squared off at {fmt(squared['Exit Price'])} "
                     f"for {fmt_signed(squared['PnL'])} and written to the ledger.")
        elif st.session_state.live_position is not None:
            log_event("Engine stopped with a position still OPEN. Its stop-loss and target are "
                      "no longer being monitored by anything.", "warn")
        log_event("Core stopped.", "info")
        st.rerun(scope="app")

    if c3.button("Manual Square-Off", disabled=position is None, width="stretch",
                 help="Closes the tracked position now and writes it to the ledger. The engine "
                      "keeps running and will take the next qualifying signal."):
        trade = square_off("Manual Square-Off")
        if trade:
            st.toast(f"Closed at {fmt(trade['Exit Price'])} for {fmt_signed(trade['PnL'])}. "
                     "The engine is still running.")
        st.rerun(scope="app")

    if running and st.session_state.live_position is None:
        st.caption("Flat and scanning. A manual square-off does not stop the engine; it will "
                   "enter again on the next qualifying signal.")


def _idle_panel(cfg: dict) -> None:
    st.info(f"The automation core is idle. Press **Start Live Automation Core** to poll "
            f"`{cfg['symbol']}` every {fmt(cfg['poll_seconds'],1)}s automatically -- no clicking "
            f"required. Live window: `{live_period_for(cfg['interval'])}` of "
            f"{cfg['interval']} candles.")
    snap = st.session_state.live_snapshot
    if snap is not None and snap.frozen:
        st.error(f"Heads up: the last poll found the newest `{cfg['symbol']}` candle to be "
                 f"{_human_age(snap.feed_age_seconds)} old. The venue is closed, so starting the "
                 "core now will poll a frozen tape until it reopens.")
    position = st.session_state.live_position
    if position is not None:
        st.error(
            f"**The engine is stopped but a {'LONG' if position.direction > 0 else 'SHORT'} "
            f"position on `{position.symbol}` is still OPEN.** Stopping does not close it — that "
            f"is the *Square off the open position when the engine stops* setting in the "
            f"sidebar, which is off. Nothing is watching its stop-loss right now.")
        if st.button("Square off this position now", type="primary", width="stretch",
                     key="idle_squareoff"):
            trade = square_off("Manual Square-Off")
            if trade:
                st.toast(f"Closed at {fmt(trade['Exit Price'])} for "
                         f"{fmt_signed(trade['PnL'])}.")
            st.rerun()
        _position_dashboard(st.session_state.live_position, st.session_state.live_snapshot,
                            cfg["currency"])
    _event_feed()


def _live_body() -> None:
    """
    Wrapper around the live panel.

    An uncaught exception inside an auto-refreshing fragment takes the whole page
    with it, and the only way back is a manual browser refresh. Whatever breaks,
    the panel reports it and keeps ticking.
    """
    try:
        _live_body_inner()
    except Exception as exc:                                        # noqa: BLE001
        st.session_state.live_panel_errors = \
            int(st.session_state.get("live_panel_errors", 0)) + 1
        st.error(f"The live panel hit an error and recovered: {exc}")
        st.caption("The engine is still running and this panel keeps refreshing. If the same "
                   "error repeats every tick, stop the engine and check the configuration.")
        with st.expander("Details"):
            st.code("".join(traceback.format_exc())[-2500:])


def _live_body_inner() -> None:
    cfg = st.session_state.live_config or {}
    if not cfg:
        st.error("Live configuration was lost. Stop and restart the engine.")
        return
    # Poll FIRST, then draw the controls. Rendering them beforehand meant the
    # square-off button described the position as it was one tick ago, so it sat
    # greyed out on the very tick that opened a trade.
    if should_poll(cfg):
        run_cycle(cfg)
    _live_controls(cfg)
    st.divider()

    if st.session_state.live_error:
        st.error(f"Live feed issue: {st.session_state.live_error}")
    backoff = st.session_state.get("live_backoff_until", 0.0) - time.time()
    if backoff > 0:
        st.warning(f"Rate-limit backoff active for another {backoff:.0f}s. This is what a feed "
                   "throttle looks like -- widen the poll interval.")

    snapshot = st.session_state.live_snapshot
    if snapshot is None:
        st.info("Waiting for the first market poll to complete ...")
        return
    for w in snapshot.data_warnings:
        st.warning(w)

    _metric_style()
    _feed_banner(cfg, snapshot)
    _heartbeat(cfg, snapshot)
    _market_data_panel(cfg, snapshot)
    position = st.session_state.live_position
    if position is not None:
        _position_dashboard(position, snapshot, cfg["currency"])
        # The entry gate stays visible while a trade runs: it is the only way to
        # see whether the profile would still take this trade right now.
        with st.expander("Entry conditions (still evaluated while the position is open)",
                         expanded=False):
            render_condition_checklist(cfg, snapshot)
    else:
        _searching_widget(cfg, snapshot)
    _strategy_status_panel(cfg, snapshot)
    _entry_decision_log(cfg)
    _live_chart(cfg, snapshot)
    _recent_trades()
    _feed_diagnostics()
    _filter_panel(snapshot)
    _broker_panel()
    _event_feed()


def _entry_decision_log(cfg: dict) -> None:
    """
    Every poll's entry verdict, newest first.

    "The crossover happened and nothing entered" is unanswerable without this,
    and it was asked three times before the app could answer it. The engine now
    files a verdict on every poll -- entered, skipped because a position was
    already open, refused as too old, held pending proof the venue is open --
    so the question is settled by reading a line rather than by guessing.
    """
    trace = list(st.session_state.get("entry_trace") or [])
    entered = sum(1 for r in trace if r["Verdict"] == "ENTERED")
    skipped = sum(1 for r in trace if r["Verdict"].startswith("Skipped"))
    refused = sum(1 for r in trace if r["Verdict"].startswith(("Refused", "Blocked")))
    headline = (f"Why the engine did or did not enter — {entered} entered, "
                f"{skipped} passed over while in a trade, {refused} refused")

    with st.expander(headline, expanded=bool(skipped or refused) and not entered):
        if not trace:
            st.caption("No polls recorded yet.")
            return
        if skipped and not cfg.get("reverse_on_opposite"):
            st.info(
                f"**{skipped} signal(s) were passed over because a position was already open.** "
                "The engine holds one position at a time and this is the same for all 50 "
                "strategy profiles — it is not specific to the one you picked. If you want "
                "reversals traded rather than sat through, tick **Exit and reverse on an "
                "opposite signal** in the sidebar.")
        frame = pd.DataFrame(trace)
        order = [c for c in ["First seen", "Last seen", "Polls", "Verdict", "Side",
                             "Signal bar", "Bars ago", "Why"] if c in frame.columns]
        st.dataframe(frame[order].head(120), width="stretch", hide_index=True)
        st.caption("One row per distinct verdict; `Polls` counts how many consecutive polls "
                   "reached the same conclusion, so a quiet market stays one line.")
        st.download_button("Download the decision log (CSV)",
                           frame[order].to_csv(index=False).encode("utf-8"),
                           f"entry_decisions_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv",
                           key="dl_entry_trace")


_LIVE_FRAGMENTS: dict[float, Callable] = {}


def _mount_live_fragment(poll_seconds: float) -> None:
    """
    Auto-refresh with nobody touching the keyboard.

    The panel is a fragment so only this section re-executes; a full app rerun
    would reset the tab selection and discard the backtest in Tab 1.

    The decorated fragment is CACHED per tick length. Re-decorating on every
    script rerun creates a fresh fragment identity each time, which can orphan
    the previously scheduled auto-rerun and leave the panel looking frozen.
    """
    tick = max(API_GUARD_DELAY, float(poll_seconds))
    if not hasattr(st, "fragment"):                                # legacy fallback
        _live_body()
        time.sleep(tick)
        st.rerun()
        return
    frag = _LIVE_FRAGMENTS.get(tick)
    if frag is None:
        frag = st.fragment(run_every=tick)(_live_body)
        _LIVE_FRAGMENTS[tick] = frag
    frag()


def ema_angle_degrees(frame: pd.DataFrame, ltp: float | None = None,
                      params: dict | None = None) -> float | None:
    """
    Convergence angle of the EMA pair, normalised by ATR.

    A raw gradient is in price units per bar, so its "angle" changes with the
    instrument and with how far you zoom. Dividing by ATR makes the number mean
    the same thing on Nifty and on Bitcoin.
    """
    if not {"ema_fast", "ema_slow", "atr"} <= set(frame.columns) or len(frame) < 3:
        return None
    a = float(frame["atr"].iloc[-1])
    if not np.isfinite(a) or a <= 0:
        return None

    spread = frame["ema_fast"] - frame["ema_slow"]
    if ltp is not None:
        # Closed-candle EMAs cannot move between bars, so the angle computed from
        # them sits frozen for the whole candle -- all day on a lagging feed. The
        # live reading projects both averages to the current price, which is the
        # angle the crossover would have if this candle closed now.
        p = params or {}
        fast_now = project_ema(safe_last(frame["ema_fast"]), ltp, int(_p(p, "ema_fast")))
        slow_now = project_ema(safe_last(frame["ema_slow"]), ltp, int(_p(p, "ema_slow")))
        if fast_now is not None and slow_now is not None:
            rate = ((fast_now - slow_now) - float(spread.iloc[-1])) / a
            if np.isfinite(rate):
                return float(abs(np.degrees(np.arctan(rate))))

    rate = float(spread.iloc[-1] - spread.iloc[-2]) / a
    if not np.isfinite(rate):
        return None
    return float(abs(np.degrees(np.arctan(rate))))


def _metric_style() -> None:
    """Large, light metric values, matching the dashboard layout."""
    st.markdown("""
        <style>
        div[data-testid="stMetricValue"] { font-size: 2.0rem; font-weight: 300;
                                           line-height: 1.15; }
        div[data-testid="stMetricLabel"] p { font-size: 0.80rem; font-weight: 400;
                                             opacity: 0.65; }
        div[data-testid="stMetricDelta"] { font-size: 0.85rem; }
        </style>""", unsafe_allow_html=True)


def _time_to_close(cfg: dict, snapshot: LiveSnapshot) -> str:
    """How long until the forming candle closes, in words."""
    bar = INTERVAL_SECONDS.get(cfg.get("interval", "5m"), 300)
    left = bar - float(snapshot.feed_age_seconds or 0.0)
    if not snapshot.last_is_forming or left <= 0:
        return "an unknown amount of time (the feed is lagging, so the newest candle has " \
               "already closed)"
    return f"about {left / 60:.0f} minute(s)" if left >= 60 else f"about {left:.0f} second(s)"


def _market_data_panel(cfg: dict, snapshot: LiveSnapshot) -> None:
    """The market half of the dashboard: price and where the EMAs stand."""
    frame = snapshot.frame
    params = cfg.get("params") or {}
    fast_closed = safe_last(frame["ema_fast"]) if "ema_fast" in frame else None
    slow_closed = safe_last(frame["ema_slow"]) if "ema_slow" in frame else None
    # Projected to the live price, so they move between candles instead of
    # sitting frozen while the market runs.
    fast = project_ema(fast_closed, snapshot.ltp, int(_p(params, "ema_fast"))) or fast_closed
    slow = project_ema(slow_closed, snapshot.ltp, int(_p(params, "ema_slow"))) or slow_closed
    angle = ema_angle_degrees(frame, snapshot.ltp, params)
    cur = cfg["currency"]

    st.markdown("#### \U0001F4C8 Current Market Data")
    c = st.columns(5)
    c[0].metric("Current Price", f"{cur}{fmt(snapshot.ltp)}")
    c[1].metric("Fast EMA", f"{cur}{fmt(fast)}",
                f"closed {fmt(fast_closed)}",
                help="Projected to the live price: where the average would sit if this candle "
                     "closed now. The delta is its value at the last candle close.")
    c[2].metric("Slow EMA", f"{cur}{fmt(slow)}", f"closed {fmt(slow_closed)}")
    c[3].metric("EMA Angle", "--" if angle is None else f"{angle:.2f}\u00b0",
                help="Convergence rate of the EMA pair at the live price, normalised by ATR so "
                     "it means the same thing on Nifty and on Bitcoin. It moves on every tick; "
                     "computed from closed candles alone it would sit frozen until the bar "
                     "closed.")
    # ---- CONFIRMED vs PROJECTED, never merged into one word ----
    #
    # This metric caused three rounds of "the crossover happened and nothing
    # entered". It used to compare the PROJECTED averages -- both pushed to the
    # live price as if this candle had already closed -- and print "Bullish".
    # Meanwhile the strategy, correctly, was reading the CLOSED candles, where
    # the fast average was still below the slow one and no crossover had
    # occurred. The panel said a thing had happened; the engine knew it had not.
    # The engine was right and the panel was lying, so the panel now reports the
    # confirmed state and labels the projection as a projection.
    if fast_closed is None or slow_closed is None:
        c[4].metric("Crossover (confirmed)", "--")
    else:
        gap = float(fast_closed) - float(slow_closed)
        confirmed = "Bullish \u2191" if gap > 0 else "Bearish \u2193"
        c[4].metric("Crossover (confirmed)", confirmed, f"{fmt(gap)} on closed candles",
                    help="Computed from CLOSED candles only \u2014 the same values the strategy "
                         "reads. This is the one that decides whether a signal fires.")

    if fast is not None and slow is not None and fast_closed is not None \
            and slow_closed is not None:
        live_gap = float(fast) - float(slow)
        closed_gap = float(fast_closed) - float(slow_closed)
        if (live_gap > 0) != (closed_gap > 0):
            st.warning(
                f"**The live price has crossed, but the candle has not closed.** Projected to "
                f"{fmt(snapshot.ltp)} the pair reads "
                f"{'bullish' if live_gap > 0 else 'bearish'} ({fmt(live_gap)}), while the "
                f"CLOSED candles still read {'bullish' if closed_gap > 0 else 'bearish'} "
                f"({fmt(closed_gap)}). No signal has fired and none will until a candle closes "
                f"on the new side \u2014 which is the correct behaviour, because an intrabar cross "
                f"that un-crosses before the close is not a crossover. The forming candle has "
                f"{_time_to_close(cfg, snapshot)} to go.")
        else:
            st.caption(
                f"Projected to the live price the pair reads "
                f"{'bullish' if live_gap > 0 else 'bearish'} ({fmt(live_gap)}), which agrees "
                f"with the closed candles. A projection is not a signal \u2014 only a candle close "
                f"can fire one.")

    # Volume, and how it compares with its own average. Shown whenever the feed
    # carries it, so a volume-gated rule can be read rather than guessed at.
    vol = safe_last(frame["Volume"]) if "Volume" in frame else None
    has_volume = float(frame["Volume"].tail(200).abs().sum()) > 0 if "Volume" in frame else False
    v = st.columns(5)
    if has_volume:
        vma = safe_last(sma(frame["Volume"], int(_p(cfg.get("params") or {}, "vol_len"))))
        ratio = (float(vol) / float(vma)) if (vol and vma) else None
        # The requirement shown must be the one actually enforced. When the
        # Volume spike FILTER is on it owns the threshold; the strategy's own
        # vol_mult only applies when it does not. Reading the strategy default
        # while the filter enforced something else displayed "needs 1.50x" to an
        # operator who had set 3x.
        fcfg = (cfg.get("filter_cfg") or {}).get("volspike") or {}
        if fcfg.get("enabled"):
            needed = float(fcfg.get("value", 1.5))
            source = "Volume spike filter"
        else:
            needed = float(_p(cfg.get("params") or {}, "vol_mult"))
            source = "strategy parameter"
        v[0].metric("Candle volume", fmt(vol, 0))
        v[1].metric("Volume average", fmt(vma, 0))
        v[2].metric("Volume x average", f"{fmt(ratio)}x" if ratio else "--",
                    f"needs {fmt(needed)}x" if ratio else None,
                    help=f"Threshold comes from the {source}.")
        v[3].metric("Volume gate", "met" if (ratio and ratio >= needed) else "not met",
                    f"{fmt(float(vma) * needed, 0)} required" if vma else None,
                    help=f"Absolute volume this candle would need: "
                         f"{fmt(float(vma) * needed, 0) if vma else '--'}.")
    else:
        v[0].metric("Candle volume", "not reported",
                    help="Indices and spot FX report no volume on Yahoo, so volume-gated "
                         "rules cannot arm and VWAP degrades to a session TWAP.")
    v[4].metric("Values as of", fmt_time(snapshot.last_closed_time),
                "stale" if snapshot.stale else "current",
                help="Every figure in this row except the price comes from the last CLOSED "
                     "candle. If the feed is lagging, they lag with it.")


def _feed_banner(cfg: dict, snapshot: LiveSnapshot) -> None:
    """Say plainly which of the three states the feed is in."""
    age = snapshot.feed_age_seconds
    human = f"{age/3600:.1f} hours" if age >= 3600 else f"{age/60:.0f} minutes"

    if snapshot.frozen and int(st.session_state.get("live_poll_count", 0)) < QUOTE_EVIDENCE_TICKS:
        st.info(f"Checking whether `{cfg['symbol']}` is actually trading — the candles are "
                f"{human} old, so the engine is watching the quote for movement before it "
                f"commits to an entry. This takes about "
                f"{QUOTE_EVIDENCE_TICKS * cfg['poll_seconds']:.1f}s.")
    elif snapshot.frozen:
        st.error(
            f"**FEED DEAD — the venue looks closed.** The newest candle for `{cfg['symbol']}` is "
            f"{human} old and the quote has not moved across recent ticks. New entries are "
            f"suppressed, because filling at a stale price books a fictitious entry that then "
            f"sits at exactly 0.00 PnL. The engine keeps polling and will pick up the first live "
            f"tick by itself.")
    elif snapshot.stale:
        st.warning(
            f"**Candles are lagging, but the price is live.** The newest `{cfg['symbol']}` candle "
            f"is {human} old while the quote is still ticking — normal for a delayed feed during "
            f"market hours. Trading continues: PnL, stop and target track the live price, but "
            f"SIGNALS are only as fresh as the candles. Shorten the interval for fresher signals.")


def _heartbeat(cfg: dict, snapshot: LiveSnapshot) -> None:
    now = pd.Timestamp.now()
    since_poll = (now - snapshot.fetched_at).total_seconds()
    next_in = max(0.0, float(cfg["poll_seconds"]) - since_poll)

    c = st.columns(6)
    c[0].metric("LTP", fmt(snapshot.ltp), help="Close of the most recent candle on the feed.")
    if snapshot.last_is_forming and np.isfinite(snapshot.next_open):
        c[1].metric("Forming candle open", fmt(snapshot.next_open),
                    fmt_signed(snapshot.ltp - snapshot.next_open),
                    help="The open of the candle currently being built — already printed, not "
                         "a forecast. Shown for reference only; live fills use the LTP, because "
                         "that open has already happened and cannot be traded.")
    else:
        c[1].metric("Forming candle open", "--",
                    help="The newest candle has already closed, so no later candle has opened "
                         "yet. There is nothing to show, and nothing is guessed.")
    c[2].metric("Last Candle", pd.Timestamp(snapshot.last_closed_time).strftime("%d %b %H:%M"),
                help=fmt_time(snapshot.last_closed_time))
    c[3].metric("Candle Age", _human_age(snapshot.feed_age_seconds),
                "FROZEN" if snapshot.stale else "live",
                help="Wall-clock age of the newest candle. This is what tells you whether the "
                     "market is open.")
    c[4].metric("Ticks", f"{st.session_state.live_poll_count:,}",
                f"next in {next_in:0.1f}s",
                help=f"Price ticks. Candle re-downloads so far: "
                     f"{st.session_state.candle_refreshes:,}.")
    c[5].metric("Clock", now.strftime("%H:%M:%S"),
                help="Redraws on every tick. If this is moving, the auto-refresh is alive.")
    st.caption(f"Price source: **{snapshot.ltp_source}** | price ticks every "
               f"{fmt(cfg['poll_seconds'], 1)}s | candles re-downloaded every "
               f"{fmt(cfg.get('candle_seconds', 15), 0)}s | {API_GUARD_DELAY}s minimum spacing "
               f"between requests.")
    if st.session_state.get("ltp_note"):
        st.caption(":warning: " + str(st.session_state.ltp_note))


def _human_age(seconds: float) -> str:
    if seconds < 90:
        return f"{seconds:.0f}s"
    if seconds < 5400:
        return f"{seconds/60:.0f}m"
    if seconds < 172800:
        return f"{seconds/3600:.1f}h"
    return f"{seconds/86400:.1f}d"


def _position_dashboard(position: Position, snapshot, currency: str) -> None:
    ltp = snapshot.ltp if snapshot else position.entry_price
    mgr = position.manager
    points, pnl = position.points(ltp), position.pnl(ltp)
    side = "LONG" if position.direction > 0 else "SHORT"

    st.markdown("#### \U0001F4CA Current Position")
    r1 = st.columns(5)
    r1[0].metric("Type", side, position.strategy.split("\u00b7 ")[-1].strip())
    r1[1].metric("Entry Price", f"{currency}{fmt(position.entry_price)}")
    r1[2].metric("Current Price", f"{currency}{fmt(ltp)}")
    r1[3].metric("Stop Loss", f"{currency}{fmt(mgr.sl)}" if mgr.sl is not None else "none",
                 None if mgr.initial_sl is None else f"from {fmt(mgr.initial_sl)}")
    tgt_label = "Target (display)" if mgr.tp_display_only else "Target"
    r1[4].metric(tgt_label, f"{currency}{fmt(mgr.tp)}" if mgr.tp is not None else "none")

    r2 = st.columns(5)
    r2[0].metric("Quantity", fmt(position.quantity, 0))
    r2[1].metric("Locked Ticker", position.symbol, position.interval)
    r2[2].metric("Current P&L", f"{currency}{fmt_signed(pnl)}", f"{fmt_signed(points)} pts")
    r2[3].metric("Highest Price",
                 f"{currency}{fmt(position.high_since_entry or ltp)}")
    r2[4].metric("Lowest Price",
                 f"{currency}{fmt(position.low_since_entry or ltp)}")

    r3 = st.columns(5)
    locked = None if mgr.sl is None else (mgr.sl - position.entry_price) * position.direction
    r3[0].metric("Locked In by Stop", fmt_signed(locked) if locked is not None else "--",
                 help="Points the stop now guarantees; positive once the trail clears cost.")
    r3[1].metric("Entry Risk", fmt(mgr.risk_points) if mgr.risk_points else "--")
    r3[2].metric("R Multiple", fmt(points / mgr.risk_points) if mgr.risk_points else "--")
    r3[3].metric("Bars Held", f"{mgr.bars_held}")
    r3[4].metric("Best Price", fmt(mgr.mfe),
                 help="Best price in the trade's favour; drives the trailing stop.")

    ref = position.entry_ltp_at_fill
    if ref is not None and np.isfinite(ref):
        slip = position.entry_price - float(ref)
        if abs(slip) > 1e-9:
            st.caption(f"Recorded entry {fmt(position.entry_price)} versus the live price at "
                       f"fill {fmt(ref)} — a gap of {fmt_signed(slip)}. A gap here means the "
                       f"position opened showing PnL it did not earn.")

    (st.success if pnl >= 0 else st.error)(
        f"{side} {position.symbol} :: running {fmt_signed(pnl)} {currency}")
    for note in mgr.notes:
        st.warning("Exit engine: " + note)
    age = position.signal_bars_ago
    st.info(
        f"**Why this position exists** — profile **{position.strategy}**, signal on the candle "
        f"at {fmt_time(position.signal_bar_time)}"
        + (f", which was **{age} candle(s) old** when it was taken" if age else "")
        + f", route: *{position.entry_route}*. A different profile can point the other way on "
        f"the same instrument, and a signal older than the Screener's window can still be "
        f"traded here if the join window allows it — that is the setting to reconcile if the "
        f"two tabs disagree.")
    st.caption(f"Entered {fmt_time(position.entry_time)}."
               + (f" LTP at fill was {fmt(position.entry_ltp_at_fill)}."
                  if position.entry_ltp_at_fill else ""))


# =============================================================================
# SECTION 14d -- ENTRY CONDITION CHECKLIST
# =============================================================================
# Prose explains one blocker at a time; a checklist shows every condition at once
# and, crucially, shows how far away each one is. Two layers are rendered: the
# ENGINE gates (feed, position, filters, signal freshness), which apply to every
# profile, and the STRATEGY conditions for the selected profile.

TICK_YES, TICK_NO, TICK_NA = "\u2705", "\u274c", "\u2796"


@dataclass
class ConditionCheck:
    label: str
    long_ok: bool | None          # None -> not applicable, shown as auto-pass
    short_ok: bool | None
    detail: str = ""
    current: str = ""             # what the parameter reads right now
    need_long: str = ""           # what it would have to read for a LONG
    need_short: str = ""
    gap_long: float | None = None   # points still needed for the LONG side
    gap_short: float | None = None


def _ck(label, long_ok, short_ok, detail="", current="", need_long="", need_short="",
        gap_long=None, gap_short=None):
    return ConditionCheck(label, long_ok, short_ok, detail, current, need_long, need_short,
                          gap_long, gap_short)


def _gap_to_band(value, low, high):
    """
    Distance to the nearest edge of a band, 0.0 when already inside.

    A one-sided comparison is wrong for a zone: price BELOW the band is just as
    far outside it as price above, and reporting the low side as "met" hides a
    condition that is not satisfied at all.
    """
    if value is None or low is None or high is None:
        return None
    try:
        v, lo, hi = float(value), float(low), float(high)
    except (TypeError, ValueError):
        return None
    if not np.isfinite([v, lo, hi]).all():
        return None
    if lo > hi:
        lo, hi = hi, lo
    if v > hi:
        return v - hi
    if v < lo:
        return lo - v
    return 0.0


def _gap(value, target, direction_up: bool):
    """Points still to travel, or 0.0 when already there. None when unknowable."""
    if value is None or target is None:
        return None
    try:
        distance = (float(target) - float(value)) if direction_up else \
            (float(value) - float(target))
    except (TypeError, ValueError):
        return None
    return max(0.0, distance)


def _mark(value) -> str:
    return TICK_NA if value is None else (TICK_YES if value else TICK_NO)


def engine_checks(cfg: dict, snapshot: LiveSnapshot) -> list[ConditionCheck]:
    """The gates the live engine applies regardless of which profile is selected."""
    checks: list[ConditionCheck] = []
    live = bool(snapshot.quote_live)
    checks.append(_ck("Feed alive (quote moving)", live, live,
                      f"source: {snapshot.ltp_source}",
                      current=snapshot.ltp_source,
                      need_long="a moving quote", need_short="a moving quote"))

    flat = st.session_state.live_position is None
    pos = st.session_state.live_position
    checks.append(_ck("No position already open", flat, flat,
                      "one position at a time" if flat else "square off first",
                      current="flat" if flat else
                      f"{'LONG' if pos.direction > 0 else 'SHORT'} {pos.symbol} open",
                      need_long="flat", need_short="flat"))

    for rep in snapshot.filter_reports:
        checks.append(_ck(f"Filter · {rep.label}", rep.long_ok, rep.short_ok, rep.value,
                          current=rep.current or rep.value,
                          need_long=rep.need_long or "filter must allow a long",
                          need_short=rep.need_short or "filter must allow a short"))

    ago = snapshot.recent_signal_bars_ago
    lookback = int(cfg.get("entry_lookback", 0) or 0)
    if snapshot.last_closed_signal != 0:
        fresh = True
        detail = "signal on the newest closed candle"
    elif snapshot.recent_signal != 0 and ago is not None:
        fresh = bool(lookback >= ago > 0)
        detail = (f"last signal {ago} candle(s) ago; catch-up allows {lookback}"
                  if not fresh else f"{ago} candle(s) ago, inside the catch-up window")
    else:
        fresh = False
        detail = "no signal on any recent closed candle"
    side_long = fresh and (snapshot.last_closed_signal == 1 or snapshot.recent_signal == 1)
    side_short = fresh and (snapshot.last_closed_signal == -1 or snapshot.recent_signal == -1)
    checks.append(_ck("Signal fresh enough to act on", side_long, side_short, detail,
                      current=("no recent signal" if snapshot.recent_signal == 0 else
                               f"{'LONG' if snapshot.recent_signal > 0 else 'SHORT'}, "
                               f"{ago} candle(s) ago"),
                      need_long="a LONG signal on the newest closed candle"
                                + (f" (or within {lookback})" if lookback else ""),
                      need_short="a SHORT signal on the newest closed candle"
                                 + (f" (or within {lookback})" if lookback else "")))

    already = st.session_state.get("live_last_signal_time")
    sig_time = snapshot.last_closed_time if snapshot.last_closed_signal != 0 \
        else snapshot.recent_signal_time
    unused = already != sig_time
    checks.append(_ck("Signal not already traded", unused, unused,
                      "fresh" if unused else "this exact signal was already taken",
                      current=fmt_time(already) if already else "none taken yet",
                      need_long="an untraded signal", need_short="an untraded signal"))
    return checks


def next_candle_close(frame: pd.DataFrame, interval: str):
    """When the candle currently forming will close, and how long that is."""
    try:
        last = pd.Timestamp(frame.index[-1])
    except Exception:                                               # noqa: BLE001
        return None, None
    seconds = INTERVAL_SECONDS.get(interval)
    if not seconds:
        return None, None
    closes_at = last + pd.Timedelta(seconds=seconds)
    now = pd.Timestamp.now(tz=last.tz) if last.tz is not None else pd.Timestamp.now()
    return closes_at, float((closes_at - now).total_seconds())


def render_next_step(cfg: dict, snapshot: LiveSnapshot) -> None:
    """
    Answer the only question that matters when nothing has happened: what now?

    An empty screen after pressing Start is indistinguishable from a broken app.
    This states plainly that an entry needs a real signal, and when the next
    chance to produce one arrives.
    """
    closes_at, remaining = next_candle_close(snapshot.frame, cfg["interval"])
    when = ""
    if closes_at is not None and remaining is not None:
        mins, secs = divmod(max(int(remaining), 0), 60)
        when = (f" The candle now forming closes at **{closes_at.strftime('%H:%M:%S')}** "
                f"(~{mins}m {secs}s), and that is the next moment a signal can appear.")

    if snapshot.last_closed_signal != 0:
        st.success("**Next step:** a signal is present on the newest closed candle. The next "
                   "tick will act on it unless a filter or the feed check blocks it.")
    elif snapshot.recent_signal != 0 and snapshot.recent_signal_bars_ago:
        side = "LONG" if snapshot.recent_signal > 0 else "SHORT"
        st.info(f"**Next step:** the last {side} signal was "
                f"{snapshot.recent_signal_bars_ago} candle(s) ago." + when)
    else:
        st.info("**Next step:** this profile has produced no signal on any recent closed "
                "candle, so nothing will be entered." + when +
                " A position is only ever opened from a real signal — that is the whole "
                "difference between a strategy and Simple Buy/Sell, which enter on command.")


def _need(value, target, direction_up: bool) -> str:
    """Human 'needs +X more' for a level that has to be crossed."""
    if value is None or target is None:
        return ""
    gap = (target - value) if direction_up else (value - target)
    return "cleared" if gap <= 0 else f"needs {abs(gap):,.2f} more"


def project_ema(previous: float | None, price: float | None, length: int) -> float | None:
    """
    Where an EMA would sit if the current candle closed at the live price.

    A closed-candle EMA cannot move between candles, so on a slow or lagging feed
    every EMA reading freezes for minutes at a time and the distance to a
    crossover looks static even while price runs. Advancing the average by one
    step at the live price gives a value that moves with the market, which is the
    number you actually want when asking "how far am I from a cross".
    """
    if previous is None or price is None:
        return None
    try:
        prev, px = float(previous), float(price)
    except (TypeError, ValueError):
        return None
    if not (np.isfinite(prev) and np.isfinite(px)) or length <= 0:
        return None
    alpha = 2.0 / (float(length) + 1.0)
    return prev + alpha * (px - prev)


def strategy_checks(name: str, frame: pd.DataFrame, params: dict,
                    ltp: float | None = None) -> list[ConditionCheck]:
    """
    Per-profile conditions, with the distance to each one.

    PRICE comes from the live tick when one is supplied, so the distances move
    on every refresh. LEVELS (EMAs, Fibonacci zones, gaps, boxes) are derived
    from closed candles and legitimately step only at a candle close — except
    the EMAs, which are projected to the live price so a crossover distance is
    not frozen between bars. The actual signal is still evaluated on the closed
    candle; that is what condition "Signal fresh enough to act on" reports.
    """
    def last(col):
        return safe_last(frame[col]) if col in frame.columns else None

    close = last("Close") if ltp is None else float(ltp)
    out: list[ConditionCheck] = []

    if name.startswith(("01 ", "32 ", "34 ")):
        fast_closed, slow_closed = last("ema_fast"), last("ema_slow")
        fast = project_ema(fast_closed, close, int(_p(params, "ema_fast"))) or fast_closed
        slow = project_ema(slow_closed, close, int(_p(params, "ema_slow"))) or slow_closed
        if fast is not None and slow is not None:
            spread = fast - slow
            out.append(_ck("Fast EMA vs slow EMA", spread > 0, spread < 0,
                           f"spread {fmt_signed(spread)}; a cross needs {fmt(abs(spread))} more",
                           current=f"fast {fmt(fast)} / slow {fmt(slow)} at the live price "
                                   f"(spread {fmt_signed(spread)}; at last close "
                                   f"{fmt(fast_closed)} / {fmt(slow_closed)})",
                           need_long=f"fast above slow — {_need(fast, slow, True)}",
                           need_short=f"fast below slow — {_need(fast, slow, False)}",
                           gap_long=_gap(fast, slow, True),
                           gap_short=_gap(fast, slow, False)))
            angle = ema_angle_degrees(frame, close, params)
            if angle is not None:
                out.append(_ck("Crossover angle", True, True, f"{angle:.2f}\u00b0",
                               current=f"{angle:.2f}\u00b0",
                               need_long="no minimum unless the angle filter is on",
                               need_short="no minimum unless the angle filter is on"))
    if name.startswith(("32 ", "30 ", "36 ", "33 ", "31 ")):
        r = last("rsi")
        lo, hi = float(_p(params, "rsi_long_level")), float(_p(params, "rsi_short_level"))
        if r is not None:
            out.append(_ck("RSI level", r >= lo, r <= hi,
                           f"long {_need(r, lo, True)} · short {_need(r, hi, False)}",
                           current=fmt(r),
                           need_long=f"at or above {fmt(lo)} — {_need(r, lo, True)}",
                           need_short=f"at or below {fmt(hi)} — {_need(r, hi, False)}"))
    if name.startswith("08 "):
        r = last("rsi")
        if r is not None:
            out.append(_ck("RSI centerline", r > 50, r < 50,
                           f"{_need(r, 50, True)} to cross up", current=fmt(r),
                           need_long=f"above 50 — {_need(r, 50, True)}",
                           need_short=f"below 50 — {_need(r, 50, False)}"))
    if name.startswith(("25 ", "04 ")):
        d = last("st_dir") if "st_dir" in frame.columns else last("trail_dir")
        if d is not None:
            out.append(_ck("Trend band direction", d == 1, d == -1,
                           "bullish" if d == 1 else "bearish",
                           current="bullish" if d == 1 else "bearish",
                           need_long="bullish band", need_short="bearish band"))
    if name.startswith("05 "):
        hi, lo = last("or_high"), last("or_low")
        out.append(_ck("Opening range break",
                       None if hi is None else close > hi,
                       None if lo is None else close < lo,
                       f"UP {_need(close, hi, True)} · DOWN {_need(close, lo, False)}",
                       current=f"price {fmt(close)}, range {fmt(lo)} - {fmt(hi)}",
                       need_long=f"above {fmt(hi)} — {_need(close, hi, True)}",
                       need_short=f"below {fmt(lo)} — {_need(close, lo, False)}"))
    if name.startswith("47 "):
        expiry = last("is_expiry_day")
        move, a = last("move_from_open"), last("atr")
        need = float(_p(params, "zero_hero_atr")) * (a or 0)
        out.append(_ck("Expiry day", bool(expiry), bool(expiry),
                       "yes" if expiry else "not an expiry weekday",
                       current="expiry day" if expiry else "not an expiry weekday",
                       need_long="an expiry weekday", need_short="an expiry weekday"))
        out.append(_ck("Burst from the session open",
                       (move or 0) >= need, (move or 0) <= -need,
                       f"move {fmt_signed(move)}",
                       current=f"{fmt_signed(move)} from the open",
                       need_long=f"+{fmt(need)} — {_need(move, need, True)}",
                       need_short=f"-{fmt(need)} — {_need(move, -need, False)}"))
    if name.startswith("48 "):
        late = last("is_late_session")
        ratio = last("atr_ratio")
        hi, lo = last("day_high"), last("day_low")
        out.append(_ck("Inside the closing stretch", bool(late), bool(late),
                       "yes" if late else "too early in the session",
                       current="in the closing stretch" if late else "too early",
                       need_long="the closing stretch", need_short="the closing stretch"))
        need_ratio = float(_p(params, "squeeze_mult"))
        out.append(_ck("Volatility expanding",
                       (ratio or 0) >= need_ratio, (ratio or 0) >= need_ratio,
                       f"ATR ratio {fmt(ratio)}", current=f"{fmt(ratio)}x its mean",
                       need_long=f">= {fmt(need_ratio)}x", need_short=f">= {fmt(need_ratio)}x"))
        out.append(_ck("Session range break",
                       None if hi is None else close > hi,
                       None if lo is None else close < lo,
                       f"UP {_need(close, hi, True)} · DOWN {_need(close, lo, False)}",
                       current=f"price {fmt(close)}, range {fmt(lo)} - {fmt(hi)}",
                       need_long=f"above {fmt(hi)} — {_need(close, hi, True)}",
                       need_short=f"below {fmt(lo)} — {_need(close, lo, False)}"))
    if name.startswith(("20 ", "41 ")):
        blo, bhi = last("fvg_bull_lo"), last("fvg_bull_hi")
        slo, shi = last("fvg_bear_lo"), last("fvg_bear_hi")
        bull_ok = None if (blo is None or bhi is None) else (close <= bhi and close >= blo * 0.99)
        bear_ok = None if (slo is None or shi is None) else (close >= slo * 0.99 and close <= shi)
        out.append(_ck(
            "Fair value gap", bull_ok, bear_ok,
            f"bull {fmt(blo)}-{fmt(bhi)} · bear {fmt(slo)}-{fmt(shi)}",
            current=f"price {fmt(close)} | bullish gap {fmt(blo)} - {fmt(bhi)} | "
                    f"bearish gap {fmt(slo)} - {fmt(shi)}",
            need_long=f"price inside the bullish gap {fmt(blo)} - {fmt(bhi)} — "
                      f"{_need(close, bhi, False) if close and bhi else ''}",
            need_short=f"price inside the bearish gap {fmt(slo)} - {fmt(shi)} — "
                       f"{_need(close, slo, True) if close and slo else ''}",
            gap_long=_gap_to_band(close, blo, bhi),
            gap_short=_gap_to_band(close, slo, shi)))

    if name.startswith(("35 ", "36 ", "37 ", "38 ", "39 ", "40 ", "41 ")):
        gh, gl = last("fib_golden_hi"), last("fib_golden_lo")
        up_leg = last("fib_up_leg")
        if gh is not None and gl is not None:
            inside = gl <= (close or 0) <= gh
            out.append(_ck("Fibonacci golden zone",
                           bool(up_leg) and inside, (not up_leg) and inside,
                           f"leg is {'up' if up_leg else 'down'}",
                           current=f"price {fmt(close)}, zone {fmt(gl)} - {fmt(gh)}",
                           need_long=f"a rising leg with price inside {fmt(gl)} - {fmt(gh)}",
                           need_short=f"a falling leg with price inside {fmt(gl)} - {fmt(gh)}",
                           gap_long=_gap_to_band(close, gl, gh),
                           gap_short=_gap_to_band(close, gl, gh)))
    if name.startswith("28 "):
        lvl = last("threshold")
        out.append(_ck("Price threshold",
                       None if lvl is None else close > lvl,
                       None if lvl is None else close < lvl,
                       f"UP {_need(close, lvl, True)} · DOWN {_need(close, lvl, False)}",
                       current=f"price {fmt(close)}, threshold {fmt(lvl)}",
                       need_long=f"above {fmt(lvl)} — {_need(close, lvl, True)}",
                       need_short=f"below {fmt(lvl)} — {_need(close, lvl, False)}",
                       gap_long=_gap(close, lvl, True), gap_short=_gap(close, lvl, False)))
    if name.startswith("29 "):
        up, dn = last("threshold_up"), last("threshold_dn")
        out.append(_ck("Percentage bands",
                       None if up is None else close > up,
                       None if dn is None else close < dn,
                       f"UP {_need(close, up, True)} · DOWN {_need(close, dn, False)}",
                       current=f"price {fmt(close)}, bands {fmt(dn)} - {fmt(up)}",
                       need_long=f"above {fmt(up)} — {_need(close, up, True)}",
                       need_short=f"below {fmt(dn)} — {_need(close, dn, False)}",
                       gap_long=_gap(close, up, True), gap_short=_gap(close, dn, False)))
    if name.startswith("43 "):
        votes_l, votes_s = last("hybrid_long_votes"), last("hybrid_short_votes")
        members = int(last("hybrid_members") or 0)
        need_all = str(params.get("hybrid_logic", "")).startswith("All")
        required = members if need_all else 1
        out.append(_ck("Hybrid member agreement",
                       (votes_l or 0) >= required, (votes_s or 0) >= required,
                       f"{'all' if need_all else 'any one'} of {members}",
                       current=f"long votes {fmt(votes_l, 0)} · short votes {fmt(votes_s, 0)}",
                       need_long=f"{required} long vote(s)",
                       need_short=f"{required} short vote(s)"))
    return out


def render_condition_checklist(cfg: dict, snapshot: LiveSnapshot) -> None:
    """The whole entry gate, one line per condition, with the distance to each."""
    strat = get_strategy(cfg["strategy"])
    engine = engine_checks(cfg, snapshot)
    strategy_side = strategy_checks(cfg["strategy"], snapshot.frame, cfg.get("params") or {},
                                    ltp=snapshot.ltp)
    # Strategy conditions first, then the filters that can veto them, then the
    # engine plumbing. The question being answered is "what does this profile
    # need", so the profile's own conditions belong at the top.
    filters = [c for c in engine if c.label.startswith("Filter \u00b7")]
    plumbing = [c for c in engine if not c.label.startswith("Filter \u00b7")]
    # What the operator configured comes first and on its own; the engine's own
    # housekeeping is real but is not a strategy condition, so it sits apart
    # instead of being interleaved with the settings being reasoned about.
    configured = strategy_side + filters
    checks = configured + plumbing
    long_ready = all(c.long_ok is not False for c in checks)
    short_ready = all(c.short_ok is not False for c in checks)

    headline = (f"**\U0001F3AF {strat.name}** — every condition must hold on the SAME bar "
                f"(`{cfg['symbol']}` · `{cfg['interval']}`)")
    if long_ready or short_ready:
        st.success(headline + f"  \u2192 **{'LONG' if long_ready else 'SHORT'} is ready**")
    else:
        st.info(headline)

    def _lines(items, start=1):
        out_lines = []
        for offset, c in enumerate(items):
            detail = f" — {c.detail}" if c.detail else ""
            out_lines.append(f"- **{start + offset}. {c.label}**: LONG {_mark(c.long_ok)} · "
                             f"SHORT {_mark(c.short_ok)}{detail}")
        return "\n".join(out_lines)

    st.markdown("**Your strategy and filter conditions**")
    st.markdown(_lines(configured) or "- _this profile has no decomposable conditions_")
    blocking = sum(1 for c in plumbing if c.long_ok is False or c.short_ok is False)
    with st.expander(f"Engine checks ({blocking} blocking of {len(plumbing)})", expanded=False):
        st.caption("Housekeeping the engine applies to every profile: is the feed alive, is the "
                   "book flat, is the signal fresh and untraded. Not strategy settings.")
        st.markdown(_lines(plumbing, start=len(configured) + 1))

    # How close each side is, as a bar rather than a paragraph.
    total = len(checks)
    met_long = sum(1 for c in checks if c.long_ok is not False)
    met_short = sum(1 for c in checks if c.short_ok is not False)
    far_long = [c.gap_long for c in checks if c.gap_long not in (None, 0.0)]
    far_short = [c.gap_short for c in checks if c.gap_short not in (None, 0.0)]

    pl, ps = st.columns(2)
    pl.progress(met_long / total if total else 0.0,
                text=f"LONG — {met_long} of {total} conditions met"
                     + (f" · furthest is {fmt(max(far_long))} points away" if far_long else ""))
    ps.progress(met_short / total if total else 0.0,
                text=f"SHORT — {met_short} of {total} conditions met"
                     + (f" · furthest is {fmt(max(far_short))} points away" if far_short else ""))

    st.markdown("##### Required vs current")
    rows = []
    for i, c in enumerate(checks, start=1):
        rows.append({
            "#": i,
            "Parameter": c.label,
            "Current value": c.current or c.detail or "--",
            "Required for LONG": c.need_long or "--",
            "LONG": _mark(c.long_ok),
            "Points to LONG": "--" if c.gap_long is None else
                              ("met" if c.gap_long == 0 else fmt(c.gap_long)),
            "Required for SHORT": c.need_short or "--",
            "SHORT": _mark(c.short_ok),
            "Points to SHORT": "--" if c.gap_short is None else
                               ("met" if c.gap_short == 0 else fmt(c.gap_short)),
        })
    st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
    st.caption("Shown for both directions at all times, whether or not a position is open, so "
               "you can see how far each side is from triggering rather than only learning why "
               "the one that fired did.")

    blocked_long = [c.label for c in checks if c.long_ok is False]
    blocked_short = [c.label for c in checks if c.short_ok is False]
    if blocked_long and blocked_short:
        st.caption(f"Blocking a LONG: {', '.join(blocked_long[:4])}. "
                   f"Blocking a SHORT: {', '.join(blocked_short[:4])}.")
    st.caption(f"{TICK_YES} met · {TICK_NO} not met · {TICK_NA} not applicable to this profile "
               "(treated as met rather than blocking every trade). Price and the distances "
               "update on every tick; EMAs are projected to the live price; zones, gaps and "
               "boxes are drawn from closed candles and step only when a candle closes. The "
               "trade itself still triggers on a closed candle, which is what condition "
               "*Signal fresh enough to act on* reports.")


def _searching_widget(cfg: dict, snapshot: LiveSnapshot) -> None:
    st.markdown("#### Signal Scanner")
    render_next_step(cfg, snapshot)
    render_condition_checklist(cfg, snapshot)
    st.divider()
    blocked = [r for r in snapshot.filter_reports
               if (snapshot.raw_signal == 1 and not r.long_ok)
               or (snapshot.raw_signal == -1 and not r.short_ok)]
    if snapshot.raw_signal != 0 and blocked:
        st.warning("**Signal fired but filters vetoed it** :: blocked by "
                   + ", ".join(f"{r.label} ({r.value})" for r in blocked))
    else:
        st.info(f"**Searching for Signal** :: {snapshot.status.headline}")

    metrics = [("Live LTP", fmt(snapshot.ltp))] + list(snapshot.status.metrics)
    cols = st.columns(min(len(metrics), 5))
    for i, (label, value) in enumerate(metrics):
        cols[i % len(cols)].metric(label, value)
    st.caption("Live LTP comes from the quote feed and updates every tick. The remaining values "
               "are read off the last CLOSED candle, so they step at the candle interval.")

    strat = get_strategy(cfg["strategy"])
    if strat.immediate and snapshot.frozen:
        st.error("This profile enters immediately, but entry is held because the feed is dead. "
                 "It will fill on the first live tick, or enable stale entries in the sidebar "
                 "to override.")

    l, r = st.columns(2)
    l.markdown(f"**Long entry requires**\n\n{snapshot.status.long_condition}")
    r.markdown(f"**Short entry requires**\n\n{snapshot.status.short_condition}")

    risk = cfg["risk"]
    sl_dist, tp_dist = risk.distances(snapshot.ltp)
    e = st.columns(4)
    e[0].metric("If filled now", fmt(snapshot.ltp))
    e[1].metric("Stop would sit at", f"{fmt(snapshot.ltp - sl_dist)} / {fmt(snapshot.ltp + sl_dist)}",
                f"{fmt(sl_dist)} pts — {risk.sl_type}",
                help="Long stop / short stop at the current price.")
    e[2].metric("Target would sit at",
                f"{fmt(snapshot.ltp + tp_dist)} / {fmt(snapshot.ltp - tp_dist)}",
                f"{fmt(tp_dist)} pts — {risk.tp_type}",
                help="Long target / short target at the current price.")
    rr = (tp_dist / sl_dist) if sl_dist else None
    e[3].metric("Reward : risk", fmt(rr) if rr else "--",
                None if not rr or rr >= 1 else "target is smaller than the stop")
    if rr and rr < 0.5:
        st.warning(f"The target is only {fmt(rr)}x the stop. A setup like this needs roughly "
                   f"{100 / (1 + rr):.0f}% accuracy just to break even, which is why a high win "
                   f"rate here is not the same thing as making money.")


def _live_chart(cfg: dict, snapshot: LiveSnapshot) -> None:
    strat = get_strategy(cfg["strategy"])
    params = cfg.get("params") or {}
    st.markdown("#### Live Chart")
    fig = price_chart(
        snapshot.frame, f"{cfg['symbol']} | {cfg['interval']} | last 120 candles",
        strat.overlays, tail=120, hide_weekends=cfg.get("hide_weekends", True), height=520,
        light=True,
        ema_lengths={"fast": _p(params, "ema_fast"), "slow": _p(params, "ema_slow")})

    position = st.session_state.live_position
    if position is not None:
        mgr = position.manager
        # Target above, entry in the middle, stop below: dotted for the levels
        # price has to travel to, dashed for where the position was opened.
        if mgr.tp is not None:
            fig.add_hline(y=mgr.tp, line=dict(width=1.4, dash="dot", color="#06b6d4"),
                          annotation_text="Target" + (" (display)" if mgr.tp_display_only else ""),
                          annotation_position="right",
                          annotation_font=dict(size=10, color="#06b6d4"))
        fig.add_hline(y=position.entry_price, line=dict(width=1.4, dash="dash", color="#26a69a"),
                      annotation_text="Entry", annotation_position="right",
                      annotation_font=dict(size=10, color="#26a69a"))
        if mgr.sl is not None:
            fig.add_hline(y=mgr.sl, line=dict(width=1.4, dash="dot", color="#ef5350"),
                          annotation_text="Stop", annotation_position="right",
                          annotation_font=dict(size=10, color="#ef5350"))
        try:                       # vertical marker at the candle we entered on
            entry_x = pd.Timestamp(position.signal_bar_time)
            if entry_x >= pd.Timestamp(snapshot.frame.index[-120 if len(snapshot.frame) > 120
                                                            else 0]):
                fig.add_vline(x=entry_x, line=dict(width=1, dash="dash", color="#9aa0a6"))
        except Exception:                                           # noqa: BLE001
            pass
    st.plotly_chart(fig, width="stretch", config={"scrollZoom": True})


def _strategy_status_panel(cfg: dict, snapshot: LiveSnapshot) -> None:
    """
    What the strategy and every active filter are doing RIGHT NOW.

    Shown whether or not a position is open: when one is open the scanner is
    hidden, and without this the operator loses all visibility into why the
    engine would or would not take the next trade.
    """
    st.markdown("#### Strategy & Filter Status")
    st.info(f"**{cfg['strategy']}** :: {snapshot.status.headline}")
    metrics = [("Live LTP", fmt(snapshot.ltp))] + list(snapshot.status.metrics)
    cols = st.columns(min(len(metrics), 5))
    for i, (label, value) in enumerate(metrics):
        cols[i % len(cols)].metric(label, value)

    l, r = st.columns(2)
    l.markdown(f"**Long needs**\n\n{snapshot.status.long_condition}")
    r.markdown(f"**Short needs**\n\n{snapshot.status.short_condition}")

    if snapshot.filter_reports:
        rows = [{"Filter": rep.label, "Now": rep.current or rep.value,
                 "Required for long": rep.need_long or "--",
                 "Long": "PASS" if rep.long_ok else "BLOCK",
                 "Required for short": rep.need_short or "--",
                 "Short": "PASS" if rep.short_ok else "BLOCK"}
                for rep in snapshot.filter_reports]
        st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
        blocking = [r["Filter"] for r in rows if r["Long"] == "BLOCK" and r["Short"] == "BLOCK"]
        if blocking:
            st.caption("Currently blocking BOTH directions: " + ", ".join(blocking))
    else:
        st.caption("No entry filters are enabled.")


def _recent_trades() -> None:
    """Closed trades, visible without leaving the tab. Tab 3 stays the full ledger."""
    rows = st.session_state.get("live_trades", [])
    st.markdown("#### Closed Trades This Session")
    if not rows:
        st.caption("Nothing closed yet. Stop-loss and target exits are automatic -- the manual "
                   "square-off is only for emergencies.")
        return
    frame = pd.DataFrame(rows).sort_values("Exit Time", ascending=False).head(8)
    cols = [c for c in ["Exit Time", "Direction", "Entry Price", "Exit Price", "Exit Reason",
                        "Points", "PnL"] if c in frame.columns]
    st.dataframe(frame[cols], width="stretch", hide_index=True)
    st.caption(f"{len(rows)} closed this session. Full history in the Live Trade Log Ledger tab.")


def _feed_diagnostics() -> None:
    """
    Proof of what is actually happening on the wire.

    If 'Polled at' keeps advancing while 'LTP' reports 'no' change, the refresh
    loop is healthy and the data source is the bottleneck.
    """
    log = st.session_state.get("feed_log", [])
    if not log:
        return
    changed = sum(1 for r in log if r["Changed"] == "yes")
    with st.expander(f"Feed diagnostics -- last {len(log)} polls, LTP changed on {changed}"):
        st.dataframe(pd.DataFrame(log), width="stretch", hide_index=True)
        if len(log) >= 8 and changed == 0:
            st.warning("The engine is polling but the price has not moved once. Either the venue "
                       "is closed, or the source is a delayed candle feed that only updates when "
                       "a new candle arrives. Polling faster cannot fix either one -- switch the "
                       "price source to Dhan, or use a 1m interval.")


def _filter_panel(snapshot: LiveSnapshot) -> None:
    if not snapshot.filter_reports:
        return
    with st.expander(f"Active entry filters ({len(snapshot.filter_reports)})", expanded=False):
        rows = [{"Filter": r.label, "Current value": r.value,
                 "Allows long": "yes" if r.long_ok else "NO",
                 "Allows short": "yes" if r.short_ok else "NO"} for r in snapshot.filter_reports]
        st.dataframe(pd.DataFrame(rows), width="stretch", hide_index=True)
        if snapshot.vix is not None:
            st.caption(f"India VIX last read {fmt(snapshot.vix)}.")


def _broker_panel() -> None:
    receipts = st.session_state.get("broker_receipts", [])
    if not receipts:
        return
    with st.expander(f"Broker order receipts ({len(receipts)})"):
        st.dataframe(pd.DataFrame(receipts), width="stretch", hide_index=True)


def _event_feed() -> None:
    events = st.session_state.get("live_events", [])
    with st.expander(f"Operator event feed ({len(events)})", expanded=False):
        if not events:
            st.caption("No events yet.")
        for e in events[:80]:
            st.write(f"`{e['time']}` {e['message']}")


