# =============================================================================
# SECTION 19e -- EXPIRY CALENDAR AND GAMMA BLAST SCREENER
# =============================================================================
# Indian expiry conventions differ by instrument, which is the whole point of
# this screener:
#   * INDICES expire WEEKLY, so the setup is judged on the expiry day itself.
#   * STOCKS and FUTURES expire MONTHLY on the last <weekday> of the month, so
#     "ten days after expiry" means roughly twenty days before the next one --
#     the stretch where a fresh series has open interest but no expiry pressure.
#
# HOLIDAYS ARE NOT MODELLED. When an expiry falls on a trading holiday the
# exchange moves it a day earlier, and there is no free holiday calendar wired
# in here. Every date below can therefore be a day out around holidays, which is
# why the windows are configurable rather than fixed.


def monthly_expiry(year: int, month: int, weekday: int = 3) -> "datetime.date":
    """Last `weekday` of the month (Monday=0 ... Sunday=6; Thursday=3)."""
    import calendar as _calendar
    last_day = _calendar.monthrange(year, month)[1]
    day = last_day
    while datetime(year, month, day).weekday() != weekday:
        day -= 1
    return datetime(year, month, day).date()


def last_monthly_expiry(on_date, weekday: int = 3):
    """The most recent monthly expiry on or before `on_date`."""
    d = pd.Timestamp(on_date).date()
    this_month = monthly_expiry(d.year, d.month, weekday)
    if this_month <= d:
        return this_month
    year, month = (d.year - 1, 12) if d.month == 1 else (d.year, d.month - 1)
    return monthly_expiry(year, month, weekday)


def days_since_monthly_expiry(on_date, weekday: int = 3) -> int:
    d = pd.Timestamp(on_date).date()
    return (d - last_monthly_expiry(d, weekday)).days


def days_to_weekly_expiry(on_date, weekday: int = 3) -> int:
    """Days until the next weekly expiry; 0 means today IS expiry day."""
    d = pd.Timestamp(on_date).date()
    return (weekday - d.weekday()) % 7


def looks_like_index(symbol: str) -> bool:
    t = (symbol or "").upper()
    return t.startswith("^") or t in {"NIFTY_FIN_SERVICE.NS"} or "NIFTY" in t or "SENSEX" in t


def expiry_gate(symbol: str, on_date, cfg: dict) -> tuple[bool, str]:
    """
    Is this instrument inside its configured expiry window?

    Returns ``(passes, description)`` so a row can explain itself even when it
    fails.
    """
    kind = cfg.get("kind", "Auto")
    is_index = looks_like_index(symbol) if kind == "Auto" else kind.startswith("Index")
    if is_index:
        to_expiry = days_to_weekly_expiry(on_date, int(cfg.get("weekly_weekday", 3)))
        limit = int(cfg.get("index_days", 0))
        return to_expiry <= limit, (f"index · {to_expiry}d to weekly expiry "
                                    f"(window <= {limit})")
    since = days_since_monthly_expiry(on_date, int(cfg.get("monthly_weekday", 3)))
    lo, hi = int(cfg.get("stock_min_days", 8)), int(cfg.get("stock_max_days", 12))
    return lo <= since <= hi, (f"stock · {since}d since monthly expiry "
                               f"(window {lo}-{hi})")


def nearest_strike(price: float, step: float) -> float:
    if not step or step <= 0 or not np.isfinite(price):
        return float("nan")
    return round(float(price) / float(step)) * float(step)


def auto_strike_step(price: float) -> float:
    """A sane strike interval for a price, when the operator has not set one."""
    for ceiling, step in ((200, 2.5), (500, 5), (1000, 10), (2500, 20), (5000, 50),
                          (15000, 50), (30000, 100)):
        if price <= ceiling:
            return step
    return 100.0


def dhan_option_chain(broker: dict, underlying_scrip: int, underlying_seg: str,
                      expiry: str) -> dict:
    """
    One option-chain snapshot from DhanHQ.

    Returns ``{strike: {"ce_oi":..., "pe_oi":..., "ce_volume":..., "pe_volume":...}}``
    or an empty dict. Never raises into a scan.
    """
    token = str(broker.get("access_token", "")).strip()
    client = str(broker.get("client_id", "")).strip()
    if not (token and client and expiry):
        return {}
    import requests
    try:
        resp = requests.post(f"{DHAN_BASE}/optionchain",
                             headers={"Content-Type": "application/json",
                                      "Accept": "application/json",
                                      "access-token": token, "client-id": client},
                             data=json.dumps({"UnderlyingScrip": int(underlying_scrip),
                                              "UnderlyingSeg": underlying_seg,
                                              "Expiry": str(expiry)}), timeout=20)
        body = resp.json()
    except Exception:                                               # noqa: BLE001
        return {}
    if resp.status_code >= 400:
        return {}
    chain = ((body.get("data") or {}).get("oc")) or {}
    out: dict[float, dict] = {}
    for strike, legs in chain.items():
        try:
            k = float(strike)
        except (TypeError, ValueError):
            continue
        ce, pe = (legs or {}).get("ce") or {}, (legs or {}).get("pe") or {}
        out[k] = {"ce_oi": _num(ce, "oi"), "pe_oi": _num(pe, "oi"),
                  # Dhan returns the PREVIOUS session's open interest alongside
                  # today's. That makes the day's OI change readable from a
                  # SINGLE call, which is the difference between this panel
                  # working now and it sitting blank until two snapshots have
                  # been collected minutes apart. Waiting for two samples was
                  # never necessary for the day change; it is only necessary for
                  # the intraday delta, which is kept separately below.
                  "ce_prev_oi": _num(ce, "previous_oi"),
                  "pe_prev_oi": _num(pe, "previous_oi"),
                  "ce_volume": _num(ce, "volume"), "pe_volume": _num(pe, "volume"),
                  "ce_ltp": _num(ce, "last_price"), "pe_ltp": _num(pe, "last_price"),
                  # Per-leg implied volatility. This is what makes an expected
                  # move computable for a SINGLE STOCK: India VIX prices Nifty
                  # options and says nothing about one company, but a stock's
                  # own chain prices that company directly.
                  "ce_iv": _num(ce, "implied_volatility"),
                  "pe_iv": _num(pe, "implied_volatility")}
    return out


def _num(leg: dict, key: str) -> float:
    """
    One numeric field from an option-chain leg, under any of its spellings.

    Dhan has shipped more than one casing for these keys, and a field read under
    the wrong spelling silently becomes zero -- which looks exactly like "no
    open interest" rather than "wrong key". NaN is returned for genuinely
    missing data so a blank stays visibly blank instead of pretending to be 0.
    """
    parts = key.split("_")
    camel = parts[0] + "".join(p.title() for p in parts[1:])
    for candidate in (key, key.upper(), key.replace("_", ""), camel,
                      "".join(p.title() for p in parts)):
        if candidate in (leg or {}):
            try:
                return float(leg[candidate])
            except (TypeError, ValueError):
                return float("nan")
    return float("nan")


def atm_implied_vol(broker: dict, ticker: str, spot: float) -> tuple[float | None, str]:
    """
    At-the-money implied volatility from the instrument's OWN option chain.

    This is the right volatility input for a single stock, and the reason the
    question "should India VIX be used for Indian stocks?" has a clear answer:
    no. India VIX is computed from NIFTY option prices. It describes the index
    and nothing else, so applying it to one company borrows a number that was
    never about that company. The stock's own chain prices the stock.

    The call and put IV at the nearest strike are averaged, because the two
    differ by skew and neither alone is "the" implied volatility. Returns
    ``(iv_percent, note)`` and never raises.
    """
    if not (str(broker.get("access_token", "")).strip()
            and str(broker.get("client_id", "")).strip()):
        return None, "no Dhan credentials"
    resolved = option_chain_underlying(ticker)
    if resolved is None:
        return None, "no option series in the Dhan master for this name"
    scrip, segment, expiry = resolved
    chain = dhan_option_chain(broker, scrip, segment, expiry)
    if not chain:
        return None, f"chain request returned nothing for {expiry}"

    try:
        strike = min(chain, key=lambda k: abs(float(k) - float(spot)))
    except (TypeError, ValueError):
        return None, "no usable strikes in the chain"
    leg = chain.get(strike) or {}
    values = [leg.get("ce_iv"), leg.get("pe_iv")]
    usable = [float(v) for v in values
              if v is not None and np.isfinite(v) and 0 < float(v) < 500]
    if not usable:
        return None, f"the chain carried no implied volatility at strike {fmt(strike, 0)}"
    return (sum(usable) / len(usable),
            f"ATM strike {fmt(strike, 0)}, expiry {expiry}, "
            f"{'CE+PE averaged' if len(usable) > 1 else 'one leg only'}")


def record_oi_snapshot(ticker: str, chain: dict) -> None:
    """
    Keep a short history of chain snapshots so OI CHANGE can be measured.

    No free source publishes historical open interest, so "OI is falling" can
    only ever be observed from the moment this app starts watching. That is a
    real limitation, not a temporary one: before the first two snapshots exist
    the short-covering test simply cannot be answered.
    """
    if st is None or not chain:
        return
    store = st.session_state.setdefault("oi_snapshots", {})
    series = store.setdefault(ticker, [])
    series.append({"at": pd.Timestamp.now(), "chain": chain})
    del series[:-40]                       # a rolling window, not a database


def option_chain_underlying(ticker: str) -> tuple[int, str, str] | None:
    """
    Resolve a ticker to ``(underlying_security_id, underlying_segment, expiry)``
    for Dhan's option-chain endpoint, using the instrument master.

    This is the piece that was missing, and the reason a Dhan token changed
    nothing for the Gamma Blast scan: the scan never asked for a chain. Open
    interest was only reachable by typing a security id, a segment and an expiry
    date into a panel, by hand, one ticker at a time -- so the OI half of the
    setup was permanently untested no matter what credentials were supplied.

    Returns ``None`` when the master has no option series for the name, which is
    the truthful answer for a stock with no listed options.
    """
    name = _default_underlying(ticker)
    if not name:
        return None
    try:
        master = st.session_state.get("scrip_master") if st is not None else None
        if master is None or getattr(master, "empty", True):
            master = load_scrip_master()
            if st is not None:
                st.session_state.scrip_master = master
    except Exception:                                               # noqa: BLE001
        return None

    hit = master[(master["name"].fillna("") == name) |
                 (master["trading_symbol"].fillna("").str.startswith(name))]
    if hit.empty:
        return None
    options = hit[hit["instrument"].fillna("").str.contains("OPT", na=False)]
    if options.empty:
        return None
    expiry = _nearest_expiry(options)
    if expiry is None:
        return None

    # The chain is keyed by the UNDERLYING, not by an option contract: an index
    # on IDX_I, a stock on its cash segment.
    if looks_like_index(ticker):
        under = hit[hit["instrument"].fillna("").str.contains("INDEX", na=False)]
        segment = "IDX_I"
    else:
        under = hit[hit["instrument"].fillna("").str.contains("EQUITY", na=False)]
        segment = "NSE_EQ"
    if under.empty:
        return None
    try:
        scrip = int(str(under.iloc[0]["security_id"]).strip())
    except (TypeError, ValueError):
        return None
    return scrip, segment, f"{pd.Timestamp(expiry):%Y-%m-%d}"


def sample_chain_for(broker: dict, ticker: str) -> tuple[dict, str]:
    """
    Fetch and store one chain snapshot for a ticker, resolving everything itself.

    Returns ``(chain, note)``. The note explains any failure in the row rather
    than leaving a blank column the operator has to guess about.
    """
    if not (str(broker.get("access_token", "")).strip()
            and str(broker.get("client_id", "")).strip()):
        return {}, "no Dhan token"
    resolved = option_chain_underlying(ticker)
    if resolved is None:
        return {}, "no option series in the Dhan master"
    scrip, segment, expiry = resolved
    chain = dhan_option_chain(broker, scrip, segment, expiry)
    if not chain:
        return {}, f"chain request returned nothing for {expiry} ({segment} {scrip})"
    record_oi_snapshot(ticker, chain)
    return chain, f"chain sampled for expiry {expiry}"


def oi_change_at(ticker: str, strike: float) -> dict:
    """
    Open interest at one strike, and how it has changed -- two different
    changes, because they answer two different questions.

    DAY change comes straight from the broker: Dhan serves the previous
    session's open interest next to today's, so this is readable from the FIRST
    call and needs no history at all. Waiting for two snapshots before showing
    anything was the reason this panel stayed blank with a valid token.

    INTRADAY change is the delta between snapshots this app has taken itself.
    That one genuinely does need two samples, because no source publishes an
    intraday open-interest history.
    """
    store = (st.session_state.get("oi_snapshots") or {}) if st is not None else {}
    series = store.get(ticker) or []
    out: dict = {"samples": len(series)}
    if not series:
        return out

    last = (series[-1].get("chain") or {}).get(strike)
    if last:
        out.update({"ce_oi": last.get("ce_oi"), "pe_oi": last.get("pe_oi"),
                    "ce_volume": last.get("ce_volume"), "pe_volume": last.get("pe_volume"),
                    "ce_prev_oi": last.get("ce_prev_oi"), "pe_prev_oi": last.get("pe_prev_oi")})
        for side in ("ce", "pe"):
            now, prev = last.get(f"{side}_oi"), last.get(f"{side}_prev_oi")
            if now is not None and prev is not None \
                    and np.isfinite(now) and np.isfinite(prev) and prev > 0:
                out[f"{side}_day_change"] = float(now) - float(prev)

    if len(series) >= 2:
        first = (series[0].get("chain") or {}).get(strike)
        if first and last:
            for side in ("ce", "pe"):
                a, b = first.get(f"{side}_oi"), last.get(f"{side}_oi")
                if a is not None and b is not None and np.isfinite(a) and np.isfinite(b):
                    out[f"{side}_oi_change"] = float(b) - float(a)
            out["minutes"] = (series[-1]["at"] - series[0]["at"]).total_seconds() / 60.0
    return out


def gamma_blast_scan_one(ticker: str, interval: str, gcfg: dict, params: dict,
                         broker: dict | None = None) -> dict:
    """
    Evaluate one ticker for the setup, and ALWAYS return a row.

    Two changes from the version that reported zero signals forever.

    First, open interest is now fetched. The scan resolves the underlying and
    the nearest expiry from the Dhan instrument master and calls the chain
    endpoint itself, so a supplied token actually does something. Before this,
    OI could only arrive by typing a security id into a panel by hand, which
    meant the OI conditions were untestable in a scan and the setup could never
    complete.

    Second, a ticker that is not near its level is no longer dropped. Dropping
    it produced an empty table and a bare "0", which is indistinguishable from
    the scan being broken -- and it hid the one number needed to fix it, the
    distance to the level. Every ticker now comes back with its measurements and
    a per-condition verdict, and the caller filters.
    """
    period, _ = lab_period_for(interval, WARMUP_BARS + 40)
    bundle = load_market_data(ticker, period, interval, freshness_seconds=300, min_bars=60)
    frame = bundle.frame
    look = int(gcfg.get("level_lookback", 60))
    if len(frame) <= look + 5:
        # Genuinely unmeasurable: say so as a row rather than vanishing.
        return {"Ticker": ticker, "Timeframe": interval, "Side": "-",
                "Conditions met": "0 of 4", "All met": "no",
                "Why not": f"only {len(frame)} candles; the level lookback needs "
                           f"{look + 6}", "Checked at": pd.Timestamp.now()}

    close = float(frame["Close"].iloc[-1])
    resistance = float(frame["High"].iloc[-(look + 1):-1].max())
    support = float(frame["Low"].iloc[-(look + 1):-1].min())
    prox = float(gcfg.get("proximity_pct", 1.0)) / 100.0

    d_res = abs(close - resistance) / resistance * 100.0 if resistance else float("inf")
    d_sup = abs(close - support) / support * 100.0 if support else float("inf")
    near_res = abs(close - resistance) <= resistance * prox
    near_sup = abs(close - support) <= support * prox
    # When both are in range, the nearer one decides the side.
    if near_res and near_sup:
        near_res, near_sup = (d_res <= d_sup), (d_sup < d_res)
    near_level = bool(near_res or near_sup)

    vol_ma = float(sma(frame["Volume"], int(gcfg.get("vol_len", 20))).iloc[-1] or 0)
    vol_now = float(frame["Volume"].iloc[-1])
    vol_ratio = (vol_now / vol_ma) if vol_ma else float("nan")
    has_volume = float(frame["Volume"].tail(100).abs().sum()) > 0

    mom_bars = int(gcfg.get("momentum_bars", 5))
    past = float(frame["Close"].iloc[-(mom_bars + 1)])
    momentum_pct = (close - past) / past * 100.0 if past else 0.0

    # Side: the level being pressed, or -- when neither is close -- whichever is
    # nearer, so the row is still readable.
    leaning_up = near_res or (not near_level and d_res <= d_sup)
    side = "BULLISH (CE)" if leaning_up else "BEARISH (PE)"
    level = resistance if leaning_up else support
    direction_ok = (momentum_pct >= float(gcfg.get("momentum_pct", 0.2))) if leaning_up else \
                   (momentum_pct <= -float(gcfg.get("momentum_pct", 0.2)))
    # Indices publish no volume on Yahoo, so a volume gate there would reject
    # every index for a reason that has nothing to do with the market.
    vol_ok = (not has_volume) or (np.isfinite(vol_ratio)
                                  and vol_ratio >= float(gcfg.get("vol_mult", 1.5)))

    last_date = pd.Timestamp(frame.index[-1])
    exp_ok, exp_note = expiry_gate(ticker, last_date, gcfg)

    step = float(gcfg.get("strike_step", 0) or 0) or auto_strike_step(level)
    strike = nearest_strike(level, step)

    # ---- open interest, fetched rather than waited for ----
    chain_note = "Dhan data not enabled"
    if gcfg.get("use_chain") and broker:
        _chain, chain_note = sample_chain_for(broker, ticker)
    oi = oi_change_at(ticker, strike)
    watched = int(oi.get("samples", 0))
    ce_oi, pe_oi = oi.get("ce_oi"), oi.get("pe_oi")
    leg = "CE" if leaning_up else "PE"
    day_change = oi.get(f"{leg.lower()}_day_change")
    intra_change = oi.get(f"{leg.lower()}_oi_change")

    # The DAY change decides the condition, because it is available on the very
    # first call. The intraday delta refines it once two snapshots exist; it is
    # no longer a precondition for saying anything at all.
    change = intra_change if intra_change is not None else day_change
    if change is not None and np.isfinite(change):
        oi_ok = change <= -abs(float(gcfg.get("oi_drop", 0.0)))
        basis = (f"intraday, over {fmt(oi.get('minutes'), 0)}m" if intra_change is not None
                 else "vs the previous session's close")
        oi_note = f"{leg} OI change {fmt(change, 0)} ({basis})"
        if intra_change is not None and day_change is not None:
            oi_note += f"; day change {fmt(day_change, 0)}"
    else:
        oi_ok = None                       # unknown, not false
        oi_note = (f"no open-interest reading at strike {fmt(strike, 0)} — {chain_note}"
                   if watched else f"no chain fetched — {chain_note}")

    conditions = {"Near level": near_level, "Volume surge": bool(vol_ok),
                  "Momentum": bool(direction_ok), "Expiry window": bool(exp_ok)}
    if oi_ok is not None:
        conditions["OI falling (short covering)"] = bool(oi_ok)
    met = sum(1 for v in conditions.values() if v)
    failing = [name for name, passed in conditions.items() if not passed]

    return {
        "Ticker": ticker, "Timeframe": interval, "Side": side,
        "Spot": round(close, 2), "Level": round(level, 2),
        "Distance %": round(abs(close - level) / level * 100.0, 3) if level else None,
        "Proximity needed %": float(gcfg.get("proximity_pct", 1.0)),
        "Resistance": round(resistance, 2), "Support": round(support, 2),
        "Strike": strike, "Strike step": step,
        "Volume x": None if not has_volume else round(float(vol_ratio), 2),
        "Volume needed": float(gcfg.get("vol_mult", 1.5)),
        "Momentum %": round(momentum_pct, 3),
        "Momentum needed": float(gcfg.get("momentum_pct", 0.2)),
        "Expiry": exp_note, "Expiry ok": "yes" if exp_ok else "no",
        "CE OI": ce_oi, "CE OI day change": oi.get("ce_day_change"),
        "CE OI intraday change": oi.get("ce_oi_change"),
        "PE OI": pe_oi, "PE OI day change": oi.get("pe_day_change"),
        "PE OI intraday change": oi.get("pe_oi_change"),
        "OI state": oi_note,
        "Near level": "yes" if near_level else "no",
        "Conditions met": f"{met} of {len(conditions)}",
        "Met count": met, "Of count": len(conditions),
        "All met": "yes" if met == len(conditions) else "no",
        "Why not": ", ".join(failing) if failing else "-",
        "Checked at": pd.Timestamp.now(),
    }


# Open-interest series colours. Two categorical hues, validated for the
# lightness band, chroma floor, CVD separation (protan dE 26.0, tritan 25.9),
# normal-vision separation and 3:1 contrast against BOTH the dark and light
# chart surfaces. They are also direct-labelled below, so identity never rests
# on colour alone.
_OI_CE, _OI_PE = "#3d87e8", "#cc7a33"


def numbers_minutes(times: list) -> float:
    """Minutes spanned by a list of snapshot timestamps."""
    if len(times) < 2:
        return 0.0
    return float((pd.Timestamp(times[-1]) - pd.Timestamp(times[0])).total_seconds() / 60.0)


def gamma_blast_detail(ticker: str, interval: str, gcfg: dict, strike: float,
                       light: bool = False):
    """
    The evidence behind one candidate, as three stacked panels.

    Price, volume and open interest are three different scales, so they get
    three panels sharing one time axis rather than two y-axes on one plot. A
    dual-axis chart lets the author slide one series against the other until
    they appear to agree, which is precisely the claim being tested here --
    whether price, volume and OI are actually moving together.

    Returns ``(figure, numbers)`` where ``numbers`` holds the absolute values
    behind every panel, because "volume is up 1.8x" is not checkable and
    "412,300 against a 20-candle average of 229,100" is.
    """
    import plotly.graph_objects as go
    from plotly.subplots import make_subplots

    period, _ = lab_period_for(interval, WARMUP_BARS + 40)
    frame = load_market_data(ticker, period, interval,
                             freshness_seconds=120, min_bars=30).frame
    tail = frame.tail(int(gcfg.get("chart_bars", 160)))
    look = int(gcfg.get("level_lookback", 60))
    vol_len = int(gcfg.get("vol_len", 20))

    resistance = float(frame["High"].iloc[-(look + 1):-1].max())
    support = float(frame["Low"].iloc[-(look + 1):-1].min())
    vol_avg = sma(frame["Volume"], vol_len)
    has_volume = float(frame["Volume"].tail(100).abs().sum()) > 0

    snaps = ((st.session_state.get("oi_snapshots") or {}) if st is not None else {}).get(ticker) or []
    times = [pd.Timestamp(s["at"]) for s in snaps]
    ce_series = [float((s["chain"].get(strike) or {}).get("ce_oi", float("nan")))
                 for s in snaps]
    pe_series = [float((s["chain"].get(strike) or {}).get("pe_oi", float("nan")))
                 for s in snaps]
    has_oi = bool(snaps) and any(np.isfinite(v) for v in ce_series + pe_series)

    rows = 3 if has_oi else 2
    heights = [0.56, 0.22, 0.22] if has_oi else [0.72, 0.28]
    titles = ["Price", f"Volume (bars) and {vol_len}-candle average (line)"]
    if has_oi:
        titles.append(f"Open interest at strike {fmt(strike, 0)} — CE and PE, contracts")
    fig = make_subplots(rows=rows, cols=1, shared_xaxes=True, vertical_spacing=0.075,
                        row_heights=heights, subplot_titles=titles)
    # Left-align the panel titles to match the rest of the application, and to
    # stop them colliding with the level annotations in the middle of the plot.
    for note in fig.layout.annotations:
        note.update(x=0, xanchor="left", font=dict(size=12))

    fig.add_trace(go.Candlestick(
        x=tail.index, open=tail["Open"], high=tail["High"], low=tail["Low"],
        close=tail["Close"], name="Price",
        increasing_line_color=_UP, decreasing_line_color=_DOWN,
        increasing_fillcolor=_UP, decreasing_fillcolor=_DOWN,
        line=dict(width=1), showlegend=False), row=1, col=1)
    # Scale the price panel to the CANDLES, then draw only the levels that fit.
    #
    # A strike several hundred points away from the market -- which is normal
    # when the level lookback reaches back over a trend -- used to stretch the
    # y-axis to cover it, squashing every candle into a strip at the bottom of
    # an empty panel. The chart became unreadable because of one dashed line.
    lo, hi = float(tail["Low"].min()), float(tail["High"].max())
    pad = max((hi - lo) * 0.08, hi * 0.002)
    y_lo, y_hi = lo - pad, hi + pad
    off_chart = []
    for level, label, colour in ((resistance, "Resistance", _DOWN), (support, "Support", _UP),
                                 (strike, "Strike", "#8d99ae")):
        if not np.isfinite(level):
            continue
        if y_lo <= level <= y_hi:
            fig.add_hline(y=level, line=dict(width=1.2, dash="dot", color=colour),
                          annotation_text=f"{label} {fmt(level)}",
                          annotation_position="top left", row=1, col=1)
        else:
            # Keep the level honest without letting it wreck the scale: pin it
            # to the edge it lies beyond and say how far away it really is.
            edge = y_hi if level > y_hi else y_lo
            away = abs(level - float(tail['Close'].iloc[-1]))
            fig.add_annotation(x=1, xref="x domain", y=edge, yanchor="top" if level > y_hi
                               else "bottom", xanchor="right", showarrow=False,
                               text=f"{label} {fmt(level)} — {fmt(away)} away, off-chart",
                               font=dict(size=10, color=colour), row=1, col=1)
            off_chart.append(label)
    fig.update_yaxes(range=[y_lo, y_hi], row=1, col=1)

    if has_volume:
        rising = tail["Close"].to_numpy() >= tail["Open"].to_numpy()
        fig.add_trace(go.Bar(x=tail.index, y=tail["Volume"], name="Volume",
                             marker=dict(color=np.where(rising, _UP, _DOWN),
                                         line=dict(width=0)),
                             opacity=0.55, showlegend=False,
                             hovertemplate="%{x}<br>Volume %{y:,.0f}<extra></extra>"),
                      row=2, col=1)
        fig.add_trace(go.Scatter(x=tail.index, y=vol_avg.reindex(tail.index),
                                 name=f"{vol_len}-candle average", mode="lines",
                                 line=dict(width=2, color="#e9c46a"), showlegend=False,
                                 hovertemplate="%{x}<br>Average %{y:,.0f}<extra></extra>"),
                      row=2, col=1)
    else:
        fig.add_annotation(text="This instrument reports no volume on Yahoo",
                           xref="x domain", yref="y2 domain", x=0.5, y=0.5,
                           showarrow=False, row=2, col=1)

    if has_oi:
        for values, label, colour in ((ce_series, "CE OI", _OI_CE),
                                      (pe_series, "PE OI", _OI_PE)):
            fig.add_trace(go.Scatter(
                x=times, y=values, name=label, mode="lines+markers",
                line=dict(width=2, color=colour), marker=dict(size=8, color=colour),
                hovertemplate="%{x}<br>" + label + " %{y:,.0f}<extra></extra>"),
                row=3, col=1)
            if len(times):
                fig.add_annotation(x=times[-1], y=values[-1], text=f" {label}",
                                   showarrow=False, xanchor="left",
                                   font=dict(size=11), row=3, col=1)

    # The window open interest was actually observed over, marked on the price
    # and volume panels too. Without it the OI panel covers an hour while the
    # others cover two days, and the eye compares a rising price across the
    # whole chart against an OI fall that only happened at the very end. The
    # question is whether they moved together IN THE SAME WINDOW, so the window
    # is drawn on all three.
    if has_oi and len(times) > 1:
        for r in (1, 2):
            fig.add_vrect(x0=times[0], x1=times[-1], row=r, col=1,
                          fillcolor="rgba(128,128,128,0.16)", line_width=0, layer="below")
        fig.add_annotation(x=times[0], y=1, yref="y domain", xanchor="left", yanchor="bottom",
                           text=f"open interest observed here ({fmt(numbers_minutes(times), 0)}"
                                f" min)", showarrow=False, font=dict(size=10), row=1, col=1)

    fig.update_layout(
        height=760 if has_oi else 620, margin=dict(l=62, r=92, t=54, b=44),
        hovermode="x unified", dragmode="pan", bargap=0.15,
        legend=dict(orientation="h", yanchor="bottom", y=1.03, xanchor="right", x=1),
        template="plotly_white" if light else None,
        title=dict(text=f"{ticker} · {interval} · last {len(tail)} candles",
                   x=0.01, xanchor="left", font=dict(size=15)))
    fig.update_xaxes(rangeslider_visible=False, showgrid=False)
    fig.update_yaxes(showgrid=True, gridcolor="rgba(128,128,128,0.15)")
    if not (ticker.endswith("-USD") or ticker.endswith("=X")):
        fig.update_xaxes(rangebreaks=[dict(bounds=["sat", "mon"])])

    last_vol = float(tail["Volume"].iloc[-1]) if has_volume else float("nan")
    avg_vol = float(vol_avg.iloc[-1]) if has_volume else float("nan")
    numbers = {
        "price": float(tail["Close"].iloc[-1]),
        "prev_price": float(tail["Close"].iloc[-2]) if len(tail) > 1 else float("nan"),
        "resistance": resistance, "support": support, "strike": strike,
        "volume": last_vol, "avg_volume": avg_vol, "vol_len": vol_len,
        "vol_multiple": (last_vol / avg_vol) if (has_volume and avg_vol) else float("nan"),
        "has_volume": has_volume, "snapshots": len(snaps),
        "ce_oi": ce_series[-1] if ce_series else float("nan"),
        "pe_oi": pe_series[-1] if pe_series else float("nan"),
        "ce_oi_change": (ce_series[-1] - ce_series[0]) if len(ce_series) > 1 else float("nan"),
        "pe_oi_change": (pe_series[-1] - pe_series[0]) if len(pe_series) > 1 else float("nan"),
        "minutes": ((times[-1] - times[0]).total_seconds() / 60.0) if len(times) > 1 else 0.0,
        # The day change needs no history at all -- the broker serves the
        # previous session's open interest next to today's.
        "ce_day_change": _leg_day_change(snaps, strike, "ce"),
        "pe_day_change": _leg_day_change(snaps, strike, "pe"),
    }
    return fig, numbers


def _leg_day_change(snaps: list, strike: float, side: str) -> float:
    """Today's open interest minus the previous session's, from the newest snapshot."""
    if not snaps:
        return float("nan")
    leg = (snaps[-1].get("chain") or {}).get(strike) or {}
    now, prev = leg.get(f"{side}_oi"), leg.get(f"{side}_prev_oi")
    try:
        if now is None or prev is None or not (np.isfinite(now) and np.isfinite(prev)):
            return float("nan")
        return float(now) - float(prev)
    except (TypeError, ValueError):
        return float("nan")


def oi_verdict(numbers: dict, side: str) -> tuple[str, str]:
    """
    Name what the three series are doing together, or say it cannot be told.

    Short covering and long unwinding both show OI FALLING; what separates them
    is which way price is going and which leg is being closed. Guessing between
    them from OI alone is the mistake this spells out.
    """
    price_up = numbers["price"] > numbers.get("prev_price", numbers["price"])
    vol_up = (np.isfinite(numbers["vol_multiple"]) and numbers["vol_multiple"] >= 1.0)
    bullish = side.startswith("BULL")
    leg = "CE" if bullish else "PE"
    intra = numbers.get("ce_oi_change" if bullish else "pe_oi_change", float("nan"))
    day = numbers.get("ce_day_change" if bullish else "pe_day_change", float("nan"))

    # Prefer the intraday delta when it exists, fall back to the day change,
    # which the broker supplies on the very first call.
    change, basis = (intra, f"over {fmt(numbers.get('minutes'), 0)} minutes") \
        if np.isfinite(intra) else (day, "against the previous session's close")

    if not np.isfinite(change):
        held = numbers.get("snapshots", 0)
        return ("Not measurable yet",
                f"No open-interest reading at this strike. {held} chain snapshot(s) held. "
                "Tick **Fetch the option chain from Dhan while scanning** and run the scan — "
                "the day's change reads immediately from the broker, and the intraday change "
                "appears once a second scan gives it two points to compare.")
    if change < 0 and price_up and vol_up and bullish:
        return ("Short covering", f"{leg} open interest is DOWN {fmt(abs(change), 0)} contracts "
                                  f"{basis} while price rises on above-average volume: call "
                                  f"writers are buying back, which is the fuel a gamma move "
                                  f"runs on.")
    if change < 0 and not price_up and vol_up and not bullish:
        return ("Short covering (puts)", f"{leg} open interest is DOWN {fmt(abs(change), 0)} "
                                         f"{basis} while price falls on above-average volume: "
                                         f"put writers are closing.")
    if change < 0 and not price_up and bullish:
        return ("Long unwinding", f"{leg} open interest is DOWN {fmt(abs(change), 0)} {basis} "
                                  f"but price is FALLING. Falling OI with falling price is call "
                                  f"holders leaving, not writers being squeezed — the opposite "
                                  f"setup.")
    if change > 0 and price_up:
        return ("Fresh longs / writing", f"{leg} open interest is UP {fmt(change, 0)} {basis}: "
                                         f"positions are being ADDED, not closed. That is not "
                                         f"covering.")
    return ("No clear signature", f"{leg} OI change {fmt(change, 0)} {basis} with price "
                                  f"{'up' if price_up else 'down'} and volume "
                                  f"{fmt(numbers['vol_multiple'])}x average. The three do not "
                                  f"line up into either pattern.")


def _gamma_detail_panel(table: pd.DataFrame, interval: str, gcfg: dict, cfg: dict) -> None:
    """Per-candidate evidence: the three panels plus the absolute numbers."""
    st.markdown("#### Inspect a candidate")
    c1, c2, c3 = st.columns([2, 1, 1])
    names = table["Ticker"].tolist()
    chosen = c1.selectbox("Ticker", names, key="gb_detail_pick")
    bars = c2.number_input("Candles to plot", 40, 600, 160, 20, key="gb_detail_bars")
    show = c3.checkbox("Show the chart", value=False, key="gb_detail_show",
                       help="Off by default: drawing a chart costs a data fetch per ticker, "
                            "and the scan should not pay for one you have not asked to see.")
    if not show:
        return

    row = table[table["Ticker"] == chosen].iloc[0].to_dict()
    strike = float(row.get("Strike") or float("nan"))
    try:
        fig, nums = gamma_blast_detail(chosen, interval, dict(gcfg, chart_bars=int(bars)),
                                       strike, light=bool(cfg.get("light_charts")))
    except Exception as exc:                                        # noqa: BLE001
        st.error(f"Could not draw `{chosen}`: {exc}")
        return

    verdict, explanation = oi_verdict(nums, str(row.get("Side", "")))
    (st.success if verdict.startswith("Short covering") else
     st.warning if verdict in ("Long unwinding", "Fresh longs / writing") else st.info)(
        f"**{verdict}.** {explanation}")

    # Absolute numbers, because a multiple is not checkable and a count is.
    a, b, c, d = st.columns(4)
    a.metric("Last price", fmt(nums["price"]),
             f"{fmt(nums['price'] - nums['prev_price'])} vs previous candle")
    b.metric("Candle volume", fmt(nums["volume"], 0),
             None if not nums["has_volume"] else f"{fmt(nums['vol_multiple'])}x average")
    c.metric(f"Average volume ({nums['vol_len']} candles)", fmt(nums["avg_volume"], 0))
    d.metric("Strike", fmt(nums["strike"], 0),
             f"level {fmt(row.get('Level'))}")

    e, f, g, h = st.columns(4)
    e.metric("CE open interest", fmt(nums["ce_oi"], 0),
             f"day change {fmt(nums.get('ce_day_change'), 0)}",
             help="Today's open interest at the strike, and how it has moved since the "
                  "previous session's close. The day change comes straight from the broker, so "
                  "it reads on the first scan.")
    f.metric("CE OI change (intraday)", fmt(nums["ce_oi_change"], 0),
             f"over {fmt(nums['minutes'], 0)} min" if nums["snapshots"] > 1
             else "needs a second scan")
    g.metric("PE open interest", fmt(nums["pe_oi"], 0),
             f"day change {fmt(nums.get('pe_day_change'), 0)}")
    h.metric("PE OI change (intraday)", fmt(nums["pe_oi_change"], 0),
             f"over {fmt(nums['minutes'], 0)} min" if nums["snapshots"] > 1
             else "needs a second scan")

    st.plotly_chart(fig, width="stretch", config={"scrollZoom": True})
    st.caption("Three panels on one time axis rather than two y-axes on one plot: price, "
               "volume and open interest are different scales, and overlaying them lets any "
               "two be slid into apparent agreement — which is the exact claim being tested.")


def tab_gamma_blast(cfg: dict) -> None:
    st.subheader("Gamma Blast Screener")
    st.caption("Spot pressing a level, participation rising, price leaning the right way, and "
               "the expiry clock in the right place. Every threshold below is yours to set.")
    st.warning("**What this can and cannot see.** Proximity, volume and momentum come from "
               "candles and always work. Strike-level OPEN INTEREST needs a broker chain, and "
               "short covering needs a HISTORY of it — no free source publishes one, so it can "
               "only be measured from the moment this app starts sampling. Rows still appear "
               "without it, marked as untested on that condition rather than quietly passed.")

    c1, c2, c3 = st.columns(3)
    universe = c1.selectbox("Universe", SCREENER_UNIVERSES, key="gb_universe")
    interval = c2.selectbox("Timeframe", INTERVALS, index=INTERVALS.index("15m"), key="gb_tf")
    kind = c3.selectbox("Expiry convention", ["Auto", "Index (weekly)",
                                              "Stock / futures (monthly)"], key="gb_kind")

    custom_text = ""
    if universe.startswith("Custom"):
        custom_text = st.text_area("Tickers", "RELIANCE\nTATAMOTORS\n^NSEI", key="gb_custom")
    all_tickers, note = universe_tickers_ui(universe, custom_text, None, "gb")
    chosen = st.multiselect(f"Tickers ({len(all_tickers)} in {universe})", all_tickers,
                            default=all_tickers, key=f"gb_tickers_{universe}")
    if note:
        st.caption(note)

    with st.expander("Expiry windows", expanded=True):
        e1, e2, e3, e4 = st.columns(4)
        weekly_weekday = e1.selectbox("Weekly expiry day", list(range(7)), index=3,
                                      format_func=lambda i: ["Mon", "Tue", "Wed", "Thu", "Fri",
                                                             "Sat", "Sun"][i], key="gb_wwd")
        index_days = e2.number_input("Index: days to expiry at or below", 0, 7, 0, 1,
                                     key="gb_idays",
                                     help="0 means the expiry day itself.")
        stock_min = e3.number_input("Stock: min days since monthly expiry", 0, 31, 8, 1,
                                    key="gb_smin")
        stock_max = e4.number_input("Stock: max days since monthly expiry", 0, 31, 12, 1,
                                    key="gb_smax",
                                    help="Ten days after expiry sits in the middle of this "
                                         "window; widen it to catch holiday-shifted expiries.")
        st.caption("Exchange holidays move an expiry a day earlier and are not modelled here, "
                   "so keep a day or two of slack in these windows.")

    with st.expander("Level, volume and momentum", expanded=True):
        f1, f2, f3 = st.columns(3)
        level_lookback = f1.number_input("Level lookback (candles)", 10, 500, 60, 5,
                                         key="gb_look",
                                         help="Resistance is the highest high over this many "
                                              "candles; support the lowest low.")
        proximity = f2.number_input("Proximity to the level (%)", 0.05, 10.0, 1.0, 0.05,
                                    key="gb_prox")
        vol_mult = f3.number_input("Volume multiple", 1.0, 10.0, 1.5, 0.1, key="gb_vol")
        g1, g2, g3 = st.columns(3)
        momentum_bars = g1.number_input("Momentum lookback (candles)", 1, 100, 5, 1,
                                        key="gb_mombars")
        momentum_pct = g2.number_input("Minimum move (%)", 0.0, 20.0, 0.2, 0.05, key="gb_mompct")
        strike_step = g3.number_input("Strike step (0 = derive from price)", 0.0, 1000.0, 0.0,
                                      0.5, key="gb_step")
        oi_drop = st.number_input("Minimum OI fall at the strike (contracts)", 0.0, 1e9, 0.0,
                                  1000.0, key="gb_oidrop",
                                  help="Applied only once chain snapshots exist. 0 accepts any "
                                       "fall.")

    show_all = st.checkbox("Show near-misses too (rows that fail some conditions)", value=True,
                           key="gb_showall",
                           help="On by default: a row two conditions short is often worth "
                                "seeing, and hiding it looks like the scan found nothing.")

    broker = cfg.get("broker") or {}
    has_token = bool(str(broker.get("access_token", "")).strip()
                     and str(broker.get("client_id", "")).strip())
    # The key CHANGES when a token appears. A Streamlit widget keeps whatever
    # value it was first created with, so a box defaulted to False before the
    # token was typed stayed False forever afterwards -- the token was entered,
    # the box looked available, and the chain was never fetched. A new key means
    # a new widget, which takes the new default.
    use_chain = st.checkbox(
        "Fetch the option chain from Dhan while scanning", value=has_token,
        disabled=not has_token, key=f"gb_use_chain_{'tok' if has_token else 'none'}",
        help="On, the scan resolves each underlying and its nearest expiry from the Dhan "
             "instrument master and pulls the chain itself, so CE/PE open interest at the strike "
             "is real data. Open interest CHANGE still needs two scans a few minutes apart, "
             "because no free or paid source publishes a history of it — it can only be measured "
             "from when this app starts watching.")
    if not has_token:
        st.info("Enter a Dhan client id and access token in the sidebar to read open interest. "
                "Everything else on this screen works without it.")
    else:
        # Prove the resolution works BEFORE a scan, on a real name, so a broken
        # security id or expiry is visible here instead of as a blank column
        # forty tickers later.
        probe_name = (chosen or all_tickers or ["^NSEI"])[0]
        probe = option_chain_underlying(probe_name)
        if probe:
            st.caption(f"Resolved automatically — `{probe_name}` → security id `{probe[0]}` on "
                       f"`{probe[1]}`, nearest expiry `{probe[2]}`. Security id, segment and "
                       f"expiry are all derived from the Dhan instrument master; nothing here "
                       f"is typed by hand.")
        else:
            st.warning(f"`{probe_name}` could not be resolved to an option series in the Dhan "
                       f"instrument master, so its open interest cannot be read. Indices and "
                       f"F&O stocks resolve; cash-only names have no options to read.")

    gcfg = {"kind": kind, "weekly_weekday": weekly_weekday, "monthly_weekday": weekly_weekday,
            "index_days": index_days, "stock_min_days": stock_min, "stock_max_days": stock_max,
            "level_lookback": level_lookback, "proximity_pct": proximity, "vol_mult": vol_mult,
            "vol_len": int(_p(cfg.get("params") or {}, "vol_len")),
            "momentum_bars": momentum_bars, "momentum_pct": momentum_pct,
            "strike_step": strike_step, "oi_drop": oi_drop,
            "use_chain": bool(use_chain and has_token)}

    slice_seconds = _auto_slice_seconds()

    def _worker(ticker):
        try:
            row = gamma_blast_scan_one(ticker, interval, gcfg, cfg.get("params") or {}, broker)
        except Exception as exc:                                    # noqa: BLE001
            return [], [{"Ticker": ticker, "Problem": str(exc)[:140]}]
        return ([row] if row else []), []

    scan_cost_notice(len(chosen), per_job_hint=1.8, prefix="gb")
    rows, errs, _done = chunked_sweep("gb", list(chosen), _worker, slice_seconds, "tickers")

    frame = pd.DataFrame(rows)
    if frame.empty:
        st.info("Nothing scanned yet. Press **Run** above.")
    else:
        full = frame[frame["All met"] == "yes"]
        near = frame[frame.get("Near level", pd.Series("no", index=frame.index)) == "yes"]
        a, b, c, d = st.columns(4)
        a.metric("Scanned", len(frame))
        b.metric("Near a level", len(near))
        c.metric("Every condition met", len(full))
        d.metric("Chain snapshots held",
                 sum(len(v) for v in (st.session_state.get("oi_snapshots") or {}).values()))

        # WHY it is zero. A bare "0" is the complaint this answers: with the
        # stock window set to 8-12 days after a monthly expiry, most days of the
        # month reject every stock on the expiry condition alone, and there was
        # nothing on screen to say so.
        if full.empty and "Why not" in frame.columns:
            tally: dict[str, int] = {}
            for entry in frame["Why not"]:
                for name in str(entry).split(", "):
                    if name and name != "-":
                        tally[name] = tally.get(name, 0) + 1
            if tally:
                ranked = sorted(tally.items(), key=lambda kv: -kv[1])
                st.warning(
                    "**Nothing met every condition.** What did the rejecting, across "
                    f"{len(frame)} ticker(s): " +
                    " · ".join(f"**{name}** rejected {count}" for name, count in ranked) +
                    ". The table below shows each ticker's own numbers against your thresholds, "
                    "so you can see how far off it was rather than guessing.")
                top = ranked[0][0]
                if top == "Expiry window":
                    st.caption("The expiry condition is the usual culprit and it is doing what "
                               "you asked: stocks only pass 8-12 days after their monthly "
                               "expiry, so most calendar days reject every stock. Widen that "
                               "window above, or switch the convention to Index (weekly).")
                elif top == "Near level":
                    st.caption("Widen 'Proximity to the level (%)' or lengthen the level "
                               "lookback — with a 1% proximity most names simply are not "
                               "pressing their extreme.")

        table = frame if show_all else full
        order = [c for c in ["Ticker", "Timeframe", "Side", "Conditions met", "All met",
                             "Why not", "Near level", "Spot", "Level", "Distance %",
                             "Proximity needed %", "Resistance", "Support", "Strike",
                             "Volume x", "Volume needed", "Momentum %", "Momentum needed",
                             "Expiry", "Expiry ok", "CE OI", "CE OI day change",
                             "CE OI intraday change", "PE OI", "PE OI day change",
                             "PE OI intraday change", "OI state", "Strike step", "Checked at"]
                 if c in table.columns]
        if table.empty:
            st.info("No row met every condition. Tick **Show near-misses too** above to see "
                    "every ticker's numbers and how far off each one was.")
        else:
            sort_cols = [c for c in ["All met", "Met count", "Distance %"] if c in table.columns]
            st.dataframe(
                table.sort_values(sort_cols,
                                  ascending=[c == "Distance %" for c in sort_cols])[order],
                width="stretch", hide_index=True)
        if not table.empty:
            _gamma_detail_panel(table, interval, gcfg, cfg)
            st.download_button("Download candidates (CSV)",
                               table[order].to_csv(index=False).encode(),
                               f"gamma_blast_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv")

            pick = st.selectbox("Apply which ticker to the sidebar?", table["Ticker"].tolist(),
                                key="gb_pick")
            if st.button("Apply to the sidebar", width="stretch", key="gb_apply"):
                st.session_state.pending_ticker = pick
                st.session_state.pending_combo = {
                    "strategy": "48 \u00b7 Options: Gamma Blast (late-session)",
                    "sl_type": "ATR Multiple", "sl_value": 1.5,
                    "tp_type": "Risk : Reward Multiple", "tp_value": 2.0,
                    "filter_key": "", "widgets": {"cfg_interval": interval}}
                st.rerun()

    with st.expander("Option chain sampling (Dhan) — manual override"):
        st.caption("The scan resolves and samples chains by itself when the box above is ticked. "
                   "This panel is for a name the instrument master does not resolve, or an "
                   "expiry other than the nearest one. Each sample stores the chain so OI CHANGE "
                   "can be measured; two are the minimum, and the gap between them is the window "
                   "the change is measured over.")
        if not has_token:
            st.info("Enter a Dhan client id and access token in the sidebar to sample chains.")
        else:
            if chosen:
                probe = option_chain_underlying(chosen[0])
                if probe:
                    st.caption(f"Resolution check — `{chosen[0]}` maps to security id "
                               f"`{probe[0]}` on `{probe[1]}`, nearest expiry `{probe[2]}`.")
                else:
                    st.caption(f"Resolution check — `{chosen[0]}` has no option series in the "
                               f"Dhan master, so its OI cannot be read. Use the fields below.")
            s1, s2 = st.columns(2)
            scrip = s1.number_input("Underlying security id", 0, 10**9, 0, 1, key="gb_scrip",
                                    help="Dhan's id for the underlying. Resolve it in the "
                                         "sidebar's Dhan panel.")
            seg = s2.selectbox("Underlying segment", DHAN_SEGMENTS, index=0, key="gb_seg")
            expiry_str = st.text_input("Expiry (YYYY-MM-DD)", key="gb_expiry")
            target = st.selectbox("Store against ticker", chosen or ["--"], key="gb_store")
            if st.button("Sample the chain now", key="gb_sample"):
                chain = dhan_option_chain(broker, int(scrip), seg, expiry_str)
                if chain:
                    record_oi_snapshot(target, chain)
                    held = len((st.session_state.get("oi_snapshots") or {}).get(target, []))
                    st.success(f"Stored a snapshot for {target}. {held} held; OI change becomes "
                               f"measurable at two.")
                else:
                    st.error("No chain returned. Check the security id, segment and expiry.")
    render_analyst_panel("gamma", "these gamma blast candidates", _frame_context(frame))


# =============================================================================
# SECTION 19f -- MOMENTUM PULSE SCREENER   (intraday checklist screener)
# =============================================================================
# A condition-count screener: each ticker is scored out of four on the bullish
# side and four on the bearish side, and the counts are shown side by side.
#
# WHAT THE FOUR CONDITIONS MEAN HERE. The abbreviations come from a screen the
# operator saw, not from a published specification, so each one is implemented
# as the most standard reading of its name and the definition is printed in the
# tab. They are configurable where a number is involved, so a different reading
# can be dialled in rather than argued about.
#
#   BULLISH            BEARISH
#   Breakout  above the opening range high      below the opening range low
#   Volume    current volume >= N x average     (same test, on the bear side)
#   PDH       trading above the PREVIOUS day's high
#   Range     today's range has EXPANDED beyond its recent average
#   VWAP                                        trading below session VWAP
#   DL                                          at or near today's LOW
#   PDL                                         trading below the PREVIOUS day's low
#
# A count is not a signal. Four of four means four conditions are true at this
# instant, which is a reason to look at a chart, not an instruction to trade.

PULSE_BULL = ["Breakout", "Volume", "PDH", "Range"]
PULSE_BEAR = ["Breakout", "VWAP", "DL", "PDL"]


def previous_session_levels(frame: pd.DataFrame) -> tuple[float, float, float]:
    """
    Previous session's high, low and close, from an intraday frame.

    Taken by grouping the intraday candles into calendar sessions rather than
    by fetching a second daily series: one download per ticker is already the
    throughput ceiling of this whole application.
    """
    sessions = session_key(frame.index)
    unique = list(dict.fromkeys(sessions.tolist()))
    if len(unique) < 2:
        return float("nan"), float("nan"), float("nan")
    previous = frame[sessions == unique[-2]]
    if previous.empty:
        return float("nan"), float("nan"), float("nan")
    return (float(previous["High"].max()), float(previous["Low"].min()),
            float(previous["Close"].iloc[-1]))


def momentum_pulse_scan_one(ticker: str, interval: str, pcfg: dict) -> dict:
    """
    Score one ticker on both checklists. ALWAYS returns a row.

    Returning a row even when nothing is true is deliberate: a screener that
    silently drops the quiet names cannot be told apart from one that is
    broken, and the counts are the whole point -- 0/4 is information.
    """
    period, _ = lab_period_for(interval, 200)
    bundle = load_market_data(ticker, period, interval, freshness_seconds=120, min_bars=30)
    frame = bundle.frame
    sessions = session_key(frame.index)
    today = frame[sessions == sessions.iloc[-1]]
    if today.empty:
        today = frame.tail(1)

    price = float(frame["Close"].iloc[-1])
    pdh, pdl, pdc = previous_session_levels(frame)
    day_high, day_low = float(today["High"].max()), float(today["Low"].min())

    # Opening range: the first N candles of the current session.
    or_bars = int(pcfg.get("or_bars", 3))
    opening = today.head(or_bars)
    or_high = float(opening["High"].max()) if len(opening) else float("nan")
    or_low = float(opening["Low"].min()) if len(opening) else float("nan")

    # Volume against its own recent average. Indices report none, so the test
    # is reported as unavailable rather than silently passed or failed.
    vol_len = int(pcfg.get("vol_len", 20))
    has_volume = float(frame["Volume"].tail(100).abs().sum()) > 0
    vol_now = float(frame["Volume"].iloc[-1])
    vol_avg = float(sma(frame["Volume"], vol_len).iloc[-1] or 0.0)
    vol_ratio = (vol_now / vol_avg) if (has_volume and vol_avg) else float("nan")
    vol_ok = bool(np.isfinite(vol_ratio) and vol_ratio >= float(pcfg.get("vol_mult", 1.5)))

    # Range expansion: today's range so far against the average session range.
    day_range = day_high - day_low
    past = frame[sessions != sessions.iloc[-1]]
    if len(past):
        per_session = past.groupby(session_key(past.index)).agg(
            hi=("High", "max"), lo=("Low", "min"))
        avg_range = float((per_session["hi"] - per_session["lo"]).tail(
            int(pcfg.get("range_len", 10))).mean())
    else:
        avg_range = float("nan")
    range_ratio = (day_range / avg_range) if (np.isfinite(avg_range) and avg_range > 0) \
        else float("nan")
    range_ok = bool(np.isfinite(range_ratio)
                    and range_ratio >= float(pcfg.get("range_mult", 1.0)))

    series, volume_backed = vwap(frame, True)
    vwap_now = float(series.iloc[-1]) if len(series) else float("nan")

    near_pct = float(pcfg.get("near_pct", 0.25)) / 100.0
    bull = {
        "Breakout": bool(np.isfinite(or_high) and price > or_high),
        "Volume": vol_ok,
        "PDH": bool(np.isfinite(pdh) and price > pdh),
        "Range": range_ok,
    }
    bear = {
        "Breakout": bool(np.isfinite(or_low) and price < or_low),
        "VWAP": bool(np.isfinite(vwap_now) and price < vwap_now),
        "DL": bool(np.isfinite(day_low) and day_low > 0
                   and (price - day_low) <= day_low * near_pct),
        "PDL": bool(np.isfinite(pdl) and price < pdl),
    }
    change_pct = ((price - pdc) / pdc * 100.0) if (np.isfinite(pdc) and pdc) else float("nan")

    row = {
        "Ticker": ticker, "Timeframe": interval,
        "Sector": SECTOR_BY_TICKER.get(ticker, "--"),
        "Price": round(price, 2),
        "Change %": round(change_pct, 2) if np.isfinite(change_pct) else None,
        "Bullish": f"{sum(bull.values())}/4", "Bearish": f"{sum(bear.values())}/4",
        "Bull count": sum(bull.values()), "Bear count": sum(bear.values()),
        "Bias": ("BULLISH" if sum(bull.values()) > sum(bear.values())
                 else "BEARISH" if sum(bear.values()) > sum(bull.values()) else "MIXED"),
        "OR High": round(or_high, 2) if np.isfinite(or_high) else None,
        "OR Low": round(or_low, 2) if np.isfinite(or_low) else None,
        "PDH": round(pdh, 2) if np.isfinite(pdh) else None,
        "PDL": round(pdl, 2) if np.isfinite(pdl) else None,
        "Day High": round(day_high, 2), "Day Low": round(day_low, 2),
        "VWAP": round(vwap_now, 2) if np.isfinite(vwap_now) else None,
        "VWAP is real": "yes" if volume_backed else "no (zero-volume feed, TWAP)",
        "Volume x": round(vol_ratio, 2) if np.isfinite(vol_ratio) else None,
        "Volume needed": float(pcfg.get("vol_mult", 1.5)),
        "Range x": round(range_ratio, 2) if np.isfinite(range_ratio) else None,
        "Range needed": float(pcfg.get("range_mult", 1.0)),
        "Checked at": pd.Timestamp.now(),
    }
    for name, passed in bull.items():
        row[f"B:{name}"] = "YES" if passed else "NO"
    for name, passed in bear.items():
        row[f"S:{name}"] = "YES" if passed else "NO"
    return row


def _pulse_checklist(row: dict) -> None:
    """The two four-row checklists, as the operator's reference screen shows them."""
    left, right = st.columns(2)
    with left:
        st.markdown(f"**BULLISH {row.get('Bullish', '--')}**")
        for name in PULSE_BULL:
            passed = str(row.get(f"B:{name}")) == "YES"
            st.markdown(f"{name} &nbsp; {':green[**YES**]' if passed else ':red[**NO**]'}",
                        unsafe_allow_html=True)
    with right:
        st.markdown(f"**BEARISH {row.get('Bearish', '--')}**")
        for name in PULSE_BEAR:
            passed = str(row.get(f"S:{name}")) == "YES"
            st.markdown(f"{name} &nbsp; {':green[**YES**]' if passed else ':red[**NO**]'}",
                        unsafe_allow_html=True)
    st.caption("Not a buy/sell signal. These are four conditions being true at this instant, "
               "which is a reason to open a chart, not an instruction to trade.")


def tab_momentum_pulse(cfg: dict) -> None:
    st.subheader("Momentum Pulse \u2014 intraday condition screener")
    st.warning(
        "**A condition count is not a strategy, and this tab does not backtest anything.** "
        "It reports which of four bullish and four bearish conditions are true right now. "
        "Nothing here has been tested for whether 4/4 makes money -- to find that out, apply a "
        "name to the sidebar and run it through the Backtesting tab or the Signal Lab.")

    c1, c2, c3 = st.columns(3)
    universe = c1.selectbox("Universe", SCREENER_UNIVERSES, key="pulse_universe")
    intraday_choices = [i for i in INTERVALS if i in INTRADAY_INTERVALS]
    interval = c2.selectbox(
        "Timeframe", intraday_choices, index=intraday_choices.index("5m"),
        key="pulse_tf",
        help="The reference screen does not state its timeframe. 5m is the usual choice for "
             "an intraday breakout screen: fast enough to catch a move, slow enough that the "
             "opening-range and volume tests are not pure noise. 15m is the steadier option.")
    bias_filter = c3.selectbox("Show", ["Everything", "Bullish only", "Bearish only",
                                        "4/4 only"], key="pulse_bias")

    custom_text = ""
    if universe.startswith("Custom"):
        custom_text = st.text_area("Tickers", "RELIANCE\nTCS\nINFY", key="pulse_custom")
    all_tickers, note = universe_tickers_ui(universe, custom_text, None, "pulse")
    chosen = st.multiselect(f"Tickers ({len(all_tickers)} in {universe})", all_tickers,
                            default=all_tickers, key=f"pulse_tickers_{universe}")
    if note:
        st.caption(note)

    with st.expander("What each condition means, and its threshold", expanded=False):
        st.markdown(
            "| Condition | Bullish test | Bearish test |\n|---|---|---|\n"
            "| **Breakout** | above the opening-range high | below the opening-range low |\n"
            "| **Volume** | current volume >= N x its average | the same test |\n"
            "| **PDH / PDL** | above the PREVIOUS day's high | below the previous day's low |\n"
            "| **Range** | today's range has expanded past its average | -- |\n"
            "| **VWAP** | -- | trading below session VWAP |\n"
            "| **DL** | -- | sitting at or near today's low |\n")
        st.caption("These are the standard readings of the abbreviations; the source screen "
                   "publishes no definitions. Every number below is yours to change.")
        st.info(
            "**Volume and Range are direction-neutral.** They appear only on the bullish "
            "checklist, exactly as the reference screen has them, but a hard sell-off also "
            "has heavy volume and an expanded range. So a falling stock can legitimately "
            "read **2/4 bullish** alongside **4/4 bearish** — the two counts are not "
            "opposites and do not sum to four. The directional tests are Breakout and "
            "PDH/PDL; those are the ones that disagree with each other.")
        p1, p2, p3 = st.columns(3)
        or_bars = p1.number_input("Opening range (candles)", 1, 24, 3, 1, key="pulse_or")
        vol_mult = p2.number_input("Volume multiple", 1.0, 10.0, 1.5, 0.1, key="pulse_vol")
        range_mult = p3.number_input("Range expansion multiple", 0.1, 5.0, 1.0, 0.05,
                                     key="pulse_range")
        q1, q2, q3 = st.columns(3)
        vol_len = q1.number_input("Volume average (candles)", 5, 200, 20, 5, key="pulse_vlen")
        range_len = q2.number_input("Range average (sessions)", 2, 60, 10, 1, key="pulse_rlen")
        near_pct = q3.number_input("\"At the low\" tolerance (%)", 0.0, 5.0, 0.25, 0.05,
                                   key="pulse_near")

    pcfg = {"or_bars": or_bars, "vol_mult": vol_mult, "range_mult": range_mult,
            "vol_len": vol_len, "range_len": range_len, "near_pct": near_pct}

    def _worker(ticker):
        try:
            return [momentum_pulse_scan_one(ticker, interval, pcfg)], []
        except Exception as exc:                                    # noqa: BLE001
            return [], [{"Ticker": ticker, "Problem": str(exc)[:140]}]

    scan_cost_notice(len(chosen), per_job_hint=1.5, prefix="pulse")
    rows, errs, _done = chunked_sweep("pulse", list(chosen), _worker,
                                      _auto_slice_seconds(), "tickers")

    frame = pd.DataFrame(rows)
    if frame.empty:
        st.info("Nothing scanned yet. Press **Run** above.")
        if errs:
            with st.expander(f"Tickers that could not be read ({len(errs)})"):
                st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
        return

    a, b, c, d = st.columns(4)
    a.metric("Scanned", len(frame))
    a_bull = frame[frame["Bias"] == "BULLISH"]
    a_bear = frame[frame["Bias"] == "BEARISH"]
    b.metric("Leaning bullish", len(a_bull))
    c.metric("Leaning bearish", len(a_bear))
    d.metric("4 of 4 either way",
             int(((frame["Bull count"] == 4) | (frame["Bear count"] == 4)).sum()))

    view = frame
    if bias_filter == "Bullish only":
        view = frame[frame["Bias"] == "BULLISH"]
    elif bias_filter == "Bearish only":
        view = frame[frame["Bias"] == "BEARISH"]
    elif bias_filter == "4/4 only":
        view = frame[(frame["Bull count"] == 4) | (frame["Bear count"] == 4)]

    if view.empty:
        st.info("Nothing matches that filter. Switch **Show** back to Everything to see the "
                "full scan and how close each name came.")
        return

    order = [c for c in ["Ticker", "Sector", "Price", "Change %", "Bias", "Bullish", "Bearish",
                         "B:Breakout", "B:Volume", "B:PDH", "B:Range",
                         "S:Breakout", "S:VWAP", "S:DL", "S:PDL",
                         "Volume x", "Volume needed", "Range x", "Range needed",
                         "OR High", "OR Low", "PDH", "PDL", "Day High", "Day Low",
                         "VWAP", "VWAP is real", "Timeframe", "Checked at"]
             if c in view.columns]
    st.dataframe(
        view.sort_values(["Bull count", "Bear count", "Change %"],
                         ascending=[False, False, False])[order],
        width="stretch", hide_index=True,
        column_config={"Change %": st.column_config.NumberColumn("Change %", format="%.2f%%")})
    st.download_button("Download the scan (CSV)", view[order].to_csv(index=False).encode(),
                       f"momentum_pulse_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv",
                       key="pulse_dl")

    st.markdown("#### Inspect and apply")
    s1, s2 = st.columns([2, 1])
    pick = s1.selectbox("Ticker", view["Ticker"].tolist(), key="pulse_pick")
    picked = view[view["Ticker"] == pick].iloc[0].to_dict()
    _pulse_checklist(picked)
    if s2.button("Apply to the sidebar", width="stretch", key="pulse_apply",
                 help="Sends this ticker and timeframe to the control console so it can be "
                      "backtested, optimised or traded live with a real strategy."):
        st.session_state.pending_ticker = pick
        st.session_state.pending_combo = {
            "strategy": "05 \u00b7 Opening Range Breakout (ORB)",
            "sl_type": "ATR Multiple", "sl_value": 1.5,
            "tp_type": "Risk : Reward Multiple", "tp_value": 2.0,
            "filter_key": "", "widgets": {"cfg_interval": interval}}
        st.rerun()

    if errs:
        with st.expander(f"Tickers that could not be read ({len(errs)})"):
            st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
    render_analyst_panel("pulse", "these momentum pulse candidates", _frame_context(frame))


# =============================================================================
# SECTION 19g -- VOLATILITY LEVELS SCREENER
# =============================================================================
# Three independent pieces, each honest about where it applies.
#
# 1. STANDARD-DEVIATION LEVELS
#    The operator's formula is (India VIX / 1600) * spot = one standard
#    deviation of a DAY's move. That constant is not arbitrary: VIX quotes an
#    ANNUALISED implied volatility in percent, so a daily sigma is
#    VIX / 100 / sqrt(252) = VIX / 1587. Rounding 1587 to 1600 is the usual
#    desk shorthand, and the divisor is exposed below so it can be set exactly.
#
#    WHERE IT APPLIES. India VIX is computed from NIFTY option prices. It is a
#    statement about Nifty and nothing else. Using it on Bank Nifty understates
#    the move -- Bank Nifty is materially more volatile than Nifty -- and on a
#    single stock or on Bitcoin it has no meaning at all. For anything that is
#    not Nifty the honest input is the instrument's OWN volatility, measured
#    from its own returns, which is what REALISED mode does.
#
# 2. ATR EXPANSION
#    ATR(14) against its own 20-period average. Instrument-agnostic: it needs
#    only OHLC, so it is as valid on Bitcoin as on Nifty.
#
# 3. OPEN-INTEREST MOMENTUM RATIO
#    change in PUT OI divided by change in CALL OI over an interval. This is a
#    statement about an options market, so it exists only where an options
#    market exists: the Indian indices and F&O stocks. There is no Indian
#    option chain for Bitcoin or for a cash-only stock, and the tab says so
#    rather than printing a number that cannot mean anything.

SD_MULTIPLES = (1, 2, 3)


def realised_daily_sigma(frame: pd.DataFrame, lookback: int = 20) -> float:
    """
    One day's standard deviation as a FRACTION of price, from the instrument's
    own daily returns.

    This is what replaces India VIX on anything that is not Nifty. It is
    backward looking where VIX is forward looking, which is a real difference
    and is stated in the tab rather than glossed over.
    """
    closes = frame["Close"].dropna()
    if len(closes) < max(5, lookback // 2):
        return float("nan")
    returns = np.log(closes / closes.shift(1)).dropna().tail(int(lookback))
    if len(returns) < 3:
        return float("nan")
    sigma = float(returns.std(ddof=1))
    return sigma if np.isfinite(sigma) and sigma > 0 else float("nan")


def sd_levels(spot: float, sigma_fraction: float,
              multiples=SD_MULTIPLES) -> dict:
    """Spot plus and minus each standard-deviation multiple."""
    out: dict = {}
    if not (np.isfinite(spot) and np.isfinite(sigma_fraction)):
        return out
    one = float(spot) * float(sigma_fraction)
    out["1SD points"] = round(one, 2)
    for n in multiples:
        out[f"+{n}SD"] = round(float(spot) + n * one, 2)
        out[f"-{n}SD"] = round(float(spot) - n * one, 2)
    return out


#: Annualisation divisors for turning a volatility INDEX into one day's sigma.
#:
#: An index quotes annualised implied volatility in percent, so one day's sigma
#: is  index / 100 / sqrt(periods in a year)  and the divisor is
#: 100 * sqrt(periods). The two markets differ because their years differ:
#:
#:   Indian equities   252 TRADING days    100*sqrt(252) = 1587.45   (1600 rounded)
#:   Crypto            365 CALENDAR days   100*sqrt(365) = 1910.50
#:
#: Crypto never closes, so every calendar day is a trading day and its divisor
#: is the larger of the two. Using the equity constant on Bitcoin would
#: overstate the expected move by about 20%.
VIX_DIVISOR_EQUITY = 1600.0
DVOL_DIVISOR_CRYPTO = 1910.5

#: Deribit publishes a DVOL index for these currencies and no others.
DVOL_CURRENCIES = {"BTC": "BTC", "ETH": "ETH"}


def vix_daily_sigma(vix: float, divisor: float = VIX_DIVISOR_EQUITY) -> float:
    """A volatility index -> one day's sigma as a fraction of spot."""
    try:
        value = float(vix) / float(divisor)
    except (TypeError, ValueError, ZeroDivisionError):
        return float("nan")
    return value if np.isfinite(value) else float("nan")


def dvol_currency_for(ticker: str) -> str | None:
    """
    The Deribit DVOL currency for a ticker, or None when there is not one.

    DVOL exists for BTC and ETH. Every other coin has no published volatility
    index, so it falls back to its own realised volatility rather than
    borrowing Bitcoin's -- an altcoin is materially more volatile than BTC and
    using BTC's number would understate its range.
    """
    symbol = (ticker or "").strip().upper()
    if not symbol.endswith("-USD"):
        return None
    base = symbol[:-4]
    return DVOL_CURRENCIES.get(base)


def load_dvol(currency: str, freshness_seconds: float = 300.0) -> float | None:
    """
    Latest DVOL reading from Deribit's public volatility-index endpoint.

    Never raises and never blocks the scan: a refusal returns None and the
    caller falls back to realised volatility, saying so in the row. The
    endpoint needs no key, but it is a third-party service that can be
    unreachable from a hosted runtime, which is why the tab also accepts the
    number typed by hand.
    """
    currency = str(currency or "").upper()
    if currency not in DVOL_CURRENCIES:
        return None

    def _fetch(cur: str, _bucket: int):
        import requests
        now_ms = int(time.time() * 1000)
        try:
            _space_quote_requests()
            resp = requests.get(
                "https://www.deribit.com/api/v2/public/get_volatility_index_data",
                params={"currency": cur, "start_timestamp": now_ms - 6 * 3600 * 1000,
                        "end_timestamp": now_ms, "resolution": "3600"}, timeout=8)
            body = resp.json()
        except Exception:                                           # noqa: BLE001
            return None
        # The payload is a list of [timestamp, open, high, low, close] candles.
        rows = ((body.get("result") or {}).get("data")) or []
        if not rows:
            return None
        try:
            return float(rows[-1][4])
        except (IndexError, TypeError, ValueError):
            return None

    bucket = int(time.time() // max(1.0, float(freshness_seconds)))
    if st is None:
        return _fetch(currency, bucket)
    if not hasattr(load_dvol, "_impl"):
        @st.cache_data(show_spinner=False, max_entries=8)
        def _impl(cur: str, b: int):
            return _fetch(cur, b)
        load_dvol._impl = _impl
    try:
        return load_dvol._impl(currency, bucket)
    except Exception:                                               # noqa: BLE001
        return _fetch(currency, bucket)


def atr_expansion(frame: pd.DataFrame, atr_len: int = 14, avg_len: int = 20) -> float:
    """
    ATR against its own average. Above 1 volatility is expanding, below 1 it is
    contracting. Instrument-agnostic: it needs only OHLC.
    """
    series = atr(frame["High"], frame["Low"], frame["Close"], int(atr_len))
    average = sma(series, int(avg_len))
    try:
        now, mean = float(series.iloc[-1]), float(average.iloc[-1])
    except (IndexError, TypeError, ValueError):
        return float("nan")
    if not (np.isfinite(now) and np.isfinite(mean)) or mean <= 0:
        return float("nan")
    return now / mean


def has_option_chain(ticker: str) -> bool:
    """
    Is there an Indian option chain for this name at all?

    The open-interest test is a statement about an options market. Bitcoin, spot
    FX, commodity futures and US equities have no NSE chain, so the ratio is not
    merely unavailable there -- it is undefined, and is reported as such.
    """
    t = (ticker or "").upper()
    if t.endswith("-USD") or t.endswith("=X") or t.endswith("=F"):
        return False
    return t.startswith("^") or t.endswith(".NS") or t in {"NIFTY_FIN_SERVICE.NS"}


def oi_momentum_ratio(ticker: str, spot: float, strikes_each_side: int = 5,
                      window_minutes: float = 15.0) -> dict:
    """
    change in PUT open interest over change in CALL open interest.

    Summed across the strikes either side of spot rather than read off one
    strike: a single strike's open interest is noisy and the claim being tested
    -- "put writers are adding faster than call writers" -- is about the band
    around the money, not about one line of the chain.

    The ratio is only formed when BOTH sides are genuinely adding. When call
    open interest is FALLING the denominator is negative and the quotient stops
    meaning what the rule says it means, so the raw changes are returned and
    the ratio is left undefined. Dividing anyway would produce a confident
    number pointing the wrong way.
    """
    store = (st.session_state.get("oi_snapshots") or {}) if st is not None else {}
    series = store.get(ticker) or []
    out = {"samples": len(series)}
    if len(series) < 2:
        out["note"] = (f"{len(series)} chain snapshot(s) held. The ratio is a CHANGE over "
                       f"time, so it needs two samples about {window_minutes:.0f} minutes "
                       f"apart. Run the scan again after that gap.")
        return out

    first, last = series[0], series[-1]
    minutes = (pd.Timestamp(last["at"]) - pd.Timestamp(first["at"])).total_seconds() / 60.0
    out["minutes"] = round(minutes, 1)

    strikes = sorted(set(first.get("chain", {})) & set(last.get("chain", {})))
    if not strikes:
        out["note"] = "The two snapshots share no strikes, so nothing can be compared."
        return out
    step = min((b - a for a, b in zip(strikes, strikes[1:]) if b > a), default=0.0)
    band = step * int(strikes_each_side) if step else float("inf")
    near = [k for k in strikes if abs(k - float(spot)) <= band] or strikes
    out["strikes compared"] = len(near)

    d_ce = d_pe = 0.0
    for k in near:
        a, b = first["chain"].get(k) or {}, last["chain"].get(k) or {}
        for side, bucket in (("ce", "d_ce"), ("pe", "d_pe")):
            was, now = a.get(f"{side}_oi"), b.get(f"{side}_oi")
            if was is None or now is None:
                continue
            if np.isfinite(was) and np.isfinite(now):
                if bucket == "d_ce":
                    d_ce += float(now) - float(was)
                else:
                    d_pe += float(now) - float(was)
    out["CE OI change"] = round(d_ce, 0)
    out["PE OI change"] = round(d_pe, 0)

    if d_ce > 0 and d_pe > 0:
        out["MR"] = round(d_pe / d_ce, 3)
    elif d_ce <= 0 < d_pe:
        out["note"] = ("Put open interest is rising while CALL open interest is FALLING. "
                       "That is call writers closing, not put writers outpacing them, and the "
                       "ratio is undefined with a non-positive denominator. Read it as bullish "
                       "pressure, but not through this formula.")
    elif d_pe <= 0 < d_ce:
        out["note"] = ("Call open interest is rising while PUT open interest is FALLING -- "
                       "bearish pressure, but again not something this ratio can express.")
    else:
        out["note"] = "Open interest fell on both sides: positions are being closed, not added."
    return out


def volatility_scan_one(ticker: str, vcfg: dict, broker: dict | None = None) -> dict:
    """One ticker: standard-deviation levels, ATR expansion, and the OI ratio."""
    # --- daily frame for the levels -----------------------------------------
    daily = load_market_data(ticker, "1y", "1d", freshness_seconds=300, min_bars=30).frame
    spot = float(daily["Close"].iloc[-1])

    # --- which volatility input belongs to this instrument ------------------
    #
    # Three sources, each valid for exactly one kind of instrument:
    #   India VIX  prices NIFTY options          -> Nifty
    #   DVOL       prices BTC / ETH options      -> Bitcoin and Ether
    #   realised   the instrument's own returns  -> everything else
    #
    # Auto picks the right one. Forcing a source is allowed, and when the
    # forced source does not describe the instrument the row says so rather
    # than quietly presenting a borrowed number as a measurement.
    mode = str(vcfg.get("sigma_mode", "Auto"))
    symbol = (ticker or "").upper()
    is_nifty = symbol in {"^NSEI"}
    dvol_ccy = dvol_currency_for(ticker)

    looks_indian = symbol.endswith(".NS") or symbol.endswith(".BO") or symbol.startswith("^")
    use_vix = (mode == "India VIX") or (mode == "Auto" and is_nifty)
    use_dvol = (mode == "DVOL (crypto)") or (mode == "Auto" and bool(dvol_ccy))
    # A typed figure needs no broker: the operator has supplied the implied
    # volatility themselves, which is the whole point of the override.
    typed = bool(vcfg.get("index_manual"))
    use_stock_iv = (mode == "Stock IV (Dhan chain)") or (
        mode == "Auto" and looks_indian and not is_nifty and not dvol_ccy
        and (bool(broker) or typed))

    vix = vcfg.get("vix")
    sigma, basis, caution = float("nan"), "", ""

    # A typed value always wins, whichever source it is standing in for. The
    # operator can read today's number off a terminal and have the levels built
    # from it rather than from whatever this app could reach.
    manual_index = vcfg.get("index_manual")
    try:
        manual_index = float(manual_index) if manual_index else None
    except (TypeError, ValueError):
        manual_index = None

    if use_stock_iv:
        divisor = float(vcfg.get("vix_divisor", VIX_DIVISOR_EQUITY))
        if manual_index:
            sigma = vix_daily_sigma(manual_index, divisor)
            basis = f"implied volatility {fmt(manual_index)} (typed) / {fmt(divisor, 0)}"
        else:
            iv, note = atm_implied_vol(broker or {}, ticker, spot)
            if iv is not None:
                sigma = vix_daily_sigma(iv, divisor)
                basis = f"own ATM implied volatility {fmt(iv)} / {fmt(divisor, 0)} ({note})"
            else:
                sigma = realised_daily_sigma(daily, int(vcfg.get("rv_lookback", 20)))
                basis = f"realised {int(vcfg.get('rv_lookback', 20))}-day volatility"
                caution = (f"This instrument's own implied volatility could not be read "
                           f"({note}), so its realised volatility was used. India VIX was NOT "
                           f"substituted: it prices NIFTY options and says nothing about a "
                           f"single stock.")
    elif use_dvol:
        manual = vcfg.get("dvol_manual") or manual_index
        dvol = float(manual) if (manual not in (None, 0, 0.0)) else None
        source = "typed by hand"
        if dvol is None and dvol_ccy:
            fetched = load_dvol(dvol_ccy)
            if fetched is not None:
                dvol, source = float(fetched), "Deribit"
        divisor = float(vcfg.get("dvol_divisor", DVOL_DIVISOR_CRYPTO))
        if dvol is not None and np.isfinite(dvol) and dvol > 0:
            sigma = vix_daily_sigma(dvol, divisor)
            basis = f"DVOL {fmt(dvol)} ({source}) / {fmt(divisor, 1)}"
            if not dvol_ccy:
                caution = ("DVOL is published for BTC and ETH only. Applied here it is a "
                           "borrowed number, not a measurement of this instrument.")
        else:
            sigma = realised_daily_sigma(daily, int(vcfg.get("rv_lookback", 20)))
            basis = f"realised {int(vcfg.get('rv_lookback', 20))}-day volatility"
            caution = ("DVOL could not be read and none was typed in, so the instrument's own "
                       "realised volatility was used instead.")
    elif use_vix and (manual_index or (vix is not None and np.isfinite(float(vix)))):
        divisor = float(vcfg.get("vix_divisor", VIX_DIVISOR_EQUITY))
        reading = manual_index if manual_index else float(vix)
        sigma = vix_daily_sigma(reading, divisor)
        basis = (f"India VIX {fmt(reading)}"
                 + (" (typed)" if manual_index else "") + f" / {fmt(divisor, 0)}")
        if not is_nifty:
            caution = ("India VIX prices NIFTY options. Applied to this instrument it is a "
                       "borrowed number, not a measurement of it.")
    else:
        sigma = realised_daily_sigma(daily, int(vcfg.get("rv_lookback", 20)))
        basis = f"realised {int(vcfg.get('rv_lookback', 20))}-day volatility"
        if use_vix:
            caution = "India VIX was unavailable, so realised volatility was used instead."
        elif dvol_ccy:
            caution = (f"{dvol_ccy} has a published DVOL index. Switch the volatility input to "
                       f"DVOL for a forward-looking number instead of a backward-looking one.")
        elif looks_indian and not is_nifty:
            caution = ("Realised volatility is this instrument's OWN past movement. India VIX "
                       "is deliberately not used here — it prices NIFTY options and describes "
                       "the index, not one stock. For a forward-looking number, connect Dhan "
                       "and switch the input to Stock IV, or type the figure in.")

    levels = sd_levels(spot, sigma)

    # --- ATR expansion on the intraday timeframe ----------------------------
    interval = str(vcfg.get("interval", "5m"))
    period, _ = lab_period_for(interval, 200)
    intraday = load_market_data(ticker, period, interval,
                                freshness_seconds=120, min_bars=40).frame
    expansion = atr_expansion(intraday, int(vcfg.get("atr_len", 14)),
                              int(vcfg.get("atr_avg_len", 20)))
    squeeze_at = float(vcfg.get("squeeze_below", 1.0))
    expand_at = float(vcfg.get("expand_above", 1.3))
    if not np.isfinite(expansion):
        vol_state = "unknown"
    elif expansion < squeeze_at:
        vol_state = "SQUEEZE"
    elif expansion > expand_at:
        vol_state = "EXPANSION"
    else:
        vol_state = "neutral"

    # --- where spot sits inside its own bands -------------------------------
    one_sd = levels.get("1SD points", float("nan"))
    band = "--"
    if np.isfinite(one_sd) and one_sd > 0:
        distance = 0.0            # spot is the anchor, so measure the DAY's travel
        open_px = float(daily["Open"].iloc[-1])
        distance = (spot - open_px) / one_sd
        band = f"{distance:+.2f} SD from today's open"

    row = {
        "Ticker": ticker, "Spot": round(spot, 2),
        "Sigma basis": basis, "1 SD (points)": levels.get("1SD points"),
        "1 SD (%)": round(sigma * 100.0, 3) if np.isfinite(sigma) else None,
        "Travelled": band,
        "ATR expansion": round(expansion, 3) if np.isfinite(expansion) else None,
        "Volatility state": vol_state,
        "Squeeze below": squeeze_at, "Expansion above": expand_at,
        "Option buying": ("avoid - theta decays while spot drifts" if vol_state == "SQUEEZE"
                          else "favourable" if vol_state == "EXPANSION" else "no edge either way"),
        "Caution": caution or "-",
        "Checked at": pd.Timestamp.now(),
    }
    row.update({k: v for k, v in levels.items() if k != "1SD points"})

    # --- open-interest momentum --------------------------------------------
    mr_note, mr_value, mr_signal = "not applicable to this instrument", None, "-"
    if vcfg.get("use_oi") and has_option_chain(ticker):
        if broker:
            _chain, fetch_note = sample_chain_for(broker, ticker)
        else:
            fetch_note = "no Dhan credentials"
        stats = oi_momentum_ratio(ticker, spot,
                                  int(vcfg.get("strikes_each_side", 5)),
                                  float(vcfg.get("mr_window", 15.0)))
        mr_value = stats.get("MR")
        row["CE OI change"] = stats.get("CE OI change")
        row["PE OI change"] = stats.get("PE OI change")
        row["OI window (min)"] = stats.get("minutes")
        if mr_value is None:
            mr_note = stats.get("note") or fetch_note
        else:
            bull_at = float(vcfg.get("mr_bull", 2.5))
            bear_at = float(vcfg.get("mr_bear", 0.4))
            if mr_value > bull_at:
                mr_signal = "BULLISH - buy ITM call"
            elif mr_value < bear_at:
                mr_signal = "BEARISH - buy ITM put"
            else:
                mr_signal = "no trigger"
            mr_note = (f"put OI change {fmt(stats.get('PE OI change'), 0)} over call OI change "
                       f"{fmt(stats.get('CE OI change'), 0)} across "
                       f"{stats.get('strikes compared', 0)} strikes in "
                       f"{fmt(stats.get('minutes'), 0)} min")
    elif vcfg.get("use_oi"):
        mr_note = "no Indian option chain exists for this instrument"

    row["OI momentum ratio"] = mr_value
    row["OI trigger"] = mr_signal
    row["OI state"] = mr_note
    return row


def tab_volatility_levels(cfg: dict) -> None:
    st.subheader("Volatility Levels — standard-deviation bands, expansion and OI flow")
    st.warning(
        "**Three separate tests, and they do not all apply to every instrument.** The "
        "standard-deviation bands need a volatility input, and India VIX only measures NIFTY. "
        "The ATR expansion test works on anything with candles. The open-interest ratio needs "
        "an options market, so it exists for the Indian indices and F&O stocks and nowhere "
        "else. Each row says which inputs it actually used.")

    c1, c2, c3 = st.columns(3)
    universe = c1.selectbox("Universe", SCREENER_UNIVERSES, key="vol_universe")
    intraday_choices = [i for i in INTERVALS if i in INTRADAY_INTERVALS]
    interval = c2.selectbox("Timeframe for ATR expansion", intraday_choices,
                            index=intraday_choices.index("5m"), key="vol_tf",
                            help="The expansion test is specified on a 5-minute chart. The "
                                 "standard-deviation levels are always computed on DAILY data, "
                                 "whatever is picked here.")
    sigma_mode = c3.selectbox(
        "Volatility input",
        ["Auto", "India VIX", "DVOL (crypto)", "Stock IV (Dhan chain)",
         "Realised volatility"], key="vol_sigma_mode",
        help="Auto picks the index that actually prices the instrument: India VIX for NIFTY, "
             "Deribit's DVOL for BTC and ETH, the stock's OWN at-the-money implied "
             "volatility for an Indian name when Dhan is connected, and realised volatility "
             "for everything else. India VIX is never applied to a single stock by Auto — it "
             "prices NIFTY options and describes the index, not one company.")

    custom_text = ""
    if universe.startswith("Custom"):
        custom_text = st.text_area("Tickers", "^NSEI\n^NSEBANK\n^BSESN\nBTC-USD",
                                   key="vol_custom")
    all_tickers, note = universe_tickers_ui(universe, custom_text, None, "vol")
    chosen = st.multiselect(f"Tickers ({len(all_tickers)} in {universe})", all_tickers,
                            default=all_tickers, key=f"vol_tickers_{universe}")
    if note:
        st.caption(note)

    with st.expander("Standard-deviation levels", expanded=True):
        st.markdown(
            "`1 SD move = spot x (volatility index / divisor)`. A volatility index quotes an "
            "ANNUALISED percentage, so the divisor is `100 x sqrt(periods in a year)` and it "
            "differs by market because the years differ:\n\n"
            "| Market | Year | Divisor |\n|---|---|---|\n"
            "| Indian equities (India VIX) | 252 **trading** days | "
            "`100*sqrt(252)` = **1587** (1600 by desk convention) |\n"
            "| Crypto (DVOL) | 365 **calendar** days | `100*sqrt(365)` = **1910.5** |\n\n"
            "Crypto never closes, so every calendar day counts and its divisor is the larger "
            "of the two.")
        s1, s2, s3 = st.columns(3)
        vix_divisor = s1.number_input("India VIX divisor", 100.0, 5000.0, VIX_DIVISOR_EQUITY,
                                      1.0, key="vol_divisor")
        dvol_divisor = s2.number_input("DVOL divisor", 100.0, 5000.0, DVOL_DIVISOR_CRYPTO, 0.5,
                                       key="vol_dvol_divisor",
                                       help="100*sqrt(365) = 1910.5. A value of 1901 is a "
                                            "common typo for it and overstates the move "
                                            "slightly.")
        rv_lookback = s3.number_input("Realised volatility lookback (days)", 5, 250, 20, 5,
                                      key="vol_rv")
        live_vix = load_vix()
        st.caption(f"India VIX now: **{fmt(live_vix)}**" if live_vix is not None
                   else "India VIX could not be read; realised volatility will be used.")

        crypto_names = [t for t in chosen if dvol_currency_for(t)]
        dvol_manual = 0.0
        index_manual = 0.0
        if crypto_names or sigma_mode == "DVOL (crypto)":
            st.markdown("**DVOL** — Deribit's volatility index, published for BTC and ETH "
                        "only. Every other coin falls back to its own realised volatility "
                        "rather than borrowing Bitcoin's, which would understate an altcoin.")
            d1, d2 = st.columns(2)
            live_dvol = {c: load_dvol(c) for c in
                         sorted({dvol_currency_for(t) for t in crypto_names} - {None})}
            if live_dvol:
                d1.caption(" · ".join(f"**{cur} DVOL: {fmt(val)}**" if val is not None
                                      else f"{cur} DVOL unavailable"
                                      for cur, val in live_dvol.items()))
            dvol_manual = d2.number_input(
                "Override DVOL (0 = use the live reading)", 0.0, 500.0, 0.0, 0.01,
                key="vol_dvol_manual",
                help="Deribit is a third party and can be unreachable from a hosted runtime. "
                     "Type today's DVOL here and it is used instead of the fetched value.")

        st.markdown("**Type the volatility index yourself**")
        index_manual = st.number_input(
            "Volatility index value (0 = use the automatic reading)", 0.0, 500.0, 0.0, 0.01,
            key="vol_index_manual",
            help="Stands in for whichever source is in play — India VIX, DVOL or a stock's "
                 "implied volatility — so a figure read off a terminal can be used directly. "
                 "It applies to EVERY ticker in the scan, so set it when screening one name "
                 "or a set that shares an index, not a mixed list.")
        if index_manual:
            st.caption(f"Every ticker in this scan will use **{fmt(index_manual)}** as its "
                       f"volatility index, divided by the divisor for its market.")

    with st.expander("ATR volatility expansion", expanded=True):
        st.markdown("`expansion = ATR(14) / average(ATR, 20)` on the timeframe above. Below "
                    "the squeeze level the market is consolidating and an option buyer pays "
                    "theta for nothing; above the expansion level a move is underway.")
        a1, a2, a3, a4 = st.columns(4)
        atr_len = a1.number_input("ATR length", 2, 100, 14, 1, key="vol_atr_len")
        atr_avg = a2.number_input("ATR average length", 2, 200, 20, 1, key="vol_atr_avg")
        squeeze_below = a3.number_input("Squeeze below", 0.1, 3.0, 1.0, 0.05,
                                        key="vol_squeeze")
        expand_above = a4.number_input("Expansion above", 0.1, 5.0, 1.3, 0.05, key="vol_expand")

    broker = cfg.get("broker") or {}
    has_token = bool(str(broker.get("access_token", "")).strip()
                     and str(broker.get("client_id", "")).strip())
    use_oi = False
    with st.expander("Open-interest momentum ratio (needs Dhan)", expanded=has_token):
        st.markdown("`MR = change in PUT OI / change in CALL OI`, summed across the strikes "
                    "either side of spot. Above the bullish level put writers are adding "
                    "faster than call writers; below the bearish level the reverse.")
        if not has_token:
            st.info("No Dhan credentials, so this test is switched off. Open interest has no "
                    "free source — the rest of the tab works without it.")
        else:
            use_oi = st.checkbox("Include the OI momentum ratio", value=True,
                                 key=f"vol_use_oi_{'tok' if has_token else 'none'}")
            o1, o2, o3, o4 = st.columns(4)
            mr_bull = o1.number_input("Bullish above", 0.1, 20.0, 2.5, 0.1, key="vol_mr_bull")
            mr_bear = o2.number_input("Bearish below", 0.01, 5.0, 0.4, 0.05, key="vol_mr_bear")
            strikes_side = o3.number_input("Strikes either side of spot", 1, 25, 5, 1,
                                           key="vol_strikes")
            mr_window = o4.number_input("Target window (minutes)", 1.0, 120.0, 15.0, 1.0,
                                        key="vol_mr_window",
                                        help="The interval the change is meant to be measured "
                                             "over. The actual gap between the two snapshots "
                                             "is reported per row, because it is whatever the "
                                             "scans happened to be.")
            st.caption("The ratio needs TWO chain snapshots. The first scan takes one; run it "
                       "again after your window and the ratio appears.")
    if not has_token:
        mr_bull, mr_bear, strikes_side, mr_window = 2.5, 0.4, 5, 15.0

    vcfg = {"interval": interval, "sigma_mode": sigma_mode, "vix": live_vix,
            "vix_divisor": vix_divisor, "rv_lookback": rv_lookback,
            "dvol_divisor": dvol_divisor, "dvol_manual": dvol_manual,
            "index_manual": index_manual,
            "atr_len": atr_len, "atr_avg_len": atr_avg,
            "squeeze_below": squeeze_below, "expand_above": expand_above,
            "use_oi": bool(use_oi and has_token), "mr_bull": mr_bull, "mr_bear": mr_bear,
            "strikes_each_side": strikes_side, "mr_window": mr_window}

    def _worker(ticker):
        try:
            return [volatility_scan_one(ticker, vcfg, broker if has_token else None)], []
        except Exception as exc:                                    # noqa: BLE001
            return [], [{"Ticker": ticker, "Problem": str(exc)[:140]}]

    scan_cost_notice(len(chosen), per_job_hint=2.5, prefix="vol")
    rows, errs, _done = chunked_sweep("vol", list(chosen), _worker,
                                      _auto_slice_seconds(), "tickers")

    frame = pd.DataFrame(rows)
    if frame.empty:
        st.info("Nothing scanned yet. Press **Run** above.")
        if errs:
            with st.expander(f"Tickers that could not be read ({len(errs)})"):
                st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
        return

    a, b, c, d = st.columns(4)
    a.metric("Scanned", len(frame))
    b.metric("In expansion", int((frame["Volatility state"] == "EXPANSION").sum()),
             "option buying favourable")
    c.metric("In a squeeze", int((frame["Volatility state"] == "SQUEEZE").sum()),
             "theta eats the premium")
    triggers = frame[frame["OI trigger"].astype(str).str.startswith(("BULLISH", "BEARISH"))] \
        if "OI trigger" in frame.columns else frame.iloc[0:0]
    d.metric("OI triggers", len(triggers))

    order = [c for c in ["Ticker", "Spot", "Volatility state", "ATR expansion",
                         "Squeeze below", "Expansion above", "Option buying",
                         "1 SD (points)", "1 SD (%)", "Travelled",
                         "+1SD", "-1SD", "+2SD", "-2SD", "+3SD", "-3SD",
                         "Sigma basis", "OI momentum ratio", "OI trigger",
                         "CE OI change", "PE OI change", "OI window (min)", "OI state",
                         "Caution", "Checked at"] if c in frame.columns]
    st.dataframe(frame[order], width="stretch", hide_index=True)
    st.download_button("Download the levels (CSV)", frame[order].to_csv(index=False).encode(),
                       f"volatility_levels_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv",
                       key="vol_dl")

    st.markdown("#### Levels for one ticker")
    p1, p2 = st.columns([2, 1])
    pick = p1.selectbox("Ticker", frame["Ticker"].tolist(), key="vol_pick")
    row = frame[frame["Ticker"] == pick].iloc[0].to_dict()

    ladder = []
    for n in (3, 2, 1):
        ladder.append({"Level": f"+{n} SD", "Price": row.get(f"+{n}SD")})
    ladder.append({"Level": "SPOT", "Price": row.get("Spot")})
    for n in (1, 2, 3):
        ladder.append({"Level": f"-{n} SD", "Price": row.get(f"-{n}SD")})
    st.dataframe(pd.DataFrame(ladder), width="stretch", hide_index=True)
    st.caption(f"One standard deviation is {fmt(row.get('1 SD (points)'))} points "
               f"({fmt(row.get('1 SD (%)'))}% of spot), from {row.get('Sigma basis')}. "
               f"About two days in three finish inside 1 SD and about 19 in 20 inside 2 SD "
               f"IF returns were normally distributed — they are not, and real markets "
               f"breach these bands more often than the maths says, especially on news.")
    if str(row.get("Caution", "-")) != "-":
        st.warning(row["Caution"])
    if str(row.get("OI state", "")) not in ("", "-"):
        st.caption(f"Open interest: {row['OI state']}")

    if p2.button("Apply to the sidebar", width="stretch", key="vol_apply"):
        st.session_state.pending_ticker = pick
        st.session_state.pending_combo = {
            "strategy": "25 · SuperTrend Flip",
            "sl_type": "ATR Multiple", "sl_value": 1.5,
            "tp_type": "Risk : Reward Multiple", "tp_value": 2.0,
            "filter_key": "", "widgets": {"cfg_interval": interval}}
        st.rerun()

    if errs:
        with st.expander(f"Tickers that could not be read ({len(errs)})"):
            st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
    render_analyst_panel("vol", "these volatility levels", _frame_context(frame))


# =============================================================================
# SECTION 19h -- INDICATOR CONDITION REGISTRY
# =============================================================================
# One entry per indicator: what it is called, which family it belongs to, the
# parameters the operator may change, and a function that turns the indicator
# into a BULLISH verdict, a BEARISH verdict and a readable current value.
#
# The contract every entry keeps:
#   fn(df, p) -> (bull: bool, bear: bool, value: float, text: str)
# evaluated on the LAST CLOSED candle, never the forming one.
#
# Bull and bear are deliberately allowed to be both False. "Neither" is the
# commonest honest answer for an indicator sitting mid-range, and forcing a
# verdict out of it is how a screener manufactures signals.

def _last(series, offset: int = 0) -> float:
    try:
        value = float(pd.Series(series).iloc[-1 - offset])
    except (IndexError, TypeError, ValueError):
        return float("nan")
    return value


def _ok(*values) -> bool:
    return all(np.isfinite(v) for v in values)


# --- trend / moving averages ------------------------------------------------
def _i_price_vs_ma(df, p, builder, name):
    ma = builder(df, int(p["length"]))
    price, basis = _last(df["Close"]), _last(ma)
    if not _ok(price, basis):
        return False, False, float("nan"), "not enough history"
    return price > basis, price < basis, basis, f"price {fmt(price)} vs {name} {fmt(basis)}"


def i_sma(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: sma(d["Close"], n), "SMA")


def i_ema(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: ema(d["Close"], n), "EMA")


def i_wma(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: wma(d["Close"], n), "WMA")


def i_hma(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: hma(d["Close"], n), "HMA")


def i_dema(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: dema(d["Close"], n), "DEMA")


def i_tema(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: tema(d["Close"], n), "TEMA")


def i_kama(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: kama(d["Close"], n), "KAMA")


def i_vwma(df, p):
    return _i_price_vs_ma(df, p, lambda d, n: vwma(d["Close"], d["Volume"], n), "VWMA")


def i_ma_cross(df, p):
    fast, slow = ema(df["Close"], int(p["fast"])), ema(df["Close"], int(p["slow"]))
    f, s = _last(fast), _last(slow)
    if not _ok(f, s):
        return False, False, float("nan"), "not enough history"
    gap = f - s
    return f > s, f < s, gap, f"fast {fmt(f)} vs slow {fmt(s)}"


def i_ma_cross_fresh(df, p):
    """Only the bar the cross actually happened on, not every bar afterwards."""
    fast, slow = ema(df["Close"], int(p["fast"])), ema(df["Close"], int(p["slow"]))
    up = bool(cross_over(fast, slow).iloc[-1]) if len(fast) > 2 else False
    down = bool(cross_under(fast, slow).iloc[-1]) if len(fast) > 2 else False
    return up, down, _last(fast) - _last(slow), "crossover on this candle only"


def i_triple_ma(df, p):
    a = _last(ema(df["Close"], int(p["fast"])))
    b = _last(ema(df["Close"], int(p["mid"])))
    c = _last(ema(df["Close"], int(p["slow"])))
    if not _ok(a, b, c):
        return False, False, float("nan"), "not enough history"
    return a > b > c, a < b < c, a - c, f"{fmt(a)} / {fmt(b)} / {fmt(c)}"


def i_linreg_slope(df, p):
    value = _last(slope(df["Close"], int(p["length"])))
    threshold = float(p["threshold"])
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value > threshold, value < -threshold, value, f"slope {fmt(value, 4)}"


# --- momentum ---------------------------------------------------------------
def i_rsi(df, p):
    value = _last(rsi(df["Close"], int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value < float(p["oversold"]), value > float(p["overbought"]), value, \
        f"RSI {fmt(value)}"


def i_rsi_trend(df, p):
    """RSI as a TREND reading rather than a reversion one: above or below 50."""
    value = _last(rsi(df["Close"], int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    mid = float(p["midline"])
    return value > mid, value < mid, value, f"RSI {fmt(value)} vs {fmt(mid)}"


def i_stochastic(df, p):
    k, d = stochastic(df["High"], df["Low"], df["Close"], int(p["k"]), int(p["d"]),
                      int(p["smooth"]))
    kv, dv = _last(k), _last(d)
    if not _ok(kv, dv):
        return False, False, float("nan"), "not enough history"
    return (kv < float(p["oversold"]) and kv > dv), \
           (kv > float(p["overbought"]) and kv < dv), kv, f"%K {fmt(kv)} %D {fmt(dv)}"


def i_stoch_rsi(df, p):
    k, _d = stoch_rsi(df["Close"], int(p["rsi_len"]), int(p["stoch_len"]))
    value = _last(k)
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value < float(p["oversold"]), value > float(p["overbought"]), value, \
        f"StochRSI {fmt(value)}"


def i_macd(df, p):
    line, signal, hist = macd(df["Close"], int(p["fast"]), int(p["slow"]), int(p["signal"]))
    m_, s_, h_ = _last(line), _last(signal), _last(hist)
    if not _ok(m_, s_):
        return False, False, float("nan"), "not enough history"
    return m_ > s_, m_ < s_, h_, f"MACD {fmt(m_)} vs signal {fmt(s_)}"


def i_macd_zero(df, p):
    line, _s, _h = macd(df["Close"], int(p["fast"]), int(p["slow"]), int(p["signal"]))
    value = _last(line)
    return value > 0, value < 0, value, f"MACD line {fmt(value)} vs zero"


def i_cci(df, p):
    value = _last(cci(df["High"], df["Low"], df["Close"], int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value > float(p["bull_above"]), value < float(p["bear_below"]), value, \
        f"CCI {fmt(value)}"


def i_williams(df, p):
    value = _last(williams_r(df["High"], df["Low"], df["Close"], int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value < float(p["oversold"]), value > float(p["overbought"]), value, \
        f"%R {fmt(value)}"


def i_roc(df, p):
    value = _last(roc(df["Close"], int(p["length"])))
    threshold = float(p["threshold"])
    return value > threshold, value < -threshold, value, f"ROC {fmt(value)}%"


def i_momentum(df, p):
    value = _last(momentum(df["Close"], int(p["length"])))
    return value > 0, value < 0, value, f"momentum {fmt(value)}"


def i_tsi(df, p):
    value = _last(tsi(df["Close"], int(p["long"]), int(p["short"])))
    threshold = float(p["threshold"])
    return value > threshold, value < -threshold, value, f"TSI {fmt(value)}"


def i_ultimate(df, p):
    value = _last(ultimate_oscillator(df["High"], df["Low"], df["Close"]))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value < float(p["oversold"]), value > float(p["overbought"]), value, \
        f"UO {fmt(value)}"


def i_awesome(df, p):
    series = awesome_oscillator(df["High"], df["Low"], int(p["fast"]), int(p["slow"]))
    now, before = _last(series), _last(series, 1)
    if not _ok(now, before):
        return False, False, float("nan"), "not enough history"
    return now > 0 and now > before, now < 0 and now < before, now, f"AO {fmt(now)}"


def i_cmo(df, p):
    value = _last(cmo(df["Close"], int(p["length"])))
    threshold = float(p["threshold"])
    return value > threshold, value < -threshold, value, f"CMO {fmt(value)}"


def i_trix(df, p):
    value = _last(trix(df["Close"], int(p["length"])))
    return value > 0, value < 0, value, f"TRIX {fmt(value, 4)}%"


def i_coppock(df, p):
    series = coppock(df["Close"])
    now, before = _last(series), _last(series, 1)
    if not _ok(now, before):
        return False, False, float("nan"), "not enough history"
    return now > before, now < before, now, f"Coppock {fmt(now)}"


def i_kst(df, p):
    line, signal = kst(df["Close"])
    a, b = _last(line), _last(signal)
    if not _ok(a, b):
        return False, False, float("nan"), "not enough history"
    return a > b, a < b, a, f"KST {fmt(a)} vs signal {fmt(b)}"


def i_dpo(df, p):
    value = _last(dpo(df["Close"], int(p["length"])))
    return value > 0, value < 0, value, f"DPO {fmt(value)}"


def i_fisher(df, p):
    value, trigger = fisher_transform(df["High"], df["Low"], int(p["length"]))
    a, b = _last(value), _last(trigger)
    if not _ok(a, b):
        return False, False, float("nan"), "not enough history"
    return a > b, a < b, a, f"Fisher {fmt(a)} vs trigger {fmt(b)}"


def i_rvi(df, p):
    value, signal = relative_vigor_index(df, int(p["length"]))
    a, b = _last(value), _last(signal)
    if not _ok(a, b):
        return False, False, float("nan"), "not enough history"
    return a > b, a < b, a, f"RVI {fmt(a, 4)}"


def i_bop(df, p):
    value = _last(balance_of_power(df, int(p["length"])))
    threshold = float(p["threshold"])
    return value > threshold, value < -threshold, value, f"BOP {fmt(value, 4)}"


# --- trend strength / direction --------------------------------------------
def i_adx(df, p):
    a, plus, minus = adx(df["High"], df["Low"], df["Close"], int(p["length"]))
    av, pv, mv = _last(a), _last(plus), _last(minus)
    if not _ok(av, pv, mv):
        return False, False, float("nan"), "not enough history"
    strong = av >= float(p["min_adx"])
    return strong and pv > mv, strong and mv > pv, av, \
        f"ADX {fmt(av)}  +DI {fmt(pv)}  -DI {fmt(mv)}"


def i_aroon(df, p):
    up, down = aroon(df["High"], df["Low"], int(p["length"]))
    uv, dv = _last(up), _last(down)
    if not _ok(uv, dv):
        return False, False, float("nan"), "not enough history"
    level = float(p["level"])
    return uv > level and uv > dv, dv > level and dv > uv, uv - dv, \
        f"Aroon up {fmt(uv)} down {fmt(dv)}"


def i_vortex(df, p):
    plus, minus = vortex(df["High"], df["Low"], df["Close"], int(p["length"]))
    pv, mv = _last(plus), _last(minus)
    if not _ok(pv, mv):
        return False, False, float("nan"), "not enough history"
    return pv > mv, mv > pv, pv - mv, f"VI+ {fmt(pv, 3)} VI- {fmt(mv, 3)}"


def i_supertrend(df, p):
    direction, _u, _l = supertrend(df["High"], df["Low"], df["Close"],
                                   int(p["length"]), float(p["mult"]))
    value = _last(direction)
    return value > 0, value < 0, value, f"SuperTrend {'up' if value > 0 else 'down'}"


def i_psar(df, p):
    sar, bull = psar(df["High"], df["Low"], float(p["step"]), float(p["cap"]))
    is_long = bool(pd.Series(bull).iloc[-1]) if len(bull) else False
    return is_long, not is_long, _last(sar), f"SAR {fmt(_last(sar))}"


def i_choppiness(df, p):
    value = _last(choppiness(df["High"], df["Low"], df["Close"], int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    trending = value < float(p["trending_below"])
    rising = _last(df["Close"]) > _last(ema(df["Close"], 20))
    return trending and rising, trending and not rising, value, \
        f"Choppiness {fmt(value)} ({'trending' if trending else 'ranging'})"


def i_ichimoku(df, p):
    tenkan, kijun, span_a, span_b = ichimoku(df["High"], df["Low"], df["Close"],
                                             int(p["conversion"]), int(p["base"]),
                                             int(p["span_b"]))
    price = _last(df["Close"])
    a, b, t, k = _last(span_a), _last(span_b), _last(tenkan), _last(kijun)
    if not _ok(price, a, b, t, k):
        return False, False, float("nan"), "not enough history"
    top, bottom = max(a, b), min(a, b)
    return (price > top and t > k), (price < bottom and t < k), price - top, \
        f"price {fmt(price)} vs cloud {fmt(bottom)}-{fmt(top)}"


def i_heikin(df, p):
    ha = heikin_ashi(df)
    need = max(int(p["streak"]), 1)
    if len(ha) < need:
        return False, False, float("nan"), "not enough history"
    tail = ha.tail(need)
    up = bool((tail["ha_close"] > tail["ha_open"]).all())
    down = bool((tail["ha_close"] < tail["ha_open"]).all())
    body = _last(ha["ha_close"]) - _last(ha["ha_open"])
    return up, down, body, f"{need} Heikin Ashi candle(s) one colour"


def i_elder_ray(df, p):
    bull_power, bear_power = elder_ray(df["High"], df["Low"], df["Close"], int(p["length"]))
    bp, sp = _last(bull_power), _last(bear_power)
    if not _ok(bp, sp):
        return False, False, float("nan"), "not enough history"
    return bp > 0 and sp > 0, bp < 0 and sp < 0, bp, \
        f"bull {fmt(bp)} bear {fmt(sp)}"


# --- volatility / channels --------------------------------------------------
def i_bollinger(df, p):
    upper, basis, lower = bollinger(df["Close"], int(p["length"]), float(p["mult"]))
    price, u, lo = _last(df["Close"]), _last(upper), _last(lower)
    if not _ok(price, u, lo):
        return False, False, float("nan"), "not enough history"
    if str(p["mode"]).startswith("Rever"):
        return price < lo, price > u, price, f"price {fmt(price)} band {fmt(lo)}-{fmt(u)}"
    return price > u, price < lo, price, f"price {fmt(price)} band {fmt(lo)}-{fmt(u)}"


def i_keltner(df, p):
    upper, _b, lower = keltner(df["High"], df["Low"], df["Close"],
                               int(p["length"]), float(p["mult"]))
    price, u, lo = _last(df["Close"]), _last(upper), _last(lower)
    if not _ok(price, u, lo):
        return False, False, float("nan"), "not enough history"
    return price > u, price < lo, price, f"price {fmt(price)} channel {fmt(lo)}-{fmt(u)}"


def i_donchian(df, p):
    hi, lo = donchian(df["High"], df["Low"], int(p["length"]))
    price, h, l_ = _last(df["Close"]), _last(hi), _last(lo)
    if not _ok(price, h, l_):
        return False, False, float("nan"), "not enough history"
    return price > h, price < l_, price, f"channel {fmt(l_)}-{fmt(h)}"


def i_squeeze(df, p):
    """Bollinger bands inside Keltner channels: a classic coiled-spring test."""
    bb_u, _bb_b, bb_l = bollinger(df["Close"], int(p["length"]), float(p["bb_mult"]))
    kc_u, _kc_b, kc_l = keltner(df["High"], df["Low"], df["Close"],
                                int(p["length"]), float(p["kc_mult"]))
    inside = bool(_last(bb_u) < _last(kc_u) and _last(bb_l) > _last(kc_l))
    rising = _last(df["Close"]) > _last(ema(df["Close"], int(p["length"])))
    width = _last(bb_u) - _last(bb_l)
    if inside:
        return False, False, width, "in a squeeze: no direction yet"
    return not inside and rising, not inside and not rising, width, \
        "squeeze released" if not inside else "squeezed"


def i_atr_expansion(df, p):
    value = atr_expansion(df, int(p["length"]), int(p["avg_length"]))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    expanding = value > float(p["expand_above"])
    rising = _last(df["Close"]) > _last(ema(df["Close"], 20))
    return expanding and rising, expanding and not rising, value, \
        f"ATR expansion {fmt(value, 3)}"


# --- volume -----------------------------------------------------------------
def _no_volume(df) -> bool:
    return float(pd.Series(df["Volume"]).tail(200).abs().sum()) <= 0


def i_obv(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    series = obv(df["Close"], df["Volume"])
    trend = ema(series, int(p["length"]))
    return _last(series) > _last(trend), _last(series) < _last(trend), _last(series), \
        "OBV above its average" if _last(series) > _last(trend) else "OBV below its average"


def i_mfi(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    value = _last(money_flow_index(df["High"], df["Low"], df["Close"], df["Volume"],
                                   int(p["length"])))
    if not _ok(value):
        return False, False, float("nan"), "not enough history"
    return value < float(p["oversold"]), value > float(p["overbought"]), value, \
        f"MFI {fmt(value)}"


def i_cmf(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    value = _last(chaikin_money_flow(df["High"], df["Low"], df["Close"], df["Volume"],
                                     int(p["length"])))
    threshold = float(p["threshold"])
    return value > threshold, value < -threshold, value, f"CMF {fmt(value, 3)}"


def i_force(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    value = _last(force_index(df["Close"], df["Volume"], int(p["length"])))
    return value > 0, value < 0, value, f"Force {fmt(value, 0)}"


def i_adline(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    line = accumulation_distribution(df["High"], df["Low"], df["Close"], df["Volume"])
    trend = ema(line, int(p["length"]))
    return _last(line) > _last(trend), _last(line) < _last(trend), _last(line), \
        "A/D above its average" if _last(line) > _last(trend) else "A/D below"


def i_eom(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    value = _last(ease_of_movement(df["High"], df["Low"], df["Volume"], int(p["length"])))
    return value > 0, value < 0, value, f"EOM {fmt(value, 4)}"


def i_pvt(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    line = price_volume_trend(df["Close"], df["Volume"])
    trend = ema(line, int(p["length"]))
    return _last(line) > _last(trend), _last(line) < _last(trend), _last(line), "PVT vs average"


def i_volume_spike(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    now = _last(df["Volume"])
    average = _last(sma(df["Volume"], int(p["length"])))
    if not _ok(now, average) or average <= 0:
        return False, False, float("nan"), "not enough history"
    ratio = now / average
    spiking = ratio >= float(p["multiple"])
    rising = _last(df["Close"]) > _last(df["Open"])
    return spiking and rising, spiking and not rising, ratio, f"volume {fmt(ratio)}x average"


def i_volume_osc(df, p):
    if _no_volume(df):
        return False, False, float("nan"), "feed reports no volume"
    value = _last(volume_oscillator(df["Volume"], int(p["fast"]), int(p["slow"])))
    threshold = float(p["threshold"])
    rising = _last(df["Close"]) > _last(df["Open"])
    return value > threshold and rising, value > threshold and not rising, value, \
        f"volume oscillator {fmt(value)}%"


def i_vwap(df, p):
    series, volume_backed = vwap(df, True)
    price, basis = _last(df["Close"]), _last(series)
    if not _ok(price, basis):
        return False, False, float("nan"), "not enough history"
    label = "VWAP" if volume_backed else "TWAP (no volume on this feed)"
    return price > basis, price < basis, basis, f"price {fmt(price)} vs {label} {fmt(basis)}"


# --- structure / levels -----------------------------------------------------
def i_pivots(df, p):
    levels = classic_pivots(df)
    if not levels:
        return False, False, float("nan"), "needs a previous session"
    price = _last(df["Close"])
    return price > levels["P"], price < levels["P"], levels["P"], \
        f"price {fmt(price)} vs pivot {fmt(levels['P'])}"


def i_prev_day(df, p):
    high, low, _close = previous_session_levels(df)
    price = _last(df["Close"])
    if not _ok(price, high, low):
        return False, False, float("nan"), "needs a previous session"
    return price > high, price < low, price, f"PDH {fmt(high)} PDL {fmt(low)}"


def i_breakout(df, p):
    hi = _last(rolling_high(df["High"], int(p["length"]), True))
    lo = _last(rolling_low(df["Low"], int(p["length"]), True))
    price = _last(df["Close"])
    if not _ok(price, hi, lo):
        return False, False, float("nan"), "not enough history"
    return price > hi, price < lo, price, f"{int(p['length'])}-bar range {fmt(lo)}-{fmt(hi)}"


def i_market_structure(df, p):
    """
    Break of structure, from the confirmed-swing engine the SMC profiles use.

    ``market_structure`` returns (direction, swing_high, swing_low) where the
    direction is +1 after a bullish break and -1 after a bearish one, carried
    forward until the opposite break.
    """
    direction, swing_high, swing_low = market_structure(df, int(p["left"]), int(p["right"]))
    value = _last(direction)
    if not _ok(value) or value == 0:
        return False, False, 0.0, "no break of structure yet"
    side = "bullish" if value > 0 else "bearish"
    return value > 0, value < 0, value, \
        (f"{side} break of structure; swing high {fmt(_last(swing_high))}, "
         f"swing low {fmt(_last(swing_low))}")


