def sector_label_for(ticker: str) -> str:
    """
    A readable sector for a ticker, from live index data where possible.

    The industry comes from the NSE constituent CSV, which is the authority and
    stays right through a rebalance. NSE frequently refuses datacentre traffic
    though, and when it does that map is empty -- which is why this column kept
    coming back blank. The bundled list covers the large caps so the column
    says something useful either way.
    """
    live = str(SECTOR_BY_TICKER.get(ticker, "")).strip()
    if live and live != "--":
        return live
    base = (ticker or "").upper().replace(".NS", "").replace(".BO", "")
    if (ticker or "").startswith("^") or base in {"NIFTY_FIN_SERVICE"}:
        return "Index"
    return _FALLBACK_SECTORS.get(base, "--")


def sector_index_for(ticker: str) -> str | None:
    """The sector index representing a ticker, or None when there is no match."""
    # Uses the same resolution as the label, so a ticker that shows a sector
    # always has one to be compared against -- they cannot disagree.
    industry = sector_label_for(ticker).strip().upper()
    if not industry or industry in ("--", "INDEX"):
        return None
    if industry in INDUSTRY_TO_SECTOR_INDEX:
        return INDUSTRY_TO_SECTOR_INDEX[industry]
    for key, symbol in INDUSTRY_TO_SECTOR_INDEX.items():
        if key in industry or industry in key:
            return symbol
    return None


def sector_bias(symbol: str, interval: str, selected: list[str] | None = None,
                params: dict | None = None) -> tuple[str, float, int, int]:
    """
    Which way a sector index is leaning, and by how much.

    Scored with the SAME indicator set the tickers are scored with, so "sector
    bullish" means the same thing as "ticker bullish" rather than being a
    different measurement wearing the same word. Returns
    ``(bias, percent, bull, bear)``.

    One download per SECTOR per timeframe, not per ticker: the market-data
    cache sees the identical arguments from every member of that sector.
    """
    if not symbol:
        return "unknown", float("nan"), 0, 0
    try:
        period, _ = lab_period_for(interval, 250)
        frame = load_market_data(symbol, period, interval,
                                 freshness_seconds=300, min_bars=60).frame
    except Exception:                                               # noqa: BLE001
        return "unknown", float("nan"), 0, 0

    keys = list(selected or ["ema", "ma_cross", "rsi_trend", "macd", "adx", "supertrend"])
    verdicts = evaluate_indicators(frame, keys, params or {})
    bull = sum(1 for v in verdicts if v["bull"])
    bear = sum(1 for v in verdicts if v["bear"])
    scored = sum(1 for v in verdicts
                 if not str(v["text"]).startswith(("failed", "not enough")))
    if not scored:
        return "unknown", float("nan"), bull, bear
    if bull == bear:
        return "MIXED", round(max(bull, bear) / scored * 100.0, 1), bull, bear
    leaning = "BULLISH" if bull > bear else "BEARISH"
    return leaning, round(max(bull, bear) / scored * 100.0, 1), bull, bear


def custom_screen_one(ticker: str, interval: str, selected: list[str], params: dict,
                      filter_cfg: dict | None, flip_on_sector: bool,
                      cfg_params: dict) -> dict:
    """Score one ticker on one timeframe across every selected indicator."""
    period, _ = lab_period_for(interval, 250)
    frame = load_market_data(ticker, period, interval,
                             freshness_seconds=180, min_bars=60).frame

    verdicts = evaluate_indicators(frame, selected, params)
    bull = sum(1 for v in verdicts if v["bull"])
    bear = sum(1 for v in verdicts if v["bear"])
    usable = sum(1 for v in verdicts if not str(v["text"]).startswith(("failed", "not enough")))

    # --- additional entry filters, the same ones the strategies use ----------
    filters_pass_long = filters_pass_short = True
    filter_note = "none enabled"
    if filter_cfg and any(v.get("enabled") for v in filter_cfg.values()):
        params_for_filters = dict(cfg_params)
        params_for_filters["intraday"] = interval in INTRADAY_INTERVALS
        attached = attach_filter_columns(frame.copy(), params_for_filters,
                                         bool(params_for_filters["intraday"]))
        ok_long, ok_short, reports = evaluate_filters(attached, filter_cfg, {})
        # The LAST row is the forming candle, so the filters are read on the
        # last CLOSED one -- the same bar the indicators were scored on.
        closed_at = max(len(frame) - 2, 0)
        filters_pass_long = bool(pd.Series(ok_long).iloc[closed_at])
        filters_pass_short = bool(pd.Series(ok_short).iloc[closed_at])
        # A report's long_ok / short_ok are scalars describing the newest bar,
        # which is enough to name what is blocking.
        blocked = [r.label for r in reports if not (r.long_ok or r.short_ok)]
        filter_note = ("blocked by " + ", ".join(blocked)) if blocked \
            else "all enabled filters pass"

    raw_bias = ("BULLISH" if bull > bear else "BEARISH" if bear > bull else "MIXED")

    # --- the sector ---------------------------------------------------------
    #
    # Read on EVERY scan, not only when the flip is enabled: the sector a name
    # belongs to and which way that sector is leaning are worth knowing whether
    # or not they are being acted on.
    sector_symbol = sector_index_for(ticker)
    sector_view, sector_pct, sector_bull, sector_bear = \
        sector_bias(sector_symbol, interval, selected, params) if sector_symbol \
        else ("no sector index", float("nan"), 0, 0)

    # --- the flip, on DISAGREEMENT -------------------------------------------
    #
    # The rule is sector alignment: when a ticker is leaning one way and its
    # own sector the other, the sector wins and the ticker's verdict is
    # inverted to match it. A ticker already agreeing with its sector is left
    # alone -- there is nothing to reconcile.
    flipped = False
    bias = raw_bias
    if flip_on_sector and sector_view in ("BULLISH", "BEARISH") and raw_bias != "MIXED":
        if sector_view != raw_bias:
            bias = sector_view
            bull, bear = bear, bull
            flipped = True

    # Filters gate the FINAL direction, after any flip -- otherwise a filter
    # would be vetting a direction the screener is no longer proposing.
    gated = bias
    if bias == "BULLISH" and not filters_pass_long:
        gated = "FILTERED OUT"
    elif bias == "BEARISH" and not filters_pass_short:
        gated = "FILTERED OUT"

    sector_name = sector_label_for(ticker)
    if sector_view in ("BULLISH", "BEARISH", "MIXED") and np.isfinite(sector_pct):
        sector_column = f"{sector_name} · {sector_pct:.0f}% {sector_view.lower()}"
    else:
        sector_column = sector_name

    row = {
        "Ticker": ticker, "Timeframe": interval,
        "Sector": sector_column,
        "Price": round(float(frame["Close"].iloc[-1]), 2),
        # The full chain, so a verdict can always be traced:
        #   indicators -> raw  ->  sector flip  ->  entry filters  -> Bias
        "Bias": gated, "Bias before filters": bias, "Bias before flip": raw_bias,
        "Bullish": bull, "Bearish": bear,
        "Agreement %": round(max(bull, bear) / usable * 100.0, 1) if usable else None,
        "Indicators scored": usable, "Indicators selected": len(selected),
        "Sector index": sector_symbol or "--", "Sector bias": sector_view,
        "Sector agreement %": sector_pct if np.isfinite(sector_pct) else None,
        "Sector bullish": sector_bull, "Sector bearish": sector_bear,
        "Flipped": "yes" if flipped else "no",
        "Filters": filter_note,
        "Checked at": pd.Timestamp.now(),
    }
    for v in verdicts:
        row[v["label"]] = "BULL" if v["bull"] else ("BEAR" if v["bear"] else "-")
    row["_detail"] = verdicts
    return row


def _multi_picker(label: str, options: list, prefix: str, defaults: list,
                  formatter=None) -> list:
    """
    A checkbox grid with select-all and clear-all.

    A multiselect would need every entry removing by hand; with sixty-odd
    indicators that is the difference between a usable control and a chore.
    """
    head, c_all, c_none = st.columns([3, 1, 1])
    head.markdown(f"**{label}**")
    if c_all.button("Select all", key=f"{prefix}_all", width="stretch"):
        for option in options:
            st.session_state[f"{prefix}_cb_{option}"] = True
        st.rerun()
    if c_none.button("Clear all", key=f"{prefix}_none", width="stretch"):
        for option in options:
            st.session_state[f"{prefix}_cb_{option}"] = False
        st.rerun()
    picked = []
    columns = st.columns(4)
    for i, option in enumerate(options):
        text = formatter(option) if formatter else str(option)
        if columns[i % 4].checkbox(text, value=option in defaults,
                                   key=f"{prefix}_cb_{option}"):
            picked.append(option)
    return picked


# =============================================================================
# SECTION 19j -- SMART MONEY CONCEPTS
# =============================================================================
# Every SMC idea the data can actually support, computed from confirmed swings
# so nothing here reads a pivot that has not finished forming.
#
# The honest framing: SMC is a VOCABULARY for describing price structure, not a
# tested edge. An order block is "the last opposite candle before the move that
# broke structure" -- a definition, not a prediction. The verdict below counts
# how many concepts currently lean each way; whether that count makes money is
# a question for the Backtesting tab, and this panel says so.

# Overlay colours. Direction uses the app's own semantic pair, so a bullish
# order block is the same green as a bullish candle. Liquidity sweeps get the
# one extra hue, validated against both chart surfaces for colour-vision
# separation; everything else is distinguished by shape and a direct label, so
# identity never rests on colour alone.
_SMC_SWEEP = "#3d87e8"
_SMC_INK = "#8d99ae"


def smc_analyse(df: pd.DataFrame, left: int = 3, right: int = 3,
                lookback: int = 150, equal_tol_pct: float = 0.05,
                min_pierce: float = 0.15, min_reject: float = 0.10,
                sweep_window: int = 10) -> dict:
    """
    Every SMC concept this data can support, on ONE frame.

    Returns a dict of concepts, each with a verdict ("bull", "bear" or
    "neutral"), a readable reading, and whatever levels the chart needs.
    """
    closed = df.iloc[:-1] if len(df) > 2 else df
    if len(closed) < max(30, left + right + 10):
        return {"error": "not enough candles for a structural read"}

    price = float(closed["Close"].iloc[-1])
    out: dict = {"price": price, "concepts": {}, "shapes": {}}

    def add(name: str, verdict: str, reading: str) -> None:
        out["concepts"][name] = {"verdict": verdict, "reading": reading}

    # --- 1. swing structure --------------------------------------------------
    swing_high, swing_low, prev_high, prev_low = swing_levels(
        closed["High"], closed["Low"], left, right)
    sh, sl_ = _last(swing_high), _last(swing_low)
    out["shapes"]["swing_high"] = sh
    out["shapes"]["swing_low"] = sl_
    out["shapes"]["prev_swing_high"] = _last(prev_high)
    out["shapes"]["prev_swing_low"] = _last(prev_low)
    if _ok(sh, sl_):
        add("Swing structure", "neutral",
            f"last confirmed swing high {fmt(sh)}, swing low {fmt(sl_)} "
            f"(confirmed {right} candles after the fact, so neither is live)")

    # --- 2. break of structure ----------------------------------------------
    direction, _sh, _sl = market_structure(closed, left, right)
    bos = _last(direction)
    if _ok(bos) and bos != 0:
        add("Break of structure (BOS)", "bull" if bos > 0 else "bear",
            f"price has broken the last swing {'high' if bos > 0 else 'low'}")
    else:
        add("Break of structure (BOS)", "neutral", "no break of structure yet")

    # --- 3. change of character ---------------------------------------------
    # CHoCH is the FIRST break against the prevailing direction: the bar where
    # the structural trend changes sign, not every subsequent break.
    flips = direction[direction != 0]
    choch_dir, choch_at = 0, None
    if len(flips) > 1:
        changed = flips[flips != flips.shift(1)]
        if len(changed) > 1:
            choch_dir = int(changed.iloc[-1])
            choch_at = changed.index[-1]
    if choch_dir:
        add("Change of character (CHoCH)", "bull" if choch_dir > 0 else "bear",
            f"structure last flipped {'bullish' if choch_dir > 0 else 'bearish'} "
            f"on {fmt_time(choch_at)}")
    else:
        add("Change of character (CHoCH)", "neutral", "no structural flip in this window")

    # --- 4. order blocks -----------------------------------------------------
    # The last down candle before an up-move that broke structure, and mirror.
    recent = closed.tail(int(lookback))
    bull_ob = bear_ob = None
    body_down = recent["Close"] < recent["Open"]
    body_up = recent["Close"] > recent["Open"]
    structure_tail = direction.tail(len(recent))
    for i in range(len(recent) - 2, 1, -1):
        if bull_ob is None and bool(body_down.iloc[i]) and \
                float(structure_tail.iloc[min(i + 2, len(structure_tail) - 1)]) > 0:
            bull_ob = (float(recent["Low"].iloc[i]), float(recent["High"].iloc[i]),
                       recent.index[i])
        if bear_ob is None and bool(body_up.iloc[i]) and \
                float(structure_tail.iloc[min(i + 2, len(structure_tail) - 1)]) < 0:
            bear_ob = (float(recent["Low"].iloc[i]), float(recent["High"].iloc[i]),
                       recent.index[i])
        if bull_ob and bear_ob:
            break
    out["shapes"]["bull_ob"], out["shapes"]["bear_ob"] = bull_ob, bear_ob
    if bull_ob:
        inside = bull_ob[0] <= price <= bull_ob[1]
        add("Bullish order block", "bull" if inside else "neutral",
            f"{fmt(bull_ob[0])}-{fmt(bull_ob[1])} from {fmt_time(bull_ob[2])}"
            + (" — price is inside it (mitigating)" if inside else " — not yet revisited"))
    if bear_ob:
        inside = bear_ob[0] <= price <= bear_ob[1]
        add("Bearish order block", "bear" if inside else "neutral",
            f"{fmt(bear_ob[0])}-{fmt(bear_ob[1])} from {fmt_time(bear_ob[2])}"
            + (" — price is inside it (mitigating)" if inside else " — not yet revisited"))

    # --- 5. fair value gaps --------------------------------------------------
    fb, fs, fb_lo, fb_hi, fs_lo, fs_hi = fair_value_gaps(closed)
    recent_bull_fvg = bool(fb.tail(int(lookback)).any())
    recent_bear_fvg = bool(fs.tail(int(lookback)).any())
    bull_gap = (_last(fb_lo), _last(fb_hi)) if recent_bull_fvg else None
    bear_gap = (_last(fs_lo), _last(fs_hi)) if recent_bear_fvg else None
    out["shapes"]["bull_fvg"], out["shapes"]["bear_fvg"] = bull_gap, bear_gap
    if bull_gap and _ok(*bull_gap):
        unfilled = price > bull_gap[1]
        add("Bullish fair value gap", "bull" if unfilled else "neutral",
            f"{fmt(bull_gap[0])}-{fmt(bull_gap[1])}"
            + (" — still unfilled below price" if unfilled else " — price has traded back into it"))
    if bear_gap and _ok(*bear_gap):
        unfilled = price < bear_gap[0]
        add("Bearish fair value gap", "bear" if unfilled else "neutral",
            f"{fmt(bear_gap[0])}-{fmt(bear_gap[1])}"
            + (" — still unfilled above price" if unfilled else " — price has traded back into it"))

    # --- 6. liquidity sweeps -------------------------------------------------
    #
    # A sweep is a wick through a CONFIRMED prior swing that closes back
    # inside: stops taken, then rejection. The close is what separates a sweep
    # from a genuine break.
    #
    # THE BUG THIS REPLACES. The first version tested "did any bar's high
    # exceed the running swing-high level while closing below it", over forty
    # bars, with no minimum penetration and no minimum rejection. On a random
    # walk that fired on 86% of samples and reported BOTH a buy-side and a
    # sell-side sweep at once on 69% of them -- so every summary said liquidity
    # had been taken in both directions, which reads as hardcoded text because
    # it carries no information. Four conditions now have to hold:
    #
    #   1. the level is a swing CONFIRMED BEFORE the sweep bar, not a level
    #      carried forward from the running series,
    #   2. the wick clears it by at least `min_pierce` x ATR, so a one-tick
    #      overshoot does not count,
    #   3. the candle closes back inside by at least `min_reject` x ATR, which
    #      is the rejection itself,
    #   4. it happened within `sweep_window` candles, because liquidity taken
    #      sixty bars ago is history, not context.
    #
    # Both sides can still be reported, but only the MORE RECENT one is treated
    # as the active narrative -- a market cannot be reacting to both at once.
    atr_now = _last(atr(closed["High"], closed["Low"], closed["Close"], 14))
    if not _ok(atr_now) or atr_now <= 0:
        atr_now = max(price * 0.002, 1e-9)
    pierce = float(min_pierce) * atr_now
    reject = float(min_reject) * atr_now

    tail = closed.tail(int(lookback))
    highs, lows = tail["High"].to_numpy(float), tail["Low"].to_numpy(float)
    closes = tail["Close"].to_numpy(float)
    stamps = list(tail.index)
    sweep_up = sweep_down = None
    scan_from = max(len(tail) - int(sweep_window), left + right + 1)

    # The actual pivot POINTS, with the bar each was confirmed on. A pivot at
    # position p is only knowable at p + right, so that is when it may be used
    # as a level. Using the window's running high instead -- which the first
    # attempt at this fix did -- tests whether a bar set a new extreme for the
    # whole window, which is a different and much rarer event, and it fired
    # asymmetrically depending on which way the sample happened to drift.
    pivot_highs, pivot_lows = [], []
    for p in range(left, len(tail) - right):
        # STRICTLY higher than the bars before it, and at least as high as the
        # bars after. A non-strict test on both sides makes every bar of a flat
        # stretch a pivot, so a one-tick poke above a sideways range registered
        # as a liquidity sweep of a level nobody was watching.
        before_h, after_h = highs[p - left:p], highs[p + 1:p + right + 1]
        before_l, after_l = lows[p - left:p], lows[p + 1:p + right + 1]
        if len(before_h) and len(after_h) and highs[p] > before_h.max() \
                and highs[p] >= after_h.max():
            pivot_highs.append((p + right, highs[p]))
        if len(before_l) and len(after_l) and lows[p] < before_l.min() \
                and lows[p] <= after_l.min():
            pivot_lows.append((p + right, lows[p]))

    def most_recent(pivots, before: int):
        """The newest pivot already CONFIRMED before this bar."""
        for confirmed_at, level in reversed(pivots):
            if confirmed_at < before:
                return level
        return None

    # Only THE most recent confirmed swing counts, not any of fifty within
    # reach. "It swept the previous high" is a statement about one specific
    # level -- testing every pivot in the window gives the scan so many chances
    # that something always matches, which is how the first two attempts at
    # this ended up firing on nine samples out of ten.
    for i in range(len(tail) - 1, scan_from - 1, -1):
        if sweep_up is None:
            level = most_recent(pivot_highs, i)
            if level is not None and highs[i] > level + pierce \
                    and closes[i] < level - reject:
                sweep_up = (level, stamps[i], len(tail) - 1 - i,
                            (highs[i] - level) / atr_now)
        if sweep_down is None:
            level = most_recent(pivot_lows, i)
            if level is not None and lows[i] < level - pierce \
                    and closes[i] > level + reject:
                sweep_down = (level, stamps[i], len(tail) - 1 - i,
                              (level - lows[i]) / atr_now)
        if sweep_up and sweep_down:
            break

    out["shapes"]["sweep_up"] = sweep_up[:2] if sweep_up else None
    out["shapes"]["sweep_down"] = sweep_down[:2] if sweep_down else None
    out["sweeps"] = {"up": sweep_up, "down": sweep_down}

    # The more recent sweep is the one the market is reacting to.
    newest = None
    if sweep_up and sweep_down:
        newest = "up" if sweep_up[2] <= sweep_down[2] else "down"
    elif sweep_up:
        newest = "up"
    elif sweep_down:
        newest = "down"
    out["sweeps"]["dominant"] = newest

    if sweep_down:
        active = newest == "down"
        add("Sell-side liquidity sweep", "bull" if active else "neutral",
            f"wick took out {fmt(sweep_down[0])} by {fmt(sweep_down[3], 2)} ATR on "
            f"{fmt_time(sweep_down[1])} ({sweep_down[2]} candle(s) ago) and closed back above"
            + ("" if active else " — superseded by a more recent buy-side sweep"))
    if sweep_up:
        active = newest == "up"
        add("Buy-side liquidity sweep", "bear" if active else "neutral",
            f"wick took out {fmt(sweep_up[0])} by {fmt(sweep_up[3], 2)} ATR on "
            f"{fmt_time(sweep_up[1])} ({sweep_up[2]} candle(s) ago) and closed back below"
            + ("" if active else " — superseded by a more recent sell-side sweep"))
    if not sweep_up and not sweep_down:
        add("Liquidity sweep", "neutral",
            f"no sweep-and-reject in the last {int(sweep_window)} candles: no swing has been "
            f"pierced by {fmt(min_pierce, 2)} ATR and rejected")

    # --- 7. premium / discount ----------------------------------------------
    window = closed.tail(int(lookback))
    top, bottom = float(window["High"].max()), float(window["Low"].min())
    equilibrium = (top + bottom) / 2.0
    out["shapes"].update({"range_high": top, "range_low": bottom,
                          "equilibrium": equilibrium})
    if top > bottom:
        position = (price - bottom) / (top - bottom) * 100.0
        zone = "premium" if price > equilibrium else "discount"
        # Discount is where a buyer wants to be, premium where a seller does.
        add("Premium / discount", "bull" if zone == "discount" else "bear",
            f"price sits at {position:.0f}% of the {int(lookback)}-candle range "
            f"({fmt(bottom)}-{fmt(top)}), i.e. in {zone}; equilibrium {fmt(equilibrium)}")

    # --- 8. equal highs and lows (liquidity pools) ---------------------------
    tolerance = price * float(equal_tol_pct) / 100.0
    highs = window["High"].tail(60)
    lows = window["Low"].tail(60)
    equal_high = bool(((highs.max() - highs.nlargest(3)) <= tolerance).sum() >= 3) \
        if len(highs) >= 3 else False
    equal_low = bool(((lows.nsmallest(3) - lows.min()) <= tolerance).sum() >= 3) \
        if len(lows) >= 3 else False
    if equal_high or equal_low:
        parts = []
        if equal_high:
            parts.append(f"equal highs near {fmt(float(highs.max()))} (buy-side liquidity)")
        if equal_low:
            parts.append(f"equal lows near {fmt(float(lows.min()))} (sell-side liquidity)")
        add("Equal highs / lows", "bear" if equal_high and not equal_low
            else ("bull" if equal_low and not equal_high else "neutral"),
            "; ".join(parts))
    else:
        add("Equal highs / lows", "neutral", "no obvious liquidity pool in this window")

    # --- the verdict ---------------------------------------------------------
    bull_n = sum(1 for c in out["concepts"].values() if c["verdict"] == "bull")
    bear_n = sum(1 for c in out["concepts"].values() if c["verdict"] == "bear")
    if bull_n > bear_n + 1:
        signal = "BUY"
    elif bear_n > bull_n + 1:
        signal = "SELL"
    else:
        signal = "HOLD"
    out.update({"bull": bull_n, "bear": bear_n, "signal": signal,
                "scored": len(out["concepts"])})
    return out


def smc_chart(df: pd.DataFrame, analysis: dict, title: str, light: bool = False,
              bars: int = 160):
    """
    The structural read, drawn on the candles it came from.

    Direction keeps the app's own semantic colours, so a bullish order block is
    the same green as a bullish candle. Every zone carries a direct label, so
    the chart is readable without matching colours to a legend -- and remains
    readable to someone who cannot separate red from green.
    """
    import plotly.graph_objects as go

    tail = df.tail(int(bars))
    fig = go.Figure()
    fig.add_trace(go.Candlestick(
        x=tail.index, open=tail["Open"], high=tail["High"], low=tail["Low"],
        close=tail["Close"], name="Price",
        increasing_line_color=_UP, decreasing_line_color=_DOWN,
        increasing_fillcolor=_UP, decreasing_fillcolor=_DOWN,
        line=dict(width=1), showlegend=False))

    shapes = analysis.get("shapes", {})
    lo, hi = float(tail["Low"].min()), float(tail["High"].max())
    pad = max((hi - lo) * 0.06, hi * 0.001)
    y_lo, y_hi = lo - pad, hi + pad
    left_edge, right_edge = tail.index[0], tail.index[-1]

    def band(low, high, colour, label, opacity=0.14, side="left"):
        """
        A price zone with its name written INSIDE it.

        Labelling at the band edge stacked every zone against the right margin,
        where four of them overlapped each other and the sweep markers. Writing
        the name at the band's own midpoint spreads the labels down the chart
        by construction, because the bands are at different prices.
        """
        if low is None or high is None or not (np.isfinite(low) and np.isfinite(high)):
            return
        if high < y_lo or low > y_hi:
            return
        fig.add_shape(type="rect", xref="x", yref="y", x0=left_edge, x1=right_edge,
                      y0=low, y1=high, fillcolor=colour, opacity=opacity,
                      line=dict(width=1, color=colour, dash="dot"), layer="below")
        at_right = side in ("right", "top", "bottom")
        if side == "top":
            at_y, anchor_y = high, "top"
        elif side == "bottom":
            at_y, anchor_y = low, "bottom"
        else:
            at_y, anchor_y = (low + high) / 2.0, "middle"
        fig.add_annotation(
            x=1.0 if at_right else 0.0, xref="x domain",
            y=at_y, text=(f"{label} " if at_right else f" {label}"),
            showarrow=False, xanchor="right" if at_right else "left", yanchor=anchor_y,
            font=dict(size=10, color=colour))

    def level(value, colour, label, dash="dash", position="top right"):
        if value is None or not np.isfinite(value) or not (y_lo <= value <= y_hi):
            return
        fig.add_hline(y=value, line=dict(width=1.2, dash=dash, color=colour),
                      annotation_text=label, annotation_position=position,
                      annotation_font=dict(size=10, color=colour))

    # premium / discount, drawn first so everything else sits on top
    eq = shapes.get("equilibrium")
    if eq is not None and np.isfinite(eq):
        band(eq, shapes.get("range_high"), _DOWN, "PREMIUM (sellers)", 0.06, side="top")
        band(shapes.get("range_low"), eq, _UP, "DISCOUNT (buyers)", 0.06, side="bottom")
        level(eq, _SMC_INK, "Equilibrium 50%", "dot", "bottom left")

    if shapes.get("bull_ob"):
        band(shapes["bull_ob"][0], shapes["bull_ob"][1], _UP, "Bullish order block", 0.22)
    if shapes.get("bear_ob"):
        band(shapes["bear_ob"][0], shapes["bear_ob"][1], _DOWN, "Bearish order block", 0.22)
    if shapes.get("bull_fvg"):
        band(shapes["bull_fvg"][0], shapes["bull_fvg"][1], _UP, "Bullish FVG", 0.12)
    if shapes.get("bear_fvg"):
        band(shapes["bear_fvg"][0], shapes["bear_fvg"][1], _DOWN, "Bearish FVG", 0.12)

    level(shapes.get("swing_high"), _SMC_INK, "Swing high")
    level(shapes.get("swing_low"), _SMC_INK, "Swing low")

    # Liquidity sweeps: the one extra hue, and a marker shape of their own.
    for key, symbol, label, place in (
            ("sweep_up", "triangle-down", "Buy-side sweep", "top center"),
            ("sweep_down", "triangle-up", "Sell-side sweep", "bottom center")):
        sweep = shapes.get(key)
        if not sweep:
            continue
        fig.add_trace(go.Scatter(
            x=[sweep[1]], y=[sweep[0]], mode="markers+text", name=label,
            marker=dict(symbol=symbol, size=14, color=_SMC_SWEEP,
                        line=dict(width=1.5, color=_SMC_SWEEP)),
            text=[label], textposition=place, textfont=dict(size=10),
            hovertemplate=f"{label}<br>%{{x}}<br>%{{y:,.2f}}<extra></extra>"))

    fig.update_layout(
        height=560, margin=dict(l=62, r=74, t=52, b=44),
        title=dict(text=title, x=0.01, xanchor="left", font=dict(size=15)),
        hovermode="x unified", dragmode="pan",
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
        template="plotly_white" if light else None,
        xaxis_rangeslider_visible=False)
    fig.update_yaxes(range=[y_lo, y_hi], showgrid=True,
                     gridcolor="rgba(128,128,128,0.15)")
    fig.update_xaxes(showgrid=False)
    return fig


# -----------------------------------------------------------------------------
# SMC across timeframes
# -----------------------------------------------------------------------------
# Higher timeframes carry more weight in the overall read, which is the one
# piece of SMC orthodoxy that is also just arithmetic: a monthly structure took
# months to build and a 1-minute structure took minutes, so they should not
# count equally.
SMC_TIMEFRAMES = ["1m", "5m", "15m", "60m", "4h", "1d", "1wk", "1mo"]
SMC_TF_WEIGHT = {"1m": 0.4, "5m": 0.7, "15m": 1.0, "60m": 1.6,
                 "4h": 2.2, "1d": 3.0, "1wk": 4.0, "1mo": 5.0}


def smc_trade_levels(analysis: dict, atr_value: float | None = None) -> dict:
    """
    Entry, stop and target implied by the structural read.

    These come from LEVELS the analysis already found, not from a fresh
    calculation: a long is stopped below the structure that would invalidate
    it, and aims at the liquidity resting above. When no such level exists the
    field is left empty rather than filled with an ATR multiple pretending to
    be structure -- the whole point of an SMC level is that it is a place other
    people's orders sit.
    """
    signal = analysis.get("signal", "HOLD")
    shapes = analysis.get("shapes", {})
    price = float(analysis.get("price", float("nan")))
    out = {"signal": signal, "entry": None, "stop": None, "target": None,
           "rr": None, "basis": ""}
    if signal == "HOLD" or not np.isfinite(price):
        out["basis"] = "no directional read, so no levels are proposed"
        return out

    def pick(*values):
        for value in values:
            if value is None:
                continue
            try:
                number = float(value)
            except (TypeError, ValueError):
                continue
            if np.isfinite(number):
                return number
        return None

    pad = float(atr_value) if (atr_value and np.isfinite(atr_value)) else price * 0.002

    if signal == "BUY":
        block = shapes.get("bull_ob")
        entry = pick(block[1] if block else None, price)
        stop = pick(block[0] - pad if block else None,
                    shapes.get("swing_low"), shapes.get("range_low"))
        target = pick(shapes.get("swing_high"), shapes.get("range_high"))
        basis = ("entry at the bullish order block, stop below it, target at the liquidity "
                 "resting above the last swing high")
        if stop is not None and stop >= price:
            stop = pick(shapes.get("range_low"), price - 2 * pad)
        if target is not None and target <= price:
            target = pick(shapes.get("range_high"), price + 4 * pad)
    else:
        block = shapes.get("bear_ob")
        entry = pick(block[0] if block else None, price)
        stop = pick(block[1] + pad if block else None,
                    shapes.get("swing_high"), shapes.get("range_high"))
        target = pick(shapes.get("swing_low"), shapes.get("range_low"))
        basis = ("entry at the bearish order block, stop above it, target at the liquidity "
                 "resting below the last swing low")
        if stop is not None and stop <= price:
            stop = pick(shapes.get("range_high"), price + 2 * pad)
        if target is not None and target >= price:
            target = pick(shapes.get("range_low"), price - 4 * pad)

    out.update({"entry": entry, "stop": stop, "target": target, "basis": basis})
    if entry is not None and stop is not None and target is not None:
        risk, reward = abs(entry - stop), abs(target - entry)
        out["rr"] = round(reward / risk, 2) if risk > 0 else None
    return out


def smc_narrative(ticker: str, interval: str, analysis: dict, levels: dict) -> str:
    """
    The chart read the way a desk reads it, in the order a desk reads it.

    Seven questions, answered from the data each time and skipped when the data
    does not answer them: what is the structure, has character changed, what
    liquidity has been taken, what liquidity remains as a draw, is price
    expensive or cheap, is there a point of interest in the way, and what would
    prove the read wrong.

    Nothing here is a fixed sentence. Every clause is built from a concept's
    own verdict and reading, so a chart with no sweep says there has been no
    sweep rather than reciting one.
    """
    concepts = analysis.get("concepts", {})
    sweeps = analysis.get("sweeps", {}) or {}
    shapes = analysis.get("shapes", {})
    price = float(analysis.get("price", float("nan")))

    def verdict(name: str) -> str:
        return str((concepts.get(name) or {}).get("verdict", "neutral"))

    def reading(name: str) -> str:
        return str((concepts.get(name) or {}).get("reading", ""))

    parts: list[str] = []

    # 1 ---- structure, which is where every SMC read starts
    bos = verdict("Break of structure (BOS)")
    if bos == "bull":
        parts.append("Structure is **bullish**: the last confirmed swing high has been taken "
                     "out, so the market is making higher highs")
    elif bos == "bear":
        parts.append("Structure is **bearish**: the last confirmed swing low has been broken, "
                     "so the market is making lower lows")
    else:
        parts.append("Structure is **unresolved** — neither the last swing high nor the last "
                     "swing low has been broken, so there is no trend to follow yet")

    # 2 ---- change of character, the warning that a trend is ending
    choch = verdict("Change of character (CHoCH)")
    if choch != "neutral":
        agrees = choch == bos
        parts.append(
            f"character last flipped **{'bullish' if choch == 'bull' else 'bearish'}**"
            + (", confirming the same direction" if agrees else
               ", which disagrees with the current structure and is the first warning that "
               "the move is maturing"))

    # 3 ---- liquidity TAKEN: the engine, said in the direction it points
    dominant = sweeps.get("dominant")
    up_sweep, down_sweep = sweeps.get("up"), sweeps.get("down")
    if dominant == "down" and down_sweep:
        parts.append(
            f"Sell-side liquidity has been taken: price wicked **{fmt(down_sweep[3], 2)} ATR** "
            f"below {fmt(down_sweep[0])} {down_sweep[2]} candle(s) ago and closed back above "
            f"it, so the stops under that low are gone and the sellers who were filled there "
            f"are now trapped")
    elif dominant == "up" and up_sweep:
        parts.append(
            f"Buy-side liquidity has been taken: price wicked **{fmt(up_sweep[3], 2)} ATR** "
            f"above {fmt(up_sweep[0])} {up_sweep[2]} candle(s) ago and closed back below it, "
            f"so the stops above that high are gone and the buyers filled there are trapped")
    else:
        parts.append("No swing has been swept and rejected recently, so no stop pool has been "
                     "cleared — moves from here are starting without that fuel")

    # 4 ---- liquidity REMAINING: the draw
    equal = concepts.get("Equal highs / lows")
    draws = []
    if equal and equal.get("verdict") != "neutral":
        draws.append(reading("Equal highs / lows"))
    high, low = shapes.get("range_high"), shapes.get("range_low")
    if np.isfinite(price) and high and low and np.isfinite(high) and np.isfinite(low):
        draws.append(f"the range extremes at {fmt(low)} and {fmt(high)} are the obvious "
                     f"resting places for orders")
    if draws:
        parts.append("As a draw on liquidity, " + "; ".join(draws))

    # 5 ---- premium / discount: are you paying up or getting a discount
    zone = concepts.get("Premium / discount")
    if zone:
        cheap = zone["verdict"] == "bull"
        parts.append(
            f"Price is in **{'discount' if cheap else 'premium'}** "
            f"({reading('Premium / discount').split('i.e.')[0].strip().rstrip(',')}), which "
            f"is where {'buyers' if cheap else 'sellers'} want to be engaging — "
            + ("buying here is buying cheap relative to the range"
               if cheap else "selling here is selling expensive relative to the range"))

    # 6 ---- the point of interest actually in the way
    poi = []
    for side in ("Bullish order block", "Bearish order block"):
        block = concepts.get(side)
        if not block:
            continue
        if "mitigating" in reading(side):
            poi.append(f"price is inside the {side.split()[0].lower()} order block at "
                       f"{reading(side).split(' from ')[0]}, which is the decision point")
        else:
            poi.append(f"an unmitigated {side.split()[0].lower()} order block sits at "
                       f"{reading(side).split(' from ')[0]}")
    for side in ("Bullish fair value gap", "Bearish fair value gap"):
        gap = concepts.get(side)
        if gap and "unfilled" in reading(side):
            poi.append(f"an unfilled {side.split()[0].lower()} imbalance remains at "
                       f"{reading(side).split(' —')[0]}, and imbalances tend to be revisited")
    if poi:
        parts.append("Points of interest: " + "; ".join(poi[:3]))

    # 7 ---- the trade, and what would disprove it
    if levels.get("entry") is not None and levels.get("stop") is not None:
        rr = levels.get("rr")
        trade = (f"**{levels['signal']}** from {fmt(levels['entry'])} with the stop at "
                 f"{fmt(levels['stop'])} and the draw at {fmt(levels['target'])}"
                 + (f", a reward:risk of {fmt(rr)}:1" if rr else ""))
        if rr and float(rr) < 1.0:
            trade += (". At that ratio the structure is not offering a trade worth taking — "
                      "the level is right but the geometry is not")
        trade += (f". The read is wrong if price closes beyond {fmt(levels['stop'])}, because "
                  f"that invalidates the structure the entry was built on")
        parts.append(trade)
    else:
        parts.append("There is no level worth acting on until structure resolves — the honest "
                     "position here is flat")

    # Each clause is a sentence of its own, so each starts with a capital --
    # the fragments are written to read on from one another, not to be glued.
    sentences = []
    for part in parts:
        text = part.strip()
        if text and text[0].islower() and not text.startswith("**"):
            text = text[0].upper() + text[1:]
        sentences.append(text)
    return f"**{interval}** — " + ". ".join(sentences) + "."


def smc_multi_timeframe(ticker: str, timeframes: list[str], pivot: int = 3,
                        lookback: int = 150) -> list[dict]:
    """
    Run the structural read on each timeframe, newest data each time.

    A timeframe whose history Yahoo cannot serve is reported as such rather
    than silently skipped: "1m has only 7 days" is information, and a missing
    row looks like a bug.
    """
    out = []
    for interval in timeframes:
        entry: dict = {"Timeframe": interval}
        try:
            period, note = lab_period_for(interval, int(lookback) + 100)
            frame = load_market_data(ticker, period, interval,
                                     freshness_seconds=180, min_bars=50).frame
            analysis = smc_analyse(frame, int(pivot), int(pivot), int(lookback))
            if analysis.get("error"):
                entry.update({"error": analysis["error"], "frame": None})
                out.append(entry)
                continue
            atr_now = _last(atr(frame["High"], frame["Low"], frame["Close"], 14))
            levels = smc_trade_levels(analysis, atr_now)
            entry.update({
                "frame": frame, "analysis": analysis, "levels": levels,
                "signal": analysis["signal"], "bull": analysis["bull"],
                "bear": analysis["bear"], "scored": analysis["scored"],
                "period": period, "note": note,
                "summary": smc_narrative(ticker, interval, analysis, levels),
                "weight": SMC_TF_WEIGHT.get(interval, 1.0),
            })
        except Exception as exc:                                    # noqa: BLE001
            entry.update({"error": str(exc)[:160], "frame": None})
        out.append(entry)
    return out


def smc_overall(reads: list[dict]) -> dict:
    """
    One verdict across every timeframe, weighted by how long each took to form.

    A monthly structure represents months of positioning and a one-minute
    structure represents a minute of it, so they are not averaged equally. The
    rationale names which timeframes carried the decision and which dissented,
    because a split read is worth knowing about rather than hiding inside an
    average.
    """
    usable = [r for r in reads if r.get("signal")]
    if not usable:
        return {"signal": "NO DATA", "score": 0.0, "rationale":
                "No timeframe returned enough history to read structure."}

    score = 0.0
    total = 0.0
    for read in usable:
        weight = float(read.get("weight", 1.0))
        total += weight
        if read["signal"] == "BUY":
            score += weight
        elif read["signal"] == "SELL":
            score -= weight
    normalised = (score / total * 100.0) if total else 0.0

    buys = [r["Timeframe"] for r in usable if r["signal"] == "BUY"]
    sells = [r["Timeframe"] for r in usable if r["signal"] == "SELL"]
    holds = [r["Timeframe"] for r in usable if r["signal"] == "HOLD"]

    if normalised >= 25:
        verdict = "BUY"
    elif normalised <= -25:
        verdict = "SELL"
    else:
        verdict = "HOLD"

    # The highest timeframe that actually has a direction sets the context.
    ranked = sorted(usable, key=lambda r: float(r.get("weight", 1.0)), reverse=True)
    anchor = next((r for r in ranked if r["signal"] != "HOLD"), None)

    parts = []
    if anchor:
        parts.append(f"The highest timeframe with a direction is **{anchor['Timeframe']}**, "
                     f"and it reads **{anchor['signal']}**")
    if buys:
        parts.append("bullish on " + ", ".join(buys))
    if sells:
        parts.append("bearish on " + ", ".join(sells))
    if holds:
        parts.append(f"undecided on {', '.join(holds)}")

    conflict = ""
    if buys and sells:
        conflict = (" Timeframes disagree, which is the normal state of a market in "
                    "transition — the lower ones usually turn first, and acting on them "
                    "against a higher-timeframe structure is counter-trend trading whether "
                    "or not it is called that.")
    elif verdict == "HOLD":
        conflict = (" Nothing carries enough weight to call, so the honest answer is to wait "
                    "for a higher timeframe to resolve.")

    return {"signal": verdict, "score": round(normalised, 1),
            "rationale": "; ".join(parts) + "." + conflict,
            "buys": buys, "sells": sells, "holds": holds}


def _smc_panel(picked: dict, cfg: dict) -> None:
    """Smart Money Concepts for the inspected ticker, across every timeframe."""
    ticker = picked["Ticker"]
    st.markdown("#### Smart Money Concepts — multi-timeframe")
    st.caption(f"Structural read of `{ticker}` on each timeframe you tick, computed from "
               "CONFIRMED swings only — nothing here uses a pivot that has not finished "
               "forming.")

    c1, c2, c3 = st.columns(3)
    pivot = c1.number_input("Swing strength (candles either side)", 1, 20, 3, 1,
                            key="smc_pivot",
                            help="How many candles either side a high must dominate before it "
                                 "counts as a swing. Larger means fewer, more significant "
                                 "swings — and a longer wait before one is confirmed.")
    lookback = c2.number_input("Structure lookback (candles)", 30, 600, 150, 10,
                               key="smc_look")
    bars = c3.number_input("Candles to plot", 40, 600, 160, 20, key="smc_bars")

    chosen_tfs = _multi_picker("Timeframes to analyse", SMC_TIMEFRAMES, "smc_tf",
                               ["15m", "60m", "1d"])
    if not chosen_tfs:
        st.info("Tick at least one timeframe above.")
        return
    st.caption("Each timeframe is a separate download, so eight of them cost eight fetches "
               "with the mandatory 0.3s guard on each. Yahoo also limits history by "
               "timeframe — 1m goes back about 7 days and 5m/15m about 60 — so the shortest "
               "ones see less structure than the long ones.")

    if not st.button(f"Analyse {len(chosen_tfs)} timeframe(s)", type="primary",
                     key="smc_run", width="stretch"):
        st.caption("Press the button to run the structural read.")
        return

    with st.spinner(f"Reading structure on {len(chosen_tfs)} timeframe(s)…"):
        reads = smc_multi_timeframe(ticker, chosen_tfs, int(pivot), int(lookback))

    # ---- per-timeframe: chart, signal, summary, levels ----------------------
    for read in reads:
        interval = read["Timeframe"]
        st.divider()
        if read.get("error"):
            st.warning(f"**{interval}** — {read['error']}")
            continue

        analysis, levels = read["analysis"], read["levels"]
        head, badge = st.columns([3, 1])
        head.markdown(f"**{ticker} · {interval}** — {read['bull']} bullish / "
                      f"{read['bear']} bearish of {read['scored']} concepts "
                      f"(history: {read['period']})")
        tone = {"BUY": badge.success, "SELL": badge.error}.get(read["signal"], badge.info)
        tone(f"**{read['signal']}**")
        if read.get("note"):
            st.caption(read["note"])

        st.plotly_chart(
            smc_chart(read["frame"], analysis, f"{ticker} · {interval}",
                      light=bool(cfg.get("light_charts")), bars=int(bars)),
            width="stretch", config={"scrollZoom": True},
            key=f"smc_chart_{ticker}_{interval}")

        st.markdown(read["summary"])
        if levels.get("entry") is not None:
            l1, l2, l3, l4 = st.columns(4)
            l1.metric("Entry", fmt(levels["entry"]))
            l2.metric("Stop", fmt(levels["stop"]),
                      f"{fmt(abs(levels['entry'] - levels['stop']))} risk"
                      if levels.get("stop") is not None else None)
            l3.metric("Target", fmt(levels["target"]),
                      f"{fmt(abs(levels['target'] - levels['entry']))} reward"
                      if levels.get("target") is not None else None)
            l4.metric("Reward : risk",
                      f"{fmt(levels['rr'])} : 1" if levels.get("rr") else "--")
            st.caption("Levels come from the structure itself — " + levels["basis"] +
                       ". They are where orders rest, not a prediction, and nothing here "
                       "has been backtested.")
        with st.expander(f"Every concept on {interval}"):
            st.dataframe(pd.DataFrame([
                {"Concept": name,
                 "Verdict": {"bull": "BULLISH", "bear": "BEARISH"}.get(c["verdict"],
                                                                       "neutral"),
                 "Reading": c["reading"]}
                for name, c in analysis["concepts"].items()]),
                width="stretch", hide_index=True)

    # ---- the overall read ---------------------------------------------------
    st.divider()
    overall = smc_overall(reads)
    st.markdown("### Overall structural verdict")
    tone = {"BUY": st.success, "SELL": st.error}.get(overall["signal"], st.info)
    tone(f"**{overall['signal']}** — weighted score {fmt(overall['score'])} out of ±100")
    st.markdown(overall["rationale"])

    table = pd.DataFrame([
        {"Timeframe": r["Timeframe"],
         "Signal": r.get("signal", "—"),
         "Weight": SMC_TF_WEIGHT.get(r["Timeframe"], 1.0),
         "Bullish": r.get("bull"), "Bearish": r.get("bear"),
         "Entry": (r.get("levels") or {}).get("entry"),
         "Stop": (r.get("levels") or {}).get("stop"),
         "Target": (r.get("levels") or {}).get("target"),
         "R:R": (r.get("levels") or {}).get("rr")}
        for r in reads if not r.get("error")])
    if not table.empty:
        st.dataframe(table, width="stretch", hide_index=True)
    st.caption("Timeframes are weighted by how long their structure took to build — a monthly "
               "break represents months of positioning and a one-minute break represents a "
               "minute of it, so they do not count equally. **SMC is a vocabulary for "
               "describing structure, not a tested edge**: an order block is 'the last "
               "opposite candle before the move that broke structure', which is a definition, "
               "not a prediction. Whether this verdict makes money is a question for the "
               "Backtesting tab.")


def tab_custom_screener(cfg: dict) -> None:
    st.subheader("Custom Indicator Screener")
    st.warning(
        "**A count of agreeing indicators is not an edge.** Most of these measure the same "
        "few things -- trend, momentum, volatility, participation -- so twenty of them "
        "agreeing is often one fact counted twenty times, not twenty independent "
        "confirmations. Use it to shortlist, then test a specific rule in the Backtesting "
        "tab or the Signal Lab, which is where the question of whether it MAKES MONEY is "
        "actually answered.")

    c1, c2 = st.columns([1, 1])
    universe = c1.selectbox("Universe", SCREENER_UNIVERSES, key="cust_universe")
    min_agree = c2.number_input("Minimum agreement to list (%)", 0, 100, 60, 5,
                                key="cust_agree",
                          help="How large a majority of the scored indicators must lean one "
                               "way before the ticker is treated as having a bias.")

    custom_text = ""
    if universe.startswith("Custom"):
        custom_text = st.text_area("Tickers", "RELIANCE\nTCS\nINFY", key="cust_custom")
    all_tickers, note = universe_tickers_ui(universe, custom_text, None, "cust")
    chosen = st.multiselect(f"Tickers ({len(all_tickers)} in {universe})", all_tickers,
                            default=all_tickers, key=f"cust_tickers_{universe}")
    if note:
        st.caption(note)

    # ---- timeframes --------------------------------------------------------
    with st.container(border=True):
        timeframes = _multi_picker("Timeframes", list(INTERVALS), "cust_tf", ["15m"])
    if not timeframes:
        st.error("Pick at least one timeframe.")
        return

    # ---- indicators --------------------------------------------------------
    with st.container(border=True):
        st.markdown(f"**Indicators** — {len(INDICATOR_SPECS)} available")
        every_key = [spec[0] for spec in INDICATOR_SPECS]
        ga, gb = st.columns(2)
        if ga.button("Select ALL indicators", key="cust_ind_all", width="stretch"):
            for key in every_key:
                st.session_state[f"cust_ind_cb_{key}"] = True
            st.rerun()
        if gb.button("Clear ALL indicators", key="cust_ind_none", width="stretch"):
            for key in every_key:
                st.session_state[f"cust_ind_cb_{key}"] = False
            st.rerun()

        selected: list[str] = []
        default_on = {"ema", "ma_cross", "rsi_trend", "macd", "adx", "supertrend",
                      "bollinger", "vwap"}
        for group, specs in INDICATOR_GROUPS.items():
            with st.expander(f"{group} ({len(specs)})", expanded=group == "Trend"):
                ha, hb = st.columns(2)
                if ha.button(f"All {group.lower()}", key=f"cust_g_all_{group}",
                             width="stretch"):
                    for spec in specs:
                        st.session_state[f"cust_ind_cb_{spec[0]}"] = True
                    st.rerun()
                if hb.button(f"None {group.lower()}", key=f"cust_g_none_{group}",
                             width="stretch"):
                    for spec in specs:
                        st.session_state[f"cust_ind_cb_{spec[0]}"] = False
                    st.rerun()
                columns = st.columns(3)
                for i, spec in enumerate(specs):
                    key, label = spec[0], spec[1]
                    if columns[i % 3].checkbox(label, value=key in default_on,
                                               key=f"cust_ind_cb_{key}"):
                        selected.append(key)

    if not selected:
        st.error("Pick at least one indicator.")
        return

    # ---- per-indicator parameters -----------------------------------------
    params: dict = {}
    with st.expander(f"Indicator settings ({len(selected)} selected)", expanded=False):
        st.caption("Every selected indicator's own inputs. Defaults are the published ones.")
        for key in selected:
            _k, label, _g, defaults, _fn = INDICATOR_BY_KEY[key]
            if not defaults:
                continue
            st.markdown(f"**{label}**")
            columns = st.columns(max(len(defaults), 1))
            for i, (name, spec) in enumerate(defaults.items()):
                default = spec[0]
                if isinstance(default, str):            # a choice, not a number
                    params[f"{key}.{name}"] = columns[i].selectbox(
                        name, list(spec[1]), index=list(spec[1]).index(default),
                        key=f"cust_p_{key}_{name}")
                elif isinstance(default, int):
                    params[f"{key}.{name}"] = columns[i].number_input(
                        name, int(spec[1]), int(spec[2]), int(default), 1,
                        key=f"cust_p_{key}_{name}")
                else:
                    params[f"{key}.{name}"] = columns[i].number_input(
                        name, float(spec[1]), float(spec[2]), float(default),
                        key=f"cust_p_{key}_{name}")

    # ---- additional entry filters -----------------------------------------
    with st.expander("Additional entry filters (all off by default)", expanded=False):
        st.caption("The same filters the strategies use. An enabled filter must pass in the "
                   "direction the screener is proposing, or the ticker is marked filtered out "
                   "rather than silently dropped.")
        filter_cfg = default_filter_config()
        columns = st.columns(3)
        for i, spec in enumerate(FILTER_SPECS):
            key = spec["key"]
            if columns[i % 3].checkbox(FILTER_LABELS.get(key, key), value=False,
                                       key=f"cust_flt_{key}"):
                filter_cfg[key]["enabled"] = True

    flip_on_sector = st.checkbox(
        "Flip the signal when the ticker DISAGREES with its own sector", value=False,
        key="cust_flip",
        help="Sector alignment, off by default. When a ticker leans one way and its own sector "
             "index leans the other, the sector wins and the ticker's verdict is inverted to "
             "match it. A ticker already agreeing with its sector is left alone — there is "
             "nothing to reconcile. The sector is scored with the SAME indicators you ticked, "
             "so the two readings mean the same thing. This is a trading opinion, not a "
             "neutral filter, and it has not been backtested here — test it in the Signal Lab "
             "before trusting it.")

    jobs = [(t, tf) for t in chosen for tf in timeframes]
    scan_cost_notice(len(jobs), per_job_hint=1.6 + 0.01 * len(selected), prefix="cust")

    def _worker(job):
        ticker, interval = job
        try:
            return [custom_screen_one(ticker, interval, selected, params, filter_cfg,
                                      flip_on_sector, cfg.get("params") or {})], []
        except Exception as exc:                                    # noqa: BLE001
            return [], [{"Ticker": ticker, "Timeframe": interval,
                         "Problem": str(exc)[:140]}]

    rows, errs, _done = chunked_sweep("cust", jobs, _worker, _auto_slice_seconds(),
                                      "ticker/timeframe jobs",
                                      describe=lambda job: f"{job[0]} · {job[1]}")

    frame = pd.DataFrame([{k: v for k, v in r.items() if k != "_detail"} for r in rows])
    if frame.empty:
        st.info("Nothing scanned yet. Press **Run** above.")
        if errs:
            with st.expander(f"Jobs that failed ({len(errs)})"):
                st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
        return

    strong = frame[pd.to_numeric(frame["Agreement %"], errors="coerce") >= float(min_agree)]
    a, b, c, d = st.columns(4)
    a.metric("Rows scanned", len(frame))
    b.metric("Bullish", int((strong["Bias"] == "BULLISH").sum()),
             f"at or above {min_agree}% agreement")
    c.metric("Bearish", int((strong["Bias"] == "BEARISH").sum()),
             f"at or above {min_agree}% agreement")
    d.metric("Flipped by sector", int((frame["Flipped"] == "yes").sum()))

    show = st.radio("Show", ["Everything", "Bullish only", "Bearish only",
                             "Above the agreement bar"], horizontal=True, key="cust_show")
    view = frame
    if show == "Bullish only":
        view = frame[frame["Bias"] == "BULLISH"]
    elif show == "Bearish only":
        view = frame[frame["Bias"] == "BEARISH"]
    elif show == "Above the agreement bar":
        view = strong
    if view.empty:
        st.info("Nothing matches that filter. Switch back to Everything to see the full scan.")
        return

    front = ["Ticker", "Timeframe", "Sector", "Price", "Bias", "Bullish", "Bearish",
             "Agreement %", "Indicators scored", "Flipped", "Sector bias",
             "Sector agreement %", "Sector bullish", "Sector bearish", "Sector index",
             "Filters", "Bias before flip", "Bias before filters"]
    order = [c for c in front if c in view.columns] + \
            [c for c in view.columns if c not in front and c != "Checked at"] + \
            (["Checked at"] if "Checked at" in view.columns else [])
    st.dataframe(view.sort_values(["Agreement %", "Bullish"], ascending=[False, False])[order],
                 width="stretch", hide_index=True)
    st.download_button("Download the scan (CSV)", view[order].to_csv(index=False).encode(),
                       f"custom_screen_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv",
                       key="cust_dl")

    st.markdown("#### Inspect one row")
    i1, i2 = st.columns([2, 1])
    labels = [f"{r['Ticker']} · {r['Timeframe']}" for r in rows]
    picked_label = i1.selectbox("Row", labels, key="cust_pick")
    picked = rows[labels.index(picked_label)]
    detail = pd.DataFrame([
        {"Indicator": v["label"], "Group": v["group"],
         "Verdict": "BULL" if v["bull"] else ("BEAR" if v["bear"] else "neutral"),
         "Reading": v["text"]}
        for v in picked.get("_detail", [])])
    if not detail.empty:
        st.dataframe(detail, width="stretch", hide_index=True)
    st.caption(f"{picked['Bullish']} bullish against {picked['Bearish']} bearish across "
               f"{picked['Indicators scored']} indicators that had enough history. "
               f"Sector {picked['Sector index']} is {picked['Sector bias']}; "
               f"flipped: {picked['Flipped']}.")

    if i2.button("Apply to the sidebar", width="stretch", key="cust_apply"):
        st.session_state.pending_ticker = picked["Ticker"]
        st.session_state.pending_combo = {
            "strategy": "01 · Dual EMA Crossover",
            "sl_type": "ATR Multiple", "sl_value": 1.5,
            "tp_type": "Risk : Reward Multiple", "tp_value": 2.0,
            "filter_key": "", "widgets": {"cfg_interval": picked["Timeframe"]}}
        st.rerun()

    _smc_panel(picked, cfg)

    if errs:
        with st.expander(f"Jobs that failed ({len(errs)})"):
            st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
    render_analyst_panel("cust", "these custom indicator results", _frame_context(frame))


# =============================================================================
# SECTION 19k -- MAKE OR BREAK SCREENER
# =============================================================================
# Tickers standing at a decision, as opposed to tickers that have already
# decided. The Chart Patterns tab answers "what pattern COMPLETED"; this one
# answers "what is coiled, pressed against a level, or has just been shaken out
# and is about to resolve".
#
# WHAT A READINESS SCORE IS AND IS NOT. Each detector returns 0-100 for how
# textbook its own shape currently looks -- how tight the compression, how many
# times the level held, how close price sits to the trigger. It is a measure of
# how WELL FORMED the setup is, not of how likely it is to work. A perfect
# ascending triangle at the apex scores high and then breaks the wrong way
# often enough to ruin anyone who mistakes the two. The tab says so, and the
# levels it proposes are the structure's own, not a forecast.


@dataclass
class MBContext:
    """Everything the detectors share, computed once per ticker/timeframe."""
    frame: pd.DataFrame
    closed: pd.DataFrame
    price: float
    atr: float
    highs: np.ndarray
    lows: np.ndarray
    closes: np.ndarray
    volumes: np.ndarray
    pivot_highs: list
    pivot_lows: list
    range_high: float
    range_low: float
    lookback: int
    tol: float                  # level tolerance in price units
    rsi_now: float
    vol_ratio: float
    vol_trend: float            # recent volume over earlier volume, <1 = drying up
    compression: float          # current range over its own historical median


def _mb_pivots(highs: np.ndarray, lows: np.ndarray, left: int, right: int):
    """
    Confirmed swing pivots, strictly higher/lower than the bars before them.

    Strict on the left and non-strict on the right, the same convention the
    liquidity-sweep detector uses: a non-strict test on both sides turns every
    bar of a flat stretch into a pivot.
    """
    pivot_highs, pivot_lows = [], []
    for p in range(left, len(highs) - right):
        before_h, after_h = highs[p - left:p], highs[p + 1:p + right + 1]
        before_l, after_l = lows[p - left:p], lows[p + 1:p + right + 1]
        if len(before_h) and len(after_h) and highs[p] > before_h.max() \
                and highs[p] >= after_h.max():
            pivot_highs.append((p, float(highs[p])))
        if len(before_l) and len(after_l) and lows[p] < before_l.min() \
                and lows[p] <= after_l.min():
            pivot_lows.append((p, float(lows[p])))
    return pivot_highs, pivot_lows


def mb_context(df: pd.DataFrame, lookback: int = 120, pivot: int = 3,
               tol_atr: float = 0.5) -> MBContext | None:
    """Precompute the shared measurements. Returns None when history is short."""
    closed = df.iloc[:-1] if len(df) > 2 else df
    if len(closed) < max(40, lookback // 3):
        return None
    window = closed.tail(int(lookback))
    highs = window["High"].to_numpy(float)
    lows = window["Low"].to_numpy(float)
    closes = window["Close"].to_numpy(float)
    volumes = window["Volume"].fillna(0.0).to_numpy(float)

    atr_now = _last(atr(closed["High"], closed["Low"], closed["Close"], 14))
    price = float(closes[-1])
    if not np.isfinite(atr_now) or atr_now <= 0:
        atr_now = max(price * 0.004, 1e-9)

    pivot_highs, pivot_lows = _mb_pivots(highs, lows, int(pivot), int(pivot))

    # Compression: this window's span against the median span of equal windows
    # earlier in the series. Below 1 the market is quieter than its own norm.
    span_now = float(highs.max() - lows.min())
    spans = []
    step = max(len(closed) // 12, 5)
    for end in range(len(closed) - len(window), 0, -step):
        chunk = closed.iloc[max(end - len(window), 0):end]
        if len(chunk) >= len(window) // 2:
            spans.append(float(chunk["High"].max() - chunk["Low"].min()))
    median_span = float(np.median(spans)) if spans else span_now
    compression = span_now / median_span if median_span > 0 else 1.0

    has_volume = float(np.abs(volumes).sum()) > 0
    half = max(len(volumes) // 4, 1)
    vol_recent = float(volumes[-half:].mean()) if has_volume else float("nan")
    vol_earlier = float(volumes[:-half].mean()) if has_volume and len(volumes) > half \
        else float("nan")
    vol_avg = float(volumes.mean()) if has_volume else float("nan")

    return MBContext(
        frame=df, closed=closed, price=price, atr=float(atr_now),
        highs=highs, lows=lows, closes=closes, volumes=volumes,
        pivot_highs=pivot_highs, pivot_lows=pivot_lows,
        range_high=float(highs.max()), range_low=float(lows.min()),
        lookback=len(window), tol=float(tol_atr) * float(atr_now),
        rsi_now=_last(rsi(closed["Close"], 14)),
        vol_ratio=(float(volumes[-1]) / vol_avg) if (has_volume and vol_avg) else float("nan"),
        vol_trend=(vol_recent / vol_earlier) if (has_volume and vol_earlier) else float("nan"),
        compression=compression)


def _touches(levels: np.ndarray, level: float, tol: float) -> int:
    """How many bars came within `tol` of a level."""
    if not np.isfinite(level):
        return 0
    return int(np.sum(np.abs(levels - level) <= tol))


def _hit(setup, direction, score, reading, trigger=None, invalidation=None,
         objective=None, extras=None) -> dict:
    out = {"setup": setup, "direction": direction, "score": float(max(0.0, min(100.0, score))),
           "reading": reading, "trigger": trigger, "invalidation": invalidation,
           "objective": objective}
    out.update(extras or {})
    return out


# --- the shapes -------------------------------------------------------------
def mb_inverted_v(ctx: MBContext):
    """
    Rose, topped, and came all the way back to where the move began.

    The operator's own description: "a ticker went up and then returned and
    reached exact location". From there it can go down, up, or sideways -- the
    point is that the entire advance has been given back, which is a decision
    rather than a trend.
    """
    peak_i = int(np.argmax(ctx.highs))
    if peak_i < 5 or peak_i > len(ctx.highs) - 4:
        return None
    base_i = int(np.argmin(ctx.lows[:peak_i]))
    base = float(ctx.lows[base_i])
    peak = float(ctx.highs[peak_i])
    rise = peak - base
    if rise < 3.0 * ctx.atr:
        return None
    back = abs(ctx.price - base)
    if back > 1.5 * ctx.atr:
        return None
    retrace = (peak - ctx.price) / rise if rise > 0 else 0.0
    score = 55.0 + 30.0 * min(rise / (6.0 * ctx.atr), 1.0) + 15.0 * (1.0 - back / (1.5 * ctx.atr))
    return _hit("Inverted V (round top)", "EITHER", score,
                f"rose {fmt(rise)} from {fmt(base)} to {fmt(peak)} and has given back "
                f"{retrace * 100:.0f}% of it, sitting {fmt(back)} from where the move began",
                trigger=base, invalidation=peak, objective=base - rise * 0.5,
                extras={"pivot_high": peak, "pivot_low": base})


def mb_v_bottom(ctx: MBContext):
    """Fell, bottomed, and has climbed back to the level it fell from."""
    trough_i = int(np.argmin(ctx.lows))
    if trough_i < 5 or trough_i > len(ctx.lows) - 4:
        return None
    start_i = int(np.argmax(ctx.highs[:trough_i]))
    start = float(ctx.highs[start_i])
    trough = float(ctx.lows[trough_i])
    fall = start - trough
    if fall < 3.0 * ctx.atr:
        return None
    back = abs(ctx.price - start)
    if back > 1.5 * ctx.atr:
        return None
    score = 55.0 + 30.0 * min(fall / (6.0 * ctx.atr), 1.0) + 15.0 * (1.0 - back / (1.5 * ctx.atr))
    return _hit("V bottom (round bottom)", "EITHER", score,
                f"fell {fmt(fall)} from {fmt(start)} to {fmt(trough)} and has recovered the "
                f"whole move, sitting {fmt(back)} from where the fall began",
                trigger=start, invalidation=trough, objective=start + fall * 0.5,
                extras={"pivot_high": start, "pivot_low": trough})


def mb_at_resistance(ctx: MBContext):
    """Pressed against the top of its range, with the level repeatedly tested."""
    level = ctx.range_high
    distance = level - ctx.price
    if distance < -ctx.tol or distance > 1.5 * ctx.atr:
        return None
    hits = _touches(ctx.highs, level, ctx.tol)
    if hits < 2:
        return None
    height = ctx.range_high - ctx.range_low
    score = 45.0 + 8.0 * min(hits, 5) + 15.0 * (1.0 - min(distance / (1.5 * ctx.atr), 1.0))
    return _hit("At resistance (about to break out)", "UP", score,
                f"price is {fmt(max(distance, 0))} under {fmt(level)}, a level touched "
                f"{hits} time(s) in {ctx.lookback} candles",
                trigger=level + 0.25 * ctx.atr, invalidation=level - 1.5 * ctx.atr,
                objective=level + height, extras={"touches": hits, "level": level})


def mb_at_support(ctx: MBContext):
    """Pressed against the bottom of its range."""
    level = ctx.range_low
    distance = ctx.price - level
    if distance < -ctx.tol or distance > 1.5 * ctx.atr:
        return None
    hits = _touches(ctx.lows, level, ctx.tol)
    if hits < 2:
        return None
    height = ctx.range_high - ctx.range_low
    score = 45.0 + 8.0 * min(hits, 5) + 15.0 * (1.0 - min(distance / (1.5 * ctx.atr), 1.0))
    return _hit("At support (about to break down)", "DOWN", score,
                f"price is {fmt(max(distance, 0))} above {fmt(level)}, a level touched "
                f"{hits} time(s) in {ctx.lookback} candles",
                trigger=level - 0.25 * ctx.atr, invalidation=level + 1.5 * ctx.atr,
                objective=level - height, extras={"touches": hits, "level": level})


def mb_multi_touch(ctx: MBContext):
    """A level tested three or more times from the same side."""
    # Counted on PIVOTS, not on every bar, and the touches must sit tightly on
    # one price. Counting bars inside a half-ATR band meant a sine wave's whole
    # upper shoulder registered as "touches", so this fired on every shape in
    # the bench; a level nobody can point to is not a level.
    band = 0.3 * ctx.atr
    best = None
    for pivots, side, label in ((ctx.pivot_highs, "UP", "resistance"),
                                (ctx.pivot_lows, "DOWN", "support")):
        if len(pivots) < 3:
            continue
        values = np.array([v for _p, v in pivots], float)
        extreme = values.max() if side == "UP" else values.min()
        near = values[np.abs(values - extreme) <= band]
        if len(near) < 3:
            continue
        spread = float(near.std())
        if spread > 0.25 * ctx.atr:
            continue                      # the touches are not on one price
        candidate = float(near.mean())
        if abs(ctx.price - candidate) > 4.0 * ctx.atr:
            continue                      # too far away to be the live question
        if best is None or len(near) > best[0]:
            best = (int(len(near)), candidate, side, label)
    if best is None:
        return None
    hits, level, side, label = best
    height = ctx.range_high - ctx.range_low
    away = abs(ctx.price - level)
    score = 40.0 + 10.0 * min(hits, 6) - 10.0 * min(away / (3.0 * ctx.atr), 1.0)
    return _hit(f"Multi-touch {label} ({hits} hits)", side, score,
                f"{hits} touches of {fmt(level)} within {fmt(ctx.tol)}; price is "
                f"{fmt(away)} away. The more often a level is tested the thinner it gets",
                trigger=level + (0.25 * ctx.atr if side == "UP" else -0.25 * ctx.atr),
                invalidation=level - (1.5 * ctx.atr if side == "UP" else -1.5 * ctx.atr),
                objective=level + (height if side == "UP" else -height),
                extras={"touches": hits, "level": level})


def mb_compression(ctx: MBContext):
    """A long quiet stretch: range well below its own historical norm."""
    if not np.isfinite(ctx.compression) or ctx.compression > 0.6:
        return None
    quiet = ""
    if np.isfinite(ctx.vol_trend) and ctx.vol_trend < 0.9:
        quiet = f"; volume is drying up ({ctx.vol_trend:.2f}x its earlier average)"
    height = ctx.range_high - ctx.range_low
    score = 50.0 + 45.0 * (1.0 - ctx.compression / 0.6)
    return _hit("Compression / accumulation zone", "EITHER", score,
                f"the last {ctx.lookback} candles span {fmt(height)}, only "
                f"{ctx.compression:.2f}x this instrument's usual range{quiet}",
                trigger=ctx.range_high + 0.25 * ctx.atr,
                invalidation=ctx.range_low - 0.25 * ctx.atr,
                objective=ctx.range_high + height,
                extras={"level": ctx.range_high, "lower": ctx.range_low})


def mb_triangle(ctx: MBContext):
    """Converging highs and lows, with the apex close."""
    if len(ctx.pivot_highs) < 2 or len(ctx.pivot_lows) < 2:
        return None
    hx = np.array([p for p, _v in ctx.pivot_highs], float)
    hy = np.array([v for _p, v in ctx.pivot_highs], float)
    lx = np.array([p for p, _v in ctx.pivot_lows], float)
    ly = np.array([v for _p, v in ctx.pivot_lows], float)
    try:
        hs = float(np.polyfit(hx, hy, 1)[0])
        ls = float(np.polyfit(lx, ly, 1)[0])
    except Exception:                                               # noqa: BLE001
        return None
    if not (np.isfinite(hs) and np.isfinite(ls)):
        return None
    converging = (hs < 0 and ls > 0) or (abs(hs) < 1e-9 and ls > 0) or \
                 (hs < 0 and abs(ls) < 1e-9)
    if not converging:
        return None
    gap_now = float(ctx.highs[-10:].max() - ctx.lows[-10:].min())
    gap_then = float(ctx.highs[:20].max() - ctx.lows[:20].min())
    if gap_then <= 0 or gap_now / gap_then > 0.7:
        return None
    kind = ("Symmetrical" if hs < 0 and ls > 0 else
            "Descending" if hs < 0 else "Ascending")
    height = gap_then
    score = 50.0 + 45.0 * (1.0 - gap_now / gap_then)
    return _hit(f"{kind} triangle at the apex", "EITHER", score,
                f"highs sloping {hs:+.4f} and lows {ls:+.4f} per candle have narrowed the "
                f"range from {fmt(gap_then)} to {fmt(gap_now)}",
                trigger=float(ctx.highs[-10:].max()) + 0.25 * ctx.atr,
                invalidation=float(ctx.lows[-10:].min()) - 0.25 * ctx.atr,
                objective=float(ctx.highs[-10:].max()) + height,
                extras={"level": float(ctx.highs[-10:].max()),
                        "lower": float(ctx.lows[-10:].min())})


def _prior_extreme(ctx: MBContext, bars_back: int):
    cut = max(len(ctx.highs) - bars_back, 10)
    return float(ctx.highs[:cut].max()), float(ctx.lows[:cut].min())


def mb_breakout_retest(ctx: MBContext):
    """Broke above an old high, came back to it, and is holding."""
    old_high, _ = _prior_extreme(ctx, 20)
    recent_max = float(ctx.highs[-20:].max())
    if recent_max <= old_high + 0.5 * ctx.atr:
        return None                                   # no break happened
    if ctx.price < old_high - 0.5 * ctx.atr:
        return None                                   # fell back through: not holding
    if ctx.price > old_high + 2.0 * ctx.atr:
        return None                                   # already gone, no retest
    score = 60.0 + 30.0 * (1.0 - abs(ctx.price - old_high) / (2.0 * ctx.atr))
    return _hit("Breakout, retest holding", "UP", score,
                f"broke {fmt(old_high)} (high was {fmt(recent_max)}) and has come back to "
                f"{fmt(ctx.price)}, still above the level it broke",
                trigger=ctx.price + 0.25 * ctx.atr, invalidation=old_high - 0.75 * ctx.atr,
                objective=ctx.price + (recent_max - old_high) * 2.0,
                extras={"level": old_high})


def mb_breakdown_retest(ctx: MBContext):
    """Broke below an old low, came back to it, and is being rejected."""
    _, old_low = _prior_extreme(ctx, 20)
    recent_min = float(ctx.lows[-20:].min())
    if recent_min >= old_low - 0.5 * ctx.atr:
        return None
    if ctx.price > old_low + 0.5 * ctx.atr:
        return None
    if ctx.price < old_low - 2.0 * ctx.atr:
        return None
    score = 60.0 + 30.0 * (1.0 - abs(ctx.price - old_low) / (2.0 * ctx.atr))
    return _hit("Breakdown, retest rejecting", "DOWN", score,
                f"broke {fmt(old_low)} (low was {fmt(recent_min)}) and has come back to "
                f"{fmt(ctx.price)}, still below the level it broke",
                trigger=ctx.price - 0.25 * ctx.atr, invalidation=old_low + 0.75 * ctx.atr,
                objective=ctx.price - (old_low - recent_min) * 2.0,
                extras={"level": old_low})


def mb_equal_highs(ctx: MBContext):
    """Two or more highs at the same price: a pool of stops sitting above."""
    if len(ctx.pivot_highs) < 2:
        return None
    # The LAST few pivots only, and within a quarter-ATR. "Equal highs" means a
    # pair a trader could point at, not any two peaks of a sine wave that
    # happen to land inside a half-ATR band.
    recent = np.array([v for _p, v in ctx.pivot_highs[-4:]], float)
    top = float(recent.max())
    band = 0.25 * ctx.atr
    matched = int(np.sum(np.abs(recent - top) <= band))
    if matched < 2:
        return None
    away = top - ctx.price
    if abs(away) > 4.0 * ctx.atr:
        return None
    score = 45.0 + 12.0 * min(matched, 4) - 12.0 * min(abs(away) / (4.0 * ctx.atr), 1.0)
    return _hit("Equal highs (liquidity above)", "UP", score,
                f"{matched} swing highs within {fmt(band)} of {fmt(top)}; the stops of "
                f"everyone short sit just above it, which is what makes it a target",
                trigger=top + 0.25 * ctx.atr, invalidation=top - 1.5 * ctx.atr,
                objective=top + (ctx.range_high - ctx.range_low) * 0.5,
                extras={"level": top, "touches": matched})


def mb_equal_lows(ctx: MBContext):
    """Two or more lows at the same price."""
    if len(ctx.pivot_lows) < 2:
        return None
    recent = np.array([v for _p, v in ctx.pivot_lows[-4:]], float)
    bottom = float(recent.min())
    band = 0.25 * ctx.atr
    matched = int(np.sum(np.abs(recent - bottom) <= band))
    if matched < 2:
        return None
    away = ctx.price - bottom
    if abs(away) > 4.0 * ctx.atr:
        return None
    score = 45.0 + 12.0 * min(matched, 4) - 12.0 * min(abs(away) / (4.0 * ctx.atr), 1.0)
    return _hit("Equal lows (liquidity below)", "DOWN", score,
                f"{matched} swing lows within {fmt(band)} of {fmt(bottom)}; the stops of "
                f"everyone long sit just below it",
                trigger=bottom - 0.25 * ctx.atr, invalidation=bottom + 1.5 * ctx.atr,
                objective=bottom - (ctx.range_high - ctx.range_low) * 0.5,
                extras={"level": bottom, "touches": matched})


def mb_failed_breakdown(ctx: MBContext):
    """Swept the lows and reclaimed them: the shakeout that traps sellers."""
    if len(ctx.pivot_lows) < 1:
        return None
    level = min(v for _p, v in ctx.pivot_lows)
    tail = slice(max(len(ctx.lows) - 10, 0), len(ctx.lows))
    pierced = float(ctx.lows[tail].min())
    if pierced > level - 0.3 * ctx.atr:
        return None
    if ctx.price < level + 0.2 * ctx.atr:
        return None                                   # not reclaimed
    depth = (level - pierced) / ctx.atr
    score = 60.0 + 25.0 * min(depth, 1.5) / 1.5
    return _hit("Support swept and reclaimed", "UP", score,
                f"price wicked {fmt(depth, 2)} ATR below {fmt(level)} and closed back above "
                f"it: the sellers filled on that break are trapped",
                trigger=ctx.price + 0.25 * ctx.atr, invalidation=pierced - 0.25 * ctx.atr,
                objective=ctx.range_high, extras={"level": level})


def mb_failed_breakout(ctx: MBContext):
    """Swept the highs and lost them again."""
    if len(ctx.pivot_highs) < 1:
        return None
    level = max(v for _p, v in ctx.pivot_highs)
    tail = slice(max(len(ctx.highs) - 10, 0), len(ctx.highs))
    pierced = float(ctx.highs[tail].max())
    if pierced < level + 0.3 * ctx.atr:
        return None
    if ctx.price > level - 0.2 * ctx.atr:
        return None
    depth = (pierced - level) / ctx.atr
    score = 60.0 + 25.0 * min(depth, 1.5) / 1.5
    return _hit("Resistance swept and lost", "DOWN", score,
                f"price wicked {fmt(depth, 2)} ATR above {fmt(level)} and closed back below "
                f"it: the buyers filled on that break are trapped",
                trigger=ctx.price - 0.25 * ctx.atr, invalidation=pierced + 0.25 * ctx.atr,
                objective=ctx.range_low, extras={"level": level})


def mb_double_bottom(ctx: MBContext):
    """W: two lows at the same price with a peak between them."""
    if len(ctx.pivot_lows) < 2:
        return None
    (i1, v1), (i2, v2) = ctx.pivot_lows[-2], ctx.pivot_lows[-1]
    if abs(v1 - v2) > ctx.tol or i2 - i1 < 5:
        return None
    between = [v for p, v in ctx.pivot_highs if i1 < p < i2]
    if not between:
        return None
    neckline = float(max(between))
    depth = neckline - min(v1, v2)
    if depth < 3.0 * ctx.atr:
        return None
    # A W has to be AT THE BOTTOM. Two similar lows anywhere inside an
    # oscillation are just an oscillation; what makes it a double bottom is
    # that the pair sits at the low of the range being reversed.
    if min(v1, v2) > ctx.range_low + 1.0 * ctx.atr:
        return None
    broken = ctx.price > neckline
    score = 55.0 + 25.0 * min(depth / (5.0 * ctx.atr), 1.0) + (15.0 if broken else 0.0)
    return _hit("Double bottom (W)" + (" — neckline broken" if broken else ""), "UP", score,
                f"two lows at {fmt(v1)} and {fmt(v2)} with a neckline at {fmt(neckline)}"
                + (", already broken" if broken else
                   f", {fmt(neckline - ctx.price)} above price"),
                trigger=neckline + 0.25 * ctx.atr, invalidation=min(v1, v2) - 0.5 * ctx.atr,
                objective=neckline + depth, extras={"level": neckline, "touches": 2})


def mb_double_top(ctx: MBContext):
    """M: two highs at the same price with a trough between them."""
    if len(ctx.pivot_highs) < 2:
        return None
    (i1, v1), (i2, v2) = ctx.pivot_highs[-2], ctx.pivot_highs[-1]
    if abs(v1 - v2) > ctx.tol or i2 - i1 < 5:
        return None
    between = [v for p, v in ctx.pivot_lows if i1 < p < i2]
    if not between:
        return None
    neckline = float(min(between))
    depth = max(v1, v2) - neckline
    if depth < 3.0 * ctx.atr:
        return None
    if max(v1, v2) < ctx.range_high - 1.0 * ctx.atr:
        return None
    broken = ctx.price < neckline
    score = 55.0 + 25.0 * min(depth / (5.0 * ctx.atr), 1.0) + (15.0 if broken else 0.0)
    return _hit("Double top (M)" + (" — neckline broken" if broken else ""), "DOWN", score,
                f"two highs at {fmt(v1)} and {fmt(v2)} with a neckline at {fmt(neckline)}"
                + (", already broken" if broken else
                   f", {fmt(ctx.price - neckline)} below price"),
                trigger=neckline - 0.25 * ctx.atr, invalidation=max(v1, v2) + 0.5 * ctx.atr,
                objective=neckline - depth, extras={"level": neckline, "touches": 2})


def mb_trendline_retest(ctx: MBContext):
    """
    A sloping trendline broken, retested, and still holding.

    The line is fitted through the swing pivots rather than drawn by eye: a
    descending resistance line through the swing HIGHS, an ascending support
    line through the swing LOWS. The setup needs all three stages -- a close
    through the line, a pullback that comes back to it, and price still on the
    breaking side now. A break alone is the Chart Patterns tab's job; what
    makes this one tradable is that the line has since been defended.
    """
    for pivots, side, name in ((ctx.pivot_highs, "UP", "resistance"),
                               (ctx.pivot_lows, "DOWN", "support")):
        if len(pivots) < 3:
            continue
        xs = np.array([p for p, _v in pivots], float)
        ys = np.array([v for _p, v in pivots], float)
        try:
            slope_, intercept = np.polyfit(xs, ys, 1)
        except Exception:                                           # noqa: BLE001
            continue
        if not (np.isfinite(slope_) and np.isfinite(intercept)):
            continue
        # A resistance line worth breaking slopes down or sideways; a support
        # line worth breaking slopes up or sideways.
        if side == "UP" and slope_ > 0.02 * ctx.atr:
            continue
        if side == "DOWN" and slope_ < -0.02 * ctx.atr:
            continue

        last = len(ctx.closes) - 1
        line_at = lambda i: float(slope_ * i + intercept)           # noqa: E731
        line_now = line_at(last)
        if not np.isfinite(line_now):
            continue

        recent = range(max(last - 25, 1), last + 1)
        broke_at = None
        for i in recent:
            above = ctx.closes[i] > line_at(i) + 0.4 * ctx.atr
            below = ctx.closes[i] < line_at(i) - 0.4 * ctx.atr
            if (side == "UP" and above) or (side == "DOWN" and below):
                broke_at = i
                break
        if broke_at is None or broke_at >= last - 1:
            continue                       # no break, or it only just happened

        # A retest: price came back within half an ATR of the line AFTER the
        # break, and is still on the breaking side now.
        retested = any(abs(ctx.closes[i] - line_at(i)) <= 0.6 * ctx.atr
                       for i in range(broke_at + 1, last + 1))
        if not retested:
            continue
        holding = (ctx.price > line_now) if side == "UP" else (ctx.price < line_now)
        if not holding:
            continue

        height = ctx.range_high - ctx.range_low
        bars_since = last - broke_at
        score = 62.0 + 25.0 * (1.0 - min(bars_since / 25.0, 1.0))
        objective = (line_now + height * 0.6) if side == "UP" else (line_now - height * 0.6)
        stop = (line_now - 0.75 * ctx.atr) if side == "UP" else (line_now + 0.75 * ctx.atr)
        return _hit(f"Trendline break + retest holding ({name})", side, score,
                    f"a {name} line fitted through {len(pivots)} pivots (slope "
                    f"{slope_:+.4f} per candle) was broken {bars_since} candle(s) ago at "
                    f"{fmt(line_at(broke_at))}, retested, and price is still "
                    f"{'above' if side == 'UP' else 'below'} it at {fmt(line_now)}",
                    trigger=ctx.price + (0.25 * ctx.atr if side == "UP" else -0.25 * ctx.atr),
                    invalidation=stop, objective=objective,
                    extras={"level": line_now, "touches": len(pivots)})
    return None


MAKE_BREAK_SETUPS = [
    ("inverted_v", "Inverted V (round top)", mb_inverted_v),
    ("v_bottom", "V bottom (round bottom)", mb_v_bottom),
    ("at_resistance", "At resistance", mb_at_resistance),
    ("at_support", "At support", mb_at_support),
    ("multi_touch", "Multi-touch level (3+)", mb_multi_touch),
    ("compression", "Compression / accumulation", mb_compression),
    ("triangle", "Converging triangle at apex", mb_triangle),
    ("breakout_retest", "Breakout + retest holding", mb_breakout_retest),
    ("breakdown_retest", "Breakdown + retest rejecting", mb_breakdown_retest),
    ("equal_highs", "Equal highs", mb_equal_highs),
    ("equal_lows", "Equal lows", mb_equal_lows),
    ("failed_breakdown", "Support swept and reclaimed", mb_failed_breakdown),
    ("failed_breakout", "Resistance swept and lost", mb_failed_breakout),
    ("double_bottom", "Double bottom / W", mb_double_bottom),
    ("double_top", "Double top / M", mb_double_top),
    ("trendline_retest", "Trendline break + retest", mb_trendline_retest),
]
MAKE_BREAK_BY_KEY = {key: (label, fn) for key, label, fn in MAKE_BREAK_SETUPS}


def mb_confirmations(ctx: MBContext, direction: str) -> tuple[float, list[str]]:
    """
    What the secondary evidence says about the proposed direction.

    Returns a score adjustment and the reasons for it. Volume and RSI do not
    create the setup -- the structure does -- but they say whether anyone is
    showing up for it.
    """
    bonus, notes = 0.0, []

    if np.isfinite(ctx.vol_ratio):
        if ctx.vol_ratio >= 1.5:
            bonus += 8.0
            notes.append(f"volume {fmt(ctx.vol_ratio)}x average on the latest candle")
        elif ctx.vol_ratio < 0.7:
            notes.append(f"volume only {fmt(ctx.vol_ratio)}x average — nobody is here yet")
    if np.isfinite(ctx.vol_trend) and ctx.vol_trend < 0.85:
        bonus += 5.0
        notes.append(f"participation drying up ({fmt(ctx.vol_trend)}x), which is what a "
                     f"coil looks like before it releases")

    if np.isfinite(ctx.rsi_now):
        if direction == "UP" and ctx.rsi_now < 35:
            bonus += 6.0
            notes.append(f"RSI {fmt(ctx.rsi_now)} — oversold into the level")
        elif direction == "DOWN" and ctx.rsi_now > 65:
            bonus += 6.0
            notes.append(f"RSI {fmt(ctx.rsi_now)} — overbought into the level")
        elif direction == "UP" and ctx.rsi_now > 70:
            bonus -= 6.0
            notes.append(f"RSI {fmt(ctx.rsi_now)} — already stretched for a long")
        elif direction == "DOWN" and ctx.rsi_now < 30:
            bonus -= 6.0
            notes.append(f"RSI {fmt(ctx.rsi_now)} — already stretched for a short")
        else:
            notes.append(f"RSI {fmt(ctx.rsi_now)}, neither stretched nor washed out")

    if np.isfinite(ctx.compression) and ctx.compression < 0.7:
        bonus += 4.0
        notes.append(f"range is {ctx.compression:.2f}x its own norm — energy stored")
    return bonus, notes


def mb_plan(ctx: MBContext, hit: dict) -> dict:
    """
    Entry, stop and target for one setup.

    Built from the structure's own levels: the trigger is the price that
    confirms the setup, the stop sits beyond what would disprove it, and the
    objective is the pattern's measured move. When the geometry does not offer
    a reward worth the risk, the row says so rather than quietly presenting a
    0.4:1 trade as an opportunity.
    """
    direction = hit["direction"]
    if direction == "EITHER":
        # An undecided shape gets both sides, which is the honest output for a
        # coil: you do not know which way, you know where.
        upper = hit.get("trigger")
        lower = hit.get("invalidation")
        return {"side": "WAIT", "entry": None, "stop": None, "target": None, "rr": None,
                "note": (f"Undecided. Long above {fmt(upper)}, short below {fmt(lower)}; "
                         f"trade the break, not the coil.")}

    entry = hit.get("trigger")
    stop = hit.get("invalidation")
    target = hit.get("objective")
    if entry is None or stop is None or target is None:
        return {"side": direction, "entry": entry, "stop": stop, "target": target,
                "rr": None, "note": "the structure does not define a complete level set"}

    risk = abs(float(entry) - float(stop))
    reward = abs(float(target) - float(entry))
    rr = round(reward / risk, 2) if risk > 0 else None
    note = ""
    if rr is not None and rr < 1.0:
        note = ("The geometry is poor: the stop is further than the objective, so the level "
                "is right but the trade is not.")
    return {"side": "LONG" if direction == "UP" else "SHORT", "entry": float(entry),
            "stop": float(stop), "target": float(target), "rr": rr, "note": note}


def make_break_scan_one(ticker: str, interval: str, period: str, wanted: list[str],
                        lookback: int = 120, pivot: int = 3, tol_atr: float = 0.5,
                        min_score: float = 0.0) -> list[dict]:
    """Every selected setup that is currently present on one ticker/timeframe."""
    frame = load_market_data(ticker, period, interval,
                             freshness_seconds=180, min_bars=60).frame
    ctx = mb_context(frame, lookback, pivot, tol_atr)
    if ctx is None:
        return []

    rows = []
    for key in wanted:
        entry = MAKE_BREAK_BY_KEY.get(key)
        if not entry:
            continue
        label, fn = entry
        try:
            hit = fn(ctx)
        except Exception as exc:                                    # noqa: BLE001
            rows.append({"Ticker": ticker, "Timeframe": interval, "Period": period,
                         "Setup": label, "Direction": "-", "Readiness": 0.0,
                         "Reading": f"failed: {str(exc)[:80]}"})
            continue
        if not hit:
            continue
        bonus, notes = mb_confirmations(ctx, hit["direction"])
        plan = mb_plan(ctx, hit)
        readiness = max(0.0, min(100.0, hit["score"] + bonus))
        if readiness < float(min_score):
            continue
        rows.append({
            "Ticker": ticker, "Timeframe": interval, "Period": period,
            "Setup": hit["setup"], "Direction": hit["direction"],
            "Readiness": round(readiness, 1),
            "Side": plan["side"], "Entry": plan["entry"], "Stop": plan["stop"],
            "Target": plan["target"], "R:R": plan["rr"],
            "Price": round(ctx.price, 2),
            "Distance to trigger": round(abs(ctx.price - float(hit["trigger"])), 2)
            if hit.get("trigger") is not None else None,
            "Touches": hit.get("touches"),
            "Volume x": round(ctx.vol_ratio, 2) if np.isfinite(ctx.vol_ratio) else None,
            "RSI": round(ctx.rsi_now, 1) if np.isfinite(ctx.rsi_now) else None,
            "Compression": round(ctx.compression, 2) if np.isfinite(ctx.compression) else None,
            "Reading": hit["reading"],
            "Confirmations": "; ".join(notes) if notes else "none",
            "Plan note": plan.get("note", ""),
            "Checked at": pd.Timestamp.now(),
        })
    return rows


def tab_make_break(cfg: dict) -> None:
    st.subheader("Make or Break — tickers standing at a decision")
    st.warning(
        "**A readiness score says how well formed a setup is, not how likely it is to "
        "work.** A textbook ascending triangle at the apex scores high and then breaks the "
        "wrong way often enough to ruin anyone who confuses the two. The levels below are the "
        "structure's own — where the trigger sits, where the idea is disproved, and what the "
        "pattern measures to — not a forecast. Rank, apply to the sidebar, then test it in "
        "Backtesting before trusting it.")

    c1, c2 = st.columns([1, 1])
    universe = c1.selectbox("Universe", SCREENER_UNIVERSES, key="mb_universe")
    min_score = c2.number_input("Minimum readiness", 0, 100, 55, 5, key="mb_minscore",
                                help="Setups below this are not listed. 55 keeps the "
                                     "reasonably formed ones; raise it to shortlist harder.")

    custom_text = ""
    if universe.startswith("Custom"):
        custom_text = st.text_area("Tickers", "RELIANCE\nTCS\nINFY", key="mb_custom")
    all_tickers, note = universe_tickers_ui(universe, custom_text, None, "mb")
    chosen = st.multiselect(f"Tickers ({len(all_tickers)} in {universe})", all_tickers,
                            default=all_tickers, key=f"mb_tickers_{universe}")
    if note:
        st.caption(note)

    with st.container(border=True):
        timeframes = _multi_picker("Timeframes", list(INTERVALS), "mb_tf", ["15m", "1d"])
    with st.container(border=True):
        periods = _multi_picker("History windows", list(PERIODS), "mb_period", ["3mo"],
                                formatter=str)
    if not timeframes or not periods:
        st.error("Pick at least one timeframe and one history window.")
        return

    with st.container(border=True):
        st.markdown(f"**Setups** — {len(MAKE_BREAK_SETUPS)} available")
        keys = [key for key, _l, _f in MAKE_BREAK_SETUPS]
        a, b = st.columns(2)
        if a.button("Select all setups", key="mb_all", width="stretch"):
            for key in keys:
                st.session_state[f"mb_setup_{key}"] = True
            st.rerun()
        if b.button("Clear all setups", key="mb_none", width="stretch"):
            for key in keys:
                st.session_state[f"mb_setup_{key}"] = False
            st.rerun()
        wanted = []
        columns = st.columns(3)
        for i, (key, label, _fn) in enumerate(MAKE_BREAK_SETUPS):
            if columns[i % 3].checkbox(label, value=True, key=f"mb_setup_{key}"):
                wanted.append(key)
    if not wanted:
        st.error("Pick at least one setup.")
        return

    with st.expander("Detection settings", expanded=False):
        d1, d2, d3 = st.columns(3)
        lookback = d1.number_input("Structure lookback (candles)", 40, 500, 120, 10,
                                   key="mb_look",
                                   help="How far back a level, range or coil is measured.")
        pivot = d2.number_input("Swing strength (candles either side)", 1, 15, 3, 1,
                                key="mb_pivot")
        tol_atr = d3.number_input("Level tolerance (ATR)", 0.1, 3.0, 0.5, 0.1, key="mb_tol",
                                  help="How close two highs must be to count as the same "
                                       "level. Wider finds more, and finds them vaguer.")

    jobs = [(t, tf, p) for t in chosen for tf in timeframes for p in periods]
    scan_cost_notice(len(jobs), per_job_hint=1.6, prefix="mb")

    def _worker(job):
        ticker, interval, period = job
        try:
            effective, _clamp = sanitize_period(interval, period)
            rows = make_break_scan_one(ticker, interval, effective, wanted,
                                       int(lookback), int(pivot), float(tol_atr),
                                       float(min_score))
            return rows, []
        except Exception as exc:                                    # noqa: BLE001
            return [], [{"Ticker": ticker, "Timeframe": interval, "Period": period,
                         "Problem": str(exc)[:140]}]

    rows, errs, _done = chunked_sweep("mb", jobs, _worker, _auto_slice_seconds(),
                                      "ticker/timeframe/period jobs",
                                      describe=lambda j: f"{j[0]} · {j[1]} · {j[2]}")

    frame = pd.DataFrame(rows)
    if frame.empty:
        st.info("Nothing scanned yet, or nothing cleared the readiness bar. Press **Run** "
                "above, or lower the minimum readiness.")
        if errs:
            with st.expander(f"Jobs that failed ({len(errs)})"):
                st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
        return

    frame = frame.sort_values("Readiness", ascending=False).reset_index(drop=True)
    frame.insert(0, "Rank", range(1, len(frame) + 1))

    a, b, c, d = st.columns(4)
    a.metric("Setups found", len(frame))
    a_long = frame[frame["Side"] == "LONG"]
    a_short = frame[frame["Side"] == "SHORT"]
    b.metric("Long side", len(a_long))
    c.metric("Short side", len(a_short))
    d.metric("Undecided coils", int((frame["Side"] == "WAIT").sum()),
             "direction unknown, level known")

    side = st.radio("Show", ["Everything", "Long only", "Short only", "Undecided only"],
                    horizontal=True, key="mb_side")
    view = frame
    if side == "Long only":
        view = frame[frame["Side"] == "LONG"]
    elif side == "Short only":
        view = frame[frame["Side"] == "SHORT"]
    elif side == "Undecided only":
        view = frame[frame["Side"] == "WAIT"]
    if view.empty:
        st.info("Nothing on that side. Switch back to Everything.")
        return

    order = [c for c in ["Rank", "Ticker", "Timeframe", "Period", "Setup", "Direction",
                         "Readiness", "Side", "Price", "Entry", "Stop", "Target", "R:R",
                         "Distance to trigger", "Touches", "Volume x", "RSI", "Compression",
                         "Reading", "Confirmations", "Plan note", "Checked at"]
             if c in view.columns]
    st.dataframe(view[order], width="stretch", hide_index=True,
                 column_config={"Readiness": st.column_config.ProgressColumn(
                     "Readiness", min_value=0, max_value=100, format="%.0f")})
    st.download_button("Download the scan (CSV)", view[order].to_csv(index=False).encode(),
                       f"make_or_break_{pd.Timestamp.now():%Y%m%d_%H%M}.csv", "text/csv",
                       key="mb_dl")

    st.markdown("#### Inspect and apply")
    labels = [f"#{r['Rank']}  {r['Ticker']} · {r['Timeframe']} · {r['Setup']}"
              for _i, r in view.iterrows()]
    i1, i2 = st.columns([3, 1])
    picked_label = i1.selectbox("Ranked setup", labels, key="mb_pick")
    picked = view.iloc[labels.index(picked_label)].to_dict()

    tone = {"LONG": st.success, "SHORT": st.error}.get(picked["Side"], st.info)
    tone(f"**{picked['Setup']}** on `{picked['Ticker']}` ({picked['Timeframe']}) — "
         f"readiness {fmt(picked['Readiness'], 0)} / 100, side **{picked['Side']}**")
    st.markdown(f"**What the chart shows.** {picked['Reading']}.")
    st.markdown(f"**Secondary evidence.** {picked['Confirmations']}.")

    if picked.get("Entry") is not None:
        p1, p2, p3, p4 = st.columns(4)
        p1.metric("Entry (trigger)", fmt(picked["Entry"]))
        p2.metric("Stop (invalidation)", fmt(picked["Stop"]),
                  f"{fmt(abs(float(picked['Entry']) - float(picked['Stop'])))} risk")
        p3.metric("Target (measured move)", fmt(picked["Target"]),
                  f"{fmt(abs(float(picked['Target']) - float(picked['Entry'])))} reward")
        p4.metric("Reward : risk", f"{fmt(picked['R:R'])} : 1" if picked.get("R:R") else "--")
    if str(picked.get("Plan note") or ""):
        st.warning(picked["Plan note"])

    if i2.button("Apply to the sidebar", width="stretch", key="mb_apply",
                 help="Sends this ticker and timeframe to the control console so it can be "
                      "backtested or traded live with a real strategy."):
        st.session_state.pending_ticker = picked["Ticker"]
        bullish = picked["Side"] == "LONG"
        st.session_state.pending_combo = {
            "strategy": ("05 · Opening Range Breakout (ORB)" if bullish
                         else "25 · SuperTrend Flip"),
            "sl_type": "ATR Multiple", "sl_value": 1.5,
            "tp_type": "Risk : Reward Multiple", "tp_value": 2.0,
            "filter_key": "", "widgets": {"cfg_interval": picked["Timeframe"]}}
        st.rerun()

    st.caption("The sidebar receives the ticker and timeframe. It does NOT receive the "
               "pattern — no strategy in this app trades 'a triangle', so a sensible "
               "breakout profile is applied and you should replace it with whatever you "
               "actually want to test.")

    if errs:
        with st.expander(f"Jobs that failed ({len(errs)})"):
            st.dataframe(pd.DataFrame(errs), width="stretch", hide_index=True)
    render_analyst_panel("mb", "these make-or-break candidates", _frame_context(frame))


# =============================================================================
# SECTION 19l -- CHART STUDIO
# =============================================================================
# One ticker, read properly: a large chart, what the structure says, the bar by
# bar record, and how it has moved against a second instrument.
#
# The returns heatmaps use a DIVERGING scale -- the app's own red and teal poles
# with a neutral grey midpoint -- because a return is polarity data, signed
# around zero. A sequential ramp would make "slightly positive" and "very
# negative" neighbours on the same hue, which is the wrong question entirely.
# Both poles are validated against the light and dark chart surfaces, and every
# cell carries its own number so the colour never has to be decoded alone.
_DIVERGING_RETURNS = [
    [0.0, "#b3372f"], [0.25, "#ef5350"], [0.5, "#8c8c8c"],
    [0.75, "#26a69a"], [1.0, "#15756c"],
]


def align_two_series(a: pd.DataFrame, b: pd.DataFrame) -> tuple[pd.DataFrame, str]:
    """
    Put two instruments on one index, whatever clocks they arrived on.

    Three things go wrong here, and all three are the timezone problem the user
    flagged. Yahoo stamps Indian equities Asia/Kolkata, crypto in UTC, and some
    series with no zone at all; joining those as they arrive either raises or --
    far worse -- silently pairs bars hours apart and calls the result a ratio.
    So everything is converted to UTC first, and a naive index is read as UTC
    with that assumption stated rather than hidden.

    That alone is not enough. India is UTC+5:30, so an hourly Indian bar lands
    at 03:45, 04:45 UTC while an hourly crypto bar lands at 04:00, 05:00 -- the
    two never share a single timestamp, and an exact join would refuse every
    India-against-crypto intraday pair outright. When an exact match is thin,
    each bar is therefore paired with the NEAREST bar of the other leg within
    half a bar's width, which is an honest pairing because no closer partner
    exists. Anything wider than half a bar is left unpaired rather than
    stretched, and the note says which rule was used.
    """
    notes = []

    def to_utc(frame: pd.DataFrame, label: str) -> pd.DataFrame:
        out = frame.copy()
        index = pd.DatetimeIndex(out.index)
        if index.tz is None:
            notes.append(f"{label} arrived without a timezone and was read as UTC")
            index = index.tz_localize("UTC")
        else:
            index = index.tz_convert("UTC")
        out.index = index
        out = out[~out.index.duplicated(keep="last")].sort_index()
        return out[["Open", "High", "Low", "Close"]].dropna()

    left, right = to_utc(a, "the first ticker"), to_utc(b, "the second")
    if left.empty or right.empty:
        return pd.DataFrame(), "One of the two legs has no usable candles."

    overlap_span = (min(left.index[-1], right.index[-1])
                    - max(left.index[0], right.index[0]))
    if overlap_span <= pd.Timedelta(0):
        return pd.DataFrame(), ("These two have no overlapping history on this timeframe, "
                                "so no ratio can be formed. Try a longer period, or a "
                                "coarser timeframe where both have data.")

    rename = {"Open": "a_open", "High": "a_high", "Low": "a_low", "Close": "a_close"}
    rename_b = {"Open": "b_open", "High": "b_high", "Low": "b_low", "Close": "b_close"}

    exact = left.index.intersection(right.index)
    smaller = min(len(left), len(right))
    if len(exact) >= max(5, 0.5 * smaller):
        joined = pd.concat([left.loc[exact].rename(columns=rename),
                            right.loc[exact].rename(columns=rename_b)], axis=1).dropna()
        notes.append(f"{len(joined)} timestamps matched exactly; "
                     f"{len(left) - len(joined)} bars of the first and "
                     f"{len(right) - len(joined)} of the second had no partner")
        return joined, "; ".join(notes)

    # Nearest-bar pairing, tolerance half a bar.
    def spacing(index: pd.DatetimeIndex) -> pd.Timedelta:
        if len(index) < 3:
            return pd.Timedelta(days=1)
        gaps = pd.Series(index[1:] - index[:-1])
        return pd.Timedelta(gaps.median())

    tolerance = min(spacing(left.index), spacing(right.index)) / 2
    if tolerance <= pd.Timedelta(0):
        tolerance = pd.Timedelta(minutes=1)
    try:
        merged = pd.merge_asof(
            left.rename(columns=rename).reset_index(names="_ts"),
            right.rename(columns=rename_b).reset_index(names="_ts"),
            on="_ts", direction="nearest", tolerance=tolerance)
    except Exception as exc:                                        # noqa: BLE001
        return pd.DataFrame(), (f"These two could not be put on a common clock ({exc}). "
                                "A coarser timeframe usually aligns them.")
    merged = merged.dropna().set_index("_ts")
    merged.index.name = None
    if merged.empty:
        return pd.DataFrame(), (
            "These two never trade within half a bar of each other on this timeframe, so "
            "no ratio can be formed. Markets on different sessions only line up on daily "
            "bars or coarser — try 1d.")
    notes.append(f"the two clocks differ, so each of {len(merged)} bars was paired with "
                 f"the nearest bar of the other within {_pretty_delta(tolerance)}")
    return merged, "; ".join(notes)


def _pretty_delta(delta: pd.Timedelta) -> str:
    """A timedelta in the words a person would use."""
    seconds = delta.total_seconds()
    if seconds < 90:
        return f"{seconds:.0f} seconds"
    if seconds < 5400:
        return f"{seconds / 60:.0f} minutes"
    if seconds < 86400:
        return f"{seconds / 3600:.1f} hours"
    return f"{seconds / 86400:.1f} days"


def ratio_frame(joined: pd.DataFrame) -> pd.DataFrame:
    """
    A candle series for the ratio of two instruments.

    The ratio's high is NOT the first high over the second high: that would be
    the best case of one paired with the worst of the other, a bar that never
    traded. Each ratio bar is built from the four pairings that can actually
    occur, and the extremes taken from those.
    """
    if joined.empty:
        return pd.DataFrame()
    corners = pd.DataFrame({
        "hh": joined["a_high"] / joined["b_high"],
        "hl": joined["a_high"] / joined["b_low"],
        "lh": joined["a_low"] / joined["b_high"],
        "ll": joined["a_low"] / joined["b_low"],
    })
    return pd.DataFrame({
        "Open": joined["a_open"] / joined["b_open"],
        "High": corners.max(axis=1),
        "Low": corners.min(axis=1),
        "Close": joined["a_close"] / joined["b_close"],
        "Volume": 0.0,
    }, index=joined.index)


def returns_heatmap(series: pd.Series, title: str, light: bool = False):
    """
    Returns laid out on the two axes that actually explain them.

    Intraday, that is weekday against hour -- the shape of a session. Daily and
    coarser, it is year against month. Picking one grid for both would leave
    half the cells empty on one of them.
    """
    import plotly.graph_objects as go

    values = pd.Series(series).dropna()
    if values.empty:
        return None, pd.DataFrame()
    index = pd.DatetimeIndex(values.index)
    intraday = bool(len(index) > 2 and (index[1:] - index[:-1]).min()
                    < pd.Timedelta(hours=23))

    if intraday:
        rows = index.hour
        cols = index.dayofweek
        row_name, col_name = "Hour", "Weekday"
        col_labels = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
        grid = pd.DataFrame({"r": rows, "c": cols, "v": values.to_numpy(float)})
        table = grid.pivot_table(index="r", columns="c", values="v", aggfunc="mean")
        x_labels = [col_labels[c] for c in table.columns]
        y_labels = [f"{int(h):02d}:00" for h in table.index]
    else:
        grid = pd.DataFrame({"r": index.year, "c": index.month,
                             "v": values.to_numpy(float)})
        table = grid.pivot_table(index="r", columns="c", values="v", aggfunc="sum")
        months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
                  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
        x_labels = [months[int(c) - 1] for c in table.columns]
        y_labels = [str(int(r)) for r in table.index]
        row_name, col_name = "Year", "Month"

    z = table.to_numpy(float)
    limit = float(np.nanmax(np.abs(z))) if np.isfinite(z).any() else 1.0
    limit = limit if limit > 0 else 1.0
    figure = go.Figure(go.Heatmap(
        z=z, x=x_labels, y=y_labels, colorscale=_DIVERGING_RETURNS,
        zmid=0.0, zmin=-limit, zmax=limit,
        text=np.round(z, 2), texttemplate="%{text}", textfont=dict(size=10),
        colorbar=dict(title="%"),
        hovertemplate=f"{col_name} %{{x}}<br>{row_name} %{{y}}<br>%{{z:.2f}}%<extra></extra>"))
    figure.update_layout(
        title=dict(text=title, x=0.01, xanchor="left", font=dict(size=14)),
        height=max(260, 42 * len(y_labels) + 120),
        margin=dict(l=70, r=20, t=50, b=40),
        template="plotly_white" if light else None)
    figure.update_xaxes(title_text=col_name, side="top")
    figure.update_yaxes(title_text=row_name, autorange="reversed")
    return figure, table


def studio_chart(frame: pd.DataFrame, title: str, light: bool = False, height: int = 720):
    """The big readable candle chart: everything else on this tab explains it."""
    import plotly.graph_objects as go

    figure = go.Figure(go.Candlestick(
        x=frame.index, open=frame["Open"], high=frame["High"],
        low=frame["Low"], close=frame["Close"], name="Price",
        increasing_line_color=_UP, decreasing_line_color=_DOWN,
        increasing_fillcolor=_UP, decreasing_fillcolor=_DOWN,
        line=dict(width=1)))
    for length, colour in ((20, "#f4a261"), (50, "#4f9df7")):
        if len(frame) > length:
            figure.add_trace(go.Scatter(
                x=frame.index, y=ema(frame["Close"], length), mode="lines",
                name=f"EMA {length}", line=dict(width=1.6, color=colour)))
    figure.update_layout(
        height=int(height), margin=dict(l=66, r=24, t=54, b=44),
        title=dict(text=title, x=0.01, xanchor="left", font=dict(size=16)),
        hovermode="x unified", dragmode="pan", xaxis_rangeslider_visible=False,
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
        template="plotly_white" if light else None)
    figure.update_yaxes(showgrid=True, gridcolor="rgba(128,128,128,0.15)")
    figure.update_xaxes(showgrid=False)
    return figure


def _studio_verdict(frame: pd.DataFrame, cfg: dict) -> tuple[str, str, list]:
    """Patterns, structure and a single recommendation for one chart."""
    ctx = mb_context(frame, min(len(frame) - 2, 150), 3, 0.5)
    setups = []
    if ctx is not None:
        for _key, _label, fn in MAKE_BREAK_SETUPS:
            try:
                hit = fn(ctx)
            except Exception:                                       # noqa: BLE001
                continue
            if hit:
                bonus, _notes = mb_confirmations(ctx, hit["direction"])
                plan = mb_plan(ctx, hit)
                setups.append({"Setup": hit["setup"], "Direction": hit["direction"],
                               "Readiness": round(min(100.0, hit["score"] + bonus), 1),
                               "Side": plan["side"], "Entry": plan["entry"],
                               "Stop": plan["stop"], "Target": plan["target"],
                               "R:R": plan["rr"], "Reading": hit["reading"],
                               "Caveat": plan.get("note", "")})
    setups.sort(key=lambda r: -r["Readiness"])

    analysis = smc_analyse(frame, 3, 3, min(len(frame) - 2, 150))
    smc_signal = analysis.get("signal", "HOLD") if not analysis.get("error") else "HOLD"

    longs = sum(1 for s in setups if s["Side"] == "LONG")
    shorts = sum(1 for s in setups if s["Side"] == "SHORT")
    if smc_signal == "BUY" and longs >= shorts:
        verdict = "BUY"
    elif smc_signal == "SELL" and shorts >= longs:
        verdict = "SELL"
    elif longs > shorts + 1:
        verdict = "BUY"
    elif shorts > longs + 1:
        verdict = "SELL"
    else:
        verdict = "HOLD"

    pieces = [f"structure reads **{smc_signal}** on the SMC engine"]
    if setups:
        top = setups[0]
        side_word = {"LONG": "long", "SHORT": "short"}.get(top["Side"], "two-sided")
        pieces.append(f"the best-formed pattern is **{top['Setup']}** at readiness "
                      f"{fmt(top['Readiness'], 0)}, which is a {side_word} setup")
        pieces.append(f"{longs} pattern(s) point up and {shorts} point down out of "
                      f"{len(setups)} found")
    else:
        pieces.append("no chart pattern is currently well formed enough to name")
    if verdict == "HOLD":
        pieces.append("nothing agrees strongly enough to act on, so the honest call is to "
                      "wait for the structure to resolve")
    narrative = ", and ".join([pieces[0], "; ".join(pieces[1:])]) if len(pieces) > 1 \
        else pieces[0]
    return verdict, narrative[0].upper() + narrative[1:] + ".", setups


def tab_chart_studio(cfg: dict) -> None:
    st.subheader("Chart Studio")
    st.caption("One instrument, read in full: the chart, what its structure says, the bar "
               "by bar record, and how it has moved against something else.")

    c1, c2, c3 = st.columns(3)
    universe_pool = sorted({t for group in ASSET_UNIVERSE.values() for t in group.values()})
    default_ticker = cfg.get("symbol", "^NSEI")
    pool = sorted(set(universe_pool) | {default_ticker})
    ticker = c1.selectbox("Ticker", pool, index=pool.index(default_ticker),
                          key="studio_ticker")
    custom = c1.text_input("or type any Yahoo symbol", value="", key="studio_custom",
                           placeholder=default_ticker).strip().upper()
    if custom:
        ticker = custom
    interval = c2.selectbox("Timeframe", INTERVALS,
                            index=INTERVALS.index(cfg.get("interval", "1d"))
                            if cfg.get("interval") in INTERVALS else INTERVALS.index("1d"),
                            key="studio_tf")
    period = c3.selectbox("Period", PERIODS,
                          index=PERIODS.index("6mo") if "6mo" in PERIODS else 0,
                          key="studio_period")
    height = c3.number_input("Chart height (pixels)", 400, 1400, 720, 40, key="studio_height")

    effective, clamp = sanitize_period(interval, period)
    if clamp:
        st.warning(clamp)

    try:
        frame = load_market_data(ticker, effective, interval,
                                 freshness_seconds=120, min_bars=20).frame
    except Exception as exc:                                        # noqa: BLE001
        st.error(f"Could not load `{ticker}` at {interval}/{effective}: {exc}")
        return

    st.plotly_chart(studio_chart(frame, f"{ticker} · {interval} · {effective}",
                                 light=bool(cfg.get("light_charts")), height=int(height)),
                    width="stretch", config={"scrollZoom": True, "displaylogo": False})
    st.caption("Scroll to zoom, drag to pan, double-click to reset.")

    # ---- what the chart says ------------------------------------------------
    st.markdown("#### What this chart is saying")
    verdict, narrative, setups = _studio_verdict(frame, cfg)
    tone = {"BUY": st.success, "SELL": st.error}.get(verdict, st.info)
    tone(f"**{verdict}** — {narrative}")
    if setups:
        st.dataframe(pd.DataFrame(setups), width="stretch", hide_index=True)
        # The headline levels come from the best setup that actually has levels:
        # an undecided coil ranks high but has nothing to enter at.
        best = next((row for row in setups if row.get("Entry") is not None), setups[0])
        if best.get("Entry") is not None:
            e1, e2, e3, e4 = st.columns(4)
            e1.metric("Entry", fmt(best["Entry"]))
            e2.metric("Stop", fmt(best["Stop"]))
            e3.metric("Target", fmt(best["Target"]))
            e4.metric("Reward : risk", f"{fmt(best['R:R'])} : 1" if best.get("R:R") else "--")
            st.caption(f"These levels belong to **{best['Setup']}** "
                       f"({best['Side'].lower()}). " + (best.get("Caveat") or ""))
    st.caption("Patterns and structure describe what HAS happened. Nothing here is "
               "backtested — send the ticker to the sidebar and test it before trading it.")

    # ---- the bar by bar record ---------------------------------------------
    st.markdown("#### Candle by candle")
    table = frame.copy()
    table["Points"] = (table["Close"] - table["Open"]).round(2)
    table["Change %"] = ((table["Close"] / table["Open"] - 1.0) * 100.0).round(3)
    table["Move from previous close"] = (table["Close"] - table["Close"].shift(1)).round(2)
    table["Return %"] = (table["Close"].pct_change() * 100.0).round(3)
    table = table.reset_index().rename(columns={table.index.name or "index": "Datetime"})
    newest_first = st.checkbox("Newest first", value=True, key="studio_order")
    shown = table.iloc[::-1] if newest_first else table

    signed_columns = ["Points", "Change %", "Move from previous close", "Return %"]

    def _ink(value):
        """Green for a gain, red for a loss, ordinary ink for flat or missing."""
        if value is None or (isinstance(value, float) and not np.isfinite(value)):
            return ""
        if value > 0:
            return f"color: {_UP}; font-weight: 600"
        if value < 0:
            return f"color: {_DOWN}; font-weight: 600"
        return ""

    styled = (shown.style
              .map(_ink, subset=signed_columns)
              .format({"Open": "{:.2f}", "High": "{:.2f}", "Low": "{:.2f}",
                       "Close": "{:.2f}", "Points": "{:+.2f}",
                       "Move from previous close": "{:+.2f}",
                       "Change %": "{:+.3f}%", "Return %": "{:+.3f}%"}, na_rep="--"))
    st.dataframe(styled, width="stretch", hide_index=True, height=360)
    st.caption("Points and percentage columns are green on a gain and red on a loss, "
               "with the sign printed as well so the colour is never the only cue.")

    d1, d2, d3 = st.columns(3)
    d1.download_button("Download CSV", table.to_csv(index=False).encode("utf-8"),
                       f"{ticker}_{interval}_{effective}.csv", "text/csv",
                       key="studio_csv", width="stretch")
    d2.download_button("Download Excel", _excel_bytes({"OHLC": table}),
                       f"{ticker}_{interval}_{effective}.xlsx",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                       key="studio_xlsx", width="stretch")
    gains = table["Points"].gt(0).sum()
    d3.metric("Up candles", f"{int(gains)} of {len(table)}",
              f"{gains / max(len(table), 1) * 100:.0f}%")

    # ---- the ratio ----------------------------------------------------------
    st.divider()
    st.markdown("#### Ratio against a second instrument")
    st.caption("A ratio chart answers which of two things is winning, independently of "
               "whether the market as a whole went up or down.")
    r1, r2 = st.columns(2)
    second_pool = [t for t in pool if t != ticker]
    second = r1.selectbox("Second ticker (the denominator)", second_pool,
                          key="studio_second")
    second_custom = r2.text_input("or type any Yahoo symbol", value="",
                                  key="studio_second_custom").strip().upper()
    if second_custom:
        second = second_custom

    try:
        other = load_market_data(second, effective, interval,
                                 freshness_seconds=120, min_bars=20).frame
    except Exception as exc:                                        # noqa: BLE001
        st.warning(f"Could not load `{second}`: {exc}. The ratio section needs both legs.")
        return

    joined, note = align_two_series(frame, other)
    if joined.empty:
        st.warning(note)
        return
    st.caption(f"Alignment: {note}.")

    ratio = ratio_frame(joined)
    st.plotly_chart(studio_chart(ratio, f"{ticker} / {second} · {interval}",
                                 light=bool(cfg.get("light_charts")),
                                 height=max(360, int(height) - 200)),
                    width="stretch", config={"scrollZoom": True, "displaylogo": False})
    first_ratio, last_ratio = float(ratio["Close"].iloc[0]), float(ratio["Close"].iloc[-1])
    drift = (last_ratio / first_ratio - 1.0) * 100.0 if first_ratio else float("nan")
    st.caption(f"The ratio moved from {fmt(first_ratio, 4)} to {fmt(last_ratio, 4)}, "
               f"{fmt(drift)}% over the window — "
               f"{'the first has outperformed' if drift > 0 else 'the second has outperformed'}.")

    # ---- binned returns -----------------------------------------------------
    st.markdown("#### Returns by bin")
    bins = st.number_input("Number of bins", 2, 50, 5, 1, key="studio_bins",
                           help="The window is split into this many equal stretches of "
                                "time, and each leg's return over each stretch is shown "
                                "side by side.")
    returns = pd.DataFrame({
        f"{ticker} return %": joined["a_close"].pct_change() * 100.0,
        f"{second} return %": joined["b_close"].pct_change() * 100.0,
    }).dropna()
    if returns.empty:
        st.info("Not enough overlapping bars to compute returns.")
        return

    labels = pd.cut(np.arange(len(returns)), int(bins), labels=False)
    rows = []
    for b in range(int(bins)):
        mask = labels == b
        if not mask.any():
            continue
        chunk = returns[mask]
        rows.append({
            "Bin": b + 1,
            "From": chunk.index[0], "To": chunk.index[-1], "Candles": len(chunk),
            f"{ticker} return %": round(float(
                (1.0 + chunk.iloc[:, 0] / 100.0).prod() - 1.0) * 100.0, 3),
            f"{second} return %": round(float(
                (1.0 + chunk.iloc[:, 1] / 100.0).prod() - 1.0) * 100.0, 3),
        })
    bin_table = pd.DataFrame(rows)
    bin_table["Difference"] = (bin_table[f"{ticker} return %"]
                               - bin_table[f"{second} return %"]).round(3)
    st.dataframe(bin_table, width="stretch", hide_index=True,
                 column_config={
                     f"{ticker} return %": st.column_config.NumberColumn(format="%.3f%%"),
                     f"{second} return %": st.column_config.NumberColumn(format="%.3f%%"),
                     "Difference": st.column_config.NumberColumn(format="%.3f%%")})
    st.caption("Each bin compounds the candle returns inside it, which is the correct way "
               "to add returns over time — summing them overstates a run of gains and "
               "understates a run of losses.")

    b1, b2 = st.columns(2)
    b1.download_button("Bins as CSV", bin_table.to_csv(index=False).encode("utf-8"),
                       f"bins_{ticker}_{second}.csv", "text/csv", key="studio_bins_csv",
                       width="stretch")
    b2.download_button("Bins as Excel",
                       _excel_bytes({"Bins": bin_table, "Returns": returns.reset_index()}),
                       f"bins_{ticker}_{second}.xlsx",
                       "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                       key="studio_bins_xlsx", width="stretch")

    # ---- the heatmaps -------------------------------------------------------
    st.markdown("#### Returns heatmaps")
    for label, column in ((ticker, returns.columns[0]), (second, returns.columns[1])):
        figure, grid = returns_heatmap(returns[column], f"{label} — returns (%)",
                                       light=bool(cfg.get("light_charts")))
        if figure is None:
            st.info(f"Not enough data to build a heatmap for {label}.")
            continue
        st.plotly_chart(figure, width="stretch", config={"displaylogo": False})
        with st.expander(f"{label} heatmap as a table"):
            st.dataframe(grid.round(3), width="stretch")
    st.caption("Red is negative and teal positive, with grey at zero — a return is signed "
               "around zero, so the scale diverges from a neutral midpoint rather than "
               "running light to dark. Every cell carries its own number as well.")


def _excel_bytes(sheets: dict) -> bytes:
    """One workbook from a dict of {sheet name: frame}, as bytes for a download."""
    import io
    buffer = io.BytesIO()
    try:
        with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
            for name, frame in sheets.items():
                safe = frame.copy()
                # Excel cannot store a timezone-aware timestamp.
                for column in safe.columns:
                    if isinstance(safe[column].dtype, pd.DatetimeTZDtype):
                        safe[column] = safe[column].dt.tz_localize(None)
                if isinstance(safe.index, pd.DatetimeIndex) and safe.index.tz is not None:
                    safe.index = safe.index.tz_localize(None)
                safe.to_excel(writer, sheet_name=str(name)[:31], index=False)
    except Exception:                                               # noqa: BLE001
        return b""
    return buffer.getvalue()


def main() -> None:
    st.set_page_config(page_title="Algo Trading Platform", layout="wide",
                       initial_sidebar_state="expanded")
    init_state()
    cfg = render_sidebar()

    head, status = st.columns([3, 1])
    head.title(APP_TITLE)
    head.caption(f"`{cfg['symbol']}` | {cfg['interval']} | {cfg['period']} | {cfg['strategy']}")
    (status.success if st.session_state.live_running else status.info)(
        "LIVE CORE: RUNNING" if st.session_state.live_running else "LIVE CORE: IDLE")

    (t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12, t13, t14) = st.tabs(
        ["Backtesting Engine Studio", "Live Sandbox Operations", "Live Trade Log Ledger",
         "Signal Screener", "Auto Screener", "Strategy Optimiser", "Signal Lab",
         "Chart Patterns", "Gamma Blast", "Momentum Pulse", "Volatility Levels",
         "Custom Indicators", "Make or Break", "Chart Studio"])
    panels = ((t1, tab_backtest, "Backtesting Engine Studio"),
              (t2, tab_live, "Live Sandbox Operations"),
              (t3, tab_ledger, "Live Trade Log Ledger"),
              (t4, tab_screener, "Signal Screener"),
              (t5, tab_auto_screener, "Auto Screener"),
              (t6, tab_optimiser, "Strategy Optimiser"),
              (t7, tab_signal_lab, "Signal Lab"),
              (t8, tab_patterns, "Chart Patterns"),
              (t9, tab_gamma_blast, "Gamma Blast"),
              (t10, tab_momentum_pulse, "Momentum Pulse"),
              (t11, tab_volatility_levels, "Volatility Levels"),
              (t12, tab_custom_screener, "Custom Indicators"),
              (t13, tab_make_break, "Make or Break"),
              (t14, tab_chart_studio, "Chart Studio"))
    for holder, render, name in panels:
        with holder:
            try:
                render(cfg)
            except Exception as exc:                                # noqa: BLE001
                # One tab failing used to take the whole page down, and with it
                # any sweep running in another tab. Now the broken panel says so
                # and everything else carries on.
                st.error(f"**{name} could not finish drawing.** {type(exc).__name__}: {exc}")
                with st.expander("Details"):
                    st.code(traceback.format_exc())

    # The deferred continuation of any running sweep. It happens here, after
    # every panel has drawn, so partial results are visible during the scan
    # instead of the tab looking blank until the very end.
    if st.session_state.pop("_sweep_rerun_pending", False):
        # A breath between passes. Without it the reruns form a hot loop that
        # starves the browser of the very updates this design exists to deliver.
        time.sleep(0.15)
        st.rerun()



