import sqlite3                                                      # noqa: E402

DB_PATH = "algo_platform_state.db"


def _db():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.execute("""CREATE TABLE IF NOT EXISTS open_position
                    (id INTEGER PRIMARY KEY CHECK (id = 1), payload TEXT, saved_at TEXT)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS trades
                    (id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT, exit_time TEXT)""")
    return conn


def db_save_position(position: "Position", cfg: dict) -> None:
    """
    Persist the open position so an overnight hold survives a restart.

    A position open at 15:30 is still risk at 09:15 the next morning. Without
    this the app forgets it, the stop stops existing, and the operator finds out
    the hard way.
    """
    if position is None:
        db_clear_position()
        return
    mgr = position.manager
    payload = {
        "strategy": position.strategy, "symbol": position.symbol,
        "interval": position.interval, "direction": position.direction,
        "quantity": position.quantity, "entry_price": position.entry_price,
        "entry_time": str(position.entry_time), "signal_bar_time": str(position.signal_bar_time),
        "broker_order_id": position.broker_order_id,
        "risk": {"sl_type": mgr.risk.sl_type, "sl_value": mgr.risk.sl_value,
                 "tp_type": mgr.risk.tp_type, "tp_value": mgr.risk.tp_value,
                 "quantity": mgr.risk.quantity, "step_trigger": mgr.risk.step_trigger,
                 "costs": mgr.risk.costs.__dict__},
        "manager": {"sl": mgr.sl, "tp": mgr.tp, "initial_sl": mgr.initial_sl,
                    "mfe": mgr.mfe, "bars_held": mgr.bars_held,
                    "risk_points": mgr.risk_points},
        "saved_at": pd.Timestamp.now().isoformat(),
    }
    with _db() as conn:
        conn.execute("INSERT OR REPLACE INTO open_position (id, payload, saved_at) "
                     "VALUES (1, ?, ?)", (json.dumps(payload), payload["saved_at"]))


def db_load_position() -> dict | None:
    try:
        with _db() as conn:
            row = conn.execute("SELECT payload FROM open_position WHERE id = 1").fetchone()
        return json.loads(row[0]) if row else None
    except Exception:                                               # noqa: BLE001
        return None


def db_clear_position() -> None:
    try:
        with _db() as conn:
            conn.execute("DELETE FROM open_position WHERE id = 1")
    except Exception:                                               # noqa: BLE001
        pass


def db_append_trade(trade: dict) -> None:
    try:
        with _db() as conn:
            conn.execute("INSERT INTO trades (payload, exit_time) VALUES (?, ?)",
                         (json.dumps(trade, default=str), str(trade.get("Exit Time"))))
    except Exception:                                               # noqa: BLE001
        pass


def db_load_trades() -> list[dict]:
    try:
        with _db() as conn:
            rows = conn.execute("SELECT payload FROM trades ORDER BY id").fetchall()
        return [json.loads(r[0]) for r in rows]
    except Exception:                                               # noqa: BLE001
        return []


def restore_position(payload: dict) -> "Position":
    """Rebuild a live position, including its trailed stop, from the database."""
    r = payload["risk"]
    costs = CostModel(**r.get("costs", {}))
    risk = RiskConfig(sl_type=r["sl_type"], sl_value=r["sl_value"], tp_type=r["tp_type"],
                      tp_value=r["tp_value"], quantity=r["quantity"],
                      step_trigger=r.get("step_trigger", 0.0), costs=costs)
    ctx = BarCtx(time=None, open=payload["entry_price"], high=payload["entry_price"],
                 low=payload["entry_price"], close=payload["entry_price"], atr=np.nan,
                 ema_fast=np.nan, ema_slow=np.nan, swing_high=np.nan, swing_low=np.nan,
                 prev_swing_high=np.nan, prev_swing_low=np.nan, prev_high=np.nan,
                 prev_low=np.nan, signal=0)
    mgr = ExitManager(risk, payload["entry_price"], payload["direction"], ctx)
    m = payload["manager"]
    # The TRAILED levels are restored, not recomputed. Recomputing would silently
    # reset a stop that had already ratcheted up, handing back risk the trade had
    # already locked away.
    mgr.sl, mgr.tp = m.get("sl"), m.get("tp")
    mgr.initial_sl, mgr.mfe = m.get("initial_sl"), m.get("mfe", payload["entry_price"])
    mgr.bars_held, mgr.risk_points = int(m.get("bars_held", 0)), m.get("risk_points")
    return Position(strategy=payload["strategy"], symbol=payload["symbol"],
                    interval=payload["interval"], direction=int(payload["direction"]),
                    quantity=float(payload["quantity"]),
                    entry_price=float(payload["entry_price"]),
                    entry_time=payload.get("entry_time"),
                    signal_bar_time=payload.get("signal_bar_time"), manager=mgr,
                    broker_order_id=payload.get("broker_order_id"))


# --------------------------------------------------------------------------- #
# EMAIL NOTIFICATIONS
# --------------------------------------------------------------------------- #
def send_email(cfg: dict, subject: str, body: str) -> str | None:
    """Send a notification via SMTP. Returns an error string, or None on success."""
    mail = (cfg or {}).get("email") or {}
    if not mail.get("enabled"):
        return None
    sender, to, password = mail.get("from"), mail.get("to"), mail.get("password")
    if not (sender and to and password):
        return "Email is enabled but the sender, recipient or app password is missing."
    try:
        import smtplib
        from email.message import EmailMessage
        msg = EmailMessage()
        msg["Subject"], msg["From"], msg["To"] = subject, sender, to
        msg.set_content(body)
        with smtplib.SMTP_SSL(mail.get("host", "smtp.gmail.com"),
                              int(mail.get("port", 465)), timeout=20) as smtp:
            smtp.login(sender, password)
            smtp.send_message(msg)
        return None
    except Exception as exc:                                        # noqa: BLE001
        return f"Email failed: {exc}"


# --------------------------------------------------------------------------- #
# WALK-FORWARD
# --------------------------------------------------------------------------- #
def walk_forward(df: pd.DataFrame, strategy: str, params: dict, risk: RiskConfig,
                 filter_cfg: dict | None, extras: dict | None, folds: int = 5) -> pd.DataFrame:
    """
    Sequential out-of-sample segments.

    IMPORTANT ON NAMING: with a fixed configuration there is no in-sample fitting
    to guard against, so this is a STABILITY report, not classical walk-forward
    optimisation. It answers "did this hold up across different stretches of the
    sample, or does one lucky window carry the whole result?" The optimiser tab
    runs the fit-then-test version.
    """
    rows = []
    size = len(df) // max(1, folds)
    for k in range(folds):
        lo = k * size
        hi = len(df) if k == folds - 1 else (k + 1) * size
        segment = df.iloc[max(0, lo - WARMUP_BARS):hi]
        try:
            res = run_backtest(segment, strategy, params, risk, filter_cfg, extras, WARMUP_BARS)
        except BacktestError:
            rows.append({"Segment": k + 1, "From": df.index[lo], "To": df.index[hi - 1],
                         "Trades": 0, "Win %": 0.0, "Net PnL": 0.0, "Sharpe": 0.0,
                         "Note": "too few candles"})
            continue
        st_ = res.stats
        rows.append({"Segment": k + 1, "From": df.index[lo], "To": df.index[hi - 1],
                     "Trades": st_["total_trades"], "Win %": st_["win_rate"],
                     "Net PnL": st_["net_pnl"], "Sharpe": st_["sharpe"], "Note": ""})
    return pd.DataFrame(rows)


# --------------------------------------------------------------------------- #
# STRATEGY OPTIMISER
# --------------------------------------------------------------------------- #
# Excluded from the search: Simple Buy, Simple Sell and both threshold profiles.
# They are execution helpers, not edges -- optimising them would just be fitting
# noise to whichever direction the sample happened to drift.
# Excluded because they cannot be backtested honestly: the immediate profiles
# take no signal, the threshold profiles depend on a hand-typed level, and the
# depth/OI profiles read a live snapshot with no published history.
_OPTIMISER_EXCLUDE = ("16 \u00b7", "17 \u00b7", "28 \u00b7", "29 \u00b7", "44 \u00b7",
                      "45 \u00b7", "46 \u00b7", "50 \u00b7")

OPTIMISER_OBJECTIVES = ["Win rate (accuracy)", "Sharpe ratio", "Net PnL", "Expectancy per trade",
                        "Profit factor",
                        # --- objectives about the SHAPE of the edge, not its size ---
                        "Return / max drawdown", "Smallest max drawdown",
                        "Reward : risk ratio", "Win-rate margin over breakeven"]

# For each objective: the results column it lives in, a sensible default target,
# the range and step the input should use, and how to label it. A single default
# cannot serve all five -- 80 is a reasonable win rate and an absurd Sharpe -- so
# the control follows whichever objective is selected.
OBJECTIVE_TARGETS = {
    "Win rate (accuracy)":  {"column": "Win %", "default": 90.0, "min": 0.0, "max": 100.0,
                             "step": 1.0, "unit": "%",
                             "note": "100% is reachable on a small sample and means almost "
                                     "nothing there. Raise the minimum trades alongside it."},
    "Sharpe ratio":         {"column": "Sharpe", "default": 1.0, "min": -10.0, "max": 100.0,
                             "step": 0.1, "unit": "",
                             "note": "Computed per trade and annualised from the sample's own "
                                     "trade frequency, so it inflates on short fast samples."},
    "Net PnL":              {"column": "Net PnL", "default": 0.0, "min": -1e9, "max": 1e9,
                             "step": 100.0, "unit": "",
                             "note": "In the instrument's own points times quantity, so it is "
                                     "not comparable across tickers."},
    "Expectancy per trade": {"column": "Expectancy", "default": 0.0, "min": -1e9, "max": 1e9,
                             "step": 1.0, "unit": "",
                             "note": "Average result per trade. The most honest single number "
                                     "of the five, and the hardest to fake with a tiny target."},
    "Profit factor":        {"column": "Profit Factor", "default": 1.5, "min": 0.0, "max": 50.0,
                             "step": 0.1, "unit": "",
                             "note": "Gross wins over gross losses. Below 1.0 the system loses "
                                     "money however high the win rate is."},
    "Return / max drawdown": {"column": "Return/DD", "default": 3.0, "min": 0.0, "max": 100.0,
                              "step": 0.5, "unit": "x",
                              "note": "Net profit divided by the worst peak-to-trough fall. "
                                      "Below 2 the profit is small next to the pain it cost; "
                                      "above 3 is respectable. A live drawdown is normally "
                                      "WORSE than the backtested one, so treat this as a "
                                      "best case."},
    "Smallest max drawdown": {"column": "Max DD", "default": 0.0, "min": -1e9, "max": 1e9,
                              "step": 100.0, "unit": "",
                              "note": "Minimised, not maximised: the search keeps the SHALLOWEST "
                                      "drawdown. Used alone it will happily pick a configuration "
                                      "that barely trades, so pair it with a minimum trade count "
                                      "and check the net PnL column."},
    "Reward : risk ratio":   {"column": "Reward:Risk", "default": 1.5, "min": 0.0, "max": 50.0,
                              "step": 0.1, "unit": ": 1",
                              "note": "Average win over average loss. Below 1 you are paying "
                                      "more for being wrong than you collect for being right, "
                                      "which only survives on a very high win rate."},
    "Win-rate margin over breakeven":
                            {"column": "Win margin %", "default": 10.0, "min": -100.0,
                             "max": 100.0, "step": 1.0, "unit": "pts",
                             "note": "Actual win rate minus the win rate this reward:risk NEEDS "
                                     "to break even. This is the fragility measure: a margin of "
                                     "2 points means a slightly worse month turns the system "
                                     "negative. Bigger is safer."},
}

# Objectives where SMALLER is better. The search maximises a score, so these are
# negated before ranking -- otherwise asking for the smallest drawdown would
# return the deepest one.
_MINIMISE_OBJECTIVES = {"Smallest max drawdown"}


#: A sensible starting combination: make money, keep the drawdown shallow, and
#: do not pay more for a mistake than being right earns.
DEFAULT_COMBO = ["Net PnL", "Return / max drawdown", "Win-rate margin over breakeven"]


def render_objective_picker(prefix: str, label: str = "Optimise for"):
    """
    Pick ONE objective, or several and rank by all of them at once.

    Returns ``(objective, column, weights, min_percentile)`` where objective is
    a string in single mode and a list in combined mode. Everything downstream
    takes either, so the tabs do not need to know which was chosen.
    """
    combined = st.checkbox(
        "Combine several objectives", value=False, key=f"{prefix}_combo_on",
        help="Off: rank by one measure. On: rank by all the measures you tick. Each is "
             "converted to its percentile within this search and the percentiles are "
             "averaged, so a win rate, a Sharpe ratio and a rupee PnL can be weighed against "
             "each other without the largest number winning by default.")
    if not combined:
        objective = st.selectbox(label, OPTIMISER_OBJECTIVES, key=f"{prefix}_obj")
        return objective, OBJECTIVE_TARGETS[objective]["column"], {}, 0.0

    st.caption("Tick every measure that matters. A combination has to be good at all of them "
               "to rank highly, which is a far harder test than topping any single one.")
    picked, weights = [], {}
    columns = st.columns(3)
    for i, objective in enumerate(OPTIMISER_OBJECTIVES):
        if columns[i % 3].checkbox(objective, value=objective in DEFAULT_COMBO,
                                   key=f"{prefix}_combo_{objective}"):
            picked.append(objective)

    if not picked:
        st.warning("Nothing ticked, so the search falls back to ranking on net PnL alone.")
        return "Net PnL", "Net PnL", {}, 0.0

    with st.expander(f"Weights and the weakest-link floor ({len(picked)} selected)"):
        st.caption("A weight of 1 counts an objective once. Raise it to let one measure pull "
                   "harder without silencing the others.")
        wcols = st.columns(min(len(picked), 4))
        for i, objective in enumerate(picked):
            weights[objective] = wcols[i % len(wcols)].number_input(
                _OBJECTIVE_SHORT.get(objective, objective), 0.0, 10.0, 1.0, 0.5,
                key=f"{prefix}_w_{objective}")
        floor = st.number_input(
            "Minimum percentile on EVERY selected objective", 0, 90, 0, 5,
            key=f"{prefix}_combo_floor",
            help="The averaging alone lets a combination that is superb on three measures and "
                 "dreadful on the fourth still win. Set this and every measure must clear the "
                 "bar. 0 turns it off; 50 means 'never worse than the median at anything'.")
    st.caption("Ranked on: " + ", ".join(_OBJECTIVE_SHORT.get(o, o) for o in picked)
               + ". The results table shows each measure's own percentile plus the weakest "
                 "of them, so a high score is always traceable.")
    return picked, "Score", weights, float(floor)


def objective_target_input(container, prefix: str, objective: str, label: str = "Desired value"):
    """
    A target input whose default and range follow the selected objective.

    Keyed per objective so switching from a win rate of 90 to a Sharpe ratio does
    not leave 90 sitting in a Sharpe box.
    """
    spec = OBJECTIVE_TARGETS.get(objective, OBJECTIVE_TARGETS["Win rate (accuracy)"])
    suffix = f" ({spec['unit']})" if spec["unit"] else ""
    value = container.number_input(
        f"{label}{suffix} — {objective}", min_value=float(spec["min"]),
        max_value=float(spec["max"]), value=float(spec["default"]), step=float(spec["step"]),
        key=f"{prefix}_target_{objective}",
        help=spec["note"])
    return float(value), spec["column"]

_OPT_SL_GRID = [("Fixed Percentage", 0.5), ("Fixed Percentage", 1.0), ("Fixed Points", 20.0),
                ("Fixed Points", 40.0), ("ATR Multiple", 1.5), ("ATR Multiple", 2.5),
                ("Trail Current Swing Low/High", 0.0), ("Trail Previous Candle Low/High", 0.0),
                ("Trailing ATR (Chandelier)", 3.0)]
_OPT_TP_GRID = [("Fixed Percentage", 1.0), ("Fixed Percentage", 2.0), ("Fixed Points", 40.0),
                ("Fixed Points", 80.0), ("ATR Multiple", 3.0),
                ("Risk : Reward Multiple", 1.5), ("Risk : Reward Multiple", 2.5),
                ("Trail Current Swing High/Low", 0.0)]
_OPT_FILTERS = [None, "adx", "rsi", "ema20", "supertrend", "macd", "regime"]


def _objective_value(stats: dict, objective: str) -> float:
    """
    The score a search maximises, for one objective.

    An infinite ratio is what a sample with no losing trade produces. It is not
    a perfect system, it is a sample too small to have met its first loss, so
    it scores 0 rather than winning every search outright.
    """
    def _finite(value, cap=None):
        try:
            number = float(value)
        except (TypeError, ValueError):
            return 0.0
        if not np.isfinite(number):
            return 0.0
        return float(min(number, cap)) if cap is not None else number

    raw = {
        "Win rate (accuracy)": _finite(stats.get("win_rate")),
        "Sharpe ratio": _finite(stats.get("sharpe")),
        "Net PnL": _finite(stats.get("net_pnl")),
        "Expectancy per trade": _finite(stats.get("expectancy")),
        "Profit factor": _finite(stats.get("profit_factor")),
        "Return / max drawdown": _finite(stats.get("return_over_dd")),
        # Negated so that "largest score" means "shallowest drawdown".
        "Smallest max drawdown": -abs(_finite(stats.get("max_drawdown"))),
        "Reward : risk ratio": _finite(stats.get("reward_risk")),
        "Win-rate margin over breakeven": _finite(stats.get("win_rate_margin")),
    }.get(objective, 0.0)
    return float(raw)


# Short names for the per-objective percentile columns, so a combined table
# stays readable instead of carrying nine long headings.
_OBJECTIVE_SHORT = {
    "Win rate (accuracy)": "Accuracy", "Sharpe ratio": "Sharpe", "Net PnL": "Net PnL",
    "Expectancy per trade": "Expectancy", "Profit factor": "Profit factor",
    "Return / max drawdown": "Return/DD", "Smallest max drawdown": "Drawdown",
    "Reward : risk ratio": "Reward:Risk", "Win-rate margin over breakeven": "Win margin",
}


def objective_label(objective) -> str:
    """A readable name for one objective or for a combination of them."""
    if isinstance(objective, (list, tuple)):
        names = [_OBJECTIVE_SHORT.get(o, o) for o in objective]
        return ("a combined score across " + ", ".join(names)) if names else "net PnL"
    return str(objective).lower()


def combine_objective_scores(frame: pd.DataFrame, objectives: list[str],
                             weights: dict | None = None,
                             min_percentile: float = 0.0) -> pd.DataFrame:
    """
    Rank one search by SEVERAL objectives at once.

    Adding the raw numbers together is meaningless: a win rate runs 0-100, a
    Sharpe ratio 0-3 and a net PnL into the tens of thousands, so a plain sum is
    just net PnL wearing a disguise. Each objective is therefore converted to
    its PERCENTILE within this search -- "better than 80% of the combinations
    tried" -- and the percentiles are averaged. That is scale-free, so every
    objective genuinely counts, and the result reads as 0-100 whatever is
    selected.

    Direction is handled per objective: drawdown is ranked so that the
    shallowest wins. A value that cannot be measured (an infinite profit factor
    from a sample with no losing trade) ranks LAST on that objective rather
    than first, because an unmeasurable result is not a good one.

    ``min_percentile`` is the weakest-link floor. Averaging alone lets a
    combination that is excellent on three objectives and dreadful on the
    fourth still win; with a floor set, every selected objective must clear it.
    """
    if frame.empty or not objectives:
        return frame
    out = frame.copy()
    weights = {k: float(v) for k, v in (weights or {}).items()}

    percentiles, used = [], []
    for objective in objectives:
        spec = OBJECTIVE_TARGETS.get(objective)
        if not spec or spec["column"] not in out.columns:
            continue
        series = pd.to_numeric(out[spec["column"]], errors="coerce")
        series = series.replace([np.inf, -np.inf], np.nan)
        if objective in _MINIMISE_OBJECTIVES:
            # Shallowest drawdown wins, so rank the magnitude in reverse.
            series = series.abs()
            ranked = series.rank(pct=True, ascending=False, na_option="bottom")
        else:
            ranked = series.rank(pct=True, ascending=True, na_option="bottom")
        ranked = (ranked * 100.0).where(series.notna(), 0.0)
        label = f"%ile {_OBJECTIVE_SHORT.get(objective, objective)}"
        out[label] = ranked.round(1)
        percentiles.append((objective, ranked))
        used.append(label)

    if not percentiles:
        return frame

    total_weight = sum(max(weights.get(obj, 1.0), 0.0) for obj, _ in percentiles) or 1.0
    blended = sum(series * max(weights.get(obj, 1.0), 0.0)
                  for obj, series in percentiles) / total_weight
    out["Score"] = blended.round(2)
    out["Weakest %ile"] = pd.concat([s for _, s in percentiles], axis=1).min(axis=1).round(1)
    out["Objectives"] = ", ".join(_OBJECTIVE_SHORT.get(o, o) for o, _ in percentiles)

    floor = float(min_percentile or 0.0)
    if floor > 0:
        keep = out["Weakest %ile"] >= floor
        # Never return nothing: if the floor eliminates every combination, say
        # so by keeping the best-of-the-rejected rather than an empty table.
        out = out[keep] if bool(keep.any()) else out
    return out.sort_values("Score", ascending=False).reset_index(drop=True)


def parse_number_list(text: str, fallback: list[float]) -> list[float]:
    """Parse '0.5, 1, 1.5' into floats, keeping order and dropping duplicates."""
    out: list[float] = []
    for chunk in str(text or "").replace(";", ",").split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        try:
            value = float(chunk)
        except ValueError:
            continue
        if value not in out:
            out.append(value)
    return out or list(fallback)


def scale_points_to_instrument(grid: dict, df: pd.DataFrame, atr_len: int = 14) -> dict:
    """
    Rewrite absolute point values as multiples of the instrument's own ATR.

    A 40-point stop is a sensible intraday stop on Nifty and 0.05% on Bitcoin.
    Searching the same absolute numbers across instruments does not compare like
    with like: on BTC every point-based combination is effectively a zero-width
    stop that is hit immediately, and on a Rs.50 stock it is wider than the whole
    day's range. The multipliers are preserved -- only their scale changes.
    """
    try:
        atr_series = atr(df["High"], df["Low"], df["Close"], atr_len)
        unit = float(atr_series.median(skipna=True))
    except Exception:                                               # noqa: BLE001
        return grid
    if not np.isfinite(unit) or unit <= 0:
        return grid

    base = 20.0                       # the point values in the default grid are multiples of this
    def rescale(pairs_in):
        out = []
        for kind, value in pairs_in:
            if kind == "Fixed Points" and value:
                multiple = float(value) / base
                scaled = round(unit * multiple * 2.0, 4)
                scaled = round(scaled, 2) if scaled >= 1 else round(scaled, 4)
                out.append((kind, scaled))
            else:
                out.append((kind, value))
        return out

    out = dict(grid)
    out["sl"] = rescale(grid["sl"])
    out["tp"] = rescale(grid["tp"])
    out["_atr_unit"] = round(unit, 4)
    return out


def build_search_grid(strategies: list[str], sl_types: list[str], sl_values: list[float],
                      tp_types: list[str], tp_values: list[float],
                      filters: list[str], safe_exits_only: bool) -> dict:
    """
    Expand the operator's choices into the axes the search walks.

    Structural exits take their level from the chart, so they are paired with a
    single dummy magnitude rather than multiplied across every value the user
    typed -- otherwise the grid inflates with combinations that are identical.
    """
    def pairs(types: list[str], values: list[float], no_value: set) -> list[tuple[str, float]]:
        out = []
        for t in types:
            if t in no_value:
                out.append((t, 0.0))
            else:
                out.extend((t, v) for v in values)
        return out

    def strip_unsafe(pairs_in):
        return [x for x in pairs_in if x[0] not in DISTANCE_TRAIL_TYPES] \
            if safe_exits_only else list(pairs_in)

    sl = strip_unsafe(pairs(sl_types, sl_values, _SL_NO_VALUE))
    tp = pairs(tp_types, tp_values, _TP_NO_VALUE)
    # The fallback must obey safe mode too. Substituting the default grid
    # unfiltered would quietly hand back the distance trails that safe mode was
    # asked to exclude. If the operator's own choice empties out, leave it empty
    # so the caller can say so rather than searching something else.
    if not sl and not sl_types:
        sl = strip_unsafe(_OPT_SL_GRID)
    if not tp and not tp_types:
        tp = list(_OPT_TP_GRID)
    return {
        "strategies": strategies or [n for n in STRATEGY_NAMES
                                     if not n.startswith(_OPTIMISER_EXCLUDE)],
        "sl": sl,
        "tp": tp,
        "filters": ([None] + [f for f in filters if f]) if filters else list(_OPT_FILTERS),
    }


def grid_size(grid: dict) -> int:
    return (len(grid["strategies"]) * max(1, len(grid["sl"])) * max(1, len(grid["tp"]))
            * max(1, len(grid["filters"])))


def optimise(df: pd.DataFrame, base_params: dict, quantity: float, costs: CostModel,
             objective, min_trades: int, iterations: int, seed: int = 11,
             safe_exits_only: bool = True, progress=None,
             grid: dict | None = None, exhaustive: bool = False,
             scale_points: bool = True, weights: dict | None = None,
             min_percentile: float = 0.0) -> pd.DataFrame:
    """
    Randomised search over strategy x stop x target x one optional filter.

    Randomised rather than exhaustive because the full grid is tens of thousands
    of backtests. And a caution that matters more than the search itself: the
    more combinations tried, the more likely the winner is luck. Treat the
    ranking as a shortlist to validate out of sample, never as a result.

    ``objective`` is either one objective name or a LIST of them. With a list
    the ranking is the average percentile across all of them, which is how a
    search can be asked for profit AND a shallow drawdown AND a sane
    reward:risk at the same time rather than one at the expense of the others.
    """
    combo = [o for o in objective] if isinstance(objective, (list, tuple, set)) else []
    primary = combo[0] if combo else objective
    rng = np.random.default_rng(seed)
    if grid is None:
        grid = {"strategies": [n for n in STRATEGY_NAMES
                               if not n.startswith(_OPTIMISER_EXCLUDE)],
                "sl": [x for x in _OPT_SL_GRID
                       if not (safe_exits_only and x[0] in DISTANCE_TRAIL_TYPES)],
                "tp": list(_OPT_TP_GRID), "filters": list(_OPT_FILTERS)}
    if scale_points:
        grid = scale_points_to_instrument(grid, df, int(base_params.get("atr_len", 14)))
    names, sl_grid = grid["strategies"], grid["sl"]
    tp_grid, filters = grid["tp"], grid["filters"]
    if not (names and sl_grid and tp_grid and filters):
        return pd.DataFrame()

    if exhaustive:
        combos = [(a, b, c, d) for a in names for b in sl_grid for c in tp_grid for d in filters]
        rng.shuffle(combos)                       # shuffled so a cap still samples the space
        combos = combos[:int(iterations)] if iterations else combos
    else:
        combos = None

    rows, seen = [], set()
    total = len(combos) if combos is not None else int(iterations)
    started = time.time()

    for it in range(total):
        if progress is not None and it % 5 == 0:
            done = (it + 1) / max(1, total)
            elapsed = time.time() - started
            eta = (elapsed / max(done, 1e-6)) - elapsed
            progress.progress(min(1.0, done),
                              text=f"Tested {it} of {total} combinations "
                                   f"({done*100:.0f}%) - about {eta:0.0f}s left")
        if combos is not None:
            strategy, (sl_type, sl_val), (tp_type, tp_val), filt = combos[it]
        else:
            strategy = names[int(rng.integers(len(names)))]
            sl_type, sl_val = sl_grid[int(rng.integers(len(sl_grid)))]
            tp_type, tp_val = tp_grid[int(rng.integers(len(tp_grid)))]
            filt = filters[int(rng.integers(len(filters)))]
        key = (strategy, sl_type, sl_val, tp_type, tp_val, filt)
        if key in seen:
            continue
        seen.add(key)

        fcfg = default_filter_config()
        if filt:
            fcfg[filt]["enabled"] = True
        risk = RiskConfig(sl_type, sl_val, tp_type, tp_val, quantity, costs=costs)
        try:
            res = run_backtest(df, strategy, dict(base_params), risk, fcfg, {}, WARMUP_BARS,
                               square_off_eod=base_params.get("square_off_eod"))
        except (BacktestError, MarketDataError, Exception):          # noqa: BLE001
            continue
        st_ = res.stats
        if st_["total_trades"] < min_trades:
            continue
        rows.append({
            "Strategy": strategy, "Stop-Loss": sl_type,
            "SL Value": sl_val if sl_type not in _SL_NO_VALUE else None,
            "Target": tp_type, "TP Value": tp_val if tp_type not in _TP_NO_VALUE else None,
            "Filter": FILTER_LABELS.get(filt, "none"), "Filter Key": filt or "",
            "Trades": st_["total_trades"],
            "Win %": st_["win_rate"], "Sharpe": st_["sharpe"], "Net PnL": st_["net_pnl"],
            "Expectancy": st_["expectancy"], "Profit Factor": st_["profit_factor"],
            "Max DD": st_["max_drawdown"],
            "Return/DD": st_.get("return_over_dd"),
            "Reward:Risk": st_.get("reward_risk"),
            "Breakeven Win %": st_.get("breakeven_win_rate"),
            "Win margin %": st_.get("win_rate_margin"),
            "Avg Win": st_.get("avg_win"), "Avg Loss": st_.get("avg_loss"),
            "Reliability": st_["reliability"],
            "Score": _objective_value(st_, primary),
        })

    frame = pd.DataFrame(rows)
    if frame.empty:
        return frame
    if combo:
        # Re-score across every selected objective. This has to happen after
        # the whole search, because a percentile only means something relative
        # to the other combinations tried.
        frame = combine_objective_scores(frame, combo, weights, min_percentile)
    else:
        frame = frame.sort_values("Score", ascending=False).reset_index(drop=True)
    frame.insert(0, "Rank", range(1, len(frame) + 1))
    return frame


if __name__ == "__main__":
    if "--selftest" in sys.argv:
        sys.exit(run_selftest())
    main()
